    \item $\calV = \left\{ 
            \begin{tabular}{l l}
                $ (S,$&$ \text{Sophie received all test messages.}),$\\ 
                $ (L,$&$ \text{Luke received all test messages.}),$\\ 
                $ (M,$&$ \text{Maja received all test messages.}),$\\
                $ (N,$&$ \text{Nino received all test messages.})$
            \end{tabular}%
    \right\}$
    \item $ \calS = \{ \{ S, L, M, N \} \} $
\end{itemize}%
}

