                    $ (A(\paramU),$          & $ \text{\paramU is an author.}),$\\
                    $ (M(\paramU),$          & $ \text{Author \paramU is a mathematician.}),$\\
                    $ (L(\paramU),$          & $ \text{Book \paramU deals with logic.}),$\\
                    $ (R(\paramU, \paramV),$ & $ \text{Book \paramU refutes book \paramV.}),$\\
                    $ (f(\paramU),$          & $ \text{Author of book \paramU}),$\\
                    $ (F(\paramU, \paramV),$ & $ \{\text{\paramU is the author of book \paramV.}\newline \text{~\,Book \paramU was written by author \paramV.}\}),$\\
                    $ (p,$                   & $ \text{The book Principia Mathematica}),$\\
                    $ (P(\paramU),$          & $ \text{\paramU is the book Principia Mathematica.})$
                \end{tabular}%
        \right\}$
        \item $ \calS = \left\{ 
                \begin{tabular}{l}
                    $ \{ B, A, M, L, R, f, p\},$\\
                    $ \{ B, A, M, L, R, f, P \},$\\ 
                    $\{ B, A, M, L, R, F, p \},$\\
                    $\{ B, A, M, L, R, F, P \} $
                \end{tabular}%
        \right\} $
        \item $ \varphi_\calS = B \land A \land M \land L \land R \land (f \lor F) \land (p \lor P) $ with redundancies $ \{ f, F \} $ and $ \{ p, P \} $
