% 		\mbox{undefined} & \mbox{otherwise}
% 								\end{cases}
% \end{eqnarray*}
Let $q, q'\in Q$, $\sigma \in I^*$ and $\rho \in O^*$.
We write $q\xrightarrow{\sigma/\rho}q'$ to denote $\lambda(q,\sigma) = \rho$ and $\delta(q,\sigma) = q'$.
We write 
$q\xrightarrow{\sigma/\rho}$ if there is a $q' \in Q$ with $q\xrightarrow{\sigma/\rho}q'$,
we write
$q\xrightarrow{\sigma}q'$ if there is a $\rho\in O^*$ with $q\xrightarrow{\sigma/\rho}q'$, and
we write
$q\xrightarrow{+} q'$ if there is a $\sigma \in I^+$ with $q\xrightarrow{\sigma}q'$.
If $q_0 \xrightarrow{\sigma}q$ then we say that $q$ is \emph{reachable} via $\sigma$.

A \emph{state cover} for $\M$ is a finite, prefix-closed set of input sequences $A \subset I^*$ such that, for every $q \in Q$, there is a $\sigma \in A$ such that $q$ is reachable via $\sigma$.
A state cover $A$ is \emph{minimal} if each state of $\M$ is reached by exactly one sequence from $A$.
%We say that 
$\M$ is \emph{initially connected} if it has a state cover.
We will only consider Mealy machines that are initially connected.
\end{definition}


\begin{definition}[Semantics and minimality]
	\label{def:equivalence}
The \emph{semantics} of a state $q$ of a Mealy machine $\M$ is the map $\semantics{q}^{\M} \colon I^*\partialto O^*$
  defined by $\semantics{q}^{\M}(\sigma) = \lambda^{\M}(q, \sigma)$.

States $q, r$ of Mealy machines $\M$ and $\N$, respectively, are \emph{equivalent},
written $q \approx r$, iff $\semantics{q}^{\M} = \semantics{r}^{\N}$.
Mealy machines $\M$ and $\N$ are \emph{equivalent}, written $\M \approx \N$, iff their initial
states are equivalent: $q_0^\M \approx q_0^\N$.
%
A Mealy machine $\M$ is \emph{minimal} iff, for all pairs of states $q, q'$, $q \approx q'$ iff $q =q'$.
\end{definition}

