\subsection{Observation Trees}
\label{prel apartness}

%In our testing setting, an \emph{undefined} value in the partial transition map
%represents lack of knowledge. 
A \emph{functional simulation} is a function between Mealy machines that preserves the initial state and the transition and output functions.

\begin{definition}[Simulation]
\label{def refinement}
A \emph{functional simulation} between Mealy machines $\M$ and $\N$ is a function
$f\colon Q^{\M} \to Q^{\N}$ satisfying $f(q^{\M}_0)= q^{\N}_0$ 
and, for $q \in Q^{\M}$ and $i \in I$, 
\begin{eqnarray*}
	\delta^{\M}(q,i) \converges & ~~ \Rightarrow ~~ & f(\delta^{\M}(q,i)) = \delta^{\N}(f(q),i) \mbox{ and }
	\lambda^{\M}(q,i) = \lambda^{\N}(f(q), i).
\end{eqnarray*} 
We write $f\colon \M\to \N$ if $f$ is a functional simulation between $\M$ and $\N$.
\end{definition}
Note that if $f\colon \M\to \N$, each transition $q \xrightarrow{i/o} q'$ of $\M$ can be matched by a transition $f(q) \xrightarrow{i/o} f(q')$ of $\N$. 

