\section{Proofs}
\label{sc:proofs}

We defined the lifted transition and output functions inductively for sequences of the form $i \sigma$. The next lemma basically says that we could have equivalently defined it inductively for sequences of the form $\sigma i$.

\begin{lemma}
	\label{la lifted functions}
	Let $\M$ be a Mealy machine, $q \in Q$, $i \in I$ and $\sigma \in I^*$. Then
	$\delta(q, \sigma i)  =  \delta(\delta(q, \sigma), i)$ and
	$\lambda(q, \sigma i) = \lambda(q, \sigma) \cdot \lambda(\delta(q, \sigma), i)$.
\end{lemma}
\begin{proof}
	We prove $\delta(q, \sigma i)  =  \delta(\delta(q, \sigma), i)$ by induction on the length of $\sigma$:
	\begin{itemize}
		\item 
		If $\sigma = \epsilon$ then
		\[
		\delta(q, \sigma i) = \delta(q, i) = \delta(\delta(q, \epsilon), i) = \delta(\delta(q, \sigma), i)
		\]
		\item 
		Induction step.  Assume $\sigma = j \rho$ with $j \in I$ and $\rho \in I^*$.  If $\delta(q, j)$ is undefined, then both
		$\delta(q, j \rho i)$ and $\delta(\delta(q, j \rho), i)$ are undefined, and the identity holds.  If $\delta(q, j)$ is defined then
		\[
		\delta(q, j \rho i) = \delta(\delta(q, j), \rho i) \overset{\text{ind. hyp.}}{=} \delta(\delta(\delta(q,j), \rho), i) = \delta(\delta(q, j \rho), i)
		\]
	\end{itemize}
	Similarly, we prove $\lambda(q, \sigma i) = \lambda(q, \sigma) \cdot \lambda(\delta(q, \sigma), i)$ by induction on the length of $\sigma$:
	\begin{itemize}
		\item 
		If $\sigma = \epsilon$ then
		\[
		\lambda(q, \sigma i) = \lambda(q, i) = \epsilon \cdot  \lambda(q, i) = \lambda(q, \epsilon) \cdot \lambda (\delta(q, \epsilon), i) = \lambda(q, \sigma) \cdot \lambda(\delta(q, \sigma), i)
		\]
		\item 
		Induction step.  Assume $\sigma = j \rho$ with $j \in I$ and $\rho \in I^*$.  If $\delta(q, j)$ and $\lambda(q, j)$ are undefined, then both $\lambda(q, \sigma i)$ and $\lambda(q, \sigma) \cdot \lambda(\delta(q, \sigma), i)$ are undefined, and the identity holds.  If $\delta(q, j)$ and $\lambda(q, j)$ are defined then
		\begin{eqnarray*}
			\lambda(q, \sigma i) & = &  \lambda(q, j \rho i) = \lambda(q, j) \cdot \lambda(\delta(q, j), \rho i) 
			\\
			& \overset{\text{ind. hyp.}}{=}	& \lambda(q, j) \cdot \lambda(\delta(q, j), \rho) \cdot \lambda(\delta(\delta(q,j), \rho), i)\\
			& = & \lambda(q, j \rho) \cdot \lambda(\delta(q, j \rho), i)\\
			& = &  \lambda(q, \sigma) \cdot \lambda(\delta(q, \sigma), i)  
		\end{eqnarray*}
	\end{itemize}
\end{proof}

The next lemma, which follows via a simple inductive argument from the definitions, states that a functional simulation preserves the transition and output functions on words.

\begin{lemma}
	\label{la:refinement lifted to sigma}
	Suppose $f \colon \M \to \N$.
	Suppose $q, q'\in Q^{\M}$, $\sigma \in I^*$ and $\rho \in O^*$.
	Then $q\xrightarrow{\sigma/\rho}q'$ implies $f(q) \xrightarrow{\sigma/\rho} f(q')$.
\end{lemma}
\begin{proof}
	Suppose $q\xrightarrow{\sigma/\rho}q'$.
	Then $\lambda^{\M}(q,\sigma) = \rho$ and $\delta^{\M}(q, \sigma) = q'$.
	In order to establish $f(q) \xrightarrow{\sigma/\rho} f(q')$,
	we need to show that
	$\lambda^{\N}(f(q),\sigma) = \rho$ and $\delta^{\N}(f(q), \sigma) = f(q')$.
	We prove both equalities by induction on the length of $\sigma$.
	\begin{itemize}
		\item 
		Assume $\sigma = \epsilon$. Then 
		\[
		\lambda^{\N}(f(q),\sigma) = \lambda^{\N}(f(q),\epsilon) = \epsilon 
		= \lambda^{\M}(q,\epsilon) = \lambda^{\M}(q,\sigma) = \rho,
		\]
		\[
		\delta^{\N}(f(q), \sigma) = \delta^{\N}(f(q), \epsilon) = f(q) = f(\delta^{\M}(q, \epsilon)) = f(\delta^{\M}(q, \sigma)) = f(q').
		\]
		\item 
		Assume $\sigma = i \sigma'$. We have
		$\delta^{\M}(q, i \sigma') = \delta^{\M}(\delta^{\M}(q,i), \sigma')$ and
		$\lambda^{\M}(q, i \sigma') = \lambda^{\M}(q,i) \lambda^{\M}(\delta^{\M}(q,i), \sigma')$.
		Let $q'' = \delta^{\M}(q, i)$, $o = \lambda^{\M}(q,i)$ and
		$\rho'= \lambda^{\M} (q'', \sigma')$.
		Then we obtain $\rho = o \rho'$, $q\xrightarrow{i/o}q''$ and $q'' \xrightarrow{\sigma'/\rho'}q'$.
		Since $f$ is a functional simulation and by the induction hypothesis,
		$f(q)\xrightarrow{i/o} f(q'')$ and $f(q'') \xrightarrow{\sigma'/\rho'} f(q')$. Then
		\[
		\lambda^{\N}(f(q),\sigma) = \lambda^{\N}(f(q),i) \lambda^{\N}(\delta^{\N}(f(q),i), \sigma') = o \lambda^{\N}(f(q''), \sigma') = o \rho'= \rho
		\]
		\[
		\delta^{\N}(f(q), \sigma) = \delta^{\N}(\delta^{\N}(f(q), i), \sigma') = \delta^{\N}(f(q''), \sigma') = f(q')
		\]
		as required.
	\end{itemize}
\end{proof}


\begin{proofappendix}{lemma testing tree}
	We check the three conditions of Definition~\ref{def refinement}:
	\begin{enumerate}
		\item 
		$f(q_0^{\Obs}) = f(\epsilon) = \delta^{\Spec} (q_0^{\Spec}, \epsilon) = q_0^{\Spec}$.
		\item 
		Assume $\sigma \in Q^{\Obs}$ and $i \in I$ such that $\delta^{\Obs}(\sigma,i) \converges$. Then by Lemma~\ref{la lifted functions}:
		\[
		f(\delta^{\Obs}(\sigma,i)) = f(\sigma i) = \delta^{\Spec}(q_0^{\Spec}, \sigma i) =
		\delta^{\Spec}(\delta^{\Spec}(q_0^{\Spec}, \sigma), i) =  \delta^{\Spec}(f(\sigma),i).
		\] 
		\item 
		Assume $\sigma \in Q^{\Obs}$ and $i \in I$ such that $\lambda^{\Obs}(\sigma,i) \converges$. Then 
		\[
		\lambda^{\Obs}(\sigma,i) 
		= \lambda^{\Spec}( \delta^{\Spec} (q_0^{\Spec}, \sigma), i)
		= \lambda^{\Spec}(f(\sigma), i).
		\]
	\end{enumerate}
\end{proofappendix}

\begin{proofappendix}{observation tree when test suite passes}
	We prove both implications:
	\begin{itemize}
		\item 
		Suppose $\M$ passes $T$.
		We prove $f \colon \Obs\to \M$ by checking the three conditions of Definition~\ref{def refinement}:
		\begin{enumerate}
			\item 
			$f(q_0^{\Obs}) = f(\epsilon) = \delta^{\M}(q_0^{\M}, \epsilon) = q_0^{\M}$.
			\item 
			Assume $\delta^{\Obs}(\sigma, i) \converges$, for some $\sigma \in Q^{\Obs}$ and $i \in I$. Then by Lemma~\ref{la lifted functions}:
			\[
			f(\delta^{\Obs}(\sigma, i)) = f( \sigma i) = 
			\delta^{\M} (q_0^{\M}, \sigma i) = \delta^{\M} (\delta^{\M} (q_0^{\M}, \sigma), i) = \delta^{\M} (f(\sigma), i)
			\]
			\item 
			As $\M$ passes $T$, for all $\sigma \in T$, 
			$\lambda^{\M} (q_0^{\M}, \sigma) = \lambda^{\Spec} (q_0^{\Spec}, \sigma)$.
			This implies that, for all $\sigma i \in \mathit{Pref}(T)$,
			$\lambda^{\M} (q_0^{\M}, \sigma i) = \lambda^{\Spec} (q_0^{\Spec}, \sigma i)$.
			By Lemma~\ref{la lifted functions}, this implies
			\begin{eqnarray*}
				\lambda^{\M} (\delta^{\M}(q_0^{\M}, \sigma), i) & = & \lambda^{\Spec} (\delta^{\Spec}(q_0^{\Spec}, \sigma), i).
			\end{eqnarray*}
			Now assume $\lambda^{\Obs}(\sigma, i) \converges$, for some $\sigma \in Q^{\Obs}$ and $i \in I$.
			Then $\sigma i \in \mathit{Pref}(T)$, and therefore, by the above equation,
			\[
			\lambda^{\Obs}(\sigma, i) = \lambda^{\Spec}( \delta^{\Spec} (q_0^{\Spec}, \sigma), i) = \lambda^{\M} (\delta^{\M}(q_0^{\M}, \sigma), i)  = \lambda^{\M}(f(\sigma), i).
			\]
		\end{enumerate}
		\item 
		Suppose $f \colon \Obs \to \M$.
		Let $\sigma \in T$.  By construction, $\sigma$ is also a state of $\Obs$ and, for some $\rho$,
		$\epsilon \xrightarrow{\sigma/\rho} \sigma$.
		By Lemma~\ref{lemma testing tree} and Lemma~\ref{la:refinement lifted to sigma},
		$q_0^{\Spec} \xrightarrow{\sigma/\rho} \delta^{\Spec}(q_0^{\Spec}, \sigma)$.
		By the assumption and Lemma~\ref{la:refinement lifted to sigma},
		$q_0^{\M} \xrightarrow{\sigma/\rho} \delta^{\M}(q_0^{\M}, \sigma)$.
		Hence $\lambda^{\M} (q_0^{\M}, \sigma) = \rho = \lambda^{\Spec} (q_0^{\Spec}, \sigma)$.
	\end{itemize}	
\end{proofappendix}

\begin{proofappendix}{theorem k-A larger than m}
	Suppose $\M \in \U_m \setminus \U^A$. We must show that $\M \in \U_k^A$.
	%Since $\M \in \U_m$, we know that $\M$ is a complete Mealy machine.
	Since $\M \not\in \U^A$, the states of $\M$ reached by sequences from $A$ are pairwise inequivalent.
	Therefore, the set $B$ of states of $\M$ that can be reached by sequences from $A$ contains $|A|$ elements. Also, since $\epsilon \in A$ we know that $q_0^{\M} \in B$.
	Let $q$ be a state of $\M$.
	Since we only consider Mealy machines that are initially connected, there exists a sequence of inputs $\sigma$ that reaches $q$.  Now pick $\sigma$ in such a way that the number of states outside $B$ visited by $\sigma$ is minimal. Observe that each state outside $B$ is visited at most once by $\sigma$ (otherwise there would be a loop and the number of visited states outside $B$ would not be minimal).
	Since $\M$ has at most $m$ states and $B$ contains $|A|$ states, this means that $\sigma$ visits at most $k$ states outside $B$.
	Since at least one state in $B$ is visited (namely $q_0^{\M}$), this means that $q$ can be reached with a sequence $\rho \in I^{\leq k}$ from a state in $B$.
	This implies that $\M \in \U_k^A$, as required.
\end{proofappendix}

\paragraph*{Bisimulations}
In the proof of our completeness result, we use the concept of bisimulation relations and the well-known fact that for (deterministic) Mealy machines bisimulation equivalence coincides with the equivalence $\approx$ defined above.

\begin{definition}[Bisimulation]
	\label{def bisimulation MM}
	A \emph{bisimulation} between Mealy machines $\M$ and $\N$ is a relation $R
	\subseteq Q^{\M} \times Q^{\N}$ satisfying, for all $q \in Q^{\M}$, $r \in Q^{\N}$, and $i \in I$,
	\begin{enumerate}
		\item
		$q^{\M}_0 \; R \; q^{\N}_0$,
		\item 
		$q \mathrel{R} r$ implies $\delta^{\M}(q, i) \converges ~ \Leftrightarrow ~ \delta^{\N}(r, i) \converges$,
		\item
		$q \mathrel{R} r \wedge \delta^{\M}(q,i) \converges$ implies
		$\delta^{\M}(q,i) \mathrel{R} \delta^{\N}(r, i)$ and
		$\lambda^{\M}(q,i) = \lambda^{\N}(r, i)$.
	\end{enumerate}
	We write $\M \simeq \N$ if there exists a bisimulation relation between $\M$ and $\N$.
\end{definition}

