\begin{lemma}
	\label{candidate set}
	Suppose $\Obs$ is an observation tree for $\M$ with $f \colon \Obs \to \M$ and basis $B$ such that $| B | = | Q^{\M} |$. Let $q$ be a state of $\Obs$.
	Then there exists a state $r \in B$ with $r \in C(q)$ and $f(q)=f(r)$.
\end{lemma}
\begin{proof}
	Let $f(q) = u$.
	By Lemma~\ref{obs tree minimal state cover}, $f$ restricted to $B$ is a bijection.
	Let $r \in B$ be the unique state with $f(r) = u$.
	Since $f(q) = f(r)$, Lemma~\ref{la: apartness refinement} implies that $q$ and $r$ are not apart.
	Hence $r \in C(q)$.
\end{proof}

\begin{proofappendix}{La:basis}
	Assume that $\M$ is a Mealy machine that passes $T$.
	By Lemma~\ref{observation tree when test suite passes}, $\Obs$ is an observation tree for $\M$.
	Let $f : \Obs \to \M$.
	Suppose $\sigma, \rho \in A$ with $\sigma \neq \rho$.
	Since $A = \mathsf{access}(B)$,
	$q = \delta^{\Obs}(q_0^{\Obs}, \sigma) \in B$ and $p = \delta^{\Obs}(q_0^{\Obs}, \rho) \in B$.
	Since $\Obs$ is a tree, $p \neq q$ and thus, as $B$ is a basis for $\Obs$, $q \apart p$.
	By Lemma~\ref{la: apartness refinement}, $f(q) \apart f(p)$.
	By Lemma~\ref{la:refinement lifted to sigma}, $f(q) = \delta^{\M}(q_0^{\M}, \sigma)$ and $f(p) = \delta^{\M}(q_0^{\M}, \rho)$. From this  we infer
	$\delta^{\M}(q_0^{\M}, \sigma) \not\approx \delta^{\M}(q_0^{\M}, \rho)$.
	This implies that distinct sequences from $A$ may never reach equivalent states in $\M$, and
	thus $\M \not\in \U^A$.
	Hence there are no Mealy machines in $\U^A$ that pass $T$, and we conclude that $T$ is $\U^A$-complete.
\end{proofappendix}

\begin{proofappendix}{k-A-complete}
	Let $f : \Obs \to \Spec$ and $g : \Obs \to \M$.  Define relation $R \subseteq Q^{\Spec} \times Q^{\M}$ by
	\begin{eqnarray*}
		(s, q) \in R & ~~ \Leftrightarrow ~~ &  [\exists t \in B \cup  F^{<k} : f(t) = s \wedge  g(t) = q].
	\end{eqnarray*}
	We claim that $R$ is a bisimulation between $\Spec$ and $\M$, as defined in Definition~\ref{def bisimulation MM}.
	\begin{enumerate}
		\item 
		Since $f$ is a functional simulation from $\Obs$ to $\Spec$, $f(q^{\Obs}_0) = q^{\Spec}_0$, and
		since $g$ is a functional simulation from $\Obs$ to $\M$, $g(q^{\Obs}_0) = q^{\M}_0$.
		Using $q^{\Obs}_0 \in B$, this implies $(q^{\Spec}_0, q^{\M}_0) \in R$.
		\item 
		Suppose $(s,q) \in R$ and $i \in I$. 
		Since $(s, q) \in R$, there is a $t \in B \cup F^{<k}$ such that $f(t) = s$ and $g(t) = q$.
		Since $B$ and $F^{<k}$ are complete, $\delta^{\Obs}(t,i) \downarrow$.
		Since $f$ and $g$ are functional simulations, also $\delta^{\Spec}(s,i) \downarrow$ and $\delta^{\M}(q,i) \downarrow$.
		Let $s' = \delta^{\Spec}(s,i)$, $q' = \delta^{\M}(q,i)$ and $t'= \delta^{\Obs}(t,i)$.
		Since $f$ and $g$ are functional simulations,
		$\lambda^{\Obs}(t,i) = \lambda^{\Spec}(s,i)$ and $\lambda^{\Obs}(t,i) = \lambda^{\M}(q,i)$.
		This implies $\lambda^{\Spec}(s,i) = \lambda^{\M}(q,i)$, as required. 
		Since $f$ and $g$ are functional simulations, $f(t') = s'$ and $g(t') = q'$.
		In order to prove $(s', q') \in R$, we consider two cases:
		\begin{enumerate}
			\item 
			$t' \in B \cup F^{<k}$.  In this case, since $f(t') = s'$ and $g(t') = q'$, $(s', q') \in R$ follows from the definition of $R$.
			\item 
			$t'\in F^k$. In this case, since we assume $\M \in \U^A_k$, there are sequences $\sigma \in \mathsf{access}(B)$ and $\rho \in I^{\leq k}$ such that $q'$ is reached by $\sigma \rho$.
			By the assumption that $B$ and $F^{<k}$ are complete, $t'' = \delta^{\Obs}(q_0^{\Obs}, \sigma\rho)$ is defined.
			By Lemma~\ref{la:refinement lifted to sigma}, $g(t'') = q'$.  
			Then, by Lemma~\ref{la: apartness refinement}, $t'$ and $t''$ are not apart.
			We claim that $t'$ and $t''$ have the same candidate set:  
			\begin{enumerate}
				\item 
				$t'' \in B$.   By definition of basis $B$, $C(t'') = \{ t'' \}$.
				Since not $t' \apart t''$ and $t'$ is identified, $C(t') = \{ t'' \}$.
				Hence $C(t'') = C(t')$.
				\item 
				$t'' \in F^{<k}$. Then by condition (\ref{cotransitivity requirement FV}) and since not $t' \apart t''$, $C(t'') = C(t')$.
			\end{enumerate}
			Since $t'$ is identified, $C(t') = \{ r \}$, for some $r \in B$.
			By Lemma~\ref{candidate set}, $f(t')=f(r)$.
			Since $C(t'') = C(t')$, also $C(t'') = \{ r \}$. Applying Lemma~\ref{candidate set} again gives
			$f(t'') = f(r)$. Hence $f(t'') = f(t') = s'$. This in turn implies $(s', q') \in R$, which completes the proof that $R$ is bisimulation.
		\end{enumerate}
	\end{enumerate}
	The theorem now follows by application of Lemma~\ref{la:bisimulation}.
\end{proofappendix}

\begin{proofappendix}{Cy:k-A-complete}
	Let $\M$ be a Mealy machine in $\U_k^A$.
	%Since $T$ is a test suite for $\Spec$, clearly $\M$ will pass $T$ if $\M \approx \Spec$.
	Assume that $\M$ passes $T$.
	By Lemma~\ref{observation tree when test suite passes}, $\Obs$ is an observation tree for both $\M$ and $\Spec$.
	Now Theorem~\ref{k-A-complete} implies $\M \approx \Spec$, and thus $T$ is $\U_k^A$-complete.
	By Lemma~\ref{La:basis}, $T$ is also $\U^A$-complete.
