\begin{proofappendix}{full frontier identified}
	Proof by contradiction.
	Assume that some state $q \in F^{<k}$ is not identified.
	Then there are distinct states $r, s \in B$ such that $\{ r, s \} \subseteq C(q)$.
	By definition of a basis, states $r$ and $s$ are apart.
	Let $\sigma$ witness the apartness of $r$ and $s$.
	Using that $F^{<k}$ is complete, we rerun $\sigma$ from state $q$ until we reach $F^k$.
	If $\delta^{\Obs}(q, \sigma) \in F^{\leq k}$, then by the
	weak co-transitivity Lemma~\ref{la: weak co-transitivity}, $q$ is apart from $r$ or from $s$, and we have a contradiction.
	Otherwise, let $\rho$ be the proper prefix of $\sigma$ with $\delta^{\Obs}(q, \rho) \in F^k$.
	If $\rho \vdash r \apart s$ then, by Lemma~\ref{la: weak co-transitivity}, $q$ is either apart from $r$ or from $s$, and we have a contradiction.
	So we may assume $\rho \not\vdash r \apart s$.
	Let $\delta^{\Obs}(q, \rho) = q'$, $\delta^{\Obs}(r, \rho) = r'$ and $\delta^{\Obs}(s, \rho) = s'$.
	Since $\sigma \vdash r \apart s$ but $\rho \not\vdash r \apart s$, we conclude $r'\apart s'$.
	Observe that both $r'$ and $s'$ are contained in $B \cup F^{<k}$.
	If both $r'$ and $s'$ are in $B$ then, since $q'$ is identified, $q'$ is apart from $r'$ or from $s'$.
	If $q' \apart r'$ then $q \apart r$ and we have a contradiction.
	If $q' \apart s'$ then $q \apart s$ and we have a contradiction.
	Otherwise, w.l.o.g., assume $r'\in F^{<k}$.
	Then, by condition (\ref{cotransitivity requirement FV}),
	$C(q') = C(r')$ or $q'\apart r'$.
	If $q' \apart r'$ then $q \apart r$ and we have a contradiction.
	So we conclude $C(q') = C(r')$.
	Since $q'$ is identified $C(q') = \{ t \}$, for some $t \in B$.
	If $s'\in B$ then, since $C(r') = \{ t \}$, $s'\neq t$ because otherwise $r'$ and $s'$ are not apart.
	This implies $q' \apart s'$, which implies $q \apart s$, which is a contradiction.
	If $s'\in F^{<k}$ then, by condition (\ref{cotransitivity requirement FV}),
	$C(q') = C(s')$ or $q'\apart s'$.
	If $q' \apart s'$ then $q \apart s$ and we have a contradiction.
	So we conclude $C(q') = C(s') = \{ t \}$.
	Let $f \colon \Obs \to \Spec$.
	By Lemma~\ref{candidate set}, $f(r') = f(t) = f(s')$.
	But since $r'\apart s'$, Lemma~\ref{la: apartness refinement} gives $f(r') \neq f(s')$.
	Contradiction.	
\end{proofappendix}

\begin{proofappendix}{variant condition}
	Note that, by the previous Proposition~\ref{full frontier identified}, all states in $F^{\leq k}$ are identified.
	Assume $i$ and $j$ are indices with $0 \leq i < j \leq k$, $q \in F^i$, $r \in F^j$ and $C(q) \neq C(r)$.  It suffices to prove that $q \apart r$.
	Let $f \colon \Obs \to \Spec$.
	Since both $q$ and $r$ are identified and $C(q) \neq C(r)$, it follows by Lemma~\ref{candidate set} and Lemma~\ref{la: apartness refinement} that $f(q) \apart f(r)$.
	Let $\sigma$ be a separating sequence for $f(q)$ and $f(r)$.
	If $\sigma \vdash q \apart r$, we are done.  Otherwise, since  $F^{<k}$ is complete, there is a prefix $\rho$ of $\sigma$ with $\delta^{\Obs}(r, \rho) \in F^k$.
	Let $q' \in F^{<k}$ and $r'\in F^k$ be the unique states such that $q \xrightarrow{\rho} q'$ and
	$r \xrightarrow{\rho} r'$.
	If $\rho \vdash q \apart r$, we are done.
	Otherwise, we conclude $f(q') \apart f(r')$.
	By Lemma~\ref{candidate set} and since both $q'$ and $r'$ are identified, we conclude $C(q') \neq C(r')$.
	Therefore, by condition (\ref{cotransitivity requirement FV}), $q' \apart r'$.
	Let $\tau$ be a witness for the apartness of $q'$ and $r'$.
	Then $\rho \tau$ is a witness for the apartness of $q$ and $r$.
	Thus $q \apart r$, as required.	
\end{proofappendix}

\begin{proofappendix}{candidate set cotransitivity}
	%$\mbox{ }$
	\begin{itemize}
		\item 
		``$\Rightarrow$''
		Assume $C(q) = C(r) \vee q \apart r$.
		Suppose $s \in B$ with $s \apart q$.  We need to show $s \apart r \vee q \apart r$.
		By our assumption, if $q \apart r$ then we are done.
		So suppose $C(q) = C(r)$. Then, since $s \apart q$, $s \not\in C(q)$.  Therefore $s \not\in C(r)$, which implies $s \apart r$, as required.
		\item 
		``$\Leftarrow$''
		Assume $\forall s \in B : s \apart q \; \Rightarrow \; s \apart r \vee q \apart r$.
		Suppose not $q \apart r$.  We need to show $C(q) = C(r)$.
		Because $q$ is identified, all basis states except one are apart from $q$.
		Let $q'$ be the unique basis state that is not apart from $q$.
		By our assumption, $r$ is apart from all states in $B \setminus \{ q'\}$.
		Thus $C(r) \subseteq \{ q'\}$.
		By Lemma~\ref{candidate set}, $C(r)$ contains at least one state.
		Therefore, we conclude that $C(r) = \{ q'\}$.
		This implies $C(q)=C(r)$, as required.
	\end{itemize}	
\end{proofappendix}

\begin{proofappendix}{correctness apartness algorithm}
	Correctness follows since two states $q$ and $q'$ are apart if and only if either (1) 
	both have an outgoing transition for the same input but with a different output, or (2) 
	both have an outgoing transition for the same input, leading to states $r$ and $r'$, respectively, such that $r$ and $r'$ are apart.
	This is exactly what the algorithm checks.

	Function {\sc ApartnessCheck} is called exactly once for each pair of states $(q,q')$.
	The overall complexity of the algorithm is $\Theta(N^2)$, because $\Obs$ has $N-1$ transitions, and each pair of transitions $(q, r)$ and $(q', r')$ is considered at most once by the algorithm
	(during execution of {\sc ApartnessCheck}$(q, q')$). The amount of work for each pair of transitions
	$(q, r)$ and $(q', r')$ is constant.
\end{proofappendix}

\begin{proofappendix}{completeness Wp}
	Since $\Spec$ is complete, $T$ is a test suite for $\Spec$.
	Let $\Obs = \mathsf{Tree}(\Spec, T)$ and $f : \Obs \to \Spec$.
	Let $B$ be the subset of states of $\Obs$ reached via an access sequence in $A$, and
	let $F^0, F^1,\ldots$ be the stratification induced by $B$.
	We check that the assumptions of Corollary~\ref{Cy:k-A-complete} hold:
	\begin{enumerate}
		\item 
		$B$ is a basis: 
		Since $A$ is a state cover for $\Spec$, it is prefix-closed. Hence, set $B$ is ancestor-closed.
		Suppose $q$ and $q'$ are two distinct states in $B$.
		We show that $q \apart q'$.
		Let $\sigma$ and $\sigma'$ be the access sequences of $q$ and $q'$, respectively.
		Then $\sigma \neq \sigma'$.
		Let $r = \delta^{\Spec}(q_0^{\Spec}, \sigma)$ and  $r' = \delta^{\Spec}(q_0^{\Spec}, \sigma')$.
		By Lemma~\ref{la:refinement lifted to sigma}, $f(q)=r$ and $f(q') = r'$.
		Since $A$ is a minimal state cover, $r \neq r'$, and since $\Spec$ is minimal, $r \not\approx r'$.
		Set $\bigcup {\cal W}$ contains a separating sequence $\rho$ for $r$ and $r'$.
		Since $A \cdot \bigcup {\cal W} \subseteq T$, $\delta^{\Obs}(q, \rho) \downarrow$ and $\delta^{\Obs}(q', \rho) \downarrow$.
		By Lemma~\ref{la:refinement lifted to sigma},
		$\lambda^{\Obs}(q, \rho) = \lambda^{\Spec}(r,\rho) \neq \lambda^{\Spec}(r',\rho) = \lambda^{\Obs}(q', \rho)$.
		Thus $\rho \vdash q \apart q'$, as required.
		\item
		Since $A \subseteq T$, $|A| = |B|$, and since $A$ is a minimal state cover, $|A| = | Q^{\Spec} |$.
		Hence $|B| = | Q^{\Spec} |$.
		\item 
		By construction, $A = \mathsf{access}(B)$.
		\item
		Since $A \cdot I^{\leq k+1} \subseteq T$, sets $B$ and $F^{<k}$ are complete.
		\item 
		All states in $F^k$ are identified:
		We show a stronger statement, namely that all states in $F^{\leq k}$ are identified.
		Suppose $r \in F^{\leq k}$.
		Let $\mathsf{access}(r) = \sigma$ and $s = \delta^{\Spec}(q_0^{\Spec}, \sigma)$.
		By Lemma~\ref{la:refinement lifted to sigma}, $f(r) = s$.
		By Lemma~\ref{obs tree minimal state cover}, $f$ restricted to $B$ is a bijection. Let $q \in B$ be the unique state with $f(q)=s$.
		Now suppose $q' \in B$ is distinct from $q$. Let $f(q') = s'$.
		By definition of a state identifier, $W_s$ contains a separating sequence $\rho$ for $s$ and $s'$.
		Since $A \cdot I^{\leq k+1} \odot {\cal W} \subseteq T$, $\delta^{\Obs}(r, \rho) \downarrow$.
		Since $ A \cdot \bigcup {\cal W} \subseteq T$,  $\delta^{\Obs}(q', \rho) \downarrow$.
		By Lemma~\ref{la:refinement lifted to sigma},
		\[
		\lambda^{\Obs}(q', \rho) = \lambda^{\Spec}(s',\rho) \neq \lambda^{\Spec}(s,\rho) = \lambda^{\Obs}(r, \rho).
		\]
		Thus $\rho \vdash r \apart q'$.
		Since $q'$ was chosen to be an arbitrary basis state different from $q$, this implies that $r$ is identified.
		\item 
		Condition (\ref{cotransitivity requirement FV}) holds:
		Suppose $q \in F^k$ and $r \in F^{<k}$.
		By the previous item, both $q$ and $r$ are identified, that is, there exist $q', r' \in B$ such that $C(q) = \{ q' \}$ and $C(r) = \{r'\}$.
		If $q'= r'$ then $C(q)=C(r)$ and we are done.  So assume $q'\neq r'$.
		Let $s = f(q')$ and $t = f(r')$. 
		By Lemma~\ref{candidate set}, $f(q) = s$ and $f(r)=t$.
		Since $f$ restricted to $B$ is a bijection, $s \neq t$,
		and since $\Spec$ is minimal, $s \not\approx t$.
		By definition of a state identifier, $W_s$ contains a separating sequence $\rho$ for $s$ and $t$.
		Since $A \cdot I^{\leq k+1} \odot {\cal W} \subseteq T$, $\delta^{\Obs}(q, \rho) \downarrow$.
		Since $A \cdot I^{\leq k} \cdot \bigcup {\cal W} \subseteq T$, $\delta^{\Obs}(r, \rho) \downarrow$.
		By Lemma~\ref{la:refinement lifted to sigma},
		$\lambda^{\Obs}(q, \rho) = \lambda^{\Spec}(s,\rho) \neq \lambda^{\Spec}(t,\rho) = \lambda^{\Obs}(r, \rho)$.
		Thus $\rho \vdash r \apart q$.
	\end{enumerate} 
	Since all conditions of Corollary~\ref{Cy:k-A-complete} hold, we conclude that $T$ is $k$-$A$-complete.
\end{proofappendix}

\begin{proofappendix}{completeness HSI}
	Since $\Spec$ is complete, $T$ is a test suite for $\Spec$.
	Let $\Obs = \mathsf{Tree}(\Spec, T)$ and $f : \Obs \to \Spec$.
	Let $B$ be the subset of states of $\Obs$ reached via an access sequence in $A$, and
	let $F^0, F^1,\ldots$ be the stratification induced by $B$.
	We check that the assumptions of Corollary~\ref{Cy:k-A-complete} hold:
	\begin{enumerate}
		\item 
		$B$ is a basis: 
