\begin{proofappendix}{k-complete}
	Let $\M$ be a Mealy machine with at most $m$ states that passes suite $T$.
	In order to prove that $T$ is $m$-complete, it suffices to prove that $\M \approx \Spec$.
	Let $f : \Obs \to \Spec$ and $g : \Obs \to \M$.  Define relation $R \subseteq Q^{\Spec} \times Q^{\M}$ by
	\begin{eqnarray*}
		(s, q) \in R & \Leftrightarrow & \exists t \in B \cup  F^{<k} : f(t) = s \wedge  g(t) = q.
	\end{eqnarray*}
	We claim that $R$ is a bisimulation between $\Spec$ and $\M$.
	\begin{enumerate}
		\item 
		Since $f$ is a functional simulation from $\Obs$ to $\Spec$, $f(q^{\Obs}_0) = q^{\Spec}_0$, and
		since $g$ is a functional simulation from $\Obs$ to $\M$, $g(q^{\Obs}_0) = q^{\M}_0$.
		Using $q^{\Obs}_0 \in B$, this implies $(q^{\Spec}_0, q^{\M}_0) \in R$.
		\item 
		Suppose $(s,q) \in R$ and $i \in I$. 
		Since $(s, q) \in R$, there exists a $t \in B \cup F^{<k}$ such that $f(t) = s$ and $g(t) = q$.
		W.l.o.g.\  we select $t$ from the lowest possible stratum, that is, if $t \in F^i$ then there is no $\overline{t} \in B \cup F^{<i}$ with $f(\overline{t}) = s$ and $g(\overline{t}) = q$.
		Since $B$ and $F^{<k}$ are complete, $\delta^{\Obs}(t,i) \downarrow$.
		Since $f$ and $g$ are functional simulations, also $\delta^{\Spec}(s,i) \downarrow$ and $\delta^{\M}(q,i) \downarrow$.
		Let $s' = \delta^{\Spec}(s,i)$, $q' = \delta^{\M}(q,i)$ and $t'= \delta^{\Obs}(t,i)$.
		Since $f$ and $g$ are functional simulations,
		$\lambda^{\Obs}(t,i) = \lambda^{\Spec}(s,i)$ and $\lambda^{\Obs}(t,i) = \lambda^{\M}(q,i)$.
		This implies $\lambda^{\Spec}(s,i) = \lambda^{\M}(q,i)$, as required.
		Since $f$ and $g$ are functional simulations, $f(t') = s'$ and $g(t') = q'$.
		In order to prove $(s', q') \in R$, we consider two cases:
		\begin{enumerate}
			\item 
			$t' \in B \cup F^{<k}$.  In this case, since $f(t') = s'$ and $g(t') = q'$, $(s', q') \in R$ follows from the definition of $R$.
			\item 
			$t'\in F^k$.
			Let $W$ be the subset of states in $F^{<k}$ that occur in the access path of $t'$.
			We claim that $g$ is injective on $B \cup W$.
			Then, since $B \cup W$ has $n+k=m$ states, there must be a state $t'' \in B \cup W$ with $g(t'') = g(t')$.
			States $t''$ and $t'$ have the same candidate set (otherwise they would be apart by condition (\ref{cotransitivity requirement IM}) or by the fact that $t'$ has been identified, which would contradict $g(t'') = g(t')$). Then by Lemma~\ref{candidate set}, $f(t'') = f(t')$.
			This in turn implies that $(s', q') \in R$, which completes the proof that $R$ is bisimulation.

			Thus it remains to prove our claim that $g$ is injective on $B \cup W$:
			\begin{enumerate}
				\item 
				By Lemma~\ref{f restricted to B injective}, $g$ is injective on $B$.
				\item
				Let $u \in W$ and let $r \in B$.
				We claim $g(u) \neq g(r)$.	
				We consider two cases:
				\begin{itemize}
					\item 
					$C(u) = \{ r \}$.   Then by Lemma~\ref{candidate set}, $f(u) = f(r)$.
					But then $g(u) \neq g(r)$, because otherwise $t$ would not be in the lowest possible stratum.
					\item 
					$C(u) \neq \{ r\}$.  Then $u \apart r$ and therefore,
					by Lemma~\ref{la: apartness refinement}, $g(u) \neq g(r)$.
				\end{itemize}
				\item
				Let $u, u' \in W$ with $u \neq u'$.
				We claim $g(u) \neq g(u')$.
				By condition (\ref{cotransitivity requirement IM}), $C(u) = C(u')$ or $u\apart u'$.
				\begin{itemize}
					\item 
					If $C(u) = C(u')$, Lemma~\ref{candidate set} gives that $f(u) = f(u')$. 
					But then $g(u) \neq g(u')$, because otherwise $t$ would not be in the lowest possible stratum.
					\item 
					If $u \apart u'$ then $g(u) \neq g(u')$ by Lemma~\ref{la: apartness refinement}. 
				\end{itemize}
			\end{enumerate}
		\end{enumerate}
	\end{enumerate}
	The proposition now follows by application of Lemma~\ref{la:bisimulation}.
\end{proofappendix}








