Also, the spaces satisfy the following inf-sup condition, as proved in  \cite[Eq. (4.17)]{zhang18}.
	\begin{equation}\label{eq:infsup}
		\inf_{\bw_h\in\bV_h,\eeta_h\in\bbK_h} \sup_{\btau_{h} \in \bbS_h} \frac{(\bdiv \btau_h,\bw_h)_{0,\Omega}+(\btau_h,\eeta_h)_{0,\Omega}}{\|\btau_h\|_{\bdiv,\Omega}(\|\bw_h\|_{{0,\Omega}}+\|\eeta_h\|_{{0,\Omega}})}\ge C_I>0.
\end{equation}

\subsection{Semi-discrete formulation and its well-posedness}
The semi-discrete problem reads as follows: starting from the initial datum $(\bsigma_{0,h}(0),\bsigma_{1,h}(0),\bv_h(0), \br_h(0)) \in \bbS_h \times \bbS_h \times \bV_h \times \bbK_h$, find $(\bsigma_{0,h},\bsigma_{1,h},\bv_h,\br_h)\in C^1( [0,{T}],\bbS_h) \times C^1( [0,{T}],\bbS_h) \times C^1( [0,{T}],\bV_h)\times C^1( [0,{T}],\bbK_h)$ such that
\begin{subequations}\label{eq:semi-discrete}
\begin{align}
a_{0,h}(\dot{\bsigma}_{0,h}, \btau_{0,h}) + a_{0,h}'(\bsigma_{0,h}, \btau_{0,h})+ (\bdiv\btau_{0,h},\bv_h)_{0,\Omega} + (\btau_{0,h},\dot\br_h)_{0,\Omega} & = 0 & \forall \btau_{0,h} \in \bbS_h,\\
 a_{1,h}(\dot{\bsigma}_{1,h}, \btau_{1,h})  + (\bdiv\btau_{1,h},\bv_h)_{0,\Omega} + (\btau_{1,h},\dot\br_h)_{0,\Omega} & = 0 & \forall \btau_{1,h} \in \bbS_h,\\
	(\varrho \dot{\bv}_h,\bw_h)_{0,\Omega} - (\bdiv(\bsigma_{0,h}+\bsigma_{1,h}),\bw_h)_{0,\Omega} - (\varrho\ff,\bw_h)_{0,\Omega}& = 0 & \forall \bw_h \in \bV_h,\\
(\dot{\bsigma}_{0,h}+\dot{\bsigma}_{1,h}, \eeta_h)_{0,\Omega} & = 0 & \forall \eeta_h\in\bbK_h,
\end{align}\end{subequations}
where $a_{*,h}(\bsigma_h,\btau_h) = \sum_{K\in \cT_h} a_{*,h}^K(\bsigma_h,\btau_h)$, and
 thanks to the model assumptions adopted in the previous section, the local bilinear forms are defined as
\begin{align*}
a_{*,h}^K({\bsigma_{*,h}},\btau_{*,h}) & : = \frac{1}{2\mu^*}\int_K \bbPi_k^0 \bsigma_{*,h}: \bbPi_k^0 \btau_{*,h} \dx - \frac{\lambda^*}{2\mu^*+d\lambda^*}\int_K \tr(\bbPi_k^0 \bsigma_{*,h}) \, \tr( \bbPi_k^0 \btau_{*,h}) \dx \\
& \qquad +  S_h^K(\bsigma_{*,h} - \bbPi_k^0\bsigma_{*,h}, \btau_{*,h} - \bbPi_k^0\btau_{*,h}),
\end{align*}
where $*$ specifies which compartment of the rheological model and which parameter set the bilinear form is describing, and where $ S_h^K$ is defined as follows:
	$$S_h^K(\bsigma_{*,h},\btau_{*,h})={|K|}\sum_i \chi_i(\bsigma_{*,h})\chi_i(\btau_{*,h}),$$
	where $\chi_i$ are the degree of freedom operators introduced in Section \ref{pbk}. {Let $\boldsymbol{\chi}$ denote the set of all such degrees of freedom. Following the proof of \cite[Theorem 4.5]{chen}, it is straightforward to verify the following norm equivalence relation for any $\btau_h  \in \bbS(K)$:
    \begin{align}\label{newdof}
         C_1 h_K\|\boldsymbol{\chi (\btau_h})\|_{l^2}\leq \|\btau_h\|_{0,K} \leq C_2 h_K\|\boldsymbol{\chi (\btau_h})\|_{l^2},
    \end{align}
    where $C_1$ and $C_2$ are positive constants independent of $h_K$. }

	Clearly, $S_h^K$ is  positive definite and symmetric.{ Moreover, in  view of \eqref{newdof},  $S_h^K$ satisfies  the following scaling property (see also \cite{beirao16})}
\[ \alpha_1 \| \btau_{*,h} - \bbPi_k^0\btau_{*,h} \|^2_{0,K} \leq  S_h^K({\btau_{*,h} - \bbPi_k^0\btau_{*,h}}, \btau_{*,h} - \bbPi_k^0\btau_{*,h}) \leq \alpha_2 \| \btau_{*,h} - \bbPi_k^0\btau_{*,h} \|^2_{0,K} ,\]
with $\alpha_1,\alpha_2$ positive constants independent of $h$, of $K$, and of $\lambda^*$.
The bilinear forms $a_{*,h}^K$ thus defined satisfy the following properties:
	\begin{align*}
		a_{*,h}^K(\btau_h,\bsigma_h)&\le C \|\btau_h\|_{0,K}\|\bsigma_h\|_{0,K}& \;\;\;\;\forall \btau_h,\bsigma_h\in{\bbS_h},\\
		a_{*,h}^K(\btau_h,\btau_h)&\geq C \|\btau_h\|_{0,K}^2&\;\;\;\;\forall \btau_h\in{\bbS_h}.
	\end{align*}
%	For our implementation, we chose the degrees of freedom $\chi_i$ such the following  is a valid choice for the stabiliser bilinear form.
%	$$S_h^K(\bsigma_{*,h},\btau_{*,h})=\sum_i \chi_i(\bsigma_{*,h})\chi_i(\btau_{*,h}).$$


The semi-discrete formulation \eqref{eq:semi-discrete} can be expressed as a system of linear ordinary differential equations in time, for which existence and uniqueness results are well established in the literature. Therefore, we do not provide a detailed proof, but instead,  below we offer a brief outline of the argument.



We proceed by writing the {semi-discrete} problem in terms of operators.
	Let $A_*:\bbS_h\to\bbS_h$ be defined by $A_*\bsigma_h=R_{\bbS_h}(a_{*,h}(\bsigma_h,\bullet))$ where $R_{\bbS_h}:\bbS_h'\to\bbS_h$ gives the Riesz-representation of the operand.
	Similarly, we define $H:\bbS_h\to\bbK_h$ as $H\bsigma_h=R_{\bbK_h}(\bsigma_h,\bullet)_{0,\Omega}$, $M:\bV_h\to\bV_h$ as $M \bu_h=\varrho \bu_h$, $J:\bbS_h\to\bV_h$ as $J\bsigma_h=R_{\bV_h}(\bdiv\bsigma_h,\bullet)_{0,\Omega}$ and $F=R_{\bV_h}(\varrho f,\bullet)$.
Finally, let us define the block operators
	\begin{align*}
	\mathscr{A}=\begin{bmatrix}
	A_0 & 0 & 0 & H^* \\
	0 & A_1 & 0 & H^* \\
	0 & 0 & M & 0 \\
	H & H & 0 & 0
	\end{bmatrix}, \qquad
	\mathscr{B}=\begin{bmatrix}
	-A_0' & 0 & -J^* & 0 \\
	0 & 0 & -J^* & 0 \\
	J & J & 0 & 0 \\
	0 & 0 & 0 & 0
	\end{bmatrix}, \qquad
	\mathscr{C}=\begin{bmatrix}
	0 \\ 0 \\ F \\ 0
	\end{bmatrix}.
	\end{align*}
With this, it readily follows that system \eqref{eq:semi-discrete} reads
	\begin{equation}\label{dgt}
		\mathscr{A}\dot{\vec{x}}_h=\mathscr{B}\vec{x}_h+\mathscr{C}, \qquad  \text{with} \quad \vec{x}_h=(\bsigma_{0,h},\bsigma_{1,h},\bv_h,\br_h)^{\tt t}.
	\end{equation}

