On the other hand, we also prove the following stability result.
\begin{theorem}
	The solution of the semi-discrete system \eqref{eq:semi-discrete} satisfies the following estimate 
	\begin{align*}
		& \max_{s\in[0,T]}(\|\bsigma_{0,h}(s)\|_{{0,\Omega}}+\|\bsigma_{1,h}(s)\|_{{0,\Omega}}+\|\bv_h(s)\|_{{0,\Omega}}) \\
		&\qquad  \lesssim \|\bsigma_{0,h}(0)\|_{{0,\Omega}}+\|\bsigma_{1,h}(0)\|_{{0,\Omega}}+\|\bv_h(0)\|_{{0,\Omega}} + \int_0^T \|\ff(s)\|_{{0,\Omega}} \ds.
	\end{align*}
%$$\|\bv_h-\bv\|+\|\br_h-\br\|+\|{\bsigma}_{0,h}-\bsigma_0\|+\|{\bsigma}_{1,h}-\bsigma_1\|\le Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{1,1}(0,{T};W^{k+1,2}(\Omega))}.$$
\end{theorem}
\begin{proof}
	Substituting $\btau_{0,h}=\bsigma_{0,h}$, $\btau_{1,h}=\bsigma_{1,h}$, $\bw_{h}=\bv_{h}$ and {$\eeta_{h}=\br_{h}$} in the first three equations of \eqref{eq:semi-discrete} and adding them all, we get the following.
	$$
	\frac{1}{2}\frac{\text{d}}{\text{d}t}(a_{0,h}(\bsigma_{0,h},\bsigma_{0,h})+a_{1,h}(\bsigma_{1,h},\bsigma_{1,h})+(\varrho \bv_h,\bv_h))
	+a_{0,h}'(\bsigma_{0,h},\bsigma_{0,h})=(\varrho \ff,\bv_h)-(\bsigma_{0,h}+\bsigma_{1,h},\dot\br_h).
	$$
	The term $(\bsigma_{0,h}+\bsigma_{1,h},\dot\br_h)$ is zero owing to both $(\bsigma_{0,h}(0)+\bsigma_{1,h}(0),\eeta_h)$ and $(\dot\bsigma_{0,h}+\dot\bsigma_{1,h},\eeta_h)$ being zero for all $\eeta_h\in\bbK_h$. Thus, we are left with the following relation
	\begin{equation}\label{eq:gtks}
	\frac{1}{2}\frac{\text{d}}{\text{d}t}(a_{0,h}(\bsigma_{0,h},\bsigma_{0,h})+a_{1,h}(\bsigma_{1,h},\bsigma_{1,h})+(\varrho \bv_h,\bv_h))
+a_{0,h}'(\bsigma_{0,h},\bsigma_{0,h})=(\varrho \ff,\bv_h).
	\end{equation}
Next we apply the {coercivity} of the bilinear forms and Cauchy--Schwarz's inequality to get the following bound
	\begin{equation}\label{eq:stnq}
	\frac{\text{d}}{\text{d}t}\left(\|\bsigma_{0,h}\|_{{0,\Omega}}^2+\|\bsigma_{1,h}\|_{{0,\Omega}}^2+\|\bv_h\|_{{0,\Omega}}^2\right) +\|\bsigma_{0,h}\|_{{0,\Omega}}^2\le C \|\ff\|_{{0,\Omega}}\|\bv_h\|_{{0,\Omega}}.
	%\le C \frac{1}{2}\|\ff\|^2+\frac{1}{2}\|\bv_h\|^2.
	\end{equation}
Then, discarding the positive term $\|\bsigma_{0,h}\|_{{0,\Omega}}^2$ and integrating in time from $0$ to $t$ for $t<T$, we readily get the estimate
	\begin{align*}
		& \|\bsigma_{0,h}(t)\|_{{0,\Omega}}^2+\|\bsigma_{1,h}(t)\|_{{0,\Omega}}^2+\|\bv_h(t)\|_{{0,\Omega}}^2 \\
		& \le  \|\bsigma_{0,h}(0)\|_{{0,\Omega}}^2+\|\bsigma_{1,h}(0)\|_{{0,\Omega}}^2+\|\bv_h(0)\|_{{0,\Omega}}^2 + C \int_0^t \|\ff(s)\|_{{0,\Omega}}\|\bv_h(s)\|_{{0,\Omega}} \ds.
	\end{align*}
Further, using  standard inequalities, it is possible to obtain
	\begin{align*}
		& (\|\bsigma_{0,h}(t)\|_{{0,\Omega}}+\|\bsigma_{1,h}(t)\|_{{0,\Omega}}+\|\bv_h(t)\|_{{0,\Omega}})^2 \\
		& \le C \left((\|\bsigma_{0,h}(0)\|_{{0,\Omega}}+\|\bsigma_{1,h}(0)\|_{{0,\Omega}}+\|\bv_h(0)\|_{{0,\Omega}})^2 + \int_0^T \|\ff(s)\|_{{0,\Omega}}\|\bv_h(s)\|_{{0,\Omega}} \text{d}s\right) \\
		& \le C \left((\|\bsigma_{0,h}(0)\|_{{0,\Omega}}+\|\bsigma_{1,h}(0)\|_{{0,\Omega}}+\|\bv_h(0)\|_{{0,\Omega}})^2 + \max_{s\in[0,T]}\|\bv_h(s)\|_{{0,\Omega}}\int_0^T \|\ff(s)\|_{{0,\Omega}} \text{d}s\right) \\
		& \le C \bigl((\|\bsigma_{0,h}(0)\|_{{0,\Omega}}+\|\bsigma_{1,h}(0)\|_{{0,\Omega}}+\|\bv_h(0)\|_{{0,\Omega}})^2 \\
		&\qquad + \max_{s\in[0,T]}(\|\bsigma_{0,h}(s)\|_{{0,\Omega}}+\|\bsigma_{1,h}(s)\|_{{0,\Omega}}+\|\bv_h(s)\|_{{0,\Omega}})\int_0^T \|\ff(s)\|_{{0,\Omega}} \text{d}s\bigr).
	\end{align*}
And finally, dividing both sides by $\max_{s\in[0,T]}(\|\bsigma_{0,h}(s)\|_{{0,\Omega}}+\|\bsigma_{1,h}(s)\|_{{0,\Omega}}+\|\bv_h(s)\|_{{0,\Omega}})$, we end up with
	\begin{align*}
		& \max_{s\in[0,T]}(\|\bsigma_{0,h}(s)\|_{{0,\Omega}}+\|\bsigma_{1,h}(s)\|_{{0,\Omega}}+\|\bv_h(s)\|_{{0,\Omega}}) \\
		& \le C \biggl(\|\bsigma_{0,h}(0)\|_{{0,\Omega}}+\|\bsigma_{1,h}(0)\|_{{0,\Omega}}+\|\bv_h(0)\|_{{0,\Omega}} + \int_0^T \|\ff(s)\|_{{0,\Omega}} \text{d}s\biggr),
	\end{align*}
	which finishes the proof. 
\end{proof}

\begin{remark} Equation \eqref{eq:gtks} shows the dissipation of the total energy consisting of the kinetic and elastic potential energy for the viscoelastic material. Specifically, when the load term is zero, it shows that the energy decays to zero with time. \end{remark}

