\section{Error analysis}\label{sec:error}
In this section we aim at the derivation of optimal  {\it a priori} error estimates for the solutions of the semi-discrete problem \eqref{eq:semi-discrete} in their natural norms.

	To that end,  we first define a weakly symmetric elliptic projection operator $\widetilde{\Pi}:\bbS\times\bbS\times\bV\times\bbK \to \bbS_h\times\bbS_h\times\bV_h\times\bbK_h$ which maps $(\bsigma_{0},\bsigma_{1},\bu,\br)$ to $(\bsigma_{0,\pi},\bsigma_{1,\pi},\bu_\pi,\br_\pi)$ where the latter is the solution of the following equations
%TODO:remove dots from last equation of projection and elsewhere, probably only afterwards.
\begin{subequations}\label{eq:projection}
\begin{align}
({\bsigma}_{0,\pi}-\bsigma_0,\btau_{0,h})_{0,\Omega} + (\bdiv\btau_{0,h},\bu_\pi-\bu)_{0,\Omega} + (\btau_{0,h},\br_\pi-\br)_{0,\Omega} & = 0 & \forall \btau_{0,h} \in \bbS_h,\\
({\bsigma}_{1,\pi}-\bsigma_1,\btau_{1,h})_{0,\Omega} + (\bdiv\btau_{1,h},\bu_\pi-\bu)_{0,\Omega} + (\btau_{1,h},\br_\pi-\br)_{0,\Omega} & = 0 & \forall \btau_{1,h} \in \bbS_h,\\
(\bdiv(\bsigma_{0,\pi}+\bsigma_{1,\pi}-\bsigma_0-\bsigma_1),\bw_h)_{0,\Omega} & = 0 & \forall \bw_h \in \bV_h,\\
({\bsigma}_{0,\pi}+{\bsigma}_{1,\pi}-{\bsigma}_0-{\bsigma}_1, \eeta_h)_{0,\Omega} & = 0 & \forall \eeta_h\in\bbK_h.
\end{align}
\end{subequations}
The operator $\widetilde{\Pi}$ is well-defined due to the following lemma.

\begin{lemma}
	The problem \eqref{eq:projection} is well posed.
\end{lemma}
\begin{proof}
	We want to show that given any $(\bsigma_{0},\bsigma_{1},\bu,\br) \in \bbS\times\bbS\times\bV\times\bbK$, there exists a unique solution to \eqref{eq:projection}. As $\bbS_h\times\bbS_h\times\bV_h\times\bbK_h$ is finite dimensional, the square system of linear equations has a unique solution if
the following system of equations possesses only the zero solution.
\begin{align*}
({\bsigma}_{0,\pi}, \btau_{0,h})_{0,\Omega}+ (\bdiv\btau_{0,h},\bu_\pi)_{0,\Omega} + (\btau_{0,h},\br_\pi)_{0,\Omega} & = 0 & \forall \btau_{0,h} \in \bbS_h,\\
({\bsigma}_{1,\pi}, \btau_{1,h})_{0,\Omega}+ (\bdiv\btau_{1,h},\bu_\pi)_{0,\Omega} + (\btau_{1,h},\br_\pi)_{0,\Omega} & = 0 & \forall \btau_{1,h} \in \bbS_h,\\
	(\bdiv(\bsigma_{0,\pi}+\bsigma_{1,\pi}),\bw_h)_{0,\Omega} & = 0 & \forall \bw_h \in \bV_h,\\
	({\bsigma}_{0,\pi}+{\bsigma}_{1,\pi}, \eeta_h)_{0,\Omega} & = 0 & \forall \eeta_h\in\bbK_h.
\end{align*}
	Substituting  $ \btau_{1,h}=\btau_{0,h}$ in the second equation and then taking the difference of the first two equations, we get that $({\bsigma}_{0,\pi}-\bsigma_{1,\pi}, \btau_{0,h})_{0,\Omega}=0 \;\;\forall \btau_{0,h} \in \bbS_h$, implying that $\bsigma_{0,\pi}=\bsigma_{1,\pi}$.
	Now, substituting $\bsigma_{1,\pi}$ by $\bsigma_{0,\pi}$ in the equations and dividing by two, we get the following system of equations.
\begin{align*}
({\bsigma}_{0,\pi}, \btau_{0,h})_{0,\Omega}+ (\bdiv\btau_{0,h},\bu_\pi)_{0,\Omega} + (\btau_{0,h},\br_\pi)_{0,\Omega} & = 0 & \forall \btau_{0,h} \in \bbS_h,\\
	(\bdiv(\bsigma_{0,\pi}),\bw_h)_{0,\Omega} & = 0 & \forall \bw_h \in \bV_h,\\
	({\bsigma}_{0,\pi}, \eeta_h)_{0,\Omega} & = 0 & \forall \eeta_h\in\bbK_h.
\end{align*}
	This is a well-posed system by \cite[Theorem 4.1]{zhang18}, hence, the kernel of the above system is zero.
\end{proof}

Next, we establish the projection error estimates, which will be used to prove the optimal error estimates between the exact solution and the solution of the semi-discrete problem \eqref{eq:semi-discrete}.
\begin{lemma}
	\label{ppel}
	Let $(\bsigma_{0},\bsigma_{1},\bu,\br) \in \amsmathbb{W}^{k+1,2}(\Omega) \times\amsmathbb{W}^{k+1,2}(\Omega)\times \mathbf{W}^{k+1,2}(\Omega)\times \amsmathbb{W}^{k+1,2}(\Omega)  $  and its projection be $(\bsigma_{0,\pi},\bsigma_{1,\pi},\bu_\pi,\br_\pi)=\widetilde{\Pi}(\bsigma_{0},\bsigma_{1},\bu,\br)$. Then, there exists $C>0$ independent of $h$ such that
	$$\|\bu_\pi-\bu\|_{{0,\Omega}}+\|\br_\pi-\br\|_{{0,\Omega}}+\|{\bsigma}_{0,\pi}-\bsigma_0\|+\|{\bsigma}_{1,\pi}-\bsigma_1\|\le Ch^{k+1}\|\bsigma_0,\bsigma_1,\bu,\br\|_{W^{k+1,2}(\Omega)}.$$
\end{lemma}
\begin{proof}
	Taking $\btau_{0,h}=\btau_{1,h}=\btau_h$ in the first and second equations of \eqref{eq:projection}, adding them, and defining $\bsigma=\frac{1}{2}(\bsigma_0+\bsigma_1)$ and $\bsigma_\pi=\frac{1}{2}(\bsigma_{0,\pi}+\bsigma_{1,\pi})$, we get the following system
%\begin{subequations}\label{eq:les}
\begin{align*}
({\bsigma}_{\pi}-\bsigma,\btau_{h})_{0,\Omega} + (\bdiv\btau_{h},\bu_\pi-\bu)_{0,\Omega} + (\btau_{h},\br_\pi-\br)_{0,\Omega} & = 0 & \forall \btau_{h} \in \bbS_h,\\
	(\bdiv(\bsigma_{\pi}-\bsigma),\bw_h)_{0,\Omega} & = 0 & \forall \bw_h \in \bV_h,\\
	({\bsigma}_{\pi}-{\bsigma}, \eeta_h)_{0,\Omega} & = 0 & \forall \eeta_h\in\bbK_h,
\end{align*}
%\end{subequations}
	which clearly satisfies the conditions to apply \cite[Lemma A.1]{zhang19}, whence we get
	\begin{equation}\label{eq:ppe} \|\bu_\pi-\bu\|_{{0,\Omega}}+\|\br_\pi-\br\|_{{0,\Omega}}\le Ch^{k+1}\|\bsigma_0.\bsigma_1,\bu,\br\|_{k+1}.\end{equation}
	In order to bound $\|{\bsigma}_{i,\pi}-\bsigma_i\|$ for $i=0,1$, we use the triangle inequality $\|{\bsigma}_{i,\pi}-\bsigma_i\|\le\|{\bsigma}_{i,\pi}-\bbPi_k^i\bsigma_i\|+\|\bbPi_k^i\bsigma_i-\bsigma_i\|$.
	Norm of each row of $(\bbPi_k^i\bsigma_i-\bsigma_i)$  is bounded by the $\bH^1$-norm of that row according to \cite[Section 3.2]{beirao16}.
	Thus, we have \begin{equation}\label{eq:sie} \|\bbPi_k^i\bsigma_i-\bsigma_i\|\le Ch^{k+1}\|\bsigma_i\|_{{k+1,\Omega}}.\end{equation}
	In order to derive suitable bounds on $\|{\bsigma}_{i,\pi}-\bbPi_k^i\bsigma_i\|$, we write the first and second equations of \eqref{eq:projection} as follows
	$$(d_{\bsigma_i}+ \bbPi_k^i\bsigma_i-\bsigma_i,\btau_{i,h})_{0,\Omega} + (\bdiv\btau_{i,h},d_{\bu}+\bPi_k^0\bu-\bu)_{0,\Omega} + (\btau_{i,h},d_\br+\bPi_k^0\br-\br)_{0,\Omega}  = 0 \;\;\; \forall \btau_{i,h} \in \bbS_h,$$
	where $d_{\bsigma_i}={\bsigma}_{i,\pi}-\bbPi_k^i\bsigma_i$, $d_{\bu}=\bu_\pi-\bPi_k^0\bu$, $d_\br=\br_\pi-\bPi_k^0\br$.
	Taking $\btau_{i,h}=d_{\bsigma_i}$ in the above equation and adding for $i=0,1$, we readily obtain
	\begin{align*}
		&	\|d_{\bsigma_0}\|^2+\|d_{\bsigma_1}\|^2+(\bdiv(d_{\bsigma_0}+d_{\bsigma_1}),d_{\bu})_{0,\Omega}+(\bdiv(d_{\bsigma_0}+d_{\bsigma_1}),\bPi_k^0\bu-\bu)_{0,\Omega} \\
		& \qquad \qquad = -(\bbPi_k^i\bsigma_0-\bsigma_0,d_{\bsigma_0})_{0,\Omega}-(\bbPi_k^i\bsigma_1-\bsigma_1,d_{\bsigma_1})_{0,\Omega}-(d_{\bsigma_0}+d_{\bsigma_1},d_\br+\bPi_k^0\br-\br)_{0,\Omega}.
	\end{align*}
	The fourth term on the left-hand side in the equation above is zero by the definition of the polynomial projection and the fact that for $\btau\in\bbS_h$, $\bdiv\btau\in\bV_h$. In addition, the third term can be analysed as follows
	\begin{align*}
	&	(\bdiv(d_{\bsigma_0}+d_{\bsigma_1}),d_{\bu})_{0,\Omega}\\
	&\qquad =(\bdiv(\bsigma_{0,\pi}+\bsigma_{1,\pi}-\bsigma_0-\bsigma_1),d_{\bu})_{0,\Omega}+(\bdiv(\bsigma_{0}+\bsigma_{1}-\bbPi_k^i\bsigma_0-\bbPi_k^i\bsigma_1),d_{\bu})_{0,\Omega}.
	\end{align*}
In turn, the first term of above is zero by the third equation of \eqref{eq:projection}.
 By \eqref{eq:pp}, the second term is equal to $(\bdiv (\bsigma_{0}+\bsigma_{1})-\bPi_k^0 \bdiv (\bsigma_{0}+\bsigma_{1}),d_{\bu})_{0,\Omega}$,
 which is zero by definition of the projection operator, and $d_{\bu}$ being in the projected space. In all, we are left with the following relation
\begin{align*}
&	\|d_{\bsigma_0}\|_{0,\Omega}^2+\|d_{\bsigma_1}\|_{0,\Omega}^2	 = -(\bbPi_k^i\bsigma_0-\bsigma_0,d_{\bsigma_0})_{0,\Omega}-(\bbPi_k^i\bsigma_1-\bsigma_1,d_{\bsigma_1})_{0,\Omega}-(d_{\bsigma_0}+d_{\bsigma_1},d_\br+\bPi_k^0\br-\br)_{0,\Omega} \\
	&\quad  {\le  C \sqrt{\|d_{\bsigma_0}\|_{0,\Omega}^2+\|d_{\bsigma_1}\|_{0,\Omega}^2}\left(\|\bbPi_k^i\bsigma_0-\bsigma_0\|_{0,\Omega}+\|\bbPi_k^i\bsigma_1-\bsigma_1\|_{0,\Omega}+\|d_\br\|_{{0,\Omega}}+\|\bPi_k^0\br-\br\|_{{0,\Omega}}\right)}.
\end{align*}
Thus we have the following estimate
$$ \sqrt{\|d_{\bsigma_0}\|_{0,\Omega}^2+\|d_{\bsigma_1}\|_{0,\Omega}^2}\le C\left(\|\bbPi_k^i\bsigma_0-\bsigma_0\|_{0,\Omega}+\|\bbPi_k^i\bsigma_1-\bsigma_1\|_{0,\Omega}+\|\br_\pi-\br\|_{{0,\Omega}}+\|\bPi_k^0\br-\br\|_{{0,\Omega}}\right),$$
where we have also used the triangle inequality.
	Now the desired estimate can be obtained from this using \eqref{eq:sie}, \eqref{eq:ppe} and standard polynomial approximation theory (see, e.g., \cite{brenner}).
\end{proof}

\begin{remark}
We note that the operator $\widetilde{\Pi}$ defined by \eqref{eq:projection} commutes with differentiation in time, that is,
\[\frac{\mathrm{d}}{\mathrm{d}t} \widetilde{\Pi}(\bsigma_{0},\bsigma_{1},\bu,\br)=\widetilde{\Pi}(\dot{\bsigma_{0}},\dot{\bsigma_{1}},\dot{\bu},\dot{\br}).\]
The proof of this result is the same as in   \cite[Lemma 6.2]{zhang19}, and this property is used in the subsequent analysis.\end{remark}

As a notational convenience, for any symbol $\bzeta$ in $\{\bsigma_0,\bsigma_1,\bv,\br\}$ and its discrete approximation  $\bzeta_h$ in $\{\bsigma_{0,h},\bsigma_{1,h},\bv_h,\br_h\}$, we define the following error quantities
\[e_{\bzeta}\doteq \bzeta-\bzeta_h,\qquad e_{\bzeta}^p\doteq \bzeta-\bzeta_\pi, \qquad e_{\bzeta}^h\doteq \bzeta_\pi-\bzeta_h.\]

We now prove the main result of this section.
\begin{theorem}\label{ppmk}
	For $(\bsigma_{0},\bsigma_{1},\bu,\br) \in W^{1,1}(0,T;\amsmathbb{W}^{k+1,2}(\Omega) \times\amsmathbb{W}^{k+1,2}(\Omega)\times \mathbf{W}^{k+1,2}(\Omega)\times \amsmathbb{W}^{k+1,2}(\Omega))  $, the solution $(\bsigma_{0,h},\bsigma_{1,h},\bv_h,\br_h)$ of \eqref{eq:semi-discrete} satisfies the following estimate for all time $t$, where the constant $C$ is independent of $h$ or $t$:
	$$\|\bv_h-\bv\|_{{0,\Omega}}+\|\br_h-\br\|_{{0,\Omega}}+\|{\bsigma}_{0,h}-\bsigma_0\|_{{0,\Omega}}+\|{\bsigma}_{1,h}-\bsigma_1\|_{{0,\Omega}}\le Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{1,1}(0,{T};W^{k+1,2}(\Omega))}.$$
\end{theorem}\begin{proof}
Subtracting the corresponding continuous and semi-discrete equations, we get the following system
with $\bv_\pi=\dot{\bu_\pi}$:
	\begin{subequations}\label{ppks}
	\begin{align}
	a_0(\dot{\bsigma}_0,\btau_{0,h})- a_{0,h}(\dot{\bsigma}_{0,h}, \btau_{0,h})+a_0'(\bsigma_0,\btau_{0,h})- a_{0,h}'({\bsigma}_{0,h}, \btau_{0,h}) & &\\
	+ (\bdiv\btau_{0,h},e_{\bv})_{0,\Omega} + (\btau_{0,h},\dot e_{\br})_{0,\Omega} & = 0 & \forall \btau_{0,h} \in \bbS_h,\\
	a_1(\dot{\bsigma}_1,\btau_{1,h})- a_{1,h}(\dot{\bsigma}_{1,h}, \btau_{1,h})+ (\bdiv\btau_{1,h},e_{\bv})_{0,\Omega} + (\btau_{1,h},\dot e_{\br})_{0,\Omega} & = 0 & \forall \btau_{1,h} \in \bbS_h,\\
	(\varrho \dot{e_{\bv}},\bw_h)_{0,\Omega} - (\bdiv(e_{\bsigma_{0}}+e_{\bsigma_{1}}),\bw_h)_{0,\Omega} & = 0 & \forall \bw_h \in \bV_h,\\
	(\dot e_{\bsigma_0}+\dot e_{\bsigma_1}, \eeta_h)_{0,\Omega} & = 0 & \forall \eeta_h\in\bbK_h.
\end{align}
	\end{subequations}

	Substituting $\btau_{0,h}=e_{\bsigma_0}^h$, $\btau_{1,h}=e_{\bsigma_1}^h$ and $\bw_h=e_{\bv}^h$ in the first, second and third equations respectively, and adding them, we get the following relation
	\begin{align*}
		& a_{0,h}(\dot e_{\bsigma_0}^h,e_{\bsigma_0}^h)+a_{0,h}'(e_{\bsigma_0}^h,e_{\bsigma_0}^h)+ a_{1,h}(\dot e_{\bsigma_1}^h,e_{\bsigma_1}^h)
		+(\varrho \dot e_{\bv}^h,e_{\bv}^h)_{0,\Omega}\\
		& = -(\varrho \dot e_{\bv}^p,e_{\bv}^h)_{0,\Omega}
		+(\dot e_{\bsigma_0}^p,e_{\bsigma_0}^h)_{0,\Omega}+(\dot e_{\bsigma_1}^p,e_{\bsigma_1}^h)_{0,\Omega} \\
		&\quad  -a_0'(\bsigma_0,e_{\bsigma_0}^h)+a_{0,h}'({\bsigma}_{0,\pi},e_{\bsigma_0}^h)
	-a_0(\dot \bsigma_0,e_{\bsigma_0}^h)+a_{0,h}(\dot {\bsigma}_{0,\pi},e_{\bsigma_0}^h)
	-a_1(\dot \bsigma_1,e_{\bsigma_1}^h)+a_{1,h}(\dot {\bsigma}_{1,\pi},e_{\bsigma_1}^h),
	\end{align*}
	where we have also considered  that $\bsigma_*,\bsigma_{*,h} \perp \bbK_h$. 	Now, using the definition of the discrete bilinear forms and {their symmetry and coercivity properties, we can define the norms
	\[ \|\btau\|_{A_{i,h}}:= \sqrt{a_{i,h}(\btau,\btau)}, \quad \|\btau\|_{A_{0,h}'}:= \sqrt{a_{0,h}'(\btau,\btau)}, \quad \text{as well as}\ \|\bw\|_\varrho:= \sqrt{\varrho}\|\bw\|_{0,\Omega} .\]
With this, we} proceed to rewrite the result
in its energy form, leading to
\begin{align*}
& \frac{1}{2}\frac{\text{d}}{\text{d}t}\left(\|e_{\bsigma_0}^h\|^2_{A_{0,h}}+\|e_{\bsigma_1}^h\|^2_{A_{1,h}}+\|e_{\bv}^h\|^2_{\varrho}\right)+\|e_{\bsigma_0}^h\|^2_{A_{0,h}'} \\
	 =&-(\varrho \dot e_{\bv}^p,e_{\bv}^h)_{0,\Omega}+(\dot e_{\bsigma_0}^p,e_{\bsigma_0}^h)_{0,\Omega}+(\dot e_{\bsigma_1}^p,e_{\bsigma_1}^h)_{0,\Omega}
	 -a_{0,h}'(e_{\bsigma_0}^p,e_{\bsigma_0}^h)-(a_0'({\bsigma}_{0},e_{\bsigma_0}^h)-a_{0,h}'({\bsigma}_{0},e_{\bsigma_0}^h)) \\
	& -a_{0,h}(\dot e_{\bsigma_0}^p,e_{\bsigma_0}^h)-(a_0(\dot {\bsigma}_{0},e_{\bsigma_0}^h)-a_{0,h}(\dot {\bsigma}_{0},e_{\bsigma_0}^h))
	 -a_{1,h}(\dot e_{\bsigma_1}^p,e_{\bsigma_1}^h)-(a_1(\dot {\bsigma}_{1},e_{\bsigma_1}^h)-a_{1,h}(\dot {\bsigma}_{1},e_{\bsigma_1}^h)).
\end{align*}
And we can apply Cauchy--Schwarz's inequality to each term on the right-hand side, to readily  get the following
\begin{align*}
& \frac{1}{2}\frac{\text{d}}{\text{d}t}\left(\|e_{\bsigma_0}^h\|^2_{A_{0,h}}+\|e_{\bsigma_1}^h\|^2_{A_{1,h}}+\|e_{\bv}^h\|^2_{\varrho}\right)+\|e_{\bsigma_0}^h\|^2_{A_{0,h}'} \\
	 \le & C ( \|\dot e_{\bv}^p\|_{{0,\Omega}} \|e_{\bv}^h\|_{{0,\Omega}}+\|\dot e_{\bsigma_0}^p\|\|e_{\bsigma_0}^h\|+\|\dot e_{\bsigma_1}^p\|\|e_{\bsigma_1}^h\|
	+ \|e_{\bsigma_0}^p\|\|e_{\bsigma_0}^h\|+\|\bbPi_k^0 {\bsigma}_{0}-{\bsigma}_{0}\|\|e_{\bsigma_0}^h\| \\
	&\quad + \|\dot e_{\bsigma_0}^p\|\|e_{\bsigma_0}^h\| +\|\bbPi_k^0 \dot {\bsigma}_{0}-\dot{\bsigma}_{0}\|\|e_{\bsigma_0}^h\|
	 +\|\dot e_{\bsigma_1}^p\|\|e_{\bsigma_1}^h\|+\|\bbPi_k^0 \dot {\bsigma}_{1}-\dot {\bsigma}_{1}\|\|e_{\bsigma_1}^h\|)
	.
\end{align*}
%
% ab<aa+bb
% a+b<sqrt(aa+bb)
%
%
Next, applying algebraic relations to the norms on the right-hand side of the above inequality, it is not difficult to arrive at the following estimate
\begin{align*}
   &\frac{1}{2}\frac{\text{d}}{\text{d}t}\left(\|e_{\bsigma_0}^h\|^2_{A_{0,h}}+\|e_{\bsigma_1}^h\|^2_{A_{1,h}}+\|e_{\bv}^h\|^2_{\varrho}\right)+\|e_{\bsigma_0}^h\|^2_{A_{0,h}'}\\
	\le & C \|\dot e_{\bsigma_0}^p,e_{\bsigma_0}^p,\dot e_{\bsigma_1}^p,\dot e_{\bv}^p,\bbPi_k^0 \dot \bsigma_{0}-\dot \bsigma_{0},\bbPi_k^0 \bsigma_{0}-\bsigma_{0},\bbPi_k^0 \dot \bsigma_{1}-\dot \bsigma_{1}\|
	\sqrt{\|e_{\bsigma_0}^h\|^2_{A_{0,h}}+\|e_{\bsigma_1}^h\|^2_{A_{1,h}}+\|e_{\bv}^h\|^2_{\varrho}}.
\end{align*}
Dividing both sides by $\sqrt{\|e_{\bsigma_0}^h\|^2_{A_{0,h}}+\|e_{\bsigma_1}^h\|^2_{A_{1,h}}+\|e_{\bv}^h\|^2_{\varrho}}$ and integrating in time, we are left with
$$\sqrt{\|e_{\bsigma_0}^h\|^2_{A_{0,h}}\!\!+\|e_{\bsigma_1}^h\|^2_{A_{1,h}}\!\!+\|e_{\bv}^h\|^2_{\varrho}}
\le C\! \int_0^t\!\! \|      \dot e_{\bsigma_0}^p,e_{\bsigma_0}^p,\dot e_{\bsigma_1}^p,\dot e_{\bv}^p,\bbPi_k^0 \dot \bsigma_{0}-\dot \bsigma_{0},\bbPi_k^0 \bsigma_{0}-\bsigma_{0},\bbPi_k^0 \dot \bsigma_{1}-\dot \bsigma_{1}         \|\, \text{d}t.
$$
	Again, by the commutativity of $\widetilde{\Pi}$ with differentiation in time, we have, for any symbol $\bzeta$ in $\{\bsigma_0,\bsigma_1,\bv\}$, that $\dot e_{\bzeta}^p=e_{\dot {\bzeta}}^p$. Thus, from Lemma \ref{ppel} and standard polynomial approximation theory, it is clear that the right-hand side of this last inequality is  bounded by $Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{1,1}(0,{T};W^{k+1,2}(\Omega))}$.
	Again, an application of the triangle inequality and Lemma \ref{ppel} gives us the desired estimate.
\end{proof}

Note that by differentiating equations \eqref{ppks} in time multiple times, and repeating the steps in the proof above, we can prove that the following holds for all time $t$ and for all $l\in\{0,1,...\}$, with $\mathcal D^l$ being the $l$-times differentiation operator
	\begin{equation}\label{gvks}
		\begin{split}
		\|\mathcal D^l\bv_h-\mathcal D^l\bv\|_{{0,\Omega}}+\|\mathcal D^l\br_h-\mathcal D^l\br\|_{{0,\Omega}}+\|{\mathcal D^l\bsigma}_{0,h}-\mathcal D^l\bsigma_0\|_{{0,\Omega}}+\|{\mathcal D^l\bsigma}_{1,h}-\mathcal D^l\bsigma_1\|_{{0,\Omega}}\\
		\le Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{l+1,1}(0,{T};W^{k+1,2}(\Omega))}.
		\end{split}
	\end{equation}

We also prove a result about error in divergence of the total viscoelastic stress.
\begin{theorem}\label{th:div}
	The semi-discrete solution satisfies the following error bound for all time $t\in[0,{T}]$:
	\begin{equation}\label{skvt}
		\|\bdiv(\bsigma_{0,h}+\bsigma_{1,h}-\bsigma_0-\bsigma_1)\|_{{0,\Omega}}\le Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{2,1}(0,{T};L^2(\Omega))}.
	\end{equation}
\end{theorem}
\begin{proof}
	Let $\bsigma=\bsigma_0+\bsigma_1$ and $\bsigma_h=\bsigma_{0,h}+\bsigma_{1,h}$. By the third equations of \eqref{eq:weak-viscoelast} and \eqref{eq:semi-discrete}, we get the following relation for all $\bw_h\in\bV_h$
	\begin{align*}
		(\varrho(\dot \bv-\dot\bv_h),\bw_h)=(\bdiv\bsigma-\bdiv\bsigma_h,\bw_h)
		=(\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h,\bw_h).
	\end{align*}
	Taking $\bw_h=\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h$, we can assert that
	$$\|\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h\|_{{0,\Omega}}^2=(\varrho(\dot\bv-\dot\bv_h),\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h)
	\le\|\varrho(\dot\bv-\dot\bv_h)\|_{{0,\Omega}}\|\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h\|_{{0,\Omega}}.$$
	Dividing both sides by $\|\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h\|_{{0,\Omega}}$, we readily obtain
	$$\|\bPi_k^0\bdiv\bsigma-\bdiv\bsigma_h\|_{{0,\Omega}}\le\|\varrho(\dot\bv-\dot\bv_h)\|_{{0,\Omega}}.$$
	Finally, owing to triangle inequality, polynomial approximation theory and \eqref{gvks}, we get \eqref{skvt}.
\end{proof}

