\section{Fully discrete formulation}\label{kvbk}
We proceed to {discretise the time derivative by employing the absolutely stable Crank--Nicolson scheme. This yields a} fully discrete version of the semi-discrete scheme \eqref{eq:semi-discrete}.
For that purpose we choose a positive integer $N$  for the number of divisions of the time interval.
Let $t_n=n {\tau}$, where $n=0,\frac{1}{2},1,\frac{3}{2},2,\cdots N$.

Take $\vec{x}=(\bsigma_{0},\bsigma_{1},\bv,\br)^{\tt t}$, and following \eqref{dgt}, the semi-discrete system is represented as $\vec{x}_h=(\bsigma_{0,h},\bsigma_{1,h},\bv_h,\br_h)^{\tt t}$ satisfying $\mathscr{A}\dot{\vec{x}}_h=\mathscr{B}\vec{x}_h+\mathscr{C}$ for $t\in[0,{T}]$.
We use the notation $\vec{x}^n$ and ${\vec{x}}_h^n$ to denote ${\vec{x}}(t_n)$ and $\vec{x}_h(t_n)$ respectively.
	The fully discrete scheme is to find  $\psgs^n \simeq {\vec{x}}_h^n$ for all $n\in\{1,2,...,N\}$ such that,
	\begin{equation}\label{pst}
		\mathscr{A}\frac{\psgs^n-\psgs^{n-1}}{\tau}=\mathscr{B}\frac{\psgs^n+\psgs^{n-1}}{2}+\mathscr{C}\left(\left(n-\frac{1}{2}\right){\tau}\right).
	\end{equation}
	Now, we state and prove the result concerning the time-discretisation error.
\begin{lemma}
	The solution of the fully discrete problem satisfies the following error bound, where the constant $c$ is independent of $h$ or ${\tau}$: 
	\begin{equation}\label{kvbtk}
	\max_{n\in\{0,1,...,N\}} \|\psgs^n-{\vec{x}}_h^n\|_{{0,\Omega}} \le c{\tau}^2
		\|\bsigma_0,\bsigma_1,\bv,\br\|_{W^{3,\infty}(0,{T};L^2(\Omega))}.
\end{equation}
\end{lemma}
\begin{proof}
Denoting $\psgs^n-\vec{x}_h^n$ by $\vdelta^n$, we readily obtain
	\begin{equation}\label{pmvkg}
\begin{aligned}
	&\mathscr{A}\frac{\vdelta^{n}-\vdelta^{n-1}}{\tau}-\mathscr{B}\frac{\vdelta^{n}+\vdelta^{n-1}}{2}\\
	&\quad =\mathscr{A}\left(\frac{\vec{x}_h^{n}-\vec{x}_h^{n-1}}{\tau}-\dot{\vec{x}}_h^{n-\frac{1}{2}}\right)-\mathscr{B}\left(\frac{\vec{x}_h^{n}+\vec{x}_h^{n-1}}{2} - \vec{x}_h^{n-\frac{1}{2}}\right).
\end{aligned}
	\end{equation}
Next, we use the following relation
	\begin{equation}\label{psnl}
\begin{aligned}
	 \left\lVert \frac{\vec{x}_h^{n}+\vec{x}_h^{n-1}}{2} - \vec{x}_h^{n-\frac{1}{2}} \right\rVert_{{0,\Omega}} &= \left\lVert \int_{t_{n-\frac{1}{2}}}^{t_n}\dot{\vec{x}}_h(s)\text{d}s- \int_{t_{n-1}}^{t_{n-\frac{1}{2}}}\dot{\vec{x}}_h(s)\text{d}s \right\rVert_{{0,\Omega}} \\
	&=\left\lVert \int_{t_{n-\frac{1}{2}}}^{t_n} \int_{t_{n-\frac{1}{2}}}^s \ddot{\vec{x}}_h(t)\text{d}t\,\text{d}s+ \int_{t_{n-1}}^{t_{n-\frac{1}{2}}}\int_{s}^{t_{n-\frac{1}{2}}}\ddot{\vec{x}}_h(t)\text{d}t\,\text{d}s \right\rVert_{{0,\Omega}} \\
	&\le {\tau}^2\pspr{\ddot{\vec{x}}_h}.
\end{aligned}
	\end{equation}
	And in order to bound the other term, we consider the following
	\begin{equation}\label{dsnl}
\begin{aligned}
	& \left\lVert \frac{\vec{x}_h^{n}-\vec{x}_h^{n-1}}{\tau}-\dot{\vec{x}}_h^{n-\frac{1}{2}} \right\rVert_{{0,\Omega}} \\
	& =\frac{1}{\tau}\left\lVert \int_{t_{n-\frac{1}{2}}}^{t_n}\int_{t_{n-\frac{1}{2}}}^{s}\int_{t_{n-\frac{1}{2}}}^{t}\dddot{\vec{x}}_h(r) \text{d}r\,\text{d}t\,\text{d}s
	+\int_{t_{n-1}}^{t_{n-\frac{1}{2}}}\int_s^{t_{n-\frac{1}{2}}}\int_t^{t_{n-\frac{1}{2}}}\dddot{\vec{x}}_h(r) \text{d}r\,\text{d}t\,\text{d}s
	\right\rVert_{{0,\Omega}}\\
	& \le {\tau}^2 \pspr{\dddot{\vec{x}}_h}.
\end{aligned}
	\end{equation}
	By the continuity of $\mathscr{A}$ and $\mathscr{B}$ (with continuity constants $c_{\mathscr{A}}$ and $c_{\mathscr{B}}$ respectively), the coercivity of $\mathscr{A}$ with constant $C_{\mathscr{A}}$, using \eqref{psnl} and \eqref{dsnl} in \eqref{pmvkg}, and then multiplying by $\frac{\vdelta^{n}+\vdelta^{n-1}}{2}$, we get the following estimate
\begin{align*}
	&\frac{\|\vdelta^{n}\|_{{0,\Omega}}^2-\|\vdelta^{n-1}\|_{{0,\Omega}}^2}{\tau}\\
	&\le c\left(\frac{\|\vdelta^{n}\|_{{0,\Omega}}^2+\|\vdelta^{n-1}\|_{{0,\Omega}}^2}{2}+{\tau}^2(\pspr{\ddot{\vec{x}}_h}+\pspr{\dddot{\vec{x}}_h})\|\vdelta^{n}+\vdelta^{n-1}\|_{{0,\Omega}}\right),
\end{align*}
where $c=C_{\mathscr{A}}^{-1}\max(1,c_{\mathscr{A}},c_{\mathscr{B}})$.
Applying the discrete form of {Gronwall's} inequality (see \cite{stpv}), we are left with
	\begin{equation*}
		\max_{n\in\{0,1,...,N\}} \|\vec{X}_h^{n}-\vec{x}_h^{n}\|_{{0,\Omega}} \le c{\tau}^2(\pspr{\ddot{\vec{x}}_h}+\pspr{\dddot{\vec{x}}_h}).
	\end{equation*}
	%$(\frac{1}{D}A-\frac{1}{2}B)X^{n}=(\frac{1}{D}A+\frac{1}{2}B)X^{n-1}+C$.
	To complete the proof, we proceed to find $h$-independent bounds for the quantities $\pspr{\ddot{\vec{x}}_h}$ and $\pspr{\dddot{\vec{x}}_h}$,  which we derive as follows
	\begin{align*}
		\pspr{\mathcal D^l\vec{x}}=&\pspr{\mathcal D^l \bsigma_{0,h},\mathcal D^l \bsigma_{1,h},\mathcal D^l \bv_h,\mathcal D^l \br_h} \\
		\le & \pspr{\mathcal D^l \bsigma_{0},\mathcal D^l \bsigma_{1},\mathcal D^l \bv,\mathcal D^l \br} + C\bigl(\|\mathcal D^l\bv_h-\mathcal D^l\bv\|_{{0,\Omega}} \\
		& \qquad +\|\mathcal D^l\br_h-\mathcal D^l\br\|_{{0,\Omega}}+\|{\mathcal D^l\bsigma}_{0,h}-\mathcal D^l\bsigma_0\|_{{0,\Omega}}+\|{\mathcal D^l\bsigma}_{1,h}-\mathcal D^l\bsigma_1\|_{{0,\Omega}}\bigr)\\
		\le &  \pspr{\mathcal D^l \bsigma_{0},\mathcal D^l \bsigma_{1},\mathcal D^l \bv,\mathcal D^l \br} + Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{l+1,1}(0,{T};W^{k+1,2}(\Omega))}
	\end{align*}
{with  \eqref{gvks} in the last step}. Now, for a sufficiently small $h$, the second term is dominated by the first. Thus, we get the desired estimate.
\end{proof}

We finally state the full-discretisation error estimate which is obtained from \eqref{kvbtk}, Theorem \ref{ppmk}, and triangle inequality.
\begin{theorem}\label{th:cv}
{Assume that the solution to \eqref{eq:weak-viscoelast} is such that $\bsigma_0,\bsigma_1 \in W^{1,1}(0,T; \mathbb{W}^{k+1,2}(\Omega))\cap W^{3,\infty}(0,{T};\bbL^2(\Omega))$ and $\bv \in W^{1,1}(0,T; \mathbf{W}^{k+1,2}(\Omega))\cap W^{3,\infty}(0,{T};\bL^2(\Omega))$. Then,}	the solution $\vec{X}^n$ of \eqref{pst} satisfies the following estimate for all $n\in\{0,1,,...,N\}$
	\begin{align*} %\max_{n\in \{0,1,...,N\}} \left(
		% \|\bv_{h\tau}(n\tau)-\bv(n\tau)\|+\|\br_{h\tau}(n\tau)-\br(n\tau)\|
		%+\|{\bsigma}_{0,h\tau}(n\tau)-\bsigma_0(n\tau)\|+\|{\bsigma}_{1,h\tau}(n\tau)-\bsigma_1(n\tau)\|
		\|\vec{X}^n-\vec{x}^n\|
		%\right)
		 %\qquad
		 \le  Ch^{k+1}\|\bsigma_0,\bsigma_1,\bv\|_{W^{1,1}(0,{T};W^{k+1,2}(\Omega))}+c{\tau}^2\|\bsigma_0,\bsigma_1,\bv,\br\|_{W^{3,\infty}(0,{T};L^2(\Omega))}.
	\end{align*}
\end{theorem}


