\begin{theorem}[Exact noise reduction for IIR graph filtering with random node-asynchronous updates]
\label{Th5}
    Under Proposition \ref{prop5} and Lemma \ref{lm2}, given $\mathbf{D}$ varies as $\mathbf{D}^{(k)}=\mathrm{diag}(\alpha_{1}^{(k)}+\beta_{1}^{(k)}\mathrm{i},\dots, \alpha_{N}^{(k)}+\beta_{N}^{(k)}\mathrm{i})$, $\Theta = \{\mathbf{D}^{(1)}\mathbf{1},\dots, \mathbf{D}^{(K)}\mathbf{1}\}\in\mathbb{C}^{N\times K}$, the closed-form solution $\alpha_{i}^{(k)}, \beta_{i}^{(k)}$, noise reduction $I(\Theta)$ are
    \begin{equation}
\begin{aligned}
\alpha_{i}^{(k)}  & = \frac{\bigg[\Re\Big[\psi_{k}\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]\mathbf{S}\Big]\bigg]_{ii}}{\Big[\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]\Big]_{ii}},\\ \beta_{i}^{(k)}& = \frac{\bigg[\Im\Big[\psi_{k}\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]\mathbf{S}\Big]\bigg]_{ii}}{\Big[\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]\Big]_{ii}},\\
I(\Theta)& =\sum_{k=1}^{K}\frac{(\sigma^{(k)})^2}{N}\sum_{i=1}^{N}\frac{\bigg|\Big[\psi_{k}\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]\mathbf{S}\Big]_{ii}\bigg|^{2}}{\Big[\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]\Big]_{ii}}.
\end{aligned}
\label{t5}
\end{equation}
\end{theorem}
\begin{proof}
    The proof is similar to that of Theorem \ref{Th1}.
\end{proof}
Theorem \ref{Th5} establishes that exact compensation of quantization noise is attainable in IIR graph filtering with random node-asynchronous updates, provided the system adheres to uniform random node selection protocol. Compared to Theorem \ref{Th4}, the closed-form expressions differ because the matrix $\mathbf{W}^{(k)}_{\mathbf{P}}$ is Hermitian rather than the real symmetric matrix as discussed before. Similarly, $\mathbf{W}^{(k)}_{\mathbf{P}}$ can also be computed through the vectorized fixed-point iteration of (\ref{l2}), whose key parameter matrix follows from the expectation
    \begin{equation}
\begin{aligned}
&\mathbb{E}\Big[\big(\mathbf{I}+(\psi_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_t}\big)\otimes\big(\mathbf{I}+(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_t}\big)\Big]  \\
& = \mathbf{I}+p\left((\psi_k\mathbf{S}^\top - \mathbf{I})\otimes\mathbf{I}+\mathbf{I}\otimes(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\right)\\
& + \left((\psi_k\mathbf{S}^\top - \mathbf{I})\otimes(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\right)\big(\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}\otimes\mathbf{P}_{\mathcal{T}_t}]\big),
\end{aligned}
\label{vec2}
\end{equation}
using the associativity and mixed-product properties of Kronecker products, the linearity of expectation, and the relation $\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}] = p\mathbf{I}$. Given $\mathbf{P}_{\mathcal{T}_t}$ is a diagonal matrix with independent Bernoulli entries along its main diagonal, $\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}\otimes\mathbf{P}_{\mathcal{T}_t}]$ is computed by considering the pairwise activation probabilities of these entries. By applying the same procedure, one can also derive $\mathbb{E}\big[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}\big]$, then obtain (\ref{t5}). It should be noted when $p\to1$, (\ref{p5})-(\ref{t5}) return to (\ref{p2})-(\ref{t2}), indicating synchronous update is a special case of the current consideration. Moreover, the noise gain regularizer, in this case, can share the same expression with (\ref{r6_final}) irrespective of $p$.

\begin{remark}[Consistency of noise gain regularizer (\ref{r6_final}) for IIR graph filter design with random node-asynchronous updates]
\label{Rm7}
\textnormal{Following the symmetry assumption $\mathbf{S}=\mathbf{S}^\top$ from random graph processes, the regularizer $\mathcal{R}(\boldsymbol{\psi})$ is identical to (\ref{r6_final}) for the noise gain defined in (\ref{p5}), based on the inequality
\begin{equation}
\begin{aligned}
\Big\Vert\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}]\Big\Vert_{2}\leq\frac{1}{1 - |\psi_{k}|^{2}\rho_{\star}^{2}}.
\end{aligned}
\label{r7_final}
\end{equation} 
A detailed proof for (\ref{r7_final}) can be found in Appendix~\ref{app:r7}. }
\end{remark}

