\subsection{Proof of Theorem 1}
\label{app:t1}
Let $\mathbf{D}_{t-1}=\mathrm{diag}(\alpha_{1, t-1},\dots, \alpha_{N, t-1})$ replace $\mathbf{D}$ in (\ref{p1}), we have mitigation term
\begin{equation}
\begin{aligned}
    I_{t-1}=-2\sum_{i=1}^{N}\Big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S}) \mathbf{S}\Big]_{ii} \alpha_{i, t-1}+ \sum_{i=1}^{N}\Big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S})\Big]_{ii}\alpha_{i, t-1}^{2}.  
\end{aligned}
\label{deqn_ex11}
\end{equation}
Let the gradient of $I_{t-1}$ be zero, i.e.,
\begin{equation}
\begin{aligned}
\frac{\partial I_{t-1}}{\partial \alpha_{i, t-1}} =\Big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S})\Big]_{ii}\alpha_{i, t-1}-\Big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S}) \mathbf{S}\Big]_{ii} = 0,
\end{aligned}
\label{deqn_ex12}
\end{equation}
we have
\begin{equation}
\begin{aligned}
\alpha_{i,t-1} = \frac{\Big [\mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S})\mathbf{S}\Big ]_{ii}}{\Big [ \mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S})\Big ]_{ii}}, I_{t-1} =\sum_{i=1}^{N}{\frac{\Big [\mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S})\mathbf{S}\Big ]^{2}_{ii}}{\Big [ \mathbf{G}_{\mathbf{n}_{t-1}}(\mathbf{S})\Big ]_{ii}}}.
\end{aligned}
\label{deqn_ex13}
\end{equation}
The proof is completed.

\subsection{Proof of Proposition 2}
\label{app:p2}
  By considering all prior noises $\mathbf{n}^{(k)}_{\tau}(\tau<t)$, we can explicitly express 
  \begin{equation}
\begin{aligned}
\widetilde{\mathbf{w}}^{(k)}_{t} = \sum_{\tau=0}^{t-1}(\psi_{k}\mathbf{S})^{t-\tau-1}(\psi_{k}\mathbf{S}-\mathbf{D})\mathbf{n}^{(k)}_{\tau}
  \end{aligned}
\label{p211}
\end{equation}
as $\widetilde{\mathbf{w}}^{(k)}_{0}=\mathbf{0}$. Then, it can be derived 
  \begin{equation}
\begin{aligned}
\mathbb{E} [\widetilde{\mathbf{w}}^{(k)}_{t} (\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H} ] = \mathbb{E}\bigg[\sum_{\tau_1=0}^{t-1}\sum_{\tau_2=0}^{t-1}(\psi_{k}\mathbf{S})^{t-\tau_1-1}(\psi_{k}\mathbf{S}-\mathbf{D})\mathbf{n}^{(k)}_{\tau_1}(\mathbf{n}^{(k)}_{\tau_2})^\mathrm{H} (\psi_{k}\mathbf{S}-\mathbf{D})^\mathrm{H}\big((\psi_k\mathbf{S})^\mathrm{H}\big)^{t-\tau_2-1}\bigg].
  \end{aligned}
\label{p212}
\end{equation}
According to the noise of the i.i.d. $\mathbb{E}[\mathbf{n}^{(k)}_{\tau_1}(\mathbf{n}^{(k)}_{\tau_2})^\mathrm{H}] = (\sigma^{(k)})^2 \mathbf{I}$ if $\tau_1=\tau_2$ and $\mathbf{0}$ if $\tau_1\neq\tau_2$, the trace cyclic property \(\mathrm{tr}(\mathbf{XY}) = \mathrm{tr}(\mathbf{YX})\) and the Hermitian transpose \((\psi_k\mathbf{S})^\mathrm{H}=\psi^{*}_k\mathbf{S}^\top\), it shows
  \begin{equation}
\begin{aligned}
\mathrm{tr}\bigg(\mathbb{E}[\widetilde{\mathbf{w}}^{(k)}_{t}(\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H}]\bigg) = (\sigma^{(k)})^2\mathrm{tr}\bigg(\sum_{\tau=0}^{t-1}(\psi_{k}\mathbf{S}-\mathbf{D})^\mathrm{H}(\psi^{*}_{k}\mathbf{S}^\top)^{t-\tau-1}(\psi_{k}\mathbf{S})^{t-\tau-1}(\psi_{k}\mathbf{S}-\mathbf{D})\bigg).
  \end{aligned}
\label{p213}
\end{equation}
 As $t\to \infty$, one finds $\sum_{\tau=0}^{t-1}(\psi^{*}_{k}\mathbf{S}^\top)^{t-\tau-1}(\psi_{k}\mathbf{S})^{t-\tau-1}\to\sum_{\tau=0}^{\infty}(\psi^{*}_{k}\mathbf{S}^\top)^{\tau}(\psi_{k}\mathbf{S})^{\tau}$. Let $\mathbf{W}^{(k)}_0=\sum_{\tau=0}^{\infty}(\psi^{*}_{k}\mathbf{S}^\top)^{\tau}(\psi_{k}\mathbf{S})^{\tau}$, then $\mathbf{W}^{(k)}_0 $ satisfies Lyapunov equation $\mathbf{W}^{(k)}_0 = \vert\psi_{k}\vert^{2}\mathbf{S}^\top\mathbf{W}^{(k)}_0 \mathbf{S}+\mathbf{I}$, and the limit of (\ref{p213}) can be written as 
   \begin{equation}
\begin{aligned}
\lim_{t\to \infty}\mathrm{tr}\bigg(\mathbb{E}[\widetilde{\mathbf{w}}^{(k)}_{t}(\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H}]\bigg) \to (\sigma^{(k)})^2\mathrm{tr}\bigg((\psi_{k}\mathbf{S}-\mathbf{D})^\mathrm{H}\mathbf{W}^{(k)}_0(\psi_{k}\mathbf{S}-\mathbf{D})\bigg).
  \end{aligned}
\label{p214}
\end{equation}
By expanding R.H.S of (\ref{p214}) with the trace cyclic property \(\mathrm{tr}(\mathbf{XY}) = \mathrm{tr}(\mathbf{YX})\) and the trace-Hermitian property $\mathrm{tr}(\mathbf{X}^\mathrm{H})=\mathrm{tr}(\mathbf{X})^{*}$, we get 
   \begin{equation}
\begin{aligned}
\mathrm{tr}\bigg((\psi_{k}\mathbf{S}-\mathbf{D})^\mathrm{H}\mathbf{W}^{(k)}_0(\psi_{k}\mathbf{S}-\mathbf{D})\bigg)=\mathrm{tr}(\vert\psi_{k}\vert^{2}\mathbf{W}^{(k)}_0 \mathbf{S}\mathbf{S}^\top)+\mathrm{tr}(\mathbf{W}^{(k)}_0\vert\mathbf{D}\vert^{2})-\psi_{k}\mathrm{tr}(\mathbf{W}^{(k)}_0\mathbf{S}\mathbf{D}^{*})-\psi_{k}^{*}\mathrm{tr}(\mathbf{W}^{(k)}_0\mathbf{S}\mathbf{D}^{*})^{*}.
  \end{aligned}
\label{p215}
\end{equation}
Finally, by using conjugate pairing $z_1z_2+z^{*}_1z^{*}_2=2\Re[z_1z_2]$ with $z_1=\psi_{k},z_2=\mathrm{tr}(\mathbf{W}^{(k)}_0\mathbf{S}\mathbf{D}^{*})$ , (\ref{p2}) then follows. The proof is completed.

\subsection{Proof of Remark 3}
\label{app:r3}
With the vectorization property $\mathrm{vec}(\mathbf{X}+\mathbf{Y}) = \mathrm{vec}(\mathbf{X}) +\mathrm{vec}(\mathbf{Y})$ and $\mathrm{vec}(\mathbf{XYZ})=(\mathbf{Z}^\top \otimes\mathbf{X})\mathrm{vec}(\mathbf{Y})$, we can firstly derive the solution of Lyapunov equation from (\ref{p2}) as
\begin{equation}
\begin{aligned}
\mathrm{vec}(\mathbf{W}^{(k)}_0) 
& = |\psi_{k}|^{2}(\mathbf{S}^\top \otimes \mathbf{S}^\top)\mathrm{vec}(\mathbf{W}^{(k)}_0) + \vec{\mathbf{1}}\\
&=(\mathbf{I}-|\psi_{k}|^{2}\mathbf{S}^\top \otimes \mathbf{S}^\top)^{-1}\vec{\mathbf{1}},
\end{aligned}
\label{reg_iir}
\end{equation}
where $\vec{\mathbf{1}}=[\mathbf{e}_1^\top,\dots,\mathbf{e}_N^\top]^\top$. Then, by using the trace property \(\mathrm{tr}(\mathbf{XY}) = \mathrm{tr}(\mathbf{YX})\), Lyapunov equation $|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{W}^{(k)}_0 \mathbf{S} = \mathbf{W}^{(k)}_0-\mathbf{I}$, the noise gain from (\ref{p2}) can be rewritten as 
\begin{equation}
\begin{aligned}
G^{(k)} = \mathrm{tr}\big(\mathbf{I}\times(\mathbf{W}^{(k)}_0-\mathbf{I})\big), 
\end{aligned}
\label{h_iir}
\end{equation}
which can be further simplified as
\begin{equation}
\begin{aligned}
G^{(k)} & =\mathrm{vec}(\mathbf{I})^\top\mathrm{vec}(\mathbf{W}^{(k)}_0-\mathbf{I})\\
& =\vec{\mathbf{1}}^\top\big((\mathbf{I}-|\psi_{k}|^{2}\mathbf{S}^\top \otimes \mathbf{S}^\top)^{-1}-\mathbf{I}\big)\vec{\mathbf{1}}
\end{aligned}
\label{rreg_iir}
\end{equation}
by using $\mathrm{tr}(\mathbf{XY})=\mathrm{vec}(\mathbf{X}^\top)^\top\mathrm{vec}(\mathbf{Y})$ and substituting the solution of $\mathrm{vec}(\mathbf{W}^{(k)}_0) $ from (\ref{reg_iir}). By aggregating $G^{(k)}$ and omitting the constant, the regularizer $\mathcal{R}(\boldsymbol{\psi})$ is derived as
\begin{equation}
\begin{aligned}
&\mathcal{R}(\boldsymbol{\psi})=\vec{\mathbf{1}}^\top\left(\sum^{K}_{k=1}(\mathbf{I}-|\psi_{k}|^{2}\mathbf{S}^\top \otimes \mathbf{S}^\top)^{-1}\right)\vec{\mathbf{1}}.
\end{aligned}
\label{rrrerrg_iir}
\end{equation}
By the mixed-product property $(\mathbf{X}\otimes\mathbf{Y})(\mathbf{Z}\otimes\mathbf{W})=(\mathbf{X}\mathbf{Z}\otimes\mathbf{Y}\mathbf{W})$ and $\mathbf{S} =\mathbf{U}\mathbf{\Lambda}\mathbf{U}^{-1}$, it can be obtained $\mathbf{S}^\top \otimes \mathbf{S}^\top = \left( \mathbf{U}^{-1} \otimes \mathbf{U}^{-1} \right)^\top(\mathbf{\Lambda} \otimes \mathbf{\Lambda})\left( \mathbf{U} \otimes \mathbf{U} \right)^\top$. Then (\ref{rrrerrg_iir}) is derived as
\begin{equation}
\begin{aligned}
\mathcal{R}(\boldsymbol{\psi})
&=\vec{\mathbf{1}}^\top\left( \mathbf{U}^{-1} \otimes \mathbf{U}^{-1} \right)^\top\left( \sum_{k=1}^{K} (\mathbf{I} - |\psi_{k}|^{2} \mathbf{\Lambda} \otimes \mathbf{\Lambda})^{-1} \right)\left( \mathbf{U} \otimes \mathbf{U} \right)^\top\vec{\mathbf{1}}.
\end{aligned}
\label{rrreg_iir}
\end{equation}
Since $\mathbf{\Lambda}=\mathrm{diag}(\lambda_{1}, \dots, \lambda_{N})$, then we have   
\begin{equation}
\begin{aligned}
\left[\left( \sum_{k=1}^{K} (\mathbf{I} - |\psi_{k}|^{2} \mathbf{\Lambda} \otimes \mathbf{\Lambda})^{-1}\right) \right]_{i'i'}=\sum_{k=1}^{K}\frac{1}{1 - |\psi_{k}|^{2}\lambda_{i}\lambda_{j}},
\end{aligned}
\label{rrrssseg_iirr}
\end{equation}
where $i'=(i-1)N+j$ and the other entries are all zero. By using the diagonal‐vector product identity $\mathbf{a}^\top\mathrm{diag}(\mathbf{b})\mathbf{c}=\mathbf{b}(\mathbf{a}\odot\mathbf{c})$ with  
\begin{equation}
\begin{aligned}
\mathbf{a}^\top  = \vec{\mathbf{1}}^\top\left( \mathbf{U}^{-1} \otimes \mathbf{U}^{-1} \right)^\top, \mathbf{c} = \left( \mathbf{U} \otimes \mathbf{U} \right)^\top\vec{\mathbf{1}}\\
\mathrm{diag}(\mathbf{b})  = \left( \sum_{k=1}^{K} (\mathbf{I} - |\psi_{k}|^{2} \mathbf{\Lambda} \otimes \mathbf{\Lambda})^{-1}\right),
\end{aligned}
\label{rrreg_iirr}
\end{equation}
(\ref{r3_final}) follows. The proof is completed.

\subsection{Proof of Proposition 3}
\label{app:p3}
 By substitution and total expectation property \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\), it shows
    \begin{equation}
\begin{aligned}
\mathbb{E}[\widetilde{\mathbf{y}}_{\mathbf{n}_{t-1}}\widetilde{\mathbf{y}}^\mathrm{H}_{\mathbf{n}_{t-1}}]=\mathbb{E}\Big[\mathbf{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})(\mathbf{S}_{t-1}-\mathbf{D})\mathbb{E}[\mathbf{n}_{t-1}\mathbf{n}^\mathrm{H}_{t-1}](\mathbf{S}_{t-1}-\mathbf{D})^\mathrm{H}\mathbf{H}^\mathrm{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})\Big].
  \end{aligned}
\label{p311}
\end{equation}
As \(\mathbb{E}[\mathbf{n}_{t-1}\mathbf{n}^\mathrm{H}_{t-1}]=\sigma_{t-1}^2\mathbf{I}\), we can further obtain 
    \begin{equation}
\begin{aligned}
\mathbb{E}[\widetilde{\mathbf{y}}_{\mathbf{n}_{t-1}}\widetilde{\mathbf{y}}^\mathrm{H}_{\mathbf{n}_{t-1}}]=\sigma_{t-1}^2\mathbb{E}\Big[\mathbf{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})(\mathbf{S}_{t-1}-\mathbf{D})(\mathbf{S}_{t-1}-\mathbf{D})^\mathrm{H}\mathbf{H}^\mathrm{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})\Big].
  \end{aligned}
\label{p312}
\end{equation}
By using real-valued \(\mathbf{X^\mathrm{H}}=\mathbf{X^\top}\), \(\mathrm{tr}(\mathbb{E}[\mathbf{X}])=\mathbb{E}[\mathrm{tr}(\mathbf{X})]\), \(\mathrm{tr}(\mathbf{XY})=\mathrm{tr}(\mathbf{YX})\), we cyclically reorder the terms to obtain 
    \begin{equation}
\begin{aligned}
\mathrm{tr}\bigg(\mathbb{E}[\widetilde{\mathbf{y}}_{\mathbf{n}_{t-1}}\widetilde{\mathbf{y}}^\mathrm{H}_{\mathbf{n}_{t-1}}]\bigg)=\sigma_{t-1}^2\mathbb{E}\bigg[\mathrm{tr}\Big((\mathbf{S}_{t-1}-\mathbf{D})^\mathrm{H}\mathbf{H}^\mathrm{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})\mathbf{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})(\mathbf{S}_{t-1}-\mathbf{D})\Big)\bigg].
  \end{aligned}
\label{p313}
\end{equation}
As $\mathbf{G}_{\mathbf{n}_{t-1}}(\mathcal{\Phi}_{t:T-1})=\mathbf{H}^\top_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})\mathbf{H}_{\mathbf{n}_{t-1}} (\mathcal{\Phi}_{t:T-1})$, \(\mathbb{E}[\mathrm{tr}(\mathbf{X})]=\mathrm{tr}(\mathbb{E}[\mathbf{X}]) \) and \(\mathbb{E}[\mathbf{S}_{t-1}]=\overline{\mathbf{S}}\), (\ref{p3}) follows. The proof is completed.

\subsection{Proof of Remark 5}
\label{app:r5}
By applying $\mathrm{tr}(\mathbf{XY})\le\Vert\mathbf{X} \Vert_{2}\mathrm{tr}(\mathbf{Y})$,  \(\mathrm{tr}(\mathbb{E}[\mathbf{X}]) = \mathbb{E}[\mathrm{tr}(\mathbf{X})]\), and $\mathrm{tr}(\mathbf{XX^\top})\le \mathrm{rank}(\mathbf{X})\Vert\mathbf{X}\Vert^{2}_{2}$, $G_{t-1}$ from~(\ref{p3}) can be bounded, satisfies the following chain: 
\begin{equation}
\begin{aligned}
G_{t-1} 
& = \mathrm{tr}\Big(\mathbb{E}\big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathcal{\Phi}_{t:T-1}) \mathbf{S}_{t-1}\mathbf{S}^\top_{t-1}\big]\Big) \\
& \le \Big\Vert\mathbb{E}\big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathcal{\Phi}_{t:T-1})\big] \Big\Vert_{2}\mathrm{tr}\Big(\mathbb{E}\big[\mathbf{S}_{t-1}\mathbf{S}^\top_{t-1}\big]\Big)\\
& \le N\rho^{2}_{\star}\Big\Vert\mathbb{E}\big[\mathbf{G}_{\mathbf{n}_{t-1}}(\mathcal{\Phi}_{t:T-1})\big] \Big\Vert_{2},
\end{aligned}
\label{r5}
\end{equation}
with $\mathrm{rank}(\mathbf{S}_{t-1})\le N$ and $\Vert\mathbf{S}_{t-1}\Vert_{2}\le \rho_{\star}$. Then 
 based on the spectral norm subadditivity $\Vert\mathbf{X}+\mathbf{Y} \Vert_{2} \le \Vert\mathbf{X} \Vert_{2}+\Vert\mathbf{Y} \Vert_{2}$, Jensen’s inequality $\big\Vert\mathbb{E}[\mathbf{X}]\big\Vert_{2}\le \mathbb{E}\big[\Vert\mathbf{X}\Vert_{2}\big]$, and the expression in (\ref{ker}), (\ref{r5}) can be further bounded as 
\begin{equation}
\begin{aligned}
G_{t-1}& \le N\rho^{2}_{\star}\left(\sum_{\tau_1 =t}^{T}\sum_{\tau_2 =t}^{T}\Big\Vert\phi_{\tau_1}\phi_{\tau_2}\mathbb{E}\big[\mathcal{\Phi}_{t:\tau_1-1}^\top\mathcal{\Phi}_{t:\tau_2-1}\big]\Big\Vert_{2}\right)\\
& \le N\rho^{2}_{\star}\left(\sum_{\tau_1 =t}^{T}\sum_{\tau_2 =t}^{T}|\phi_{\tau_1}\phi_{\tau_2}|\mathbb{E}\Big[\big\Vert\mathcal{\Phi}_{t:\tau_1-1}^\top\mathcal{\Phi}_{t:\tau_2-1}\big\Vert_{2}\Big]\right).
\end{aligned}
\label{r5_}
\end{equation}
From (\ref{ker})-(\ref{vec}) and the sub‐multiplicativity of the spectral norm \(\|\mathbf{XY}\|_{2} \leq \|\mathbf{X}\|_{2} \|\mathbf{Y}\|_{2}\), we find a new bound for (\ref{r5_}) 
\begin{equation}
\begin{aligned}
G_{t-1} & \le N\rho^{2}_{\star}\left(\sum_{\tau_1 =t}^{T}\sum_{\tau_2 =t}^{T}|\phi_{\tau_1}\phi_{\tau_2}|\Vert\mathbf{S}_{t}\Vert^{2l}_{2} \Vert\overline{\mathbf{S}}^{|\tau_2-\tau_1|}\Vert_{2}\right)\\
& \le N\rho^{2}_{\star}\left(\sum_{\tau_1 =t}^{T}\sum_{\tau_2 =t}^{T}|\phi_{\tau_1}\phi_{\tau_2}|p^{|\tau_2-\tau_1|}\rho^{\tau_2+\tau_1-2t}_{\star}\right)
\end{aligned}
\label{r555}
\end{equation}
by $l= \textnormal{min} \{\tau_1,\tau_2\}-t$ and $\Vert\overline{\mathbf{S}}\Vert_{2}=p\rho_{\star}$. Then vector form of (\ref{r555}) can be easily written as
\begin{equation}
\begin{aligned}
G_{t-1} \le N\rho^{2}_{\star}\left(\boldsymbol{\phi'}^\top \mathbf{V'}_{t-1}\boldsymbol{\phi'}\right),
\end{aligned}
\label{r55555}
\end{equation}
owing to the fact that $[\boldsymbol{\phi'}]_{\tau_1+1}=\vert\phi_{\tau_1}\vert,[\boldsymbol{\phi'}]_{\tau_2+1}=\vert\phi_{\tau_2}\vert$, and $\big[\mathbf{V'}_{t-1}\big]_{(\tau_1+1)(\tau_2+1)}=p^{|\tau_2-\tau_1|}\rho^{\tau_2+\tau_1-2t}_{\star}$. As $\tau_1,\tau_2>t$, all remaining entries in $\mathbf{V'}_{t-1}$ are zero. Then after the summation over $t$, (\ref{r5_final}) follows. The proof is completed.

\subsection{Proof of Proposition 4}
\label{app:p4}
With $\widetilde{\mathbf{w}}^{(k)}_{0}=\mathbf{0}$, analogous to (\ref{p211}), $\widetilde{\mathbf{w}}^{(k)}_{t}$ satisfies
\begin{equation}
\begin{aligned}
\widetilde{\mathbf{w}}^{(k)}_{t} = \sum_{\tau=0}^{t-1}\psi_{k}^{t-\tau-1}\mathcal{\Phi}_{\tau+1:t-1}(\psi_{k}\mathbf{S}_{\tau}-\mathbf{D})\mathbf{n}^{(k)}_{\tau}.
 \end{aligned}
\label{pp4}
\end{equation}
Then  $\mathbb{E} [\widetilde{\mathbf{w}}^{(k)}_{t} (\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H} ]$ is given by 
\begin{equation}
\begin{aligned}
&\mathbb{E} [\widetilde{\mathbf{w}}^{(k)}_{t} (\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H} ] = \mathbb{E}\bigg[\sum_{\tau_1=0}^{t-1}\sum_{\tau_2=0}^{t-1}\psi_{k}^{t-\tau_1-1}\mathcal{\Phi}_{\tau_1+1:t-1}(\psi_{k}\mathbf{S}_{\tau_1}-\mathbf{D})\mathbf{n}^{(k)}_{\tau_1}(\mathbf{n}^{(k)}_{\tau_2})^\mathrm{H} (\psi_{k}\mathbf{S}_{\tau_2}-\mathbf{D})^\mathrm{H}\mathcal{\Phi}^\mathrm{H}_{\tau_2+1:t-1}(\psi^{*}_{k})^{t-\tau_2-1}\bigg].
 \end{aligned}
\label{pp4ss}
\end{equation}
Since \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\), $\mathbb{E}[\mathbf{n}^{(k)}_{\tau_1}(\mathbf{n}^{(k)}_{\tau_2})^\mathrm{H}] = (\sigma^{(k)})^2 \mathbf{I}$ if $\tau_1=\tau_2$ and $\mathbf{0}$ if $\tau_1\neq\tau_2$, and real-valued \(\mathbf{X^\mathrm{H}}=\mathbf{X^\top}\), (\ref{pp4ss}) can be rewritten as 
\begin{equation}
\begin{aligned}
\mathbb{E} [\widetilde{\mathbf{w}}^{(k)}_{t} (\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H} ] &= (\sigma^{(k)})^2\sum_{\tau=0}^{t-1}|\psi_{k}|^{2(t-\tau-1)}\mathbb{E}\Big[\mathcal{\Phi}_{\tau+1:t-1} (\psi_{k}\mathbf{S}_{\tau}-\mathbf{D})(\psi_{k}\mathbf{S}_{\tau}-\mathbf{D})^\mathrm{H}\mathcal{\Phi}^\top_{\tau+1:t-1}\Big].
 \end{aligned}
\label{pp4sss}
\end{equation}
By \(\mathrm{tr}(\mathbb{E}[\mathbf{X}]) = \mathbb{E}[\mathrm{tr}(\mathbf{X})]\), \(\mathrm{tr}(\mathbf{XY}) = \mathrm{tr}(\mathbf{YX})\), \(\mathbb{E}[\mathrm{tr}(\mathbf{X})]=\mathrm{tr}(\mathbb{E}[\mathbf{X}]) \), we can write 
\begin{equation}
\begin{aligned}
\mathrm{tr}&\bigg(\mathbb{E} [\widetilde{\mathbf{w}}^{(k)}_{t} (\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H} ]\bigg) = (\sigma^{(k)})^2\mathrm{tr}\bigg(\sum_{\tau=0}^{t-1}|\psi_{k}|^{2(t-\tau-1)}\mathbb{E}\Big[(\psi_{k}\mathbf{S}_{\tau}-\mathbf{D})^\mathrm{H}\mathcal{\Phi}^\top_{\tau+1:t-1}\mathcal{\Phi}_{\tau+1:t-1}(\psi_{k}\mathbf{S}_{\tau}-\mathbf{D})\Big]\bigg).
 \end{aligned}
\label{pp4sss44}
\end{equation}
Since \(\mathcal{\Phi}_{\tau+1:t-1}\) and \(\mathbf{S}_{\tau}\) are independent in the summation for every $\tau$, we can rewrite (\ref{pp4sss44}) using total expectation \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\) and linearity $\mathbb{E}[\mathbf{X}+\mathbf{Y}] = \mathbb{E}[\mathbf{X}]+\mathbb{E}[\mathbf{Y}]$ as
\begin{equation}
\begin{aligned}
&\mathrm{tr}\bigg(\mathbb{E} [\widetilde{\mathbf{w}}^{(k)}_{t} (\widetilde{\mathbf{w}}^{(k)}_{t})^\mathrm{H} ]\bigg) = (\sigma^{(k)})^2\mathrm{tr}\bigg(\mathbb{E}\Big[(\psi_{k}\mathbf{S}_{\star}-\mathbf{D})^\mathrm{H}\mathbb{E}\Big[\sum_{\tau=0}^{t-1}|\psi_{k}|^{2(t-\tau-1)}\mathcal{\Phi}^\top_{\tau+1:t-1}\mathcal{\Phi}_{\tau+1:t-1}\Big](\psi_{k}\mathbf{S}_{\star}-\mathbf{D})\Big]\bigg),
 \end{aligned}
\label{pp4sww44}
\end{equation}
where \(\mathbf{S}_\star\) denotes a random graph shift operator that is not associated with any specific time stamp but is defined solely by its independence properties. Then, let $t\to \infty$, it holds
\begin{equation}
\begin{aligned}
\lim_{t\to \infty}\mathbb{E}\Big[\sum_{\tau=0}^{t-1}|\psi_{k}|^{2(t-\tau-1)}\mathcal{\Phi}^\top_{\tau+1:t-1}\mathcal{\Phi}_{\tau+1:t-1}\Big]\to \mathbf{W}^{(k)}_{\mathcal{\Phi}}=\sum_{\tau=0}^{\infty}\mathbb{E}\big[|\psi_{k}|^{2\tau}\mathcal{\Phi}_{0:\tau-1}^\top\mathcal{\Phi}_{0:\tau-1}\big].
 \end{aligned}
\label{pp}
\end{equation}
Finally, let $\mathbf{S}_{\star}$ be instantiated as $\mathbf{S}_{t}$ and follow the expansion rule (\ref{p215}). Then (\ref{p4}) follows. The proof is completed. 


\subsection{Proof of Lemma 1}
\label{app:l1}
We shall prove the convergence of \(\mathbf{W}^{(k)}_{\mathcal{\Phi}}\) from the spectral norm analysis. By applying Jensen's inequality $\big\Vert\mathbb{E}[\mathbf{X}]\big\Vert_{2}\le \mathbb{E}\big[\Vert\mathbf{X}\Vert_{2}\big]$, any subterm of \(\mathbf{W}^{(k)}_{\mathcal{\Phi}}\) satisfies
\begin{equation}
\begin{aligned}
\Big\Vert \mathbb{E} \big[|\psi_{k}|^{2\tau} \mathcal{\Phi}_{0:\tau-1}^\top \mathcal{\Phi}_{0:\tau-1}\big] \Big\Vert_{2} \leq \mathbb{E} \Big[\big\Vert |\psi_{k}|^{2\tau} \mathcal{\Phi}_{0:\tau-1}^\top\mathcal{\Phi}_{0:\tau-1} \big\Vert_{2}\Big].
\end{aligned}
\end{equation}
From the sub‐multiplicativity of the spectral norm \(\|\mathbf{XY}\|_{2} \leq \|\mathbf{X}\|_{2} \|\mathbf{Y}\|_{2}\), we can obtain  
\begin{equation}
\begin{aligned}
\mathbb{E} \Big[\big\Vert |\psi_{k}|^{2\tau} \mathcal{\Phi}_{0:\tau-1}^\top\mathcal{\Phi}_{0:\tau-1} \big\Vert_{2}\Big] \leq \mathbb{E} \Big[(\|\psi_{k} \mathbf{S}_{t}\|_{2})^{2\tau}\Big].
\end{aligned}
\end{equation}
Since \(\|\psi_k \mathbf{S}_{t}\|_{2} \leq |\psi_k \rho_{\star}| < 1\), it follows that
\begin{equation}
\begin{aligned}
\Big\Vert \mathbb{E} \big[|\psi_{k}|^{2\tau} \mathcal{\Phi}_{0:\tau-1}^\top \mathcal{\Phi}_{0:\tau-1}\big] \Big\Vert_{2} \leq \mathbb{E} \Big[(\|\psi_{k} \mathbf{S}_{t}\|_{2})^{2\tau}\Big] \leq |\psi_k \rho_{\star}|^{2\tau}.
\end{aligned}
\end{equation}
Since \(0 < |\psi_k \rho_{\star}| < 1\), the term \(|\psi_k \rho_{\star}|^{2\tau}\) converges. Then, $\mathbf{W}^{(k)}_{\mathcal{\Phi}}  = \sum_{\tau=0}^{\infty} \mathbb{E} \left[|\psi_{k}|^{2\tau} \mathcal{\Phi}_{0:\tau-1}^\top  \mathcal{\Phi}_{0:\tau-1}\right]$ converges. Finally, by applying total expectation \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\), (\ref{l1}) follows. The proof is completed.

\subsection{Proof of Lemma 2}
\label{app:l2}
Leveraging total expectation \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\), the term 
\begin{equation}
\begin{aligned}
& \mathbb{E}\bigg[\prod_{t'=1}^{\tau\leftarrow}\big(\mathbf{I}+(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_{t'}}\big)\times \prod_{t'=1}^{\rightarrow\tau}\big(\mathbf{I}+\mathbf{P}_{\mathcal{T}_{t'}} (\psi_k\mathbf{S} - \mathbf{I})\big)\bigg]\\
& = \mathbb{E}\bigg[ \prod_{t'=2}^{\tau\leftarrow}\big(\mathbf{I}+(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_{t'}}\big)\times \mathbb{E}\Big[\big(\mathbf{I}+(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_{1}}\big)\\ 
&\times\big(\mathbf{I}+\mathbf{P}_{\mathcal{T}_{1}} (\psi_k\mathbf{S} - \mathbf{I})\big)\Big]
\prod_{t'=2}^{\rightarrow\tau}\big(\mathbf{I}+\mathbf{P}_{\mathcal{T}_{t'}} (\psi_k\mathbf{S} - \mathbf{I})\big)\bigg].
\end{aligned}
\label{TERM}
\end{equation}
Then the middle expectation can be written as 
\begin{equation}
\begin{aligned}
 &\mathbb{E}\Big[\big(\mathbf{I}+(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_{1}}\big)\big(\mathbf{I}+\mathbf{P}_{\mathcal{T}_{1}} (\psi_k\mathbf{S} - \mathbf{I})\big)\Big]\\
 & = \mathbb{E}\Big[\mathbf{I}+|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{P}_{\mathcal{T}_{1}}\mathbf{S}-\mathbf{P}_{\mathcal{T}_{1}}\Big]\\
 & = \mathbf{I}+|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{P}\mathbf{S}-\mathbf{P},
\end{aligned}
\end{equation}
with the fact $\mathbf{P}_{\mathcal{T}_{t}}\mathbf{P}_{\mathcal{T}_{t}} = \mathbf{P}_{\mathcal{T}_{t}}$ and $\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}] = \mathbf{P}$. Since $\mathbf{P} = p\mathbf{I}$ and \(\Vert \psi_{k}\mathbf{S}\Vert_{2}<1 \to |\psi_{k}|^{2}\mathbf{S}^\top\mathbf{S}\prec \mathbf{I}\), we can have 
\begin{equation}
\begin{aligned}
 &\mathbf{I}+|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{P}\mathbf{S}-\mathbf{P}=\mathbf{I}+p|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{S}-p\mathbf{I}\prec\mathbf{I}.
\end{aligned}
\label{loose}
\end{equation}
This means $\exists \epsilon \in (0,1)$ makes (\ref{loose}) tight
\begin{equation}
\begin{aligned}
 \mathbf{I}+p|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{S}-p\mathbf{I}\preceq\epsilon\mathbf{I}.
\end{aligned}
\label{tight}
\end{equation}
By substituting (\ref{tight}) into (\ref{TERM}) and iteratively applying total expectation \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\), we have 
\begin{equation}
\begin{aligned}
& \mathbb{E}\bigg[\prod_{t'=1}^{\tau\leftarrow}\big(\mathbf{I}+(\psi^{*}_k\mathbf{S}^\top - \mathbf{I})\mathbf{P}_{\mathcal{T}_{t'}}\big) \times \prod_{t'=1}^{\rightarrow\tau}\big(\mathbf{I}+\mathbf{P}_{\mathcal{T}_{t'}} (\psi_k\mathbf{S} - \mathbf{I})\big)\bigg] \preceq\epsilon^{\tau}\mathbf{I}.
\end{aligned}
\label{upterm}
\end{equation}
As $\sum^{\infty}_{\tau=0}\epsilon^{\tau}\mathbf{I}$ is a geometric series that absolutely converges, then $\mathbf{W}^{(k)}_{\mathbf{P}}$ converges. Then by total expectation \(\mathbb{E}[\mathbf{X}] = \mathbb{E}[\mathbb{E}[\mathbf{X}|\mathbf{Y}]]\) again, (\ref{l2}) follows. The proof is completed. 
