\subsection{Proof of Remark 7}
\label{app:r7}
With the symmetry, $\Vert\mathbf{S}\Vert_{2}=\rho_{\star}$ holds. Then we can specify $\epsilon$ in (\ref{tight}) as
\begin{equation}
\begin{aligned}
\epsilon=\rho(\mathbf{I}+p|\psi_{k}|^{2}\mathbf{S}^\top\mathbf{S}-p\mathbf{I})= 1+p|\psi_{k}|^{2}\rho^{2}_{\star}-p.
\end{aligned}
\label{epss}
\end{equation}
By substituting (\ref{epss}) into (\ref{upterm}), we have
\begin{equation}
\begin{aligned}
\mathbf{W}^{(k)}_{\mathbf{P}} \preceq \sum^{\infty}_{\tau=0}(1+p|\psi_{k}|^{2}\rho^{2}_{\star}-p)^{\tau}\mathbf{I}=\frac{1}{p-p|\psi_{k}|^{2}\rho^{2}_{\star}}\mathbf{I}.
\end{aligned}
\label{upespp}
\end{equation}
Then, it shows 
\begin{equation}
\begin{aligned}
\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}\mathbf{W}^{(k)}_{\mathbf{P}}\mathbf{P}_{\mathcal{T}_t}] \preceq \frac{1}{p-p|\psi_{k}|^{2}\rho^{2}_{\star}}\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}\mathbf{P}_{\mathcal{T}_t}]=\frac{1}{1-|\psi_{k}|^{2}\rho^{2}_{\star}}\mathbf{I},
\end{aligned}
\label{upespp_2}
\end{equation}
with $\mathbf{P}_{\mathcal{T}_{t}}\mathbf{P}_{\mathcal{T}_{t}} = \mathbf{P}_{\mathcal{T}_{t}}$ and $\mathbb{E}[\mathbf{P}_{\mathcal{T}_t}] = \mathbf{P} =p\mathbf{I}$. Then by taking the spectral norm of (\ref{upespp_2}), (\ref{r7_final}) follows. The proof is completed. 

\section{Detailed Derivation of QEF-ATC for Regression over Networks}
In this section, we provide the detailed derivations of QEF-ATC for Section \ref{s5b}.
\subsection{Corollary of Theorem 2}
\label{Appb1}
Based on the noise propagation model by (\ref{Noiseppp}), its error feedback version
\begin{equation}
\begin{aligned}
\boldsymbol{\widetilde{\xi}}_{t} &= \mathcal{B}\mathcal{A}\boldsymbol{\widetilde{\xi}}_{t-1} + \mathcal{B}(\mathcal{A}-\mathcal{D})\boldsymbol{n}_{t-1},
\end{aligned}
\label{qefr1}
\end{equation}
where $\mathcal{D}=\mathrm{blkdiag}(\mathbf{D}_{1},\dots,\mathbf{D}_{N})$ and $\mathbf{D}_i\in\mathbb{R}^{M\times M}$. Analogous to Proposition \ref{prop2}, the total noise gain
\begin{equation}
    \begin{aligned}
     G_{\xi}+I_{\xi} & = \mathrm{tr} \Big( (\mathcal{A}-\mathcal{D})^\mathrm{H}\mathcal{B}^\mathrm{H}\mathbf{W}_{\xi}\mathcal{B}(\mathcal{A}-\mathcal{D})\Big)
    \end{aligned}
    \label{gig}
\end{equation}
with $G_{\xi}$ is the original noise gain and $I_{\xi}$ is the mitigation, respectively. By parameterizing $\mathbf{D}_i=\alpha_{i}\mathbf{I}$, $\mathcal{D}$ becomes a diagonal matrix and is linked to Theorem \ref{Th2}. Therefore, we can directly have the Corollary:
\begin{corollary}
    Given the propagation of noise (\ref{qefr1}) and the gain (\ref{gig}), the feedback coefficient $\alpha_i$ from $\mathbf{D}_i=\alpha_{i}\mathbf{I}$ satisfies 
    \begin{equation}
    \begin{aligned}
     \alpha_i & = \frac{\sum_{j=1}^{M}[\mathcal{B}^\mathrm{H}\mathbf{W}_{\xi}\mathcal{B}\mathcal{A}]_{\big((i-1)M +j\big)\big((i-1)M +j\big)}}{\sum_{j=1}^{M}[\mathcal{B}^\mathrm{H}\mathbf{W}_{\xi}\mathcal{B}]_{\big((i-1)M +j\big)\big((i-1)M +j\big)}}.
    \end{aligned}
    \label{gigss}
\end{equation}
\end{corollary}
\subsection{Equivalent Form of Algorithm}
\label{Appb2}
Here we show the QEF-ATC with differential quantization for the regression task. Based on (\ref{qefr1})-(\ref{gigss}), the explicit form of the quantized version of (\ref{ATC}) with error feedback is given by:
\begin{equation}
    \begin{aligned}
    \xi_{i,t} &= \mathbf{x}_{i,t-1} - \mu\nabla f_{i}(\mathbf{x}_{i,t-1})\\
    \hat{\xi}_{i,t}&=\hat{\xi}_{i,t-1}+\mathcal{Q}[\xi_{i,t}-\hat{\xi}_{i,t-1}] \\
    \mathbf{x}_{i,t} &= \sum_{j\in\mathcal{N}_{i}}w_{ij}\hat{\xi}_{i,t} - \alpha_i\mathbf{n}_{i,t-1}  
    \end{aligned}
\end{equation}
where the quantization noise is defined as $\mathbf{n}_{i,t-1} = (\xi_{i,t}-\hat{\xi}_{i,t-1})-\mathcal{Q}[\xi_{i,t}-\hat{\xi}_{i,t-1}]$. Notably, we apply error feedback during the combination step, as opposed to the more common approach of gradient compensation. This demonstrates that the benefits of error feedback are not limited to gradient compression.  
