\section{Derivation}
\subsection{Derivation of Eq.~\eqref{eq:timestep_reschedule}}
\label{append:derivation_timestep}
Starting from Eq.~\eqref{eq:endpoint_upsample}, the conditional distribution of the linear combination of upsampled latent $\text{Up}(\hat{\mathbf{x}}_{e_k})$ and the correlated noise $\mathbf{z} \sim \mathcal{N}(0, \mathbf{\Sigma'})$ is:
\begin{equation}
\label{append_eq:s1}
\left( a\text{Up}(\hat{\mathbf{x}}_{e_k}) + b\mathbf{z} \right) | \mathbf{x}_1 \sim  \mathcal{N}\left(ae_k\text{Up}(\mathbf{x}_1), \; a^2(1-{e_k})^2\Sigma + b^2\mathbf{\Sigma'}\right),
\end{equation}
where $\mathbf{\Sigma'} = \mathbf{I} - c\mathbf{\Sigma}$. The conditional distribution of the latent of next stage starting timestep $\text{Up}(\hat{\mathbf{x}}_{s_{k+1}})$is:
\begin{equation}
\label{append_eq:startpoint_upsample}
\text{Up}(\hat{\mathbf{x}}_{s_{k+1}}) | \mathbf{x}_1 \sim \mathcal{N}\left(s_{k+1}\text{Up}(\mathbf{x}_1), (1-{s_{k+1}})^2 \mathbf{\Sigma}\right)
\end{equation}

Since we want Eq.~\eqref{append_eq:s1} and Eq.~\eqref{append_eq:startpoint_upsample}, we can obtain the following equations for the mean and standard deviation, respectively:
\begin{equation}
\label{append_eq:mean_eq}
ae_k=s_{k+1},
\end{equation}
\begin{equation}
\label{append_eq:std_eq}
a^2(1-e_k)^2\mathbf{\Sigma}+b^2(\mathbf{I}-c\mathbf{\Sigma})=(1-s_{k+1})^2\mathbf{I}
\end{equation}

From Eqs.~(\ref{append_eq:mean_eq})–(\ref{append_eq:std_eq}), matching the $\mathbf{\Sigma}$ coefficient to zero gives
\begin{equation}
\label{append_eq:A1_1}
a^2(1-e_k)^2 = b^2c
\;\Longrightarrow\;
a(1-e_k)=b\sqrt{c}.
\end{equation}

Comparing the \(\mathbf I\) part,
\begin{equation}
\label{append_eq:A1_2}
b^2=(1-s_{k+1})^2 \;\Longrightarrow\; b=1-s_{k+1}.
\end{equation}

Collecting Eq.~\eqref{append_eq:mean_eq}, Eq.~\eqref{append_eq:A1_1} and Eq.~\eqref{append_eq:A1_2} yields:
\begin{equation}
s_{k+1} = \frac{e_k}{(1-e_k)/\sqrt{c} \; + e_k},
\end{equation}
\begin{equation}
a = \frac{1}{(1-e_k)/\sqrt{c} \; + e_k},
\end{equation}
\begin{equation}
b = \frac{(1-e_k)/\sqrt{c}}{(1-e_k)/\sqrt{c} \; + e_k}.
\end{equation}

Since $\mathbf{\Sigma'} = \mathbf{I} - c\mathbf{\Sigma} \succeq 0$, $0 \leq c \leq 1/4$ for 2× nearest-neighbor upsampling.

