The Power function  $P_{X_n}$  plays a central role in defining the \ac{tr} constraint in the proposed framework. Its properties are therefore critical to the convergence analysis of the  \ac{hktr} algorithm. In particular, it is essential that the Power function exhibits Hölder continuity. The following theorem establishes mild conditions under which this property holds.
\begin{theorem}(Hölder continuity of the Power function) \label{theorem_P_hölder}\\
Let $\Omega \subseteq \mathbb{R}^N$ be non-empty, $X_n = \{ x_j \}_{j=1}^n \subset \Omega$ be a pairwise distinct point set,  $k \in C^{2}(\Omega \times \Omega)$ be an \ac{spd} kernel with $k(x,\cdot): \Omega \rightarrow \mathbb{R}$ being uniformly Lipschitz continuous for all $x \in \Omega$, i.e., there exists a $C_k < \infty$ such that \begin{align*}
|k(x, \tilde{x}) - k(x, x')| \leq C_k \Vert\tilde{x} - x'\Vert \quad \forall \; \tilde{x}, x' \in \Omega,
\end{align*} then the Power function $P_{X_n}$ is Hölder continuous with $\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$, i.e.,
\begin{align*}
\left\vert P_{X_n}(x) - P_{X_n}(y) \right\vert \leq 4 \sqrt{C_k} \Vert x-y \Vert^{\frac{1}{2}} \quad \forall \; x,y \in \Omega.
\end{align*}
\end{theorem}
\begin{proof}
    It holds
    \begin{align}
        \left| P_{X_n}(x) - P_{X_n}(y) \right| &= \left| \left\Vert k(\cdot, x) - \Pi_{V(X_n)}(k(\cdot, x)) \right\Vert_{\mathcal{H}_k(\Omega)} - \left\Vert k(\cdot, y) - \Pi_{V(X_n)}(k(\cdot, y)) \right\Vert_{\mathcal{H}_k(\Omega)} \right| \nonumber \\
        &\leq  \left| \left\Vert k(\cdot, x) - k(\cdot, y)  + \Pi_{V(X_n)}(k(\cdot, y)) - \Pi_{V(X_n)}(k(\cdot, x))\right\Vert_{\mathcal{H}_k(\Omega)} \right| \label{eqn:theorem_P_hölder1} \\
                &\leq   \left\Vert k(\cdot, x) - k(\cdot, y)\right\Vert_{\mathcal{H}_k(\Omega)}  + \left\Vert \Pi_{V(X_n)}(k(\cdot, y) -k(\cdot, x))\right\Vert_{\mathcal{H}_k(\Omega)} \label{eqn:theorem_P_hölder2} \\
                &  \leq  2 \Vert k(\cdot, x) - k(\cdot, y)\Vert_{\mathcal{H}_k(\Omega)} \label{eqn:theorem_P_hölder3}\\
                &  = 2 \sqrt{ k(x, x) - k(x, y) + k(y, y) - k(y, x)} \label{eqn:theorem_P_hölder4}\\
                &\leq 2 \sqrt{|k(x,x) - k(x,y)| + |k(y,y) - k(y,x)|} \label{eqn:theorem_P_hölder5} \\
                 &  \leq  2 \sqrt{ |k(x, x) - k(x, y)|} + 2\sqrt{|k(y, y) - k(y, x)|} \label{eqn:theorem_P_hölder6}\\
                 &  \leq  4 \sqrt{C_k} \Vert x-y \Vert^{\frac{1}{2}}, \label{eqn:theorem_P_hölder7}
    \end{align}
    where we used the inverse triangle inequality in \eqref{eqn:theorem_P_hölder1}, the triangle inequality in \eqref{eqn:theorem_P_hölder2}, the submultiplicativity of the norm together with the fact that $\Vert\Pi_{V(X_n)}\Vert_{\mathcal{L}\left(\mathcal{H}_k(\Omega),\mathcal{H}_k(\Omega)\right)} = 1$ in \eqref{eqn:theorem_P_hölder3}, the reproducing property of the \ac{rkhs} in \eqref{eqn:theorem_P_hölder4}, the monotonicity of the square root in \eqref{eqn:theorem_P_hölder5}, the fact that $\sqrt{a +b} \leq \sqrt{a} + \sqrt{b}$ for $a, b \geq 0$ in \eqref{eqn:theorem_P_hölder6}  and the uniform Lipschitz continuity of the kernel in \eqref{eqn:theorem_P_hölder7}. 
\end{proof}
The Lipschitz continuity of the gradient of the kernel surrogate model is another key property in the convergence analysis of the \ac{hktr} algorithm introduced later. This property can be ensured under relatively mild conditions on the kernel, as demonstrated by the following theorem.
\begin{theorem}(Lipschitz continuity of the Hermite kernel interpolant) 
\label{thm:LipschitzDerivKernel} \\
Let $\Omega \subseteq \mathbb{R}^N$ be non-empty and $k \in C^{2}(\Omega \times \Omega)$ be an \ac{spd} kernel  with $\partial_1^l\partial_2^l k(x,\cdot): \Omega \rightarrow \mathbb{R}$ being uniformly Lipschitz continuous for all $x \in \Omega$ and all $l=1,...,N$ with maximum Lipschitz constant $C_{\nabla k} \geq 0$, then  the gradient of the Hermite kernel interpolant $ s_f^n = \Pi_{V(X_n)} f$ for $f \in \mathcal{H}_{k(\Omega)}$ is uniformly Lipschitz continuous w.r.t. the set of interpolation points. Specifically, there exists a constant $C_{k, \nabla k, f, N}
\geq 0$ such that \begin{align*}
    \left\Vert \nabla \left(\Pi_{V(X_n)} f\right)(x) - \nabla \left(\Pi_{V(X_n)} f\right)(x') \right\Vert \leq C_{k, \nabla k, f, N} \Vert x - x' \Vert \quad \textnormal{ for all } x, x' \in \Omega
\end{align*} 
for all finite, pairwise distinct subsets $X \subset \Omega$, where  $C_{k, \nabla k, f, N} := 2 C_{\nabla k}\sqrt{N}\Vert  f \Vert_{\mathcal{H}_k(\Omega)}$. 
\end{theorem}

\begin{proof}
We have
\begin{align} 
    &\left\Vert\nabla \left(\Pi_{V(X_n)} f\right)(x) - \nabla \left(\Pi_{V(X_n)} f\right)(x') \right\Vert^2 \nonumber \\
    =& \sum_{l=1}^N  \left| \partial^l \left(\Pi_{V(X_n)} f\right)(x) - \partial^l \left(\Pi_{V(X_n)} f\right)(x') \right|^2 \nonumber \\
    =& \sum_{l=1}^N  \left \langle \partial^l_1 k(x,\cdot)- \partial^l_1 k(x',\cdot), \Pi_{V(X_n)} f \right \rangle_{\mathcal{H}_k(\Omega)}^2 \label{eqn:theorem_s_Lip1} \\
        \leq & \sum_{l=1}^N \left\Vert \partial^l_1 k(x,\cdot)- \partial^l_1 k(x',\cdot) \right\Vert_{\mathcal{H}_k(\Omega)}^2  \left\Vert  \Pi_{V(X_n)} f \right\Vert_{\mathcal{H}_k(\Omega)}^2  \label{eqn:theorem_s_Lip2}\\
                \leq & \Vert  f \Vert_{\mathcal{H}_k(\Omega)}^2 \sum_{l=1}^N \left\Vert \partial^l_1 k(x,\cdot)- \partial^l_1 k(x',\cdot) \right\Vert_{\mathcal{H}_k(\Omega)}^2 \label{eqn:theorem_s_Lip3} \\ 
                %=& \sum_{l=1}^N \left\Vert \partial^l_1 k(x,\cdot)- \partial^l_1 k(x',\cdot) \right\Vert_{\mathcal{H}_k(\Omega)}^2  \left\Vert  \Pi_{V(X_n)} f \right\Vert_{\mathcal{H}_k(\Omega)}^2 \nonumber \\
                \leq & \Vert  f \Vert_{\mathcal{H}_k(\Omega)}^2 \sum_{l=1}^N  \left(\partial_1^l\partial_2^l k(x,x)- \partial_1^l\partial_2^l k(x,x') +\partial_1^l\partial_2^l k(x',x')- \partial_1^l\partial_2^l k(x',x) \right)^2 \label{eqn:theorem_s_Lip4}\\
          \leq& \Vert  f \Vert_{\mathcal{H}_k(\Omega)}^2\sum_{l=1}^N   \left( \left|\partial_1^l\partial_2^l k(x,x)- \partial_1^l\partial_2^l k(x,x') \right| +\left|\partial_1^l\partial_2^l k(x',x')- \partial_1^l\partial_2^l k(x',x)\right|\right)^2\label{eqn:theorem_s_Lip5}\\
          \leq& \Vert  f \Vert_{\mathcal{H}_k(\Omega)}^2\sum_{l=1}^N   \left(C_{\nabla k}\Vert x - x' \Vert +C_{ \nabla k} \Vert x - x' \Vert\right)^2 \label{eqn:theorem_s_Lip6} \\  
           \leq & \; 4C_{\nabla k}^2 \;  N \Vert  f \Vert_{\mathcal{H}_k(\Omega)}^2\Vert x - x' \Vert^2 \nonumber \\
           =& \; C_{k, \nabla k, f, N}^2 \Vert x - x' \Vert^2 \nonumber,
\end{align}
    where we used 
    \eqref{eq:repPropDeriv} in \eqref{eqn:theorem_s_Lip1}, the Cauchy-Schwartz inequality in \eqref{eqn:theorem_s_Lip2}, the submultiplicativity of the norm together with the fact that $\Vert\Pi_{V(X_n)}\Vert_{\mathcal{L}\left(\mathcal{H}_k(\Omega),\mathcal{H}_k(\Omega)\right)} = 1$ in \eqref{eqn:theorem_s_Lip3}, \eqref{eq:repPropDeriv} in \eqref{eqn:theorem_s_Lip4}, the  triangle inequality in \eqref{eqn:theorem_s_Lip5} and the uniform Lipschitz continuity of the kernel in \eqref{eqn:theorem_s_Lip6}.
\end{proof}

Popular kernels, that will be used in the numerical experiments in \Cref{chapter_numerical_examples} are: \begin{definition}(Widely used kernels)  \label{def:three_kernels} \\
The Gaussian kernel, defined as \begin{align*}
         k(x,x'; \varepsilon) &= \exp(-\varepsilon^2\Vert x - x'\Vert^2).
    \end{align*}
The quadratic Matérn kernel, defined as \begin{align*}
        k(x,x'; \varepsilon) &= (3 + 3\varepsilon  \Vert x - x'\Vert + \varepsilon^2\Vert x - x'\Vert^2)\exp(-\varepsilon \Vert x - x'\Vert).
    \end{align*}
The Wendland kernel of second order, defined as \begin{align*}
         k(x, x'; \varepsilon) &= \frac{(l + 4)!}{l!} \max(1 -\varepsilon\Vert x-x'\Vert, 0)^{l+2} \left( (l^2+ 4l +3)\varepsilon^2\Vert x-x'\Vert^2 + (3l + 6) \varepsilon\Vert x-x'\Vert + 3\right),
    \end{align*}
where  $l= \left\lfloor \sfrac{N}{2}\right\rfloor + 3$.

\end{definition} 

Note that these three kernels are \ac{spd} (Gaussian kernel: \cite[Theorem 6.10]{wendland_2004}, quadratic Matérn kernel: Can be concluded from \cite[Theorem 4.2] {Fasshauer_2011} together with \cite[Example 5.7]{Fasshauer_2011}, Wendland kernel of second order: \cite[Theorem 9.13]{wendland_2004}).
   %\ac{imq} kernel: Example 4.1 in \cite{michelli_1986}).
Furthermore, as so-called radial basis function kernels, they are also translation invariant. Additionally, these three kernels are at least in the function class $C^3( \Omega \times \Omega)$ and having the first, second, and third derivatives  bounded on $\mathbb{R}^N$. This guarantees with the mean value theorem that the uniformly Lipschitz continuity of $k(x,\cdot)$ and $\partial_1^l\partial_2^l k(x,\cdot)$ are satisfied. Therefore, the conditions of Theorem \ref{theorem_P_hölder} and Theorem \ref{thm:LipschitzDerivKernel} are satisfied for these kernels. 
