%for all iterations $i$, where $\kappa_{umh} $ is independent of $i$. 
%\end{assumption}

\begin{assumption}(Assumptions on $J$ and $\hat{J}^{(i)}$)
\label{assumption_list}
\begin{enumerate}[label=(\alph*)]
    \item The surrogate model $\hat{J}^{(i)}$ is twice differentiable for all iterations $i$. 
    \textnormal{We will use the \ac{bfgs} method to solve the subproblem (\ref{suboptimzation_problem_abstract}) presented in the next section. In order for a quasi-Newton scheme to converge, $C^2(\mathcal{P})$ of the function is required. This assumption is satisfied for the Hermite kernel surrogate model $\hat{J}^{(i)}$ using any of the kernel stated in \Cref{def:three_kernels}, as they are all at least in $C^3(\mathcal{P} \times \mathcal{P})$.}
    \item The objective function $J$ is uniformly bounded away from zero, i.e, there exists $c > 0$ s.t. $J(\mu) > c > 0$ for all parameters $\mu \in \mathcal{P}$. \textnormal{This assumption is not restrictive, as the boundedness from below is a usual assumption in minimization problems for physical applications, e.g., if $J(\mu)$ is an energy function. Therefore, if a lower global bound exists for $J(\mu)$, we can add a sufficiently large constant without changing the position of its local minima and ensure its strict positivity, cf.\,\cite{Keil_2021}.}
    \item For all iterations $i$, the kernel surrogate model $\hat{J}^{(i)}(\mu)$ is uniformly (w.r.t $\mu$ and $i$) bounded away from zero, i.e., there exists $c > 0$ s.t. $\hat{J}^{(i)}(\mu) > c > 0$ for all $\mu \in \mathcal{P}, i \in \mathbb{N}$.  \textnormal{Given that $\hat{J}^{(i)}$ is designed to approximate the objective function $J$ within the current \ac{tr}, this assumption appears justified. Moreover, we note that there exist techniques which, by construction, ensure this property for the (Hermite) kernel surrogate globally, cf.\,\cite[Section 3]{hermite_kernel_interpolation}.}
    \item  We require that $J \in \mathcal{H}_k(\mathcal{P})$. \textnormal{This assumption plays a crucial role, as it enables the estimation of the upper bound on the interpolation error stated in \eqref{eqn:def:interpolation error}, which is a fundamental component of Algorithm \ref{kernel_TR_algorithm}. Certainly not every kernel will be a suitable choice for every objective function $J$.}
    \item For all iterations $i$, the kernel surrogate model $\hat{J}^{(i)}$ as well as its gradient $\nabla \hat{J}^{(i)}$ are Lipschitz continuous on the parameter space $\mathcal{P}$. \textnormal{The reason behind assuming Lipschitz continuity for $\hat{J}^{(i)}$ and $\nabla \hat{J}^{(i)}$ is to prevent abrupt changes in these functions, which could pose challenges for gradient-based optimization algorithms. The remark after \Cref{def:three_kernels} guarantees this assumption for the Gaussian, the quadratic Matérn and the Wendland kernel of second order.}
\end{enumerate}
\end{assumption}


