%\end{align*}
%where $j^{(i)}_{\textnormal{AGC}}\in \mathbb{N}_0$ is the first nonegative integer, s.t. (\ref{subproblem_armijo_cond}) and (\ref{subproblem_constraint_cond}) hold for $l=0$. 
This point will serve the purpose of evaluating whether a new iterate $\mu^{(i+1)}$ achieves a satisfactory reduction in the objective function $J$ and can consequently be accepted. We adapt the ideas from \citep[Section 4.2]{Keil_2021} and \cite[Section 3.2.3]{YueMeerbergen} to the Hermite kernel setting for the remainder of this section. 

\begin{condition}(Sufficient decrease condition) \\
The sufficient decrease condition for the \ac{hktr} algorithm is \begin{align}
\label{error_aware_sufficient_decrease_condition}
J(\mu^{(i+1)}) \leq \hat{J}^{(i)}(\mu_{\textnormal{AGC}}^{(i)}). 
\end{align}
\end{condition}
The underlying motivation for this condition is that the \ac{agc} point $\mu_{\textnormal{AGC}}^{(i)}$ is expected to yield a decrease in the surrogate objective $\hat{J}^{(i)}$ relative to the current iterate $\mu^{(i)}$. This decrease will be formalized and rigorously proven in \Cref{section_convergence_theory_kernel_TR}.
%This condition plays a key part in the convergence analysis presented in \Cref{section_convergence_theory_kernel_TR}, specifically in the proof of Theorem \ref{theorem_convergence_kernel_tr}. 
If (\ref{error_aware_sufficient_decrease_condition}) is satisfied, we accept $\mu^{(i+1)}$, build the next kernel surrogate model $\hat{J}^{(i+1)}$ and continue to formulate the $(i+1)$-th optimization subproblem. However, checking (\ref{error_aware_sufficient_decrease_condition}) is computationally expensive, as we have to evaluate $J(\mu^{(i+1)})$. If the check \eqref{error_aware_sufficient_decrease_condition} fails, the point $\mu^{(i+1)}$ gets rejected and we wasted computational time. To prevent this scenario from occurring, we now establish sufficient and necessary conditions for (\ref{error_aware_sufficient_decrease_condition}) that do not require the evaluation $J(\mu^{(i+1)})$. This has the potential to significantly reduce the computational cost of the \ac{hktr} algorithm.

\begin{lemma}
\label{theorem_when_to_accept_iterate}
Using the definition of the upper bound on the interpolation error from \eqref{eq:eta_upper_bound}, \begin{enumerate}
\item a sufficient condition for (\ref{error_aware_sufficient_decrease_condition}) is \begin{align}
\label{eqn_requirement_acceptance}
\hat{J}^{(i)}(\mu^{(i+1)}) + \eta^{(i)}(\mu^{(i+1)}) \leq \hat{J}^{(i)}(\mu^{(i)}_{\textnormal{AGC}}),
\end{align}
\item a necessary condition for (\ref{error_aware_sufficient_decrease_condition}) is 
\begin{align}
\label{eqn_requirement_rejection}
\hat{J}^{(i)}(\mu^{(i+1)}) - \eta^{(i)}(\mu^{(i+1)}) \leq \hat{J}^{(i)}(\mu^{(i)}_{\textnormal{AGC}}).
\end{align}
\end{enumerate}
\end{lemma}
\begin{proof}
Sufficient condition: Using the definition of $\eta^{(i)}$ in \eqref{eq:eta_upper_bound} yields \begin{align*}
     J(\mu^{(i+1)}) \leq  \hat{J}^{(i)}(\mu^{(i+1)}) + \eta^{(i)}(\mu^{(i+1)}).
\end{align*}
by utilizing the inverse triangle inequality. Therefore, \eqref{eqn_requirement_acceptance} implies \eqref{error_aware_sufficient_decrease_condition}. Necessary condition: Similarly, it holds \begin{align*}
 J(\mu^{(i+1)}) \geq \hat{J}^{(i)}(\mu^{(i+1)}) - \eta^{(i)}(\mu^{(i+1)}).
\end{align*}
Therefore, if \eqref{error_aware_sufficient_decrease_condition} holds, also \eqref{eqn_requirement_rejection} is satisfied. 
\end{proof}
