\subsection{Convergence analysis}
\label{section_convergence_theory_kernel_TR}
To establish convergence of the kernel \ac{tr} algorithm 
(Algorithm~\ref{kernel_TR_algorithm}), it is assumed that the algorithm 
generates an infinite sequence of iterates 
$\left\{\mu^{(i)}\right\}_{i \in \mathbb{N}_0}$. 
In Theorem~\ref{auxilary_statements_from_YM}, a lower bound is derived for 
the decrease in \(\hat{J}^{(i)}\) achieved by \(\mu^{(i)}_{\textnormal{AGC}}\). 
A key assumption in the proof of Theorem~\ref{auxilary_statements_from_YM} 
is the Hölder continuity of \(c^{(i)}\), defined in the constraint of the 
subproblem \eqref{suboptimzation_problem_abstract}, with Hölder exponent 
$\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$. The following theorem demonstrates 
that this requirement is satisfied for \(c^{(i)}\) as defined in 
\eqref{suboptimzation_problem_advanced}.

\begin{lemma}
\label{lemma:c_hölder}
Let the conditions of Theorem \ref{theorem_P_hölder} be satisfied. Then $c^{(i)}$, defined in (\ref{suboptimzation_problem_advanced}) as \begin{align*}
c^{(i)}(\mu) = \delta^{(i)} - \frac{\eta^{(i)}(\mu)}{\hat{J}^{(i)}(\mu)} = \delta^{(i)} - \frac{P_{M^{(i)}}(\mu) \Vert J \Vert_{\mathcal{H}_k(\mathcal{P})}}{\hat{J}^{(i)}(\mu)}, 
\end{align*}
is Hölder continuous with the Hölder exponent $\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$, i.e., it exists $C_c^{(i)} \geq 0$ s.t. \begin{align*}
\left|c^{(i)}(\mu) - c^{(i)}(\tilde{\mu})\right| \leq C_c^{(i)} \Vert\mu - \tilde{\mu}\Vert^{\frac{1}{2}} \quad \forall \; \mu, \tilde{\mu} \in \mathcal{P}.
\end{align*} 
\end{lemma}

\begin{proof}
 Theorem \ref{theorem_P_hölder} states that $P_{M^{(i)}}$ is Hölder continuous with $\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$. According to Assumption \ref{assumption_list} c) and e), $\hat{J}^{(i)}$ is uniformly bounded away from zero and Lipschitz continuous. Thus, the fraction \begin{align*}
\frac{P_{M^{(i)}}(\mu)}{\hat{J}^{(i)}(\mu)}
\end{align*} is also Hölder continuous with $\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$. Since $\Vert J \Vert_{\mathcal{H}_k(\mathcal{P})}$ as well as $\delta^{(i)}$ are constant values, we obtain the desired result. \end{proof}

The next theorem is based on \citep[Theorem 3.2]{YueMeerbergen} .
%where we require $c^{(i)}$ defined in the optimization subproblem (\ref{suboptimzation_problem_abstract}) to be Hölder continuous with $\alpha_{H\textnormal{ö}l} = \sfrac{1}{2}$, whereas in \cite{YueMeerbergen}, only Lipschitz continuity of $c^{(i)}$ is required. On top of that, we include more mathematical details than the proof given in \cite{YueMeerbergen}. 
The theorem states a lower bound for the decrease in $\hat{J}^{(i)}$ achieved by the \ac{agc} point $\mu^{(i)}_{\textnormal{AGC}}$ and is the key result in the convergence analysis. 

\begin{theorem}
\label{auxilary_statements_from_YM}
Let the assumptions of Lemma \ref{lemma:c_hölder} be satisfied, s.t. $c^{(i)}$ is Hölder continuous with exponent $\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$ and Hölder constant $C_c^{(i)} > 0$.
Further, let Assumption \ref{assumption_list} e)  hold, i.e., $\nabla \hat{J}^{(i)}$ is Lipschitz continuous, so there exists $ C_{\nabla \hat{J}}^{(i)} > 0$ s.t. \begin{align*}
\left\Vert\nabla \hat{J}^{(i)}(\mu) - \nabla \hat{J}^{(i)}(\tilde{\mu})\right\Vert \leq C_{\nabla \hat{J}}^{(i)} \Vert \mu - \tilde{\mu}\Vert \quad \forall \; \mu, \tilde{\mu} \in \mathcal{P}.
\end{align*}
Let furthermore $\Phi^{(i)} < \frac{\pi}{2}$, $\kappa_{\textnormal{arm}} \in (0,1)$, $c^{(i)}(\mu^{(i)}) > 0$. Then, we obtain the following result: 
A lower bound for the decrease in $\hat{J}^{(i)}$ achieved by the \ac{agc} point $\mu_{\textnormal{AGC}}^{(i)}$ is given by \begin{align}
\label{theorem3.2_eqn315}
\hat{J}^{(i)} (\mu^{(i)}) - \hat{J}^{(i)} (\mu_{\textnormal{AGC}}^{(i)}) \geq \left(\kappa_{\textnormal{arm}} \cos \Phi^{(i)} \right) \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \min \left\{ \kappa_{\nabla \hat{J}}^{(i)} \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)})\right\Vert, \kappa_{\textnormal{bt}} \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)} \right)^2} \right\},
\end{align}
where $\kappa_{\nabla \hat{J}}^{(i)} := \min \left\{ 1, \frac{\kappa_{\textnormal{bt}}(1 - \kappa_{\textnormal{arm}})\cos \Phi^{(i)}}{C_{\nabla \hat{J}}^{(i)}} \right\}$.
\end{theorem}

\begin{proof}
    See Appendix \ref{appendix_proof_YM}.
\end{proof}

The following theorem is an adapted version of \citep[Theorem 3.3]{YueMeerbergen}. It shows the convergence of the objective function $J$, if the sufficient decrease condition (\ref{error_aware_sufficient_decrease_condition}) is satisfied for all iterations $i$. Furthermore, it requires uniformity in $i$ for the Hölder and Lipschitz constants defined in Theorem \ref{auxilary_statements_from_YM}, which is satisfied, as the Hölder constant in Theorem \ref{theorem_P_hölder} and the Lipschitz constant in Theorem \ref{thm:LipschitzDerivKernel} are independent of the number of interpolation points, i.e., independent of the iteration $i$.  

\begin{theorem}
\label{theorem_convergence_kernel_tr}
Assume that all conditions of Theorem \ref{auxilary_statements_from_YM} hold and $\Phi^{(i)} \leq \Phi < \frac{\pi}{2}$, $c^{(i)}(\mu^{(i)}) \geq c_l > 0$, $ 0 < C_c^{(i)} \leq C_c$, $0 < C_{\nabla \hat{J}}^{(i)} < C_{\nabla \hat{J}}$ for all $i$. Then, if the sufficient decrease condition (\ref{error_aware_sufficient_decrease_condition}) holds for all iterations $i$, we get: \begin{align*}
\lim_{i \rightarrow \infty} \left\Vert\nabla J(\mu^{(i)}) \right\Vert = 0.
\end{align*}
\end{theorem}

\begin{proof}
According to $J(\mu^{(i+1)}) = \hat{J}^{(i+1)}(\mu^{(i+1)})$, (\ref{error_aware_sufficient_decrease_condition}) and \eqref{theorem3.2_eqn315} we get \begin{align*}
\hat{J}^{(i)}(\mu^{(i)}) &- \hat{J}^{(i+1)}(\mu^{(i+1)})  \\
&\geq \hat{J}^{(i)}(\mu^{(i)}) - \hat{J}^{(i)}(\mu_{\textnormal{AGC}}^{(i)}) \\
&\geq \left(\kappa_{\textnormal{arm}} \cos \Phi^{(i)} \right) \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \min \left\{ \kappa_{\nabla \hat{J}}^{(i)} \; \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert, \kappa_{\textnormal{bt}} \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)} \right)^2} \right\}.
\end{align*}
Using summation, we end up with \begin{align*}
\hat{J}^{(0)}(\mu^{(0)}) &- \hat{J}^{(m)}(\mu^{(m)})  
\\ &\geq \kappa_{\textnormal{arm}} \sum_{i=0}^{m-1} \cos \Phi^{(i)} \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \min \left\{ \kappa_{\nabla \hat{J}}^{(i)} \; \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert, \kappa_{\textnormal{bt}} \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)}\right)^2} \right\},
\end{align*}
for all $m \in \mathbb{N}$, which can be seen via induction. Since \begin{align*}
\kappa_{\nabla \hat{J}}^{(i)} = \min \left\{ 1,  \frac{\kappa_{\textnormal{bt}}(1 - \kappa_{\textnormal{arm}}) \cos \Phi^{(i)}}{C_{\nabla \hat{J}}^{(i)}} \right\} \geq \min \left\{ 1, \frac{\kappa_{\textnormal{bt}}(1 - \kappa_{\textnormal{arm}}) \cos \Phi}{C_{\nabla \hat{J}}} \right\} =: \kappa_{\nabla\hat{J}},
\end{align*}
we get \begin{align*}
\hat{J}^{(0)}(\mu^{(0)}) &- \hat{J}^{(m)}(\mu^{(m)}) \\
&\geq (\kappa_{\textnormal{arm}} \cos \Phi) \sum_{i=0}^{m-1} \left\Vert \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \min \left\{ \kappa_{\nabla \hat{J}} \; \left\Vert\hat{J}^{(i)}(\mu^{(i)}) \right\Vert, \kappa_{\textnormal{bt}} \frac{c_l^2}{C_c^2} \right\}.
\end{align*}
Now we prove $\lim_{i \rightarrow \infty} \left\Vert\nabla J(\mu^{(i)}) \right\Vert = 0$ by contradiction. Assume there exists an $\epsilon \in \left(0, \left\Vert\nabla \hat{J}^{(0)}(\mu^{(0)}) \right\Vert \right)$ and a index-subsequence $\nu_j$ satisfying $\left\Vert \nabla \hat{J}^{(\nu_j)} (\mu^{(\nu_j)}) \right\Vert \geq \epsilon$ for all $j \in \mathbb{N}$ with $\nu_0 = 0$. Applying $\lim_{j \rightarrow \infty}$ on both sides of the previous inequality yields \begin{align*}
\lim_{j \rightarrow \infty} \hat{J}^{(0)} (\mu^{(0)}) - \hat{J}^{(\nu_j)}(\mu^{(\nu_j)}) \geq \lim_{j \rightarrow \infty} \kappa_{\textnormal{arm}} \cos \Phi \sum_{m=0}^{j-1} \epsilon \min \left\{ \kappa_{\nabla \hat{J}} \; \epsilon, \kappa_{\textnormal{bt}} \frac{c_l^2}{C_c^2} \right\} = + \infty,
\end{align*}
contradicting the fact that $\hat{J}^{(0)}(\mu^{(0)})$ is finite and $\hat{J}^{(i)}(\mu^{(i)})$ is bounded from below. Therefore, \begin{align*}
    \lim_{i \rightarrow \infty} \left\Vert\nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert = \lim_{i \rightarrow \infty} \left\Vert\nabla J(\mu^{(i)}) \right\Vert = 0.
\end{align*}   
\end{proof}

All assumptions of Theorem \ref{theorem_convergence_kernel_tr} are not very restrictive except that (\ref{error_aware_sufficient_decrease_condition}) has to be satisfied for all iterations $i$. In Section \ref{section_hermite_TR_kernel}, we have already discussed how to deal with the scenario where (\ref{error_aware_sufficient_decrease_condition}) is not satisfied and proposed sufficient and necessary conditions that should be utilized instead of (\ref{error_aware_sufficient_decrease_condition}). 

\subsection{Parameter constrained optimization problems}
\label{section:projected_hktr}
Until now, we focused on the optimization problem using the feasible set $\mathcal{P} = \mathbb{R}^p$. In this section, we comment on the required changes if we restrict the iterates to subsets  $\mathcal{P} \subset \mathbb{R}^p$ of the form \label{section_constrained_optimization}
\begin{align*}
\mathcal{P} := \left\{ \mu \in \mathbb{R}^p \; | \; \mu_a \leq \mu \leq \mu_b \right\} \subset \mathbb{R}^p.
\end{align*}
Here, we have $\mu_a, \mu_b \in (\mathbb{R} \cup \{ \pm \infty \})^p $ and $\leq$ should be understood component-wise. This is commonly referred to as box-constraints. The primary distinction compared to the unconstrained scenario is that we must ensure that all calculated iterates, both in the \ac{hktr} algorithm and when solving the optimization subproblem, remain within the specified parameter set $\mathcal{P}$. In order to describe this rigorously, we define a projection map that maps $\mu$ to the nearest point (measured in the Euclidean norm) in $\mathcal{P}$. 


\begin{definition}(Projection map) \\
We define the projection map $\Pi_{\mathcal{P}}: \mathbb{R}^p \rightarrow \mathcal{P}$ as \begin{align*}
(\Pi_{\mathcal{P}}(\mu))_m := \begin{cases}
(\mu_a)_m \quad \textnormal{ if } \mu_m \leq (\mu_a)_m \\
(\mu_b)_m \quad \textnormal{ if } \mu_m \geq (\mu_b)_m \\
(\mu)_m \quad \; \; \textnormal{ otherwise }
\end{cases}
\qquad \forall \; m=1,...,p.
\end{align*} 
\end{definition}

We also introduce \begin{align*}
\mu^{(i,l)}(j) := \Pi_{\mathcal{P}}(\mu^{(i,l)} + \kappa_{\textnormal{bt}}^j p^{(i,l)}) \textnormal{ for } j \geq 0, 
\end{align*}
in order to guarantee, that all iterates of the \ac{bfgs} algorithm and the Armijo backtracking search also lie within $\mathcal{P}$. We have to reformulate the termination criteria for the optimization subproblem as well as the one for the \ac{hktr} algorithm (Algorithm \ref{kernel_TR_algorithm}) as \begin{align*}
\left\Vert \mu^{(i,l)} - \Pi_{\mathcal{P}} \left( \mu^{(i,l)} - \nabla \hat{J}^{(i)} (\mu^{(i,l)}) \right) \right\Vert_\infty \leq \tau_{\textnormal{sub}},
\end{align*}
respectively 
\begin{align*}
\left\Vert \mu^{(i)} - \Pi_{\mathcal{P}} \left( \mu^{(i)} - \nabla \hat{J}^{(i)} (\mu^{(i)}) \right) \right\Vert_\infty \leq \tau_{\textnormal{FOC}}.
\end{align*}
The convergence proof of this projected version of the \ac{hktr}, which we will refer to as the \ac{phktr} algorithm, follows identical to the argumentation presented in Section \ref{section_convergence_theory_kernel_TR} and relies on the Lipschitz continuity of the projection map $\Pi_\mathcal{P}$ with Lipschitz constant $C=1$. We refer to \citep[Section 4.2]{Keil_2021}, which outlines a convergence proof based on such projected quantities. 

