\section{Proof of Theorem \ref{auxilary_statements_from_YM}}
\label{appendix_proof_YM}

\begin{proof}
We start by proving the following auxiliary result: (\ref{subproblem_armijo_cond}) and (\ref{subproblem_constraint_cond}) (for $\mu$ instead of $\mu^{(i)}(j)$) are satisfied for all $\mu$ of the form (\ref{eqn:lsForConvergence}) that satisfy
\begin{align}
\label{eqn:theorem_decrease_agc_first_aux_result}
\left\Vert\mu^{(i)} - \mu \right\Vert \leq \min \left\{ \frac{(1-\kappa_{\textnormal{arm}})\cos \Phi^{(i)} \left\Vert\nabla
\hat{J}^{(i)}(\mu^{(i)})\right\Vert}{C_{\nabla \hat{J}}^{(i)}}, \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)} \right)^2} \right\}.
\end{align}
If $\left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert = 0$, then (\ref{eqn:theorem_decrease_agc_first_aux_result}) implies $\Vert\mu^{(i)} - \mu\Vert = 0$, thus $ \mu = \mu^{(i)}$. Therefore, (\ref{subproblem_armijo_cond}) and (\ref{subproblem_constraint_cond}) hold trivially (for $\mu$ instead of $\mu^{(i)})$. Now we consider the case $\left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)})\right\Vert > 0$. We introduce the abbreviation \begin{align}
\label{eqn_def_descent_dir}
\nabla_{p^{(i)}} \hat{J}^{(i)} (\mu) := \left(\nabla \hat{J}^{(i)}(\mu) \right)^T p^{(i)}.
\end{align}
For a descent direction $p^{(i)}$ we have \begin{align}
\label{eqn_descent_dir}
\nabla_{p^{(i)}} \hat{J}^{(i)} (\mu^{(i)}) = - \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)})\right\Vert \left\Vert p^{(i)}\right\Vert \cos \Phi^{(i)} < 0.
\end{align}
Let us consider the equation \begin{align}
\label{theorem3.2_eqn316}
\nabla_{p^{(i)}} \hat{J}^{(i)} (\mu) = -  \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert  \left\Vert p^{(i)} \right\Vert \cos \Phi^{(i)},
\end{align}
which has at least one solution $\tilde{\mu}$ of the form (\ref{eqn:lsForConvergence}). We prove this by contradiction. Assume \eqref{theorem3.2_eqn316} has no solution. As $\nabla \hat{J}^{(i)}$ is Lipschitz continuous according to the assumption of this theorem, it is also continuous.
\begin{enumerate}[label=\roman*)]
\item Assume that $\nabla_{p^{(i)}} \hat{J}^{(i)} (\mu) < -  \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert  \left\Vert p^{(i)} \right\Vert \cos \Phi^{(i)}$ holds for all $\mu$ of the form (\ref{eqn:lsForConvergence}). Using Lagrange's mean value theorem yields existence of a $\bar{\mu} \in \left\{ \lambda \mu + (1 - \lambda) \mu^{(i)} \; | \; \lambda \in (0,1) \right\}$, s.t. \begin{align}
\label{eqn_mu_bar_kleiner}
\hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i)}) &= \left( \nabla \hat{J}^{(i)}(\bar{\mu}) \right)^T(\mu - \mu^{(i)}).
\end{align}
Note that $\bar{\mu}$ is also of the form (\ref{eqn:lsForConvergence}), as \begin{align*}
\bar{\mu} = \lambda \mu + (1 - \lambda) \mu^{(i)} = \lambda ( \mu^{(i)} + \alpha p^{(i)} ) + (1 - \lambda) \mu^{(i)} = \mu^{(i)} + \lambda \alpha p^{(i)},
\end{align*} 
using a scaled step length $\bar{\alpha} := \lambda \alpha \geq 0$. Therefore, \begin{align}
\label{mu_bar_follows_assumption}
\nabla_{p^{(i)}} \hat{J}^{(i)} (\bar{\mu}) < -  \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert \cos \Phi^{(i)},
\end{align}  holds and we can use this inequality to conclude \begin{align*}
\hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i)}) &= \left( \nabla \hat{J}^{(i)}(\bar{\mu}) \right)^T(\mu - \mu^{(i)}) \\
&= \left( \nabla \hat{J}^{(i)}(\bar{\mu}) \right)^T (\alpha p^{(i)}) \\
\overset{(\ref{eqn_def_descent_dir})}&{=} \alpha \; \nabla_{p^{(i)}} \hat{J}^{(i)} (\bar{\mu}) \\
\overset{(\ref{mu_bar_follows_assumption})}&{<}  - \alpha \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert \cos \Phi^{(i)} \\
&= - \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i,l)}) \right\Vert  \left\Vert\mu - \mu^{(i)} \right\Vert \cos \Phi^{(i)}.
\end{align*}
%Thus, we obtain \begin{align*}
%\hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i)}) < - \kappa_{\textnormal{arm}} \Vert \nabla \hat{J}^{(i)} (\mu^{(i)})\Vert\; \Vert\mu - \mu^{(i)}\Vert \cos \Phi^{(i)}
%\end{align*}
for all $\mu$ of the form (\ref{eqn:lsForConvergence}), even for the case $\Vert\mu - \mu^{(i)}\Vert \rightarrow \infty $. This indicates $\hat{J}^{(i)}(\mu) \rightarrow - \infty$, which contradicts Assumption \ref{assumption_list} b) , namely that $\hat{J}^{(i)}$ is bounded from below. Hence, this case is not possible. 
\item Now assume $\nabla_{p^{(i)}} \hat{J}^{(i)} (\mu) > -  \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert \cos \Phi^{(i)}$ holds for all $\mu$ of the form (\ref{eqn:lsForConvergence}). Analogously, we can conclude \begin{align*}
\hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i)}) > - \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \left\Vert\mu - \mu^{(i)} \right\Vert \cos \Phi^{(i)}
\end{align*}
for all $\mu$ of the form (\ref{eqn:lsForConvergence}). By choosing $\alpha=0$ we obtain $\mu = \mu^{(i)}$ and therefore \begin{align*}
0 = \hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i)}) > - \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert \underbrace{\left\Vert\mu - \mu^{(i)} \right\Vert}_{ = 0} \cos \Phi^{(i)} = 0,
\end{align*}
which is a contradiction. Consequently, it is also impossible for this case to occur. 
\end{enumerate}
Because neither case i) nor case ii) holds, we can conclude using the intermediate value theorem that a solution $\tilde{\mu}$ of the form (\ref{eqn:lsForConvergence}) for (\ref{theorem3.2_eqn316}) has to exist. 
As $\nabla \hat{J}^{(i)}$ is Lipschitz continuous by assumption, this solution satisfies \begin{align*}
\left\Vert \mu^{(i)} -\tilde{\mu} \right\Vert &\geq \frac{ \left\Vert\nabla \hat{J}^{(i)}(\tilde{\mu}) - \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert}{C_{\nabla \hat{J}}^{(i)}} = \frac{ \left\Vert\nabla \hat{J}^{(i)}(\tilde{\mu}) - \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert}{C_{\nabla \hat{J}}^{(i)} \left\Vert p^{(i)} \right\Vert} \\
&\geq \frac{ \left|\nabla_{p^{(i)}} \hat{J}^{(i)} (\tilde{\mu}) - \nabla_{p^{(i)}} \hat{J}^{(i)} (\mu^{(i)}) \right|}{C_{\nabla \hat{J}}^{(i)} \left\Vert p^{(i)} \right\Vert} = \frac{(1 - \kappa_{\textnormal{arm}})\cos \Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert}{C_{\nabla \hat{J}}^{(i)}},
\end{align*}
where we used the Cauchy-Schwarz inequality to obtain the second inequality and (\ref{eqn_descent_dir}) as well as (\ref{theorem3.2_eqn316}) to obtain the last equality. We show that (\ref{subproblem_armijo_cond}) holds for all $\mu$ of the form (\ref{eqn:lsForConvergence}) satisfying \begin{align}
\label{eqn_mu_mui}
\left\Vert\mu^{(i)} - \mu \right\Vert \leq \frac{(1 - \kappa_{\textnormal{arm}})\cos \Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert}{C_{\nabla \hat{J}}^{(i)}}.
\end{align}
First note that for $\bar{\mu}$ introduced in \eqref{eqn_mu_bar_kleiner} the following holds \begin{align}
\label{eqn_mu_bar_kleiner_2}
\left\Vert\bar{\mu} - \mu^{(i)} \right\Vert = \left\Vert \lambda \mu + (1 - \lambda) \mu^{(i)} - \mu^{(i)} \right\Vert = \left\Vert \lambda ( \mu - \mu^{(i)} ) \right\Vert \leq \left\Vert \mu - \mu^{(i)} \right\Vert.
\end{align}
%For all $\bar{\mu}$ s.t. $\Vert \bar{\mu} - \mu^{(i,l)} \Vert \leq \Vert \mu - \mu^{(i,l)} \Vert$, we obtain 
Let $\mu$ be of form \eqref{eqn:lsForConvergence} s.t. \eqref{eqn_mu_mui} holds. By first utilizing the Cauchy-Schwarz inequality, followed by the Lipschitz continuity of $\nabla \hat{J}^{(i)}$ and inequality (\ref{eqn_mu_bar_kleiner_2}), we obtain
\begin{align*}
\left|\nabla_{p^{(i)}} \hat{J}^{(i)} (\bar{\mu}) - \nabla_{p^{(i)}} \hat{J}^{(i)} (\mu^{(i)}) \right| &\leq \left\Vert\nabla \hat{J}^{(i)}(\bar{\mu}) - \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert \\
 &\leq C_{\nabla \hat{J}}^{(i)} \; \left\Vert\bar{\mu} - \mu^{(i)} \right\Vert \left\Vert p^{(i)}\right\Vert\\
 &\leq C_{\nabla \hat{J}}^{(i)} \; \left\Vert\mu - \mu^{(i)}\right\Vert \left\Vert p^{(i)}\right\Vert \\
\overset{(\ref{eqn_mu_mui})}&{\leq} C_{\nabla \hat{J}}^{(i)} \; \frac{(1 - \kappa_{\textnormal{arm}})\cos \Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert}{C_{\nabla \hat{J}}^{(i)}} \left\Vert p^{(i)} \right\Vert \\ 
&= (1 - \kappa_{\textnormal{arm}})\cos \Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert \\
\overset{(\ref{eqn_descent_dir})}&{=} - \kappa_{\textnormal{arm}} \cos \Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert - \nabla_{p^{(i)}} \hat{J}^{(i)} (\mu^{(i)}),
\end{align*}
yielding \begin{align}
\label{eqn_upper_bound_nabla_derivative}
\nabla_{p^{(i)}} \hat{J}^{(i)} (\bar{\mu}) \leq - \kappa_{\textnormal{arm}} \cos \Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert.
\end{align}
%for all $\bar{\mu}$ s.t. $\Vert \bar{\mu} - \mu^{(i,l)} \Vert \leq \Vert \mu - \mu^{(i,l)} \Vert$. We rewrite the \ac{lhs} of  (\ref{subproblem_armijo_cond}) using Lagrange's mean value theorem \begin{align*}
%\hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i,l)}) &= ( \nabla \hat{J}^{(i)}(\bar{\mu}))^T(\mu - \mu^{(i,l)}),
%\end{align*}
%with $ \bar{\mu} := \lambda \mu + (1 - \lambda) \mu^{(i,l)}$ for some $\lambda \in (0,1)$. Then \begin{align*}
%\Vert\bar{\mu} - \mu^{(i,l)}\Vert = \Vert \lambda ( \mu - \mu^{(i,l)} ) \Vert \leq \Vert \mu - \mu^{(i,l)}\Vert
%\end{align*}  
%holds. Therefore, (\ref{eqn_upper_bound_nabla_derivative}) is applicable for $\bar{\mu}$
We can now conclude that
\begin{align*}
\hat{J}^{(i)}(\mu) - \hat{J}^{(i)}(\mu^{(i)}) &= \left( \nabla \hat{J}^{(i)}(\bar{\mu}) \right)^T(\mu - \mu^{(i)} ) \\
\overset{(\ref{eqn_def_descent_dir})}&{=} \alpha \; \nabla_{p^{(i)}} \hat{J}^{(i)} (\bar{\mu}) \\
\overset{(\ref{eqn_upper_bound_nabla_derivative})}&{\leq} - \alpha \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert \left\Vert p^{(i)} \right\Vert  \cos \Phi^{(i)} \\
&=  - \kappa_{\textnormal{arm}} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert\ \left\Vert\mu - \mu^{(i)} \right\Vert \cos \Phi^{(i)}, 
\end{align*}
thus (\ref{subproblem_armijo_cond}) holds. Due to the Hölder continuity of $c^{(i)}$ with $\alpha_{\textnormal{Höl}} = \sfrac{1}{2}$, a solution $\tilde{\tilde{\mu}}$ of $c^{(i)}(\mu) = 0$ satisfies \begin{alignat*}{2}
&\left\Vert \mu^{(i)} - \tilde{\tilde{\mu}} \right\Vert^{\frac{1}{2}} &&\geq \frac{ \left|c^{(i)}(\mu^{(i)}) - c^{(i)}(\tilde{\tilde{\mu}})\right|}{C_c^{(i)}} = \frac{c^{(i)}(\mu^{(i)})}{C_c^{(i)}} \\
\Longleftrightarrow \quad &\left\Vert \mu^{(i)} - \tilde{\tilde{\mu}} \right\Vert &&\geq \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)} \right)^2}
\end{alignat*}
which means that (\ref{subproblem_constraint_cond}) holds for all $\mu$ of the form (\ref{eqn:lsForConvergence}) satisfying \begin{align*}
\left\Vert \mu^{(i)} - \mu \right\Vert \leq \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)} \right)^2},
\end{align*} 
because then we obtain \begin{align*}
\left|c^{(i)}(\mu^{(i)}) - c^{(i)}(\mu) \right| &\leq C_c^{(i)} \left\Vert \mu^{(i)} - \mu \right\Vert^{\frac{1}{2}} \leq C_c^{(i)} \frac{c^{(i)}(\mu^{(i)})}{C_c^{(i)}} = c^{(i)}(\mu^{(i)}),
\end{align*}
yielding the desired result $c^{(i)} (\mu) \geq 0$, as we assume $c^{(i)}(\mu^{(i)}) > 0$. This proves the auxiliary result (\ref{eqn:theorem_decrease_agc_first_aux_result}). \\

We continue by proving another auxiliary statement, namely: The \ac{agc} point $\mu_{\textnormal{AGC}}^{(i)}$ satisfies \begin{align}
\label{eqn:theorem_descrease_agc_second_aux}
\left\Vert \mu_{\textnormal{AGC}}^{(i)} - \mu^{(i)} \right\Vert \geq \min \left\{ \kappa_{\nabla \hat{J}}^{(i)} \left\Vert\nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert, \kappa_{\textnormal{bt}} \frac{c^{(i)}(\mu^{(i)})^2}{(C_c^{(i)})^2} \right\},
\end{align}
where $\kappa_{\nabla \hat{J}}^{(i)} := \min \left\{ 1, \frac{\kappa_{\textnormal{bt}}(1 - \kappa_{\textnormal{arm}})\cos \Phi^{(i)}}{C_{\nabla \hat{J}}^{(i)}} \right\}$. The first line search point  $\mu^{(i)}(0) = \mu^{(i)} + p^{(i)}$ satisfies \begin{align}
\label{eqn_upper_bound_first_iterate_agc_proof}
\left\Vert \mu^{(i)}(0) - \mu^{(i)} \right\Vert = \left\Vert p^{(i)} \right\Vert = \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert.
\end{align}
If $\mu^{(i)}(0)$ satisfies (\ref{eqn:theorem_decrease_agc_first_aux_result}), it gets accepted as $\mu_{\textnormal{AGC}}^{(i)}$. In this case, the required upper bound \eqref{eqn:theorem_descrease_agc_second_aux} holds trivially due to (\ref{eqn_upper_bound_first_iterate_agc_proof}) as $ \kappa_{\nabla \hat{J}}^{(i)} \leq 1$: \begin{align*}
\left\Vert \mu^{(i)}(0) - \mu^{(i)} \right\Vert \geq \min \left\{ \kappa_{\nabla \hat{J}}^{(i)} \; \left\Vert \nabla \hat{J}^{(i)} (\mu^{(i)}) \right\Vert, \kappa_{\textnormal{bt}} \frac{c^{(i)}(\mu^{(i)})^2}{(C_c^{(i)})^2} \right\}.
\end{align*} 
 If $\mu^{(i)}(0)$ is not accepted as $\mu_{\textnormal{AGC}}^{(i)}$, backtracking occurs. However, it must stop before \begin{align}
\label{gleichung319}
\left\Vert\mu^{(i)}(j) - \mu^{(i)} \right\Vert \leq \kappa_{\textnormal{bt}} \min \left\{ \frac{(1 - \kappa_{\textnormal{arm}})\cos\Phi^{(i)} \left\Vert \nabla \hat{J}^{(i)}(\mu^{(i)}) \right\Vert}{C_{\nabla \hat{J}}^{(i)}} , \frac{\left(c^{(i)}(\mu^{(i)})\right)^2}{\left(C_c^{(i)}\right)^2} \right\}
\end{align}
holds, since otherwise the previous backtracking point $\mu^{(i)}(j-1)$ would satisfy  (\ref{eqn:theorem_decrease_agc_first_aux_result}) and thus be already accepted as $\mu_{\textnormal{AGC}}^{(i)}$. Therefore, (\ref{gleichung319}) cannot hold for $\mu_{\textnormal{AGC}}^{(i)}$. According to these two arguments, $\mu^{(i)}_{\textnormal{AGC}}$ satisfies (\ref{eqn:theorem_descrease_agc_second_aux}). \\

Now the desired result \eqref{theorem3.2_eqn315} follows immediately from (\ref{subproblem_armijo_cond}) and (\ref{eqn:theorem_descrease_agc_second_aux}).
\end{proof}

\section{Computation of the \ac{rkhs}-norm from Section \ref{subsection_numerical_examples_1D}}
%\section*{Appendix A: }
\label{appendix_rhhsnorm}
Following \cite[Theorem 10.12]{wendland_2004}, the \ac{rkhs}-norm - corresponding to a translation invariant \ac{spd} kernel $k$ with $\phi \in C(\mathbb{R}) \cap L^1(\mathbb{R})$ - of a univariate function $J \in L^2(\mathbb{R}) \cap C(\mathbb{R})$,  s.t $\frac{\mathcal{F}(J)}{\sqrt{\mathcal{F}(\phi)}} \in L^2(\mathbb{R})$,  can be computed via 
\begin{align*}
    \Vert J\Vert_{\mathcal{H}_{k}}^2 = \frac{1}{\sqrt{2 \pi}} \int_{\mathbb{R}} \frac{|\mathcal{F}(J)(\omega)|^2}{\mathcal{F}(\phi)(\omega)} d\omega,
\end{align*}
where $\mathcal{F}$ denotes the Fourier transformation, given for $J \in L^1(\mathbb{R})$ by  \begin{align*}
    \mathcal{F}(J)(\omega) := \frac{1}{\sqrt{2 \pi}} \int_{\mathbb{R}} J(x) \exp(- i \omega x) dx.
\end{align*}
For the Fourier transformations of the target function $J(\mu) = - \exp\left(-\mu^2\right) + 3 \exp(- 0.001 \mu^2)$ and the radial basis function of the Gaussian kernel (in one dimension) $\phi_G(r;\varepsilon) := \exp(- \varepsilon^2 r^2) $ we obtain: \begin{align*}
    \mathcal{F}(J)(\omega) &= - \exp\left(- \frac{\omega^2}{4}\right) + 67082 \exp(-250 \omega^2) \\
    \mathcal{F}(\phi_G)(\omega) &= \frac{1}{\sqrt{2 \varepsilon^2}} \exp\left(- \frac{\omega^2}{4 \varepsilon^2}\right).
\end{align*}

Together this yields for $\varepsilon^2 > \sfrac{1}{2}$ the following result {\small \[
    \Vert J \Vert_{\mathcal{H}_{k}(\mathcal{P})}^2 = \frac{\varepsilon^2 \left(\sqrt{2000\varepsilon^{2} - 1} \left( \sqrt{1001 \varepsilon ^{2} - 1} - 33541 \cdot 2^{\frac{5}{2}} \sqrt{2\varepsilon^{2} - 1}\right) + 8999989448 \sqrt{2 \varepsilon^{2} - 1} \sqrt{1001\varepsilon^{2} - 1}\right)}{\sqrt{2\varepsilon^{2} - 1} \sqrt{1001\varepsilon^{2} - 1} \sqrt{2000\varepsilon^{2} - 1}}.
\]}

