The following hypothesis captures the notion of an extension of some difference field~$F$
that contains “enough” $F$-hypergeometric solutions of the linear equation~\eqref{eq:linear-sigma}
to suitably describe the “full” solution set of the Riccati equation~\eqref{eq:riccati-sigma} in~$F$.
The hypothesis is illustrated in Figure~\ref{fig:unsurprizing-ring}.

\begin{hyp}\label{def:propertyP}
Let $F$ be a difference field extension of\/~$\rat\bK$,
with constant field\/~$\bL$ containing~$\bK$.
A difference ring extension~$\dring$ of~$F$ is
said to satisfy Hypothesis~\ref{def:propertyP}
if
\begin{enumerate}%[label=H\arabic*]
\item \label{it:universal-constant}
  the constant ring of~$\dring$ is the field\/~$\bL$,
\item \label{it:universal-1}
  for each nonzero~$u \in F$, the equation $\sigma y = uy$ has nonzero solutions in~$\dring$,
\item \label{it:universal-simplicity}
  $\dring$~is simple, meaning that $\sigma$~is an automorphism
  and that the only ideals of~$\dring$ stable under~$\sigma$ are $(0)$ and~$\dring$.

\end{enumerate}

\end{hyp}

In contrast with the classical theory,
we do not consider any universal Picard--Vessiot algebra
\parencites[Prop.~1.33]{PutSinger-1997-GTD}[Theorem~35]{Roques-2018-ARB}:
by point~\ref{it:universal-1},
only equations of order~$1$ are known to have solutions in~$\dring$.
On the other hand, Hypothesis~\ref{def:propertyP} ensures the following natural bound on the dimension of solution space.

\begin{lem}\label{lem:has-Property-U}
Let $\dring \supseteq F \supseteq \rat\bK$ be difference rings satisfying
of Hypothesis~\ref{def:propertyP}
for a suitable constant field\/~$\bL$ containing~$\bK$.

Then, the extension~$\dring$ is such that
  for any linear difference equation~\eqref{eq:linear-sigma} of order~$r$ with coefficients in\/~$\rat\bK$,
  the vector space of solutions in~$\dring$ of this equation
  has dimension at most~$r$ over~$\bL$.

\end{lem}

\begin{proof}
By the assumption of simplicity
\parencites[Def.~1.1]{PutSinger-1997-GTD}[Def.\ 4.1 and~4.4]{Singer-2016-AAA},
the ring~$\dring^\sigma$ of constants
is a field \parencite[Lemma~1.7]{PutSinger-1997-GTD}.
By our assumption $\ell_0\ell_r \neq 0$ made in the introduction (Hypothesis~\ref{hyp:l0-neq-0}),
the companion matrix~$A$ of~$L$ is invertible over~$\rat\bK$
and hence nonsingular over~$\dring$.
Suppose $y_1$, \dots, $y_m$ are $\bL$-linearly independent solutions of~$Ly = 0$,
and, for $1\leq i\leq m$, introduce $Y_i = (y_i,\sigma y_i,\dots,\sigma^{r-1}y_i)^T$,
which satisfies $\sigma Y_i = A Y_i$.
By point~\ref{it:universal-constant} and \parencite[Lemma~4.8]{Singer-2016-AAA},
this family~$\{Y_i\}_{i=1}^m$ of solutions of $\sigma Y = AY$,
which is linearly independent over~$\bL$,
is linearly independent over~$\dring$ in the free $\dring$-module~$\dring^r$.
By the commutativity of~$\dring$, the relation~$m \leq r$ holds,
thus proving the lemma.
\end{proof}




\subsection{Parametrization of the solution set}
\label{sec:parametrization}
Let $F$ be a fixed difference field extension of~$\rat\bK$.
Note that an extension~$\dring$ of~$F$ satisfying Hypothesis~\ref{def:propertyP} is only a ring,
so $\sigma y/y$~is not defined for all~$y\in \dring$.
However, restricting to nonzero $F$-hypergeometric~$y$ makes $1/y$ well defined,
as stated in the following lemma.

\begin{lem}\label{lem:invertible-hypergeom}
Any nonzero $F$-hypergeometric element~$y$
of some  difference ring extension~$\dring$ satisfying Hypothesis~\ref{def:propertyP} over~$F$
has an $F$-hypergeometric inverse in~$\dring$.
\end{lem}
\begin{proof}
For any nonzero $F$-hypergeometric~$y \in \dring$,
introduce~$u\in F$ satisfying $\sigma y = uy$.
The ideal generated by~$y$ in~$D$ contains~$1$ by simplicity,
so $y$~has an inverse~$z$.
Consequently, $\sigma z = 1/(\sigma y) = 1/(uy) = (1/u) \, z$,
proving that $z$~is $F$-hypergeometric.
\end{proof}

We now define similarity, a key concept in what follows.
\begin{defi}\label{def:similarity}
Given a difference field extension $F$ of\/ $\rat\bK$
and a difference ring extension~$\dring$ of $F$,
two elements $y_1$ and~$y_2$ of~$\dring$ are $F$-similar
if there exists a nonzero~$q \in F$ satisfying $y_1 = q y_2$.
\end{defi}
Similarity is an equivalence relation,
and $y_1$ and~$y_2$ in the definition
are either both nonzero or both zero.
In what follows, we focus on nontrivial equivalence classes,
that is, other than~$\{0\}$, which therefore do not contain~$0$.
We will denote
such nontrivial similarity classes by~$\nonz{\fH}$,
reserving for the augmentation by~$0$ of these similarity classes
the notation $\fH = \nonz{\fH} \cup \{0\}$.
(Cf.\ Notation~\ref{notation:general} in the introduction.)

\begin{lem}\label{thm:F-sim-F-hyp-is-L-vec}
For any $F$-similarity class~$\nonz{\fH}$ of $F$-hypergeometric elements,
the set~$\fH$ is an~$\bL$-vector space.
\end{lem}
\begin{proof}
Because $\bL$ is a subfield of~$F$, $\fH$~is an $\bL$-cone.
We show that it is also stable under addition.
Consider two elements $y_1$ and~$y_2$ in~$\nonz{\fH}$ such that $y_1+y_2 \neq 0$,
and $u$ and~$q$ in~$\nonz{F}$ such that $\sigma y_1 = u y_1$ and~$y_2 = q y_1$.
Then, as~$q \neq -1 \neq \sigma q$,
$\sigma(y_1+y_2) = (1+\sigma q) u y_1 = (1+\sigma q)(1+q)^{-1} u (y_1+y_2)$,
from which follows that $y_1+y_2$~is $F$-hypergeometric and $F$-similar to~$y_1$,
thus in~$\nonz{\fH}$.
\end{proof}

We use the notation~$\projzn{V}$
to denote the projectivization of a vector space~$V$,
leaving implicit the field over which $V$~is defined.
We also write~$\bP^n(K)$
for the $K$-projective space $\projzn{K^{n+1}}$ of dimension~$n$ over a field~$K$.

\begin{thm}\label{thm:structure-main}
Let $\dring$~be a  difference ring extension of~$F$ satisfying Hypothesis~\ref{def:propertyP}.
For a fixed~\eqref{eq:linear-sigma}, the following holds:
\begin{enumerate}
%
\item\label{it:vect-H}
The $\bL$-cone of $F$-hypergeometric solutions of~\eqref{eq:linear-sigma} in~$\dring$
naturally partitions into the class~$\{0\}$
and nontrivial $F$-similarity classes~$\nonz{\fH}$.
Moreover, the $\bL$-cones~$\fH$ are $\bL$-vector spaces in direct sum, and
their dimensions add up to at most~$r$.
%
\item\label{it:param-H}
The set of solutions in~$F$ of~\eqref{eq:riccati-sigma} partitions
into the images under the map $y \mapsto \sigma y/y$
of all nontrivial\/ $F$-similarity classes
of the set of\/ $F$-hy\-per\-geo\-met\-ric solutions of~\eqref{eq:linear-sigma}.
%
\item\label{it:param-U}
Each nontrivial\/ $F$-similarity class~$\nonz{\fH} \subseteq \dring$
of the set of\/ $F$-hy\-per\-geo\-met\-ric solutions of~\eqref{eq:linear-sigma}
induces a one-to-one parametrization of its image under $y \mapsto \sigma y/y$
by the $\bL$-projective space~$\projzn{\fH}$.
%
\item\label{it:disjoint-U}
The sum of the dimensions of the parametrizing $\bL$-projective spaces~$\projzn{\fH}$
does not exceed the order~$r$ of the equation~\eqref{eq:linear-sigma}
minus the number of nontrivial similarity classes~$\nonz{\fH}$.
%
\end{enumerate}
\end{thm}
%
\begin{proof}
\begin{trivlist}

\item \ \ \ref{it:vect-H}.
For each $F$-similarity class~$\nonz{\fH}$ of $F$-hypergeometric solutions of~$L$,
Lemma~\ref{thm:F-sim-F-hyp-is-L-vec} implies that $\fH$~is an $\bL$-vector space.
We now prove that all the~$\fH$ are in direct sum.
Given a relation $\lambda_0y_0 + \dots + \lambda_Ny_N = 0$
with coefficients~$\lambda_k \in \nonz{\bL}$
between nonzero $F$-hypergeometric solutions~$y_k$
in distinct $F$-similarity classes,
introduce $u_k\in F$ such that $\sigma y_k = u_ky_k$ for~$0\leq k\leq N$.
Applying~$\sigma - u_0$ yields
\begin{equation}\label{eq:shorter-rel}
\lambda_1(u_1-u_0)y_1 + \dots + \lambda_N(u_N-u_0)y_N = 0 .
\end{equation}
Because the~$y_k$ were taken from distinct classes,
each of the~$y_0/y_k$, which exists by Lemma~\ref{lem:invertible-hypergeom},
cannot be in~$F$, let alone be a constant.
So, $\sigma\bigl(y_0/y_k\bigr) = \bigl(u_0/u_k\bigr) \times \bigl(y_0/y_k\bigr)$ is not~$y_0/y_k$,
and $u_0/u_k$~is not~$1$.
Therefore,
none of the coefficients $\lambda_k(u_k-u_0)$ for $1\leq k\leq N$ is zero,
and \eqref{eq:shorter-rel}~is a shorter nontrivial relation.
Iterating the process, we obtain that some~$y_k$ is zero, a contradiction.
As a consequence, the $\bL$-vector spaces~$\fH$
are in direct sum.
By the conclusion of Lemma~\ref{lem:has-Property-U},
this direct sum is included in an $\bL$-space of dimension at most~$r$,
hence the dimension bound.

\item \ \ \ref{it:param-H}.
Given a solution~$u \in F$ of~\eqref{eq:riccati-sigma},
Lemma~\ref{lem:linear-riccati-equiv} implies
that $\sigma-u$~is a right-hand factor of~$L$.
Because of Hypothesis~\ref{def:propertyP}, there exists~$y\neq0$ such that $\sigma y = uy$,
and $y$~is invertible by Lemma~\ref{lem:invertible-hypergeom}.
As a consequence, $y$~is also a solution of~\eqref{eq:linear-sigma}
and $u$~equals~$\sigma y/y$.
So the map $y \mapsto \sigma y/y$ is a (well-defined) surjection
from the set of nonzero $F$-hypergeometric solutions of~\eqref{eq:linear-sigma}
to the set of solutions of~\eqref{eq:riccati-sigma} in~$F$.
If $u$~can be obtained by two solutions $y_1$ and~$y_2$,
that is, if $\sigma y_1/y_1 = \sigma y_2/y_2$,
then $\sigma(y_1/y_2) = y_1/y_2$ is a constant in~$\dring$, thus in~$\bL$,
so that, $y_1$ and~$y_2$ are $F$-similar.
As a consequence, the partitioning
of the set of nonzero $F$-hypergeometric solutions of~\eqref{eq:linear-sigma}
translates into a partitioning
of the set of solutions of~\eqref{eq:riccati-sigma} in~$F$.

\item \ \ \ref{it:param-U}.
By the proof of point~\ref{it:param-H},
a nontrivial\/ $F$-similarity class~$\nonz{\fH}$
of the set of\/ $F$-hy\-per\-geo\-met\-ric solutions of~\eqref{eq:linear-sigma}
maps under $y \mapsto \sigma y/y$ to a subset~$U$
of the set of solutions of~\eqref{eq:riccati-sigma} in~$F$.
Given $y_1$ and~$y_2$ in the same class~$\nonz{\fH}$,
thus satisfying $y_1 = q y_2$
for some $q \in F$ (which needs to be nonzero),
if both share the same image in~$U$,
that is, $\sigma y_1/y_1 = \sigma y_2/y_2$ is the same element of~$U$,
then the proof of~\ref{it:param-H} has shown that $q$~is a constant from~$\bL$.
This implies that $y_1$ and~$y_2$ are in the same $\bL$-projective class,
thus proving the result.

\item \ \ \ref{it:disjoint-U}.
Point~\ref{it:vect-H} implies that each similarity class~$\fH$ is finite-dimensional.
If it has $\bL$-dimension~$s$,
its associated $\bL$-projective space~$\projzn{\fH}$ has dimension~$s-1$.
The statement is next a direct consequence
of points \ref{it:vect-H} and~\ref{it:param-U}.
\qedhere

\end{trivlist}
\end{proof}

\begin{rem}\label{rem:rational-param}
Point~\ref{it:param-U} of Theorem~\ref{thm:structure-main}
leads to a more explicit parametrization,
owing to the finite $\bL$-dimension of the space~$\fH$.
Fix~$y_0$ in~$\nonz{\fH}$ and let $u_0$ satisfy $\sigma y_0 = u_0 y_0$.
Let $(q_1y_0, \dots, q_s y_0)$ be some basis of~$\fH$.
With coordinates, the bijection of the theorem translates into the map
\begin{equation*}
(c_1:\ldots:c_s) \mapsto
  \frac{\sigma(c_1 q_1 + \dots + c_s q_s)}{c_1 q_1 + \dots + c_s q_s} u_0 ,
\end{equation*}
now a rational bijection from~$\bP^{s-1}(\bL)$ to its image.
\end{rem}

\begin{rem}
The partition obtained by point~\ref{it:param-H} of the theorem can be interpreted
as the partition induced on the solution set of~\eqref{eq:riccati-sigma}
by the equivalence relation on~$\nonz{F}$ defined by:
$u$~and~$u'$ are $F$-equivalent
if there exists~$f \in \nonz{F}$ such that $u/u' = \sigma f/f$.
\end{rem}


\section{Generalized series solutions of the linear equation}
\label{sec:concrete}

In this section, we define a Mahler difference ring, denoted~$\omdr$ (Definition~\ref{def:omdr}), of explicit formal expressions
that is an extension satisfying Hypothesis~\ref{def:propertyP}
of both $\ramrat\bKbar$ and $\puiseux\bKbar$.
This will be a crucial ingredient to describe
the Puiseux series solutions of a Riccati Mahler equation (Theorem~\ref{thm:structure-puiseux}).
To this end,
we describe $\puiseux\bL$-hypergeometric elements
(Proposition~\ref{prop:puiseux-hypergeometric-element})
so as to apply Theorem~\ref{thm:structure-main} for a given field~$\bL$.
The properties of~$\omdr$ are again used in~\S\ref{sec:rational-ramified-sol}
to describe the ramified rational solutions of the Riccati equation
(Theorem~\ref{thm:structure-rational-ramified}).


\subsection{The difference ring \texorpdfstring{$\omdr$}{D}}
\label{sec:difference}

Slightly adapting \parencite[\S5.2]{Roques-2018-ARB},
we introduce the $\puiseux\bKbar$-algebra with basis~$(e_\lambda)_{\lambda \in \nonz{\bKbar}}$ for elements~$e_\lambda$
satisfying the algebraic relations
$e_\lambda e_{\lambda'} = e_{\lambda\lambda'}$ and $e_1 = 1$.
This ring is not a domain, as shown by the product
$(e_\lambda + e_{-\lambda}) \times (e_\lambda - e_{-\lambda}) = 0$.
Next, we equip it with a structure of difference ring
by enforcing $M e_\lambda = \lambda e_\lambda$.
%
To support the intuition,
we henceforth denote $e_\lambda$ by $\mylog{\lambda}$
for $\lambda \in \nonz{\bKbar}$.
This mere notation bears no analytic meaning,
but it is reminiscent of the relation $\ln(x^b) = b \ln(x)$
in analysis,
as well as of the linear independence over
the field of meromorphic functions
of the family of functions $\left(\mylog{\lambda}\right)_{\lambda\in\nonz{\bC}}$.

\begin{defi}\label{def:omdr}
We define a difference ring by
\begin{equation}\label{eq:def-R}
  \omdr = \bigoplus_{\lambda \in \nonz{\bKbar}}\, \mylog{\lambda}\puiseux\bKbar ,
\end{equation}
where $\mylog{\lambda}$~is an eigenvector of~$M$ with respect to the eigenvalue~$\lambda$.

%
Given a subfield~$\bL$ of~$\bKbar$, we also define a difference subring~$\omdr_\bL$ of~$\omdr$ by
\begin{equation}\label{eq:def-R_L}
  \omdr_\bL = \bigoplus_{\lambda \in \nonz{\bL}} \, \mylog{\lambda}\puiseux\bL ,
\end{equation}
so that $\omdr$~is the special case $\omdr_{\bKbar}$.

\end{defi}

For an operator of~$\rat{\bKbar}\langle M\rangle$,
\begin{equation}\label{eq:L-in-R}
L = L(x,M) = \sum_{k=0}^r \ell_k(x) M^k ,
\end{equation}
and an element of~$\omdr$,
\begin{equation}\label{eq:y-in-D}
y = \sum_{\lambda\in S} \mylog{\lambda} \, p_\lambda(x) ,
\end{equation}
where the set~$S$ is a finite subset of~$\bKbar$
and the~$p_\lambda(x)$ are Puiseux series,
the action of~$L$ on~$y$ has a special structure given by
\begin{equation}\label{eq:action-L-y}
L(x,M) \, y = \sum_{\lambda\in S} \mylog{\lambda} L(x,\lambda M) \, p_\lambda(x) .
\end{equation}
This formula decomposes~\eqref{eq:linear} into equations on the~$p_\lambda(x)$ as follows.
\begin{lem}\label{lem:split-eqn-to-equiv}
For an operator~$L \in \rat{\bKbar}\langle M\rangle$ as in~\eqref{eq:L-in-R}
and an element~$y$ of~$\omdr$ as in~\eqref{eq:y-in-D},
the equality $L(x,M)\, y = 0$ is equivalent to the finite set of equalities
\begin{equation}\label{eq:indep-eqns}
L(x,\lambda M) \, p_\lambda(x) = 0,\qquad \lambda\in S .
\end{equation}
\end{lem}
\begin{proof}
This follows directly from \eqref{eq:action-L-y},
by the uniqueness of coefficients in~$\omdr$.
\end{proof}


The following lemma can be deduced from
\textcite[Theorem~35]{Roques-2018-ARB} in the case $\bL=\bQbar$.
\begin{lem}\label{lem:R-contants-field}
The field of constants of the ring~$\omdr_\bL$ is~$\bL$.
\end{lem}
\begin{proof}
By Lemma~\ref{lem:split-eqn-to-equiv},
the equation $My = y$ is equivalent to
$\lambda M p_\lambda = p_\lambda$ for $\lambda\in\bKbar$.
For each~$\lambda$, if $p_\lambda$~is nonzero,
its valuation must be~$0$
and its leading coefficient~$c$ must satisfy~$\lambda c = c$,
implying~$\lambda = 1$.
This means that $y$~is in~$\bL$.
We conclude that the
constant field of~$\omdr_\bL$ is $\bL$~itself.
\end{proof}

\subsection{Bounds}
\label{sec:bounds}

The goal of this section is to bound the valuation and ramification order of
the Puiseux series solutions of~\eqref{eq:linear} in~$\omdr$.
We need to introduce notions related to a \emph{lower} Newton polygon attached to~$L$,
which the reader should not confuse with parallel notions attached to the \emph{upper} Newton polygon
that will be defined in~\S\ref{sec:bgpf} (Definition~\ref{def:upper-newton}).

\begin{defi}\label{def:lower-newton}
To the polynomial
\[
  L = \sum_{k=0}^r \ell_k(x) M^k = \sum_{k,j} \ell_{k,j} x^j M^k
\]
we associate
the set of points $(b^k,j) \in \bR^2$ such that $\ell_{k,j}\neq0$.
The lower convex hull of this set is called the \emph{lower Newton polygon} (of~$L$).
\end{defi}

The following lemma is borrowed from
\parencite[Lemma~2.2]{ChyzakDreyfusDumasMezzarobba-2018-CSL}.

\begin{lem}\label{lem:admissibility}
The valuation of any Puiseux series solution of~\eqref{eq:linear}
is the opposite of the slope of an edge of the lower
Newton polygon of\/~$L$.
Moreover the coefficients~$\ell_{k,j}$
corresponding to all points $(b^k,j)$ lying on the edge
must add up to zero.
\end{lem}

For a solution~$y$ of~\eqref{eq:linear}, that is, satisfying $L(x,M)\, y = 0$,
to be of the form $\mylog{\lambda} p(x)$ with $p(x)$ a Puiseux series,
the series~$p(x)$ must by the formula~\eqref{eq:action-L-y}
be a solution of $L(x,\lambda M)\, p = 0$.
The change from~$L(x,M)$ to~$L(x,\lambda M)$ does not modify the
Newton polygon, but the coefficients at abscissa~$b^k$
are multiplied by~$\lambda^k$.
So, by Lemma~\ref{lem:admissibility},
the only~$\lambda$ for which a nonzero solution of the form $\mylog{\lambda} p(x)$ may exist
are  the (necessarily nonzero) roots of the characteristic polynomials defined by~\eqref{eqn:lower-char-poly} in the following definition.


\begin{defi}\label{def:lower-char-poly}
The edges of the lower Newton polygon of~$L$ are indexed so that their slopes form an increasing sequence.
%
Given the abscissae $b^{k_1}$ and~$b^{k_2}$, with~$k_1\leq k_2$, of the $j$th edge,
the polynomial~$\chi_j$ defined by
\begin{equation}\label{eqn:lower-char-poly}
\chi_j(X) := \sum_{k=k_1}^{k_2}\ell_{k,j}X^{k-k_1}
\end{equation}
is called the \emph{characteristic polynomial} of the $j$th edge.
%
We define~$\Lambda$ as the union of the roots of these polynomials:
\begin{equation}\label{eq:def-Lambda}
\Lambda = \{ \lambda \in \bKbar : \exists j, \ \chi_j(\lambda) = 0 \} .
\end{equation}
%
Given~$\lambda$ in~$\Lambda$, the $j$th edge will be called \emph{$\lambda$-admissible} (for~$L$)
if $\chi_j(\lambda) = 0$.
\end{defi}

The present $1$-admissible edges were simply called admissible in \parencite{ChyzakDreyfusDumasMezzarobba-2018-CSL}.
Lemma~\ref{lem:admissibility} extends slightly
to accommodate a logarithmic part,
leading to the following result.
The omitted proof parallels that of \parencite[Lemma~2.2]{ChyzakDreyfusDumasMezzarobba-2018-CSL}.

\begin{lem}\label{lem:extd-admissibility}
The valuation of the Puiseux series~$p(x)$ in any nonzero solution of~\eqref{eq:linear}
of the form $\mylog\lambda p(x)$
is the opposite of the slope of a $\lambda$-admissible edge of the lower
Newton polygon of\/ $L$.
\end{lem}

As already noted for~$\lambda = 1$ in \parencite{ChyzakDreyfusDumasMezzarobba-2018-CSL},
$\lambda$-admissibility is only a necessary condition
for the existence of a series solution with logarithmic part~$\mylog{\lambda}$.


\begin{prop}\label{lem:single-lambda-equiv}
For an operator~$L \in \rat{\bKbar}\langle M\rangle$ as in~\eqref{eq:L-in-R}
and an element $y = \mylog{\lambda} \, p(x)$ of~$\omdr$ given by $\lambda \in \nonz\bKbar$ and~$p \in \puiseux\bKbar$,
the equality $L(x,M)\, y = 0$ is equivalent to the equality
\begin{equation}\label{eq:single-eqn}
L(x,\lambda M) \, p(x) = 0 .
\end{equation}
Moreover, \eqref{eq:single-eqn}~can have a nonzero solution
only if $\lambda$~is the root of some characteristic polynomial of~$L$.
\end{prop}

\begin{proof}
The stated equivalence is a mere specialization of Lemma~\ref{lem:split-eqn-to-equiv}.
The necessary condition on~$\lambda$ has been proved
above when introducing characteristic polynomials.
\end{proof}


In order to discuss ramifications, we import
\parencite[Prop.~2.19]{ChyzakDreyfusDumasMezzarobba-2018-CSL},
which deals with $1$-admissible edges.
In doing so, we slightly reformulate the result
so as to describe solutions over an algebraic extension~$\bL$ of~$\bK$.

\begin{lem}\label{lem:puiseux-denominator-bound}
Any Puiseux series solution of~\eqref{eq:linear} is an element of\/ $\rfls\bKbar{q_1}$,
where $q_1$~is the lcm of the denominators of the slopes of those $1$-admissible edges
such that said denominators are coprime with~$b$.
Furthermore, a $\bKbar$-vector basis of the solutions can be written
in~$\rfls\bK{q_1}$.
Given an intermediate field\/~$\bL$,
such a $\bKbar$-vector basis is also
an $\bL$-vector basis for the $\bL$-space of solutions in~$\puiseux{\bL}$.
\end{lem}
\begin{proof}
The first assertion of the statement is exactly the proposition we referred to,
using $\bKbar$~as a base field.
The second and third assertions are implicit in
\parencite{ChyzakDreyfusDumasMezzarobba-2018-CSL},
which finds solutions by solving linear systems over~$\bK$.
\end{proof}

\begin{defi}
More generally, we denote by $q_\lambda$ the lcm of the denominators coprime with~$b$
of the slopes of the $\lambda$-admissible edges of the lower Newton polygon
of~$L$, that is
\begin{multline}\label{eq:q-lambda}
q_\lambda =
\operatorname{lcm} \, \{q \in \bN : \exists j,p, \ \gcd(b,q) = \gcd(p,q) = 1, \ \chi_j(\lambda) = 0, \\
\text{and the $j$th edge has slope~$p/q$}\} .
\end{multline}
We call~$q_\lambda$ the \emph{ramification bound} with respect to~$\lambda$.
\end{defi}

We can then prove the following result on solutions in~$\omdr_\bL$ (Definition~\ref{def:omdr}).

\begin{prop}\label{prop:structure-sol-space-lin-eq}
Given an intermediate field~$\bL$,
the solution space of~\eqref{eq:linear} in~$\omdr_\bL$ is included in
\[
  \bigoplus_{\lambda\in\Lambda\cap\bL}
  \mylog{\lambda} \, \rfls{\bL}{q_\lambda}.
\]
Furthermore, an $\bL$-basis of this space can be written in
\[
  \coprod_{\lambda\in\Lambda\cap\bL}
  \mylog{\lambda} \, \rfls{\bK[\lambda]}{q_\lambda}.
\]
\end{prop}

\begin{proof}
For a nonzero solution~$y$ of~$L$ in~$\omdr_\bL$,
Lemma~\ref{lem:split-eqn-to-equiv} splits the relation $L y = 0$
into the equivalent finite set of equations~\eqref{eq:indep-eqns}.
This proves the first part,
where the direct sum of the solution space is induced
by the direct sum in the expression~\eqref{eq:def-R_L} of~$\omdr_\bL$.
%
Next, according to Lemma~\ref{lem:admissibility},
the equation~\eqref{eq:indep-eqns} for a given~$\lambda\in\bL$ has a nonzero solution
only if there exists a $\lambda$-admissible edge, that is, only if
$\lambda$~is an element of~$\Lambda$.
Moreover, the change from $L(x,M)$ to $L(x,\lambda M)$ modifies the linear system
that is used in the proof of Lemma~\ref{lem:puiseux-denominator-bound} to determine the solutions
by moving its coefficients to the algebraic extension~$\bK[\lambda]$.
As a result,
a basis of the Puiseux-series solutions~$p_\lambda$
can be found with coefficients in~$\bK[\lambda]$
and ramification order (bounded by)~$q_\lambda$.
The result is proved.
\end{proof}

The following corollary is already proved as Lemma~\ref{lem:has-Property-U}:
we obtain here an alternative proof
by considering properties of the lower Newton polygon.

\begin{cor}\label{cor:dimension-vs-order}
Given an intermediate field~\/$\bL$,
the solution set in~$\omdr_\bL$ of the linear equation~\eqref{eq:linear}
is an $\bL$-vector space
whose dimension over the field\/~$\bL$
is at most the order~$r$ of the equation.
\end{cor}

\begin{proof}
Proposition~\ref{prop:structure-sol-space-lin-eq} provides us
with an $\bL$-basis of the solutions of~\eqref{eq:linear} in~$\omdr_\bL$,
which can be chosen such that for each~$\lambda$
the basis elements of the form $\mylog{\lambda} \, p(x)$ involve series~$p(x)$ with distinct valuations.
By Lemma~\ref{lem:extd-admissibility}, these valuations are
opposites of slopes of distinct edges of the Newton polygon
whose characteristic polynomials~$\chi_j$ all have~$\lambda$ as a root.
Therefore, the total number of elements of the basis is bounded by
$\sum_j \deg \chi_j \leq r$.
\end{proof}

The order~$r$ is not always reached in Corollary~\ref{cor:dimension-vs-order},
as shown by the following two examples.

\begin{ex}
For any radix~$b\geq2$, the operator $L = M^2-2M+1$ admits the series solution~$1$,
and no nonconstant solution.
This reflects the fact that the nonhomogeneous equation $My-y = 1$
has no solution in~$\omdr$,
while any solution of this equation needs to be killed by~$L$.
\end{ex}

\begin{ex}
Similarly, when~$b\geq2$, $x^{b-1}M^2 - (1+x^{b-1})M + 1$ admits the series solution~$1$,
and otherwise would require a Hahn series $x^{-1/b}+x^{-1/b^2}+x^{-1/b^3}+\dotsb$
to get a second dimension of solutions,
the latter solving $My-y = 1/x$.
See \parencite{FaverjonRoques-2024-HSM} for a definition and developments.
\end{ex}

\subsection{Puiseux-hypergeometric solutions}
\label{sec:puiseux}

In the present section,
we focus on the field $F = \puiseux\bL$ to obtain the Puiseux series
with coefficients in~$\bL$ that are solutions of the Riccati equation.
We describe the $\puiseux\bL$-hypergeometric elements in~$\omdr_\bL$
and deduce that $\omdr_\bL$~satisfies Hypothesis~\ref{def:propertyP} over~$\puiseux\bL$.

\begin{lem}\label{lem:unique-monic-series}
Fix $q\in \nonz{\bN}$ and $u\in \rfls\bL{q}$
of valuation~$\alpha$ and with leading coefficient\/~$\lambda$.
If $\lambda \neq 1$, then the equation $M v = u v$ admits no nonzero solution in~$\puiseux\bL$.
Otherwise,
it
admits a unique series solution
$v$ in $x^{\alpha/(b-1)} \rfps\bL{q}$
of valuation $\alpha/(b-1)$ and with leading coefficient\/~$1$, and the solution space of this equation in~$\puiseux\bL$
is exactly the one-dimensional space\/~$\bL v$.
\end{lem}

\begin{proof}
The Puiseux series~$u$ can be written in the form $u = \lambda x^{\alpha} \hat u$
for some
$\hat u = \sum_{k\in\bN} \hat u_k x^{k/q} \in \rfps\bL{q}$
such that $\hat u_0 = 1$.
Assume that the equation $M v = u v$ admits a nonzero solution $v \in \puiseux\bL$ with valuation~$\beta$ and leading coefficient~$v_0 \neq 0$.
Taking leading terms on both sides yields $v_0 x^{b\beta} = \lambda v_0 x^{\alpha+\beta}$,
which implies~$\lambda = 1$.
This proves the absence of nonzero solutions if~$\lambda \neq 1$
and the announced valuation of~$v$ if~$\lambda = 1$.

We continue with the latter case.
Write $v$ in the form $x^{\alpha / (b-1)}\hat v$ for a series
$\hat v = \sum_ {k\in\bN}\hat v_k x^{k/q}$ and $\hat v_0 = v_0 \neq 0$,
the equation is equivalent to the relation
\begin{equation*}
\sum_{k\in\bN} \hat v_k x^{bk/q} =
\sum_{n\in\bN} \sum_{i\in\bN} \hat u_{n - i} \hat v_i \,  x^{n/q} ,
\end{equation*}
which in turn is equivalent to the recurrence formula
\[ \hat v_n = \hat v_{n / b} - \sum_{i=0}^{n-1} \hat u_{n - i} \hat v_i \]
for $n\in\nonz{\bN}$,
where $\hat v_{n/b}$ is understood to be zero if $n/b$~is not in~$\bN$.
The sequence $(\hat v_n)_{n\in\bN}$, and therefore the solution~$v$,
is fully determined by the choice of $\hat v_0 = 1$.

Next, for any Puiseux series solution~$w$ of the equation $Mw = uw$,
the quotient $w/v$ is in the constant field of~$\puiseux\bL$,
that is, it lies in~$\bL$.
\end{proof}


The following result is to be found
as \parencite[Theorem~35, top of page~342]{Roques-2018-ARB},
where~$\omdr$ is named~$B$ and is defined in \parencite[Lemma~36]{Roques-2018-ARB}.
We reproduce it here for the readers' convenience,
while removing the unnecessary hypothesis
of an algebraically closed field~$\bL$.
\begin{lem}\label{lem:D-is-simple}
$\omdr_\bL$~is a simple difference ring.
\end{lem}
\begin{proof}
Let $J$ be a nonzero difference ideal of~$\omdr_\bL$.
Let $y = \sum_{\lambda \in \nonz{\bL}} \mylog{\lambda} p_\lambda$
for $p_\lambda \in \puiseux\bL$
be a nonzero element of~$J$
such that the cardinality of the support of~$(p_\lambda)_{\lambda \in \nonz{\bL}}$ is minimal.
Let $\lambda_0$~be such that
$p_{\lambda_0} \neq 0$
and replace~$y$ with~$y/p_{\lambda_0}$,
so that we assume that~$p_{\lambda_0} = 1$.
Because $p_{\lambda_0}$~appears with zero coefficient in~$y - M y \in J$
and by the minimality assumption,
$y - M y = 0$.
Consequently, for all~$\lambda \in \nonz{\bL}$,
$p_\lambda = \lambda M p_\lambda$.
For~$\lambda \neq 1$, we conclude~$p_\lambda = 0$
by Lemma~\ref{lem:unique-monic-series}.
Consequently, $y$~reduces to~$p_1$, which is invertible,
thus proving~$J = \omdr_\bL$.
\end{proof}


\begin{cor}\label{cor:DL-1-univ-U}
$\omdr_\bL$ is an extension satisfying Hypothesis~\ref{def:propertyP} over
any intermediate difference field~$F$ between $\rat\bL$ and~$\puiseux\bL$,
so that Theorem~\ref{thm:structure-main} applies to~$\omdr_\bL$, viewed as an extension of~$F$.
\end{cor}
%
\begin{proof}
This follows directly from
Lemma~\ref{lem:R-contants-field},
 Lemma~\ref{lem:unique-monic-series},
and Lemma~\ref{lem:D-is-simple}.
\end{proof}

We will use
$F = \puiseux\bL$ in Theorem~\ref{thm:structure-puiseux} below,
and $\ramrat\bL$ in Theorem~\ref{thm:structure-rational-ramified}.

\begin{prop}\label{prop:puiseux-hypergeometric-element}
The $\puiseux\bL$-hypergeometric elements in~$\omdr_\bL$ are
its elements $y = \mylog{\lambda} p(x)$
where $\lambda$~is in~$\nonz{\bL}$
and $p(x)$~is a Puiseux series in\/~$\puiseux\bL$.
%
Two such nonzero elements are $\puiseux\bL$-similar if and only if they share the same~$\lambda$.
\end{prop}

\begin{proof}
Let $y$ be a nonzero $\puiseux\bL$-hypergeometric element in~$\omdr_\bL$,
together with the corresponding Puiseux series~$u$ satisfying the equation~$My = uy$.
The series~$u$ lies in a subfield~$\rfls\bL{q}$ with $q$ a positive integer.
Let its leading term be denoted~$\lambda_0 x^{m/q}$,
for suitable $\lambda_0 \in \bL$ and~$m \in \bZ$.
By Lemma~\ref{lem:split-eqn-to-equiv},
writing~$y$ as in~\eqref{eq:y-in-D}
for a finite subset~$S$ of~$\nonz{\bL}$ and some~$p_\lambda(x)$ in~$\puiseux\bL$
leads to the equations
$\lambda M p_\lambda = u p_\lambda$ for $\lambda\in S$.
Any such equation can have a nonzero solution
only if $\lambda$~is equal to~$\lambda_0$,
forcing~$y$ to be of the form
$y = \mylog{\lambda_0} p_{\lambda_0}(x)$
where~$p_{\lambda_0}(x) \in \puiseux\bL$ is nonzero.
Conversely, any~$y$ of that form
is $\puiseux\bL$-hypergeometric in~$\omdr_\bL$.

Now suppose that
$y_1 = \mylog{\lambda_1} p_1(x)$ and $y_2 = \mylog{\lambda_2} p_2(x)$
are $\puiseux\bL$-similar and nonzero.
The similarity implies the linear dependence of $\mylog{\lambda_1}$ and~$\mylog{\lambda_2}$ over $\puiseux\bL$,
and therefore the equality~$\lambda_1 = \lambda_2$.
Conversely two nonzero hypergeometric solutions of~\eqref{eq:linear} in~$\omdr_\bL$
with the same $\lambda\in\bL$ are similar by definition.
\end{proof}

\begin{rem}\label{rem:puiseux-hypergeometric-element-with-q}
The same approach,
supplemented with Lemma~\ref{lem:unique-monic-series},
shows more precisely
that the  $\rfls\bL{q}$-hypergeometric elements in~$\omdr_\bL$ are of the form
\begin{equation}\label{eq:puiseux-hypergeometric-element}
  y = \mylog{\lambda} x^{m /(q(b-1))} s(x^{1/q})
\end{equation}
with $\lambda$ in~$\nonz{\bL}$,
$q$~a positive integer, $m$~an integer,
and $s(x)$~a series of valuation\/~$0$ in\/~$\fps\bL$.
Observe (e.g., by making~$m=1$) that $My/y$ may have a lower ramification order than~$y$.
Consequently,
obtaining \emph{all} Laurent power series solutions to~\eqref{eq:riccati} in the form~$u = My/y$
generally requires to consider
\emph{ramified} hypergeometric solutions~$y$ of~\eqref{eq:linear}.
A simple example is provided by $L = M - u$ for~$b = 5$ and $u = x  (1+x^3)$,
with solution $y = x^{1/4} \prod_{k\geq0}(1+x^{3\cdot 5^k})^{-1}$.
\end{rem}

\begin{rem}
We could have written the series~$s$ in Proposition~\ref{prop:puiseux-hypergeometric-element}
as an infinite product.
Indeed, this representation will prove useful later:
in Proposition~\ref{prop:ramified-rational-hypergeometric-element}
where we obtain an infinite product of rational functions;
in Proposition~\ref{prop:rational-ramified-hypergeometric}
where we provide a characterization of the similarity classes.
\end{rem}

\begin{defi}\label{def:Lambda'}
Let $\Lambda'$ denote the finite set of~$\lambda \in \Lambda$
(see~\eqref{eq:def-Lambda})
such that
there exists a nonzero solution of~\eqref{eq:linear} in~$\mylog{\lambda} \puiseux\bKbar$.
%
For an intermediate field\/~$\bL$ and $\lambda \in \Lambda' \cap \bL$, define~$\fH_{\bL,\lambda}$ to be
the set of hypergeometric solutions in~$\mylog{\lambda} \puiseux{\bL}$.
%
Let\/~$\ricsol_{\bL,\lambda} \subseteq \puiseux\bL$ denote
the image of~$\nonz{(\fH_{\bL,\lambda})}$ under the map $y\mapsto My/y$.

\end{defi}

The elements of~$\fH_{\bL,\lambda}$
are necessarily in~$\mylog{\lambda} \rfls{\bL}{q_\lambda}$
by Proposition~\ref{prop:structure-sol-space-lin-eq}.
%
With this notation, Theorem~\ref{thm:structure-main} specializes as follows.

\begin{thm}\label{thm:structure-puiseux}
The solution set\/~$\ricsol_{\puiseux\bL}$ of the Riccati equation~\eqref{eq:riccati}
in the ramified rational function field\/~$\puiseux\bL$ is the disjoint union
\begin{equation}\label{eq:R-disj-union}
  \ricsol_{\puiseux\bL} = \coprod_{\lambda\in\bL\cap\Lambda'} \ricsol_{\bL,\lambda}
\end{equation}
indexed by the finite set\/~$\bL\cap\Lambda'$.
Each\/~$\ricsol_{\bL,\lambda}$ is a set of series from\/~$\rfls\bL{q_\lambda}$ with leading coefficient~$\lambda$
and is one-to-one rationally parametrized by the\/ $\bL$-projective space\/ $\projzn{\fH_{\bL,\lambda} }$.
The corresponding parametrization is obtained
by restricting the map $y\mapsto My/y$ from~$\nonz{(\fH_{\bL,\lambda})} $ to its image in\/~$\puiseux\bL$
and projectivizing its source.
Moreover the dimensions of the\/ $\bL$-projective spaces add up to a number
that is at most the order~$r$ of the linear equation~\eqref{eq:linear}
minus the cardinality of\/~$\bL\cap\Lambda'$.
\end{thm}

\begin{proof}
By Corollary~\ref{cor:DL-1-univ-U},
the ring~$\omdr_\bL$ satisfies Hypothesis~\ref{def:propertyP} as an extension of~$\puiseux\bL$,
so Theorem~\ref{thm:structure-main} applies
to $\dring = \omdr_\bL$ and~$F = \puiseux\bL$.
Points \ref{it:vect-H} to~\ref{it:param-U} of that theorem justify
the partitioning according to~\eqref{eq:R-disj-union}
as well as the form of the parametrization.
Moreover,
from the inclusion $\fH_{\bL,\lambda} \subseteq \mylog{\lambda} \rfls{\bL}{q_\lambda}$
follows the inclusion
$\ricsol_{\bL,\lambda} \subseteq \rfls{\bL}{q_\lambda}$.
Point~\ref{it:disjoint-U} proves the bound on dimensions.
\end{proof}


\section{Ramified rational solutions to the Riccati equation}
\label{sec:rational-ramified-sol}

We now study the $F$-hypergeometric solutions of~\eqref{eq:linear}
for $F = \ramrat\bL$, or, equivalently, the ramified rational solutions of
\eqref{eq:riccati} with coefficients in some intermediate field~$\bL$.

\subsection{Hypergeometric elements}
\label{sec:hypergeom}

We begin by characterizing the $\ramrat\bL$-hypergeo\-metric elements
of~$\omdr_\bL$ (Definitions \ref{def:F-hyperg} and~\ref{def:omdr}).

\begin{prop}\label{prop:ramified-rational-hypergeometric-element}
The nonzero\/ $\ramrat\bL$-hypergeometric elements in $\omdr_\bL$
are the elements
\begin{equation}\label{eq:ramified-rational-hypergeometric-element}
  y = c \, \mylog{\lambda} x^{m/q} f(x^{1/q})
\end{equation}
with $c$~and~$\lambda$~in\/~$\nonz{\bL}$, $m$~an integer,
$q$~a positive integer,
and $f(x)$~a formal power series that is expressible as an infinite product
\begin{equation}\label{eq:inf-product}
  f(x) = \prod_{k\geq 0} 1/g(x^{b^k}) \in \fps\bL
\end{equation}
for some $g(x) \in \rat\bL$ satisfying $g(0) = 1$.
\end{prop}

\begin{proof}
Any nonzero $\ramrat\bL$-hypergeometric element~$y$ in~$\omdr_\bL$
is $\puiseux\bL$-hyper\-geo\-met\-ric.
By Proposition~\ref{prop:puiseux-hypergeometric-element},
it can be written $y = \mylog{\lambda} x^{m/q} s(x^{1/q})$
with $\lambda$ in~$\nonz{\bL}$, $q$ a positive integer, $m$ an integer,
and $s(x)$~in~$\fps\bL$ of valuation~$0$.
One then has
$My/y = \lambda x^{(b-1)m/q} s(x^{b/q})/s(x^{1/q}) \in \rfls\bL{q} \cap \ramrat\bL$,
so $g(x) := s(x^b)/s(x)$ is a rational function.
The infinite product~\eqref{eq:inf-product} for this value of~$g$ converges
to~$s$,
hence $y$~is of the form~\eqref{eq:ramified-rational-hypergeometric-element}
with~$f = s$.
\end{proof}

\begin{rem}
If the hypergeometric element~$y$ is such that $My/y$~is in~$\rfls{\bL}{q'}$,
then $q = q'(b-1)$ can be used
in formula~\eqref{eq:ramified-rational-hypergeometric-element},
as a consequence
of Remark~\ref{rem:puiseux-hypergeometric-element-with-q}.
\end{rem}



\subsection{Similarity classes}
\label{sec:similarity-classes}

The set of $\ramrat\bL$-hypergeometric solutions of~\eqref{eq:linear}
decomposes into $\ramrat\bL$-similarity classes that refine the
$\puiseux\bL$-similarity classes~$\fH_{\bL,\lambda} $ described in~\S\ref{sec:concrete} (Definition~\ref{def:Lambda'}).
The following proposition gives a normal form for these new similarity classes.
Recall from Proposition~\ref{prop:structure-sol-space-lin-eq} that the ramification bound~$q_\lambda$
defined by~\eqref{eq:q-lambda} is a bound on the ramification orders
of solutions of~\eqref{eq:linear} in~$\mylog\lambda \, \puiseux\bL$,
and recall as well the definition of~$\Lambda'$ in Definition~\ref{def:Lambda'}.

\begin{prop}\label{prop:rational-ramified-hypergeometric}
Any nontrivial\/ $\ramrat\bL$-similarity class~$\nonz{\fH}$
of\/ $\ramrat\bL$-hyper\-geo\-met\-ric solutions of~\eqref{eq:linear} uniquely determines
a tuple $(\lambda, g, (p_j)_{1\leq j\leq s})$ \hbox{made of}:
\begin{itemize}
  \item $\lambda$ in\/ $\bL\cap\Lambda'$,
  \item an integer~$s>0$ and Laurent polynomials $p_1$, \dots, $p_s$ of\/~$\bL[x,x^{-1}]$,
  \item a rational function~$g$ in\/~$\rat\bL$ satisfying $g(0) = 1$,
\end{itemize}
and such that:
\begin{enumerate}
\item\label{it:basis-using-p} the $s$ generalized series
\begin{equation}\label{eq:rational-ramified-hypergeometric}
  \mylog{\lambda}
    \times p_j(x^{1/q_\lambda}) \times
      \prod_{k\geq 0} 1/g(x^{b^k/q_\lambda}) ,
  \qquad 1 \leq j \leq s,
\end{equation}
form a basis of the $\bL$-vector space~$\fH$,
  \item\label{it:family-of-p} the family $(p_1, \dots, p_s)$ is in
    reduced echelon form w.r.t.\ ascending degree
    (meaning in particular that the coefficient of minimal degree of~$p_j$ is\/~$1$),
  \item\label{it:coprime-p} the elements $p_1$, \dots, $p_s$ are coprime in\/~$\bL[x,x^{-1}]$
    (in other words, the $p_j/x^{\val p_j}$ are coprime in\/~$\pol\bL$).
\end{enumerate}
\end{prop}

\begin{proof}
The $\ramrat\bL$-similarity class~$\nonz{\fH}$
of $\ramrat\bL$-hypergeometric solutions of~\eqref{eq:linear}
is contained in an $\puiseux\bL$-similarity class of
$\puiseux\bL$-hypergeometric elements of~$\omdr_\bL$, which, by
Proposition~\ref{prop:puiseux-hypergeometric-element},
is of the form
$\mylog\lambda \, \nonz{\puiseux\bL}$ for some~$\lambda \in \nonz{\bL}$.
Since, additionally, $\fH$~is contained in the solution space
of~\eqref{eq:linear},
Proposition~\ref{prop:structure-sol-space-lin-eq} implies
$\fH \subseteq \mylog\lambda \, \rfls\bL{q_\lambda}$.
Additionally, $\fH$~has finite dimension over~$\bL$
by Theorem~\ref{thm:structure-main}.

For any element $y \in \nonz{\fH}$, use
Proposition~\ref{prop:ramified-rational-hypergeometric-element}
to write
\begin{equation}\label{eq:ramified-factorization}
  y = c \, \mylog{\lambda} x^{m/q} f(x^{1/q}), \qquad
  f(x) = \prod_{k\geq 0} 1/g(x^{b^k}),
\end{equation}
with $c \in \bL$, $g(x) \in \bL(x)$, and $g(0) = 1$.
We contend that we can without loss of generality
make $q$ equal to the ramification bound~$q_\lambda$ in~\eqref{eq:ramified-factorization}.
First, the valuation~$m/q$ of~$y/\mylog{\lambda}$
is in~$q_\lambda^{-1}\bZ$,
and can thus be written $m/q = \tilde m/q_\lambda$ for~$\tilde m \in \bZ$.
Second, $f(x^{1/q}) = y / (\mylog{\lambda} x^{\tilde m/q_\lambda})$
is in~$\rfls\bL{q_\lambda}$,
so that $h(x) := f(x^{q_\lambda/q})$~is in~$\fls\bL$.
From $Mf/f = g \in \rat\bL$ follows the membership of
$g(x^{q_\lambda/q}) = Mh/h$ in $\bL(x^{q_\lambda/q}) \cap \fls\bL$.
Write $q_\lambda/q = n/d$ in lowest terms
and observe that $g$~is a series in~$x^d$.
Define $\tilde g(x) := g(x^{n/d})$, a rational series satisfying $\tilde g(0) = 1$.
Define $\tilde f(x) := \prod_{k\geq 0} 1/\tilde g(x^{b^k})$ and observe
$f(x^{1/q}) = \tilde f(x^{1/q_\lambda})$.
%\[ f(x^{1/q}) = \prod_{k\geq 0} 1/g(x^{b^k/q}) = \prod_{k\geq 0} 1/\tilde g(x^{b^k/q_\lambda}) = \tilde f(x^{1/q_\lambda}) . \]
We have obtained a new expression of~$y$ of the form~\eqref{eq:ramified-factorization}
with $(q, m, g)$ replaced with~$(q_\lambda, \tilde m, \tilde g)$.
In particular, we have made~$q$ independent of~$y$.

Pick an element $y_0 \in \nonz{\fH}$ and obtain
its decomposition of the form~\eqref{eq:ramified-factorization},
thus fixing $(q, m, g)$ to some~$(q_\lambda, m_0, g_0)$.
Replace~$y_0$ with~$y_0/c$ so as to set~$c$ to~$1$.
%
Since $\nonz{\fH}$ is an $\ramrat\bL$-similarity class,
the set $V := \{ y/y_0 : y \in \fH \}$
is an $\bL$-subspace of $\ramrat\bL$,
and thus, by the previous paragraph,
a finite-dimensional $\bL$-subspace of $\rrat\bL{q_\lambda}$.
Let $a(x^{1/q_\lambda})$
be the least common denominator of the elements of~$V$,
with valuation coefficient normalized to one.
Write
$a(x^{1/q_\lambda}) = x^{v/q_\lambda} \tilde a(x^{1/q_\lambda})$
for $\tilde a$ of valuation zero.
Then $a(x^{1/q_\lambda}) V$ is a finite-dimensional subspace of
$\bL[x^{1/q_\lambda}]$;
as such, it admits a basis
$(\tilde p_1(x^{1/q_\lambda}), \dots, \tilde p_s(x^{1/q_\lambda}))$
in reduced echelon form w.r.t.\ ascending degree.
The polynomials $\tilde p_1, \dots, \tilde p_s$ are coprime by the minimality
of~$a$.
Setting $g = g_0 a/Ma$ and $p_j = x^{m_0-v} \tilde p_j$, the
expressions~\eqref{eq:rational-ramified-hypergeometric}
form a basis of~$\fH$ that satisfies the conditions
\ref{it:family-of-p} and~\ref{it:coprime-p}.

We already have noticed that $\lambda$~is uniquely determined by~$\fH$.
Suppose that $\fH$~admits a second basis
of the form~\eqref{eq:rational-ramified-hypergeometric},
with parameters $g', p'_1, \dots, p'_s$ also satisfying
\ref{it:family-of-p} and~\ref{it:coprime-p}.
Let $f' = \prod_{k\geq 0} 1/g'(x^{b^k})$.
Then $(p_1, \dots, p_s)$ and $(p'_1 f'/f, \dots, p'_s f'/f)$
are two bases of the same $\bL$-vector space.
In particular, the $p'_j f'/f$ are Laurent polynomials.
A Bézout relation $\sum_j u_j p'_j = 1$ for Laurent polynomials~$u_j$
then implies that $f'/f = \sum_j u_j (p'_j f'/f)$ is a Laurent polynomial.
By symmetry, $f/f'$~is also Laurent,
and in fact equal to~$1$ because $g(0) = g'(0) = 1$.
Then the uniqueness of the reduced echelon form of a given vector space implies
$(p_1, \dots, p_s) = (p'_1, \dots, p'_s)$.
We have thus proved the uniqueness of the tuple $(\lambda, g, p_1, \dots, p_s)$
under conditions
\ref{it:basis-using-p},
\ref{it:family-of-p}, and~\ref{it:coprime-p}.
\end{proof}

A direct consequence of Proposition~\ref{prop:rational-ramified-hypergeometric}
is that for a given~\eqref{eq:linear},
$\ramrat\bL$-similarity classes are uniquely identified by the pairs~$(\lambda, g)$
extracted from the tuples~$(\lambda, g, p)$ of the proposition.
Indeed,
if two classes share the same~$(\lambda, g)$, then,
in view of the form~\eqref{eq:rational-ramified-hypergeometric} of the bases associated with the two classes,
any element of one class must be $\ramrat\bL$-similar to any element of the other class.
These two classes must therefore be equal.
This leads us to the following definition that the reader will compare with Definition~\ref{def:Lambda'}.

\begin{defi}\label{def:classes-L-lambda-g}
Given a nontrivial\/ $\ramrat\bL$-similarity class
of\/ $\ramrat\bL$-hyp\-er\-geo\-met\-ric solutions of~\eqref{eq:linear},
let $(\lambda, g, (p_j)_{1\leq j\leq s})$ be
the uniquely determined tuple of Proposition~\ref{prop:rational-ramified-hypergeometric}.
Then the similarity class will be denoted~$\fH_{\bL,\lambda,g}$.
%
We will also write~$\ricsol_{\bL,\lambda,g}$ for the image of~$\nonz{\fH_{\bL,\lambda,g}}$ under $y \mapsto My/y$.
\end{defi}

Summing up the previous discussion, the full solution set of the Riccati
equation can be described as follows.

\begin{thm}\label{thm:structure-rational-ramified}
The solution set\/~$\ricsol_{\ramrat\bL}$ of the Riccati
equation~\eqref{eq:riccati}
in~$\ramrat\bL$ is a disjoint union
\begin{equation}\label{eq:structure-rational-ramified}
  \ricsol_{\ramrat\bL} = \coprod_{(\lambda,g)} \ricsol_{\bL,\lambda,g}
\end{equation}
indexed by a finite set of
pairs $(\lambda,g)$, where~$\lambda$ is in~$\bL\cap\Lambda'$
and~$g$ is a rational function satisfying $g(0) = 1$,
such that the~$\fH_{\bL,\lambda,g}$ partition~$\fH_{\bL,\lambda}$.
Each\/~$\ricsol_{\bL,\lambda,g}$ can be parametrized bijectively
by
\begin{equation*}
  u(x) = \lambda\,
        \frac{\sum_{j=1}^s c_j p_j(x^{b/q_\lambda}) }
        {\sum_{j=1}^s c_j p_j(x^{1/q_\lambda}) }
        g(x^{1/q_\lambda})
  \quad\text{for}\quad
  (c_1:\ldots:c_s) \in \bP^{s-1}(\bL)
\end{equation*}
where the~$p_j$ are those in the uniquely determined tuple of Proposition~\ref{prop:rational-ramified-hypergeometric}.
The dimensions~$s-1$ of the projective spaces add up to a number
that is at most the order~$r$ of the linear equation~\eqref{eq:linear}
minus the cardinality of the set of pairs~$(\lambda,g)$ indexing the disjoint union~\eqref{eq:structure-rational-ramified}.
\end{thm}

\begin{proof}
The classes~$\nonz{\fH}$ of Theorem~\ref{thm:structure-main},
applied to $\dring = \puiseux\bL$ and $F = \ramrat\bL$,
are the~$\fH_{\bL,\lambda,g}$ of Definition~\ref{def:classes-L-lambda-g}.
The result then follows, using Remark~\ref{rem:rational-param}
and the explicit basis~\eqref{eq:rational-ramified-hypergeometric} of~$\fH_{\bL,\lambda,g}$
provided by Proposition~\ref{prop:rational-ramified-hypergeometric}.
\end{proof}


\section{Degree bounds for rational solutions}
\label{sec:bounds-for-rational-solutions}

In the present section, we derive
degree bounds for rational solutions of the Riccati equation
in terms of its order~$r$ and coefficient degree~$d$.
Such bounds will be useful
in~\S\ref{sec:approx-syz}
to select relevant Hermite--Padé approximants.

The following easy consequence of Lemma~3.1(c) in
\parencite{ChyzakDreyfusDumasMezzarobba-2018-CSL}
will be used throughout;
we prove it for self-containedness.
\begin{lem}\label{lem:M-Bezout}
Given a field~$K$, $P$ and~$Q$ in~$K[x]$, and any~$j \in \bN$,
$P$ and~$Q$ are coprime if and only if so are $M^j P$ and~$M^j Q$.
\end{lem}
\begin{proof}
If $P$ and~$Q$ are coprime, there exist polynomials $A$ and~$B$
such that the relation $AP + BQ = 1$ holds.
Therefore, $M^jA \, M^jP + M^jB \, M^jQ = 1$,
so that $M^jP$ and~$M^jQ$ are coprime.
%
Conversely, if $M^jP$ and~$M^jQ$ are coprime,
then there exist polynomials $A$ and~$B$
such that $A \, M^jP + B \, M^jQ = 1$.
If some $G \in K[x]$ divides both $P$ and~$Q$,
then $M^jG$~divides~1, so $G$~must be a constant.
Therefore, $P$ and~$Q$ are coprime.
\end{proof}

\begin{prop}\label{prop:deg-bounds-for-ratfuns}
  Assume that $P / Q \in \rat\bKbar$, with $\gcd(P, Q) = 1$, is a solution
  of~\eqref{eq:riccati}. Then, the following degree bounds hold:
    \begin{equation}\label{eq:bound-P}
     \deg P \leq \Bnum :=
       \begin{cases}
         2d & (b=2) , \\
         {4d}/{b^{r-1}} & (b\ge3) ,
       \end{cases}
    \end{equation}
    \begin{equation}\label{eq:bound-Q}
    \deg Q \leq \Bden :=
      \begin{cases}
        2(1-1/2^{r})d & (b=2) , \\
        {3d}/{b^{r-1}} & (b\ge3) .
      \end{cases}
    \end{equation}
\end{prop}

\begin{proof}
By Lemma~\ref{lem:M-Bezout} over~$K=\bKbar$,
the assumption $\gcd(P, Q) = 1$ implies $\gcd(M^{r-1} P, M^{r-1} Q) = 1$,
that is, $M^{r-1} P$ and~$M^{r-1} Q$ are coprime.
For $n\in \bN$, let $\rfact{n}{y}$ denote the ``rising factorial''
$\prod_{i=0}^{n-1} M^i y$.
In particular, $\rfact{0}{y}=1$.
Multiplying~\eqref{eq:riccati} by $\rfact{r}{Q}$ yields
\begin{equation}\label{eq:cleared-riccati}
\sum_{i=0}^r \ell_i \rfact{i}{P} \rfact{r-i}{(M^i Q)} = 0 .
\end{equation}
Since the factor $M^{r - 1} Q$ appears in all terms on the left-hand side
of~\eqref{eq:cleared-riccati} but the term for~$i = r$,
and since $M^{r - 1} Q $ and $M^{r - 1} P$ are coprime,
$M^{r - 1} Q$ must divide $\ell_r \, \rfact{r-1}{P}$.
Hence, since $\deg \ell_r \leq d$,
the degrees of $Q$ and~$P$ are related by the inequality
\begin{equation}\label{eq:first-bound-PQ}
   b^{r-1} \deg Q \leq d + \frac{b^{r-1} - 1}{b - 1} \deg P .
\end{equation}
Furthermore,
for~\eqref{eq:cleared-riccati} to hold,
at least one term of index~$i<r$
must have a degree greater than or equal to
the degree of the term of index~$r$.
Simplifying by the common factor $\rfact{i}{P}$
yields
\begin{equation*}
\deg\left(\ell_r \, \rfact{r-i}{(M^i P)}\right) \leq
\deg\left(\ell_i \, \rfact{r-i}{(M^i Q)}\right) ,
\end{equation*}
from which follows
\begin{equation*}
   \deg P - \deg Q \leq
   \frac{\deg \ell_i - \deg \ell_r}{(b^{r} - b^{i})/(b-1)} \leq
   \frac{d}{b^{r-1}} .
\end{equation*}
The above inequality yields an upper bound on~$\deg P$,
\begin{equation}\label{eq:second-bound-PQ}
\deg P \leq \frac{d}{b^{r-1}} + \deg Q .
\end{equation}
Substituting it into~\eqref{eq:first-bound-PQ},
we find
\begin{equation*}
b^{r-1} \deg Q \leq d + \frac{b^{r-1} - 1}{b - 1} \left(\frac{d}{b^{r-1}}+\deg Q\right)
= d\frac{b^r-1}{(b - 1)b^{r-1}} +\frac{b^{r-1} - 1}{b - 1}\deg Q .
\end{equation*}
Multiplying by~$b-1$ yields
\begin{equation}\label{eq:third-bound-PQ}
(b^r-2b^{r-1}+1) \deg Q \leq \frac{d}{b^{r-1}} (b^r-1) \leq db .
\end{equation}
%
For the case~$b\geq3$,
using the last term,~$db$, in~\eqref{eq:third-bound-PQ},
and the inequality $b^r \leq 3(b^r-2b^{r-1}+1)$
yields~\eqref{eq:bound-Q}.
%
For the case~$b=2$,
specializing the left inequality in~\eqref{eq:third-bound-PQ} at~$b=2$
yields precisely~\eqref{eq:bound-Q}.
%
In both cases, \eqref{eq:bound-P}~is a direct consequence
of \eqref{eq:second-bound-PQ} and~\eqref{eq:bound-Q}.
\end{proof}

\begin{rem}
The elementary result of Proposition~\ref{prop:deg-bounds-for-ratfuns} is remarkable
as it provides a uniform polynomial bound
in terms of scalar parameters describing the size of the equation,
namely its order~$r$ and degree~$d$.
This is unreachable in the shift operator case, where the degrees of rational
solutions of Riccati equations may be exponential in the bit size of the
equation.
For example, the Charlier polynomials
\[
  C_n(x,a) =
  {}_2F_0\left(
    \begin{array}{c}
      -n,-x\\ -
    \end{array}; -a^{-1}
  \right)
\]
viewed as functions of~$x$ with parameters $n\in\bN$ and $a > 0$ satisfy the recurrence equation \parencite[\S18.22]{DLMF}
\[
  a C_n(x+1,a)
  -(a + x) C_n(x,a)
  +x C_n(x-1,a)
  + n C_n(x,a)
  = 0
\]
whose degrees of coefficients are bounded by~$d = 1$
and whose last coefficient~$n$ has bit size~$\log n$,
while $C_n(x,a)$ has degree~$n$.
As a result the associated Riccati equation has solutions $C_n(x+1,a)/C_n(x,a)$ whose numerator and denominator cannot be bounded solely as a function of~$d$.
The fact that the Mahler operator drastically increases the degree is sometimes a difficulty,
but here it allows us to obtain the bounds in Lemma~\ref{prop:deg-bounds-for-ratfuns}.
\end{rem}

\begin{rem}
The exponents of $b$ and~$d$ in the bounds \eqref{eq:bound-P} and~\eqref{eq:bound-Q} are tight,
as we show now.
For a given nonzero rational function~$u = P/Q$ in its lowest terms with both $P$ and~$Q$ monic,
let us consider any operator of order~$r\geq 2$
\begin{multline*}
  L = \biggl(\sum_{k=0}^{r-1} c_k M^k\biggr) (QM - P) \\
  = c_{r-1}(M^{r-1}Q) M^r + \sum_{k=1}^{r-1} \left( c_{k-1} M^{k-1}Q - c_k M^k P  \right) M^k - c_0 P,
\end{multline*}
with constant coefficients~$c_0$, \dots, $c_{r-1}$ in~$\bKbar$
satisfying $c_{r-1} \neq 0$.
The operator admits $M - u$ as a right-hand factor, hence $u$ is a solution of the Riccati equation according to Lemma~\ref{lem:linear-riccati-equiv}.
The leading coefficient of~$L$ has degree $b^{r-1}\deg Q$.
In case $\deg Q \geq b \deg P$, all other coefficients have lower degree.
In case $\deg Q < b \deg P$, the coefficient of $M^{r-1}$ has degree $b^{r-1}\deg P$ and the remaining ones have lower degree.
Hence, in both cases
the maximum degree of the coefficients of~$L$ is equal to $d = b^{r-1} \max(\deg P,\deg Q)$.
Upon choosing $b \geq 3$ and~$\deg P = \deg Q$,
the bounds \eqref{eq:bound-P} and~\eqref{eq:bound-Q} become $\Bnum = 4\deg P$ and $\Bden = 3\deg Q$,
showing that they overshoot by no more than a constant factor~$4$.
\end{rem}


\part{Algorithm by exploration of the possible singularities}
\label{part:petkovsek}


\section{Mahlerian variant of Petkovšek's algorithm}
\label{sec:petkovsek-variant}

In this section, we present an algorithm for computing hypergeometric solutions
of linear Mahler equations adapted from Petkovšek's algorithm for difference
equations in the usual shift operator.
In doing so, we generalize to arbitrary order a previous adaptation of
Petkovšek's algorithm to Mahler equations of order~2 due to Roques.

Equations are given with polynomial coefficients over a field~$\bK$,
and we solve them for solutions
with coefficients in a field~$\bL$ satisfying $\bKbar \supseteq \bL \supseteq \bK$.
As a consequence of~\S\ref{sec:bounds}, particularly the definition~\eqref{eq:q-lambda} for the ramification bound~$q_\lambda$,
we have a bound
\begin{equation}\label{eq:q-L}
  q_\bL = \lcm_{\lambda\in\bL\cap\Lambda} q_\lambda
\end{equation}
on the ramification orders of solutions in~$\ramrat\bK$ of the Riccati equation,
so that computing all ramified rational solutions reduces to computing the plain
rational solutions of a modified equation.
%
Additionally, the method to be used in \S\ref{sec:roques} and~\S\ref{sec:bgpf}
requires a supplementary ramification in its intermediate calculations:
whatever the target ramification order,
our method requires
the working ramification order  to be multiplied by a factor~$b^{r-1}$.


\subsection{Petkovšek's classical algorithm}
\label{sec:petkovsek}

In the case of the linear classical difference equation
\begin{equation}\label{eq:shift-linear}
\ell_r(x) y(x+r) + \dots + \ell_0(x) y(x) = \sum_{i=0}^r \ell_i(x) y(x+i) = 0
\end{equation}
and the corresponding Riccati equation
\begin{equation}\label{eq:shift-riccati}
\ell_r(x) u(x) \dotsm u(x+r-1) + \dots + \ell_1(x) u(x) + \ell_0(x) = \sum_{i=0}^r \ell_i(x) \prod_{j=0}^{i-1} u(x+j) = 0 ,
\end{equation}
an algorithm due to \textcite{Petkovsek-1992-HSL} is known
to solve~\eqref{eq:shift-riccati} for all its rational function solutions,
or equivalently to find
all first-order right-hand factors of~\eqref{eq:shift-linear}.

The algorithm is based on the concept of a \emph{Gosper--Petkovšek form}:
for any rational function $u(x) \in \nonz{\rat\bL}$,
there exist
a constant~$\zeta \in \nonz{\bL} $
and monic polynomials $A(x),B(x),C(x)$ in~$\pol\bL$
satisfying:
\begin{enumerate}
\item $u(x) = \zeta \frac{C(x+1)}{C(x)} \frac{A(x)}{B(x)}$,
\item $A(x)$ and~$C(x)$ are coprime,
\item $B(x)$ and~$C(x+1)$ are coprime,
\item\label{it:petkovsek-AB}
  $A(x)$ and~$B(x+i)$ are coprime for all $i \geq 0$.
\end{enumerate}
Now, any potential nonzero rational solution~$u$
of the Riccati equation~\eqref{eq:shift-riccati}
leads to the necessary relation
\begin{equation}\label{eq:denom-free-shift-riccati}
\sum_{i=0}^r \ell_i(x) \, \zeta^i \, C(x+i) \, \biggl(\prod_{j=0}^{i-1} A(x+j)\biggr) \biggl(\prod_{j=i}^{r-1} B(x+j)\biggr) = 0 .
\end{equation}
Here, $A(x)$~appears in all the terms of the sum but the one for~$i=0$.
As it is coprime to all forward shifts of~$B(x)$ and to~$C(x)$,
it must divide~$\ell_0(x)$.
Similarly, $B(x+r-1)$~appears in every term but the one for~$i=r$,
and so must divide~$\ell_r(x)$.
%
This motivates iterating on all pairs of monic divisors of $\ell_0$ and~$\ell_r$.
Given monic $A(x) \divides \ell_0(x)$ and $B(x) \divides \ell_r(x-r+1)$,
where divisibility is meant in~$\pol\bL$,
the leading coefficient of the left-hand side of~\eqref{eq:denom-free-shift-riccati}
is independent of the choice of a monic~$C(x)$.
So this leading coefficient yields
an algebraic equation in~$\zeta$.
Each choice of a solution~$\zeta \in \bL$
turns~\eqref{eq:denom-free-shift-riccati} into an equation
that can be solved for polynomial solutions $C(x)\in\pol\bL$.
The algorithm then gathers and returns all found $(\zeta, A(x), B(x), C(x))$.

Remark that the classical definition of the literature,
quantified over all integers~$i \in \bN$
and reproduced as point~\ref{it:petkovsek-AB} above,
is stronger than needed:
the proof has used the property for $0\leq i \leq r-1$ only.
In the Mahler case,
it will prove important to use the weaker constraint
to get an algorithm.
The reader should also compare point~\ref{it:petkovsek-AB} of the present section
with its analogues in \S\ref{sec:roques} and~\S\ref{sec:bgpf}.

\subsection{Roques's algorithm for order~2}
\label{sec:roques}

Inspired by Hendriks' works
for usual difference equations \parencite{Hendriks-1998-ADD}     % [page~450]
and for $q$-difference equations \parencite{Hendriks-1997-ACS},  % [page~338]
\textcite[\S6.2]{Roques-2018-ARB} recently presented
an analogue of Petkovšek's algorithm for Mahler equations of order~$2$,
that is, equations of the form
\begin{equation}\label{eq:mahler-riccati-2}
\ell_2(x) u(x) u(x^b) + \ell_1(x) u(x) + \ell_0(x) = 0 .
\end{equation}
Roques's original presentation
determines along his algorithm
a suitable extension of~$\bK$        % $l_1$ in his text
sufficient to obtain all solutions from~$\ramrat\bKbar$.
Here, we present a variant that computes with an input field~$\bL$,
so as to be consistent with the rest of our text.

After finding a bound~$q$ such that all solutions~$u \in \ramrat\bL$
are in fact in~$\rrat\bL{q}$,
let us introduce a new indeterminate~$t$ for which $x = t^{qb}$,
so as to prove, for any given~$u \in \ramrat\bL$,
the existence
of a nonzero constant~$\zeta \in \nonz{\bL}$
and monic polynomials $A,B,C \in \bL[t]$
satisfying
\begin{enumerate}
\item\label{it:u-of-ABC-in-BGPF}
  $u(x) = \zeta \frac{C(x^{1/q})}{C(x^{1/qb})} \frac{A(x^{1/qb})}{B(x^{1/qb})}$,
  that is, $u(t^{qb}) = \zeta \frac{C(t^b)}{C(t)} \frac{A(t)}{B(t)}$,
\item $A$ and~$C$ are coprime,
\item $B$ and~$M C$ are coprime,
\item\label{it:roques-AB-bounded}
  $A$ and~$M^i B$ are coprime for all $i \in \{0,1\}$,
\item\label{it:roques-C-MC} $C$ and~$M C$ are coprime,
\end{enumerate}
where $M$~acts on~$\bL[t]$ by substituting $t^b$ for~$t$.

Now, any nonzero ramified rational solution~$u$
of the Riccati equation~\eqref{eq:mahler-riccati-2}
leads to the necessary relation
\begin{multline}\label{eq:roques-necessary}
\ell_2(t^{qb}) \zeta^2 C(t^{b^2}) A(t) A(t^b)
\\ \hbox{} + \ell_1(t^{qb}) \zeta C(t^b) A(t) B(t^b)
+ \ell_0(t^{qb}) C(t) B(t) B(t^b) = 0 .
\end{multline}
This time, one finds that
$A(t)$~must divide~$\ell_0(t^{qb})$,
while $B(t^b)$~must divide~$\ell_2(t^{qb})$,
implying that $B(t)$~must divide~$\ell_2(t^q)$.

Roques's approach continues in a way similar in spirit to Petkovšek's,
although technical reasons require to exchange the order of steps.
Roques indeed finds a linear constraint on the degree of~$C$ by putting apart the term with~$\zeta^2$ in~\eqref{eq:roques-necessary}.
Finding the coefficients of~$C$ then amounts to solving a finite linear system.
As a side remark, in Roques's text valuations and degrees are treated interchangeably, and the calculation of the coefficient~$\zeta$ is obscured.
We will clarify this in the next section.

\subsection{A new algorithm for higher-order Mahler equations}
\label{sec:bgpf}

In this section,
we deal with Riccati Mahler equations~\eqref{eq:riccati}
of general order~${r \geq 2}$.
The core of the section describes an algorithm for solving
for (plain) rational functions from~$\rat\bL$.

In order to go beyond order~2,
we observe that
point~\ref{it:roques-AB-bounded} in Roques's definition
requires a coprimality only for~$0 \leq i \leq  r-1 = 1$ (when~$r = 2$),
whereas point~\ref{it:petkovsek-AB} in the shift situation
requires a coprimality for~$0 \leq i$,
although the proof in~\S\ref{sec:petkovsek} for an equation of order~$r$
only uses the cases~$0 \leq i \leq r-1$.
This motivates us
to introduce the following notion of a bounded Gosper--Petkovšek form.
%
\begin{defi}\label{def:BGP}
Given a rational function $u(x) \in \nonz{\rat\bL}$ and an integer~$r \geq 2$,
a \emph{bounded Gosper--Petkovšek form}
of order~$r$ for~$u(x)$ is a tuple
$(\zeta, A, B, C) \in \nonz{\bL} \times \bL[t]^3$,
with $A$, $B$, $C$ monic polynomials in a new indeterminate~$t$,
\hbox{such that}:
\begin{enumerate}
\item\label{it:gen-def-u}
%  $M^{r-1} u = \zeta \frac{M C}{C} \frac{M^{r-1} A}{B}$,
%  that is,
  $u(t^{b^{r-1}}) = \zeta \frac{C(t^b)}{C(t)} \frac{A(t^{b^{r-1}})}{B(t)}$,
\item\label{it:coprimality-Mr-1A-C}
  $M^{r-1} A$ and~$C$ are coprime,
\item\label{it:coprimality-B-MC}
  $B$ and~$M C$ are coprime,
\item\label{it:bounded-AB}
  $M^i A$ and~$B$ are coprime for all $i \in \{0,\dots,r-1\}$,
\end{enumerate}
where $M$~acts on~$\bL[t]$ by substituting $t^b$ for~$t$.
\end{defi}
%
By Lemma~\ref{lem:M-Bezout} over~$K=\bL$,
point~\ref{it:bounded-AB} above can be restated equivalently into:
$M^{r-1} A$ and~$M^i B$ are coprime for all $i \in \{0,\dots,r-1\}$.
Also remark that
for a polynomial triple $(A, B, C)$ satisfying our definition for~$r = 2$,
the polynomial triple $(MA, B, C)$ satisfies Roques's definition (with~$q = 1$),
at least provided $\gcd(C, MC) = 1$.
A~constructive proof of the existence
of bounded Gosper--Petkovšek forms
will be provided in~\S\ref{sec:bounded-gpf-computation}.

Now, consider any potential nonzero rational solution~$u$
of the Riccati equation~\eqref{eq:riccati},
represented by one of its bounded Gosper--Petkovšek forms.
Substituting the Gosper--Petkovšek form for~$u$
and $t^{b^{r-1}}$ for~$x$ in~\eqref{eq:riccati} leads
after canceling denominators
to the necessary relation
\begin{equation}\label{eq:mahler-necessary-1}
  \tilde L(t, \zeta M)\, C = 0 ,
\end{equation}
where $\tilde L$~is the operator in~$\bL[t]\langle M \rangle$ defined by
\begin{equation}\label{eq:mahler-necessary-2}
  \tilde L (t, M) =
\sum_{k=0}^r \biggl( M^{r-1}\ell_k(t) \times \prod_{j=0}^{k-1} M^{r-1+j}A(t) \times \prod_{j=k}^{r-1} M^jB(t) \biggr) M^k .
\end{equation}
In this formula, note that beside the polynomials $A$ and~$B$ that are by definition in the ring~$\bL[t]$,
we have noted $\ell_k(t)$ for the result of the substitution
of~$t$ for~$x$ in~$\ell_k$.
The factor $M^{r-1} A$~appears in all the terms
of the expansion of~\eqref{eq:mahler-necessary-1}, except for the one corresponding to~$k=0$,
\[ M^{r-1}\ell_0(t) \times C(t) \times \prod_{j=0}^{r-1} M^jB(t) ; \]
using points \ref{it:coprimality-Mr-1A-C} and~\ref{it:bounded-AB} in Definition~\ref{def:BGP},
$M^{r-1} A$~must divide~$M^{r-1} \ell_0$,
and Lemma~\ref{lem:M-Bezout} implies that $A$~must divide~$\ell_0$.
Similarly, $M^{r-1} B$~appears in all the terms of~\eqref{eq:mahler-necessary-1} , except for the one corresponding to~$k=r$,
\[ M^{r-1}\ell_r(t) \times \zeta^r M^rC(t) \times \prod_{j=0}^{r-1} M^{r-1+j}A(t) ; \]
thus, $M^{r-1} B$~must divide~$M^{r-1} \ell_r$,
and Lemma~\ref{lem:M-Bezout} implies that $B$~must divide~$\ell_r$.

To complete the pairs~$(A,B)$ into candidate tuples $(\zeta, A, B, C)$
delivering rational functions in~$\bL(t)$,
we interpret~\eqref{eq:mahler-necessary-1} as an analogue of~\eqref{eq:single-eqn} in Proposition~\ref{lem:single-lambda-equiv}.
To this end,
we start by introducing
in analogy with the construction of~$\omdr$ in~\S\ref{sec:difference}
a ring whose coefficients are series in~$t^{-1}$, in the form
\begin{equation*}
  \omdr' = \bigoplus_{\lambda \in \nonz{\bKbar}}\, \mylogalt{\lambda}\puiseuxalt\bKbar .
\end{equation*}
Here, the~$\mylogalt{\lambda}$ denote elements of some new family~$(e'_\lambda)_{\lambda\in\nonz\bKbar})$ of generators
satisfying the algebraic relations
$e'_\lambda e'_{\lambda'} = e'_{\lambda\lambda'}$ and $e'_1 = 1$.
The theory of~$\omdr'$ parallels that of~$\omdr$,
including the results developed
in~\S\ref{sec:bounds}
to find the possible
logarithmic parts~$\mylog\lambda$ and valuations of the corresponding Puiseux series in a
solution of~\eqref{eq:linear}
by
using the lower Newton polygon.

\begin{defi}\label{def:upper-newton}
Let $L$ be a general linear Mahler operator.
The upper convex hull of the set of points $(b^k,j) \in \bR^2$ of Definition~\ref{def:lower-newton} is called the \emph{upper Newton polygon} (of~$L$).
%
In analogy with Definition~\ref{def:lower-char-poly},
we index its edges by decreasing slopes and
denote by~$\xi_j(X)$ the \emph{characteristic polynomial} of its $j$th edge.
%
Define~$Z(L)$ to be the union of the sets of roots in~$\bKbar$ of the~$\xi_j$,
\begin{equation}\label{eq:def-Zeta}
Z(L) = \{ \zeta \in \bKbar : \exists j, \ \xi_j(\zeta) = 0 \} .
\end{equation}
%
The $j$th edge will be called \emph{$\zeta$-admissible} (for~$L$) if~$\xi_j(\zeta) = 0$.
\end{defi}

Now, an analogue of Proposition~\ref{lem:single-lambda-equiv} holds,
with the difference that the parameter~$\lambda$ of the new proposition
needs to be the root of some characteristic polynomial
associated with an edge of an upper Newton polygon,
rather than a lower Newton polygon.
Consequently,
the constant~$\zeta$ in~\eqref{eq:mahler-necessary-1}
must be an element of~$Z(\tilde L)$.
In this situation, the degree of~$C$ in~$t$
must be the opposite of the slope of some edge
associated with the upper Newton polygon:
the degree of a solution~$C$ of~\eqref{eq:mahler-necessary-1} in~$t$ is the opposite of the valuation with respect to~$t^{-1}$ of~$C$,
which is given by the lower Newton polygon of~$\tilde L(t^{-1},M)$;
the upper Newton polygon of~$\tilde L(t,M)$ is the symmetric with respect to a horizontal axis of the lower Newton polygon of~$\tilde L(t^{-1},M)$;
edges associated by this symmetry have opposite slopes;
the result follows.

We summarize the previous discussion in the following result.

\begin{prop}\label{prop:bGP-necessary-conds}
Let $(\zeta, A, B, C)$ be a bounded Gosper--Petkovšek form of order~$r$
of any rational solution~$u$ of~\eqref{eq:riccati},
and let $\tilde L$ be defined by~\eqref{eq:mahler-necessary-2}.
Then, necessarily:
\begin{itemize}
\item $\zeta \in Z(\tilde L)$,
\item $A$~divides~$\ell_0(t)$,
\item $B$~divides~$\ell_r(t)$,
\item $C$~is a nonzero polynomial solution of~\eqref{eq:mahler-necessary-1},
  implying $\deg C$~is the opposite of a nonpositive integer slope of an edge
  associated with the upper Newton polygon of~$\tilde L$.
\end{itemize}
\end{prop}

\begin{algo}
\inputs{
  A Riccati Mahler equation~\eqref{eq:riccati} with coefficients $\ell_k(x) \in \pol\bK$.
  Some intermediate field~$\bL$, that is, a field satisfying $\bKbar \supseteq \bL \supseteq \bK$.
}
\outputs{
  The set of rational functions $u \in \rat\bL$ that solve~\eqref{eq:riccati}.
}
\caption{\label{algo:BP}%
Rational solutions to a Riccati Mahler equation.
Compare with the efficiency improvements in Algorithm~\ref{algo:IP}.}
%%% Special source formatting to ease the writing of the variant algorithm:
%%% \begin{enum}/\item/\end{enum} start on same column; contents of an item
%%% shifted by 6 spaces to the right; this reflects the typeset pdf, in such
%%% a way that one can imagine \item is an item label. Give up the 80-char
%%% lines. All enums label styles are forced so as to match with the variant,
%%% albeit without following the default nesting of styles.
\begin{deepenum}[label=(\Alph*)]
\item Set $\cU := \varnothing$.
\item \label{algo:BP:main-loop}
      For each monic factor $A(t) \in \bL[t]$ of~$\ell_0(t)$, for each monic factor $B(t) \in \bL[t]$ of~$\ell_r(t)$ such that $M^iA$ and~$B$ are coprime for $0 \leq i < r$:
      \begin{deepenum}[label=(\arabic*)]
      \item \label{it:compute-L-tilde}
            compute $\tilde L(t,M)$ by~\eqref{eq:mahler-necessary-2},
      \item \label{it:upper-newton-polygon}
            compute the upper Newton polygon of~$\tilde L$, the set~$Z(\tilde L) \cap \bL$ of roots~$\zeta$ in~$\bL$ of the associated characteristic polynomials,
      \item \label{it:loop-over-zeta}
            for each~$\zeta$ in~$Z(\tilde L) \cap \bL$:
            \begin{deepenum}[label=(\alph*)]
            \item \label{it:candidate-degree-C}
                  compute the maximum $\Delta_\zeta$ of the integer values of the opposites of the slopes of the $\zeta$-admissible edges (for~$\tilde L$),
            \item \label{it:unchanged-steps}
                  if $\Delta_\zeta \geq 0$:
                  \begin{deepenum}[label=(\roman*)]
                  \item \label{it:solving-for-C}
                        compute a basis $(C_i)_{1\leq i \leq s}$ of solutions in $\bL[t]_{\leq \Delta_\zeta}$ of the equation
                        $\tilde L(t, \zeta M)\, C = 0$,
                  \item \label{it:parametrizing-for-C}   % -> has sols
                        if $s>0$:
                        \begin{deepenum}[label=(\greek*)]
                        \item \label{it:param-C}
                              set~$C := \sum_{i=1}^s c_i C_i$ for formal parameters $c_i$,
                        \item \label{it:identify-rf}
                              normalize the rational function \\
                              \begin{myequation*}
                              \tilde u(t) := \zeta \frac{C(t^b)}{C(t)} \frac{A(t^{b^{r-1}})}{B(t)} ,
                              \end{myequation*}\\[1ex]
                              which is an element of $\bL(c_1,\dots,c_s)(t^{b^{r-1}})$,
                              so as to identify $u(x) \in \bL(c_1,\dots,c_s)(x)$ such that $u(t^{b^{r-1}}) = \tilde u(t)$,
                        \item augment~$\cU$ with~$u$.
                        \end{deepenum} % greek
                  \end{deepenum} % roman
            \end{deepenum} % alph
      \end{deepenum} % arabic
\item \label{it:algo-return}
      Remove redundant elements from~$\cU$ by the method described before Proposition~\ref{prop:BP-no-loss} and return the resulting~$\cU$.
\end{deepenum} % Alph
\end{algo}

The previous considerations lead to Algorithm~\ref{algo:BP},
whose general structure is the following:
\begin{itemize}
\item a loop over candidates~$(A,B)$ is set up at step~\ref{algo:BP:main-loop} from the \emph{lower} Newton polygon of the input~$L$;
\item candidates~$\zeta$, then degrees for candidates~$C$ at step~\ref{algo:BP:main-loop}\ref{it:loop-over-zeta}\ref{it:candidate-degree-C}, are obtained from the \emph{upper} Newton polygon of the auxiliary operator~$\tilde L$;
\item solving for~$C$ at step~\ref{algo:BP:main-loop}\ref{it:loop-over-zeta}\ref{it:unchanged-steps}\ref{it:solving-for-C} is done by appealing
to our algorithm for polynomial solutions of bounded degree
in \parencite[\S2.6, Algorithm~5]{ChyzakDreyfusDumasMezzarobba-2018-CSL};
\item to avoid redundancy in the output,
  the cleaning step~\ref{it:algo-return} makes sure to return a partition
  by enforcing that no parametrization is included in another.
\end{itemize}

Regarding the last item,
the cleaning step~\ref{it:algo-return} removes redundant elements of~$\cU$ by a simple loop:
while $\cU$~contains two distinct elements $u^{(1)}$ and~$u^{(2)}$
with inclusion of~$u^{(1)}$ in~$u^{(2)}$,
it removes $u^{(1)}$ from~$\cU$.
This is effective provided we have an algorithmic inclusion test available.
To describe one, observe that,
given two parametrized rational functions,
$u^{(1)}$~with parameters $c^{(1)} = (c^{(1)}_1,\dots,c^{(1)}_{s_1})$
and $u^{(2)}$~with parameters $c^{(2)} = (c^{(2)}_1,\dots,c^{(2)}_{s_2})$,
inclusion of~$u^{(1)}$ in~$u^{(2)}$ is only possible if~$s_1 \leq s_2$,
in which case getting rid of denominators in the equation~$u^{(1)} = u^{(2)}$
and equating like powers of~$x$
results in a linear system in~$c^{(2)}$ linearly parametrized by~$c^{(1)}$.
Either this system has no nonzero solution, proving noninclusion,
or it provides a parametrization proving inclusion.
We thus have an algorithm by linear algebra over~$\bL$.

We now prove a first part of the correctness of the algorithm:
no rational solution is lost.

\begin{prop}\label{prop:BP-no-loss}
Algorithm~\ref{algo:BP} computes the set of rational solutions of the Riccati equation~\eqref{eq:riccati}
as a union of sets parametrized by finite-dimensional\/ $\bL$-projective spaces.
\end{prop}

\begin{proof}

Observe that Algorithm~\ref{algo:BP}
iterates on all tuples $(\zeta, A, B, \Gamma(c))$
in $\nonz{\bL} \times \bL[t]^2 \times \bL(c_1,c_2,\dots)[t]$ such that,
for any values of the parameters~$c_i$ in~$\bL$,
the tuple $(\zeta, A, B, C)$ where $C = \Gamma(c)$ satisfies:
the necessary conditions (i), (ii), and~(iii) of Proposition~\ref{prop:bGP-necessary-conds},
point~\ref{it:bounded-AB} of Definition~\ref{def:BGP},
a degree bound on~$C$ that is necessarily satisfied by the polynomial kernel of~$\tilde L(t,\zeta M)$, cf. the necessary condition~(iv) in the same proposition.
The algorithm therefore represents a set that is less constrained that
the set of bounded Gosper--Petkovšek forms of order~$r$ of~$u$
for any rational solution~$u$ of~\eqref{eq:riccati};
in particular, it represents them all, and,
by the existence of bounded Gosper--Petkovšek forms (see~\S\ref{sec:bounded-gpf-computation}),
the algorithm must find any solution~$u$ of~\eqref{eq:riccati}.
%
Conversely, for any~$u(x)$ element of the output~$\cU$,
obtained by the algorithm from a tuple $(\zeta, A, B, C)$,
expanding~\eqref{eq:mahler-necessary-1} by using~\eqref{eq:mahler-necessary-2},
then dividing  by the relevant product
shows that $u(x)$~solves~\eqref{eq:riccati}.
%
We have thus proved that Algorithm~\ref{algo:BP} computes all rational solutions.
\end{proof}

For the end of the present section, we call a \emph{block}
the image of a similarity class of nonzero hypergeometric elements
under $y \mapsto M y/y$.
The following theorem states the correctness of Algorithm~\ref{algo:BP}.

\begin{thm}\label{thm:BP}
%
Algorithm~\ref{algo:BP} computes the set of rational solutions of the Riccati equation~\eqref{eq:riccati}
as a disjoint union of sets bijectively parameterized by finite-dimensional\/ $\bL$-projective spaces.
Equivalently, the output~$\cU$ of Algorithm~\ref{algo:BP} consists
of formal parametrizations of blocks, with exactly one parametrization for each block,
and each such parametrization is a bijection.
\end{thm}
\begin{proof}
Each element~$U(c) = (c_1,\dots,c_s)$ of~$\cU$ can be interpreted as a parametrization
\begin{equation}\label{eq:BP}
\gamma = (\gamma_1:\ldots:\gamma_s) \in \bP^{s-1}(\bL)
\mapsto
U(\gamma) = \zeta \frac{MC}{C} \frac{M^{r-1}A}{B} \in \rat\bL .
\end{equation}
Fix $y_0$, a nonzero solution of~$My_0 = \zeta \frac{M^{r-1}A}{B} y_0$.
The solutions of $My = U(\gamma)y$ when $\gamma$~ranges in~$\nonz{(\bL^s)}$
form a vector space~$\fG$ that is exactly $C(\bL^s)y_0$.
Because $C$~is a polynomial in~$x$,
the set~$\nonz{\fG}$ is included in a similarity class.

For each similarity class~$\nonz{\fH}$,
the finite-dimensional space~$\fH$
is by Proposition~\ref{prop:BP-no-loss}
covered as a finite union of vector spaces~$\fG$ obtained from elements~$U\in\cU$.
Let $d$~denote the dimension of~$\fH$.
Assume that no~$\fG$ has dimension~$d$.
Then, each~$\fG$ is in some hyperplane defined by some nonzero linear form~$\phi$.
Fix a coordinate system of~$\fH$ and
let $S$ be the parametrized curve $t \mapsto (1,t,\dots,t^{d-1})$,
whose image is included in~$\fH$.
The curve can only meet a given~$\fG$ at finitely many intersections,
provided by the zeros of the polynomial $\phi(S(t))$.
Because the curve has infinitely many points,
this contradicts that $\fH$~is covered.
So at least one of the~$\fG$ is equal to~$\fH$.

By the absence of redundancy enforced at step~\ref{it:algo-return} in the algorithm,
no two distinct elements of~$\cU$ can produce vector spaces $\fG_1$ and~$\fG_2$
with $\fG_1 \subseteq \fG_2$.
So any vector space~$\fH$ of a similarity class~$\nonz{\fH}$
is obtained exactly once as a~$\fG$,
and only such~$\fH$ are obtained.
The result for blocks then follows.

Because the algorithm constructs~$C$ in~\eqref{eq:BP}
as a formal sum $C = \sum_{j=1}^s c_j C_j$
for $\bL$-linearly independent polynomials~$C_j \in \pol\bL$,
the~$C_jy_0$ form an $\bL$-basis of~$C(\bL^s)y_0$.
The implied bijection from~$\bL^s$ to the suitable~$\fH$
induces a bijection from~$\bP^{s-1}(\bL)$ to the block associated with~$\nonz{\fH}$.
\end{proof}

\begin{cor}\label{cor:riccati-to-hypergeom}
The set of\/ $\rat\bL$-hypergeometric solutions of the Mahler equation~\eqref{eq:linear}
can be described as a union of\/ $\bL$-vector spaces~$\fH$ in direct sum
pa\-ram\-e\-triz\-ed by the output~$\cU$ as follows:
for given~$U \in \cU$, the vector space~$\fH$ is spanned by a basis $(y_1,\dots,y_s)$
where each~$y_i$ is any nonzero solution of the equation $My_i = U(e_i) y_i$
for the $i$th element of the canonical basis.
\end{cor}

\begin{proof}
The statement is a direct consequence of the last paragraph
in the proof of Theorem~\ref{thm:BP}.
\end{proof}

\begin{rem}[efficiency of Algorithm~\ref{algo:BP}]
The double loop over $A$ and~$B$
induces an exponential behavior,
making this basic algorithm inefficient.
We will discuss several pruning strategies in~\S\ref{sec:efficiency-improvements}.
Furthermore, the algorithm considers tuples~$(\zeta,A,B,C)$ that provide solutions
but are not bounded Gosper--Petkovšek forms.
These tuples are redundant because the algorithm also produces the same
solutions in bounded Gosper--Petkovšek form.
From the point of view of efficiency,
the problem is not in rejecting tuples that are not bounded Gosper--Petkovšek forms,
but in not computing too many (redundant) candidates in the first place.
The necessity to determine the polynomials~$C$ late in the algorithm
makes it impossible to consider only bounded Gosper--Petkovšek forms,
and is the main cause for getting repeated solutions in the course of the algorithm
(see also the Remark~\ref{rem:GPforms-not-unique} below).
\end{rem}

\begin{rem}[solving large linear systems]
When searching for polynomial solutions of the auxiliary equations
$\tilde L(t,\zeta M)\, C = 0$,
it is crucial for performance to use the fast algorithms
introduced in~\parencite{ChyzakDreyfusDumasMezzarobba-2018-CSL}.
% in particular Algorithms 2 and~5.
% 5 = Polynomial solutions of bounded degree
% 2 = Solutions over prescribed monomial support
We take the opportunity to clarify a minor point of confusion in that work.
In~\parencite[Algorithm~2]{ChyzakDreyfusDumasMezzarobba-2018-CSL},
we appeal to the linear solving algorithm of~\textcite{IbarraMoranHui-1982-GFL}
for computing the kernel of an $m \times n$ matrix~$A$ in $O(m^{\omega-1}n)$ field
operations.
This algorithm is based on computing an LSP decomposition of~$A$, that is,
a decomposition as a product of a lower square matrix~$L$, a semi-upper
triangular matrix~$S$, and a permutation matrix~$P$.
Strictly speaking, however, this approach is only valid when~$m \leq n$
(fewer rows than columns).
As our need is for an $m\times n$ matrix~$A$ with~$m \geq n$ (more rows than columns),
a workaround is to apply the LSP decomposition algorithm to the transpose~$A^T$,
thus obtaining a PSU decomposition of~$A$,
that is, as a permutation matrix~$P$, a semi-lower triangular matrix~$S$, and an upper square matrix~$U$.
To solve for the (right) kernel, we observe $\ker A = U^{-1} (\ker S)$.
As $S$~reduces to a lower triangular matrix with nonzero diagonal elements
when the zero columns are deleted,
finding its kernel is immediate.
Inverting~$U$ takes~$O(n^\omega)$ operations.
So~$\ker A$ is obtained in $O(m/n)$ square matrix products,
hence in complexity $O(mn^{\omega-1})$.
Taking the rank~$r$ of~$A$ into account and refining the analysis
yields the complexity $O(mn r^{\omega - 2})$ announced
in~\parencite[Prop.~2.14]{ChyzakDreyfusDumasMezzarobba-2018-CSL}.
\end{rem}

To compute all \emph{ramified} rational solutions of~\eqref{eq:riccati},
we now propose Algorithm~\ref{algo:ramP},
which is a simple variant of Algorithm~\ref{algo:BP}.
By the property of~$q_\bL$ to be a uniform bound
on the ramification order of ramified rational solutions,
Algorithm~\ref{algo:ramP} is also correct, in the sense that it satisfies
an analogue of Theorem~\ref{thm:BP},
where rational solutions are replaced by ramified rational solutions.
An obvious adaptation of Corollary~\ref{cor:riccati-to-hypergeom}
to $\ramrat\bL$-hypergeometric solutions also holds.

\begin{algo}
\inputs{
  A Riccati Mahler equation~\eqref{eq:riccati} with coefficients $\ell_k(x) \in \pol\bK$.
  Some intermediate field~$\bL$, that is, a field satisfying $\bKbar \supseteq \bL \supseteq \bK$.
}
\outputs{
  The set of ramified rational functions $u \in \ramrat\bL$ that solve~\eqref{eq:riccati}.
}
\caption{\label{algo:ramP}%
Ramified rational solutions to a Riccati Mahler equation.}
\begin{deepenum}[label=(\Alph*)]
\item Compute the lower Newton polygon of $L := \sum_{k=0}^r \ell_k(x) M^k$, the associated characteristic polynomials, the set $\Lambda\cap\bL$, and the ramification bound~$q_\bL$ by~\eqref{eq:q-L}.
\item Call Algorithm~\ref{algo:BP} for computing the rational solutions of~$L(x^{q_\bL}, M)$ in~$\rat\bL$.
\item Substitute $x^{1/q_\bL}$ for~$x$ in the obtained solutions and return the resulting set.
\end{deepenum}
\end{algo}


\subsection{Existence and computation of bounded Gosper--Petkovšek forms}
\label{sec:bounded-gpf-computation}

The following lemma proves the existence of bounded Gosper--Petkovšek forms at all orders,
and its proof provides an algorithm for putting a rational function
in bounded Gosper--Petkovšek form of a given order.

\begin{lem}\label{lem:exists-bgpf}
Given any two coprime monic polynomials $P$ and~$Q$ in~$\pol\bK$,
define
a sequence of triples of polynomials given for all~$k \in \nonz{\bN}$ by
\begin{align}
\label{eq:def-ABC-1}
(A_1, B_1, C_1) &= (P, Q, 1) \\
\label{eq:def-ABC-k}
(A_{k+1}, B_{k+1}, C_{k+1}) &= \left(\frac{A_k}{G_k}, \frac{M B_k}{G_k}, M C_k \times (M^0 G_k \dotsm M^{k-1} G_k)\right) ,
\end{align}
where $G_k = \gcd(A_k, MB_k)$.
Then, for all~$k \in \nonz{\bN}$,
$(1, A_k, B_k, C_k)$ is a bounded Gosper--Petkovšek form of order~$k$
for the rational function~$P/Q$.
Additionally, there exists $k \in \nonz{\bN}$ satisfying
\begin{equation}\label{eq:stationary-ABC}
A_{k+i} = A_k , \quad B_{k+i} = M^i B_k , \quad C_{k+i} = M^i C_k ,
\qquad\text{for all~$i \in \bN$.}
\end{equation}
\end{lem}
%
\begin{proof}
The proof is by induction on~$k$.
The case~$k=1$ is immediate by~\eqref{eq:def-ABC-1}.
For some~$k \in \nonz{\bN}$, assume
that $(1, A_k, B_k, C_k)$ is a bounded Gosper--Petkovšek form of order~$k$
for the rational function~$P/Q$
and that \eqref{eq:def-ABC-k}~holds.
This provides the formulas:
\begin{align}
\label{eq:bgpf-ABC}
M^{k-1} \frac{P}{Q} &= \frac{M C_k}{C_k} \frac{M^{k-1} A_k}{B_k} , \\
\label{eq:bgpf-coprime-MkA-C}
\gcd(M^{k-1} A_k, C_k) &= 1 , \\
\label{eq:bgpf-coprime-B-MC}
\gcd(B_k, M C_k) &= 1 , \\
\label{eq:bgpf-coprime-MiA-B}
\gcd(M^i A_k, B_k) &= 1 \quad\text{for all}\quad 0 \leq i < k .
\end{align}
Then, first observe
\begin{equation*}
\frac{M C_{k+1}}{C_{k+1}} = \frac{M^2 C_k}{M C_k} \frac{M^k G_k}{G_k}
\end{equation*}
and apply~$M$ to~\eqref{eq:bgpf-ABC}, so that
\begin{equation*}
M^k \frac{P}{Q} = \frac{M^2 C_k}{M C_k} \frac{M^k (A_{k+1} G_k)}{B_{k+1} G_k}
  = \frac{M C_{k+1}}{C_{k+1}} \frac{M^k A_{k+1}}{B_{k+1}} .
\end{equation*}
Applying Lemma~\ref{lem:M-Bezout} with $K=\bK$ and~$j=1$ to~(\ref{eq:bgpf-coprime-MkA-C}--\ref{eq:bgpf-coprime-MiA-B}) implies
\begin{gather*}
\gcd(M^{i+1} (A_{k+1} G_k), B_{k+1} G_k) = 1 \quad\text{for all}\quad 0 \leq i < k , \\
\gcd(M^k (A_{k+1} G_k), M C_k) = \gcd(B_{k+1} G_k, M^2 C_k) = 1 ,
\end{gather*}
so that in particular
\begin{gather}
\label{eq:several-gcd}
\gcd(M^{i+1} A_{k+1}, B_{k+1}) = \gcd(M^{i+1} A_{k+1}, G_k) = \gcd(M^{i+1} G_k, B_{k+1}) = 1 , \\
\label{eq:several-more-gcd}
\gcd(M^k A_{k+1}, M C_k) = \gcd(B_{k+1}, M^2 C_k) = 1 .
\end{gather}
The construction~\eqref{eq:def-ABC-k} ensures $\gcd(M^0 A_{k+1}, B_{k+1}) = 1$,
so combining with the left gcd in~\eqref{eq:several-gcd}
shows~\eqref{eq:bgpf-coprime-MiA-B} at~$k+1$.
Applying Lemma~\ref{lem:M-Bezout} with~$j=k-i-1$ to the middle gcd in~\eqref{eq:several-gcd} next yields
\begin{equation*}
\gcd(M^k A_{k+1}, M^{k-i-1} G_k) = 1 .
\end{equation*}
Considering those gcds for~$0 \leq i < k$ as well as the left gcd in~\eqref{eq:several-more-gcd}
proves~\eqref{eq:bgpf-coprime-MkA-C} at~$k+1$.
Combining the right gcd in~\eqref{eq:several-gcd} for $0 \leq i < k$
together with the right gcd in~\eqref{eq:several-more-gcd}
proves~\eqref{eq:bgpf-coprime-B-MC} at~$k+1$.
We have obtained
that $(1, A_{k+1}, B_{k+1}, C_{k+1})$ is a bounded Gosper--Petkovšek form of order~$k+1$
for the rational function~$P/Q$.

Last, in view of~\eqref{eq:def-ABC-k},
the existence of~$k$ satisfying~\eqref{eq:stationary-ABC}
is equivalent
to the existence of~$k$ such that $G_{k+i} = 1$ for all~$i \in \bN$.
This~$k$ exists because $\deg A_k$~cannot decrease indefinitely.
\end{proof}

\begin{rem}\label{rem:GPforms-not-unique}
Bounded Gosper--Petkovšek forms are not unique,
even for a given order.
An example with~$b = 2$ is given for order~$r = 3$
by $(\zeta, A, B, C) = (1, x+1, 1, 1)$
and $(\zeta', A', B', C') = (1, 1, 1, x^4-1)$,
%% \begin{equation*}
%% \zeta \frac{M C}{C} \frac{M^2 A}{B}
%%   = x^4+1
%%   = \frac{x^8-1}{x^4-1}
%%   = \zeta' \frac{M C'}{C'} \frac{M^2 A'}{B'} .
%% \end{equation*}
where the first form is computed
by the direct use of the recurrence in Lemma~\ref{lem:exists-bgpf}.
\end{rem}

\begin{rem}
Point~\ref{it:roques-C-MC} in our presentation of Roques's definition
(see~\S\ref{sec:roques})
is not enforced in our definition of bounded Gosper--Petkovšek forms.
(Also compare with the constraints on $r$, $s$, and~$t$ in \parencite[\S6.2, top of page~345]{Roques-2018-ARB}.)
The mere construction of~$C_{k+1}$ in~\eqref{eq:def-ABC-k} makes
the coprimality between $C$ and~$MC$ generally impossible,
at least for~$r\geq3$.
\end{rem}


\section{A more practical algorithm}
\label{sec:efficiency-improvements}

As experiments show
(see~\S\ref{sec:discussion} and especially the timings in Table~\ref{tab:Basic-vs-Improved-GP}),
a direct implementation of Algorithm~\ref{algo:BP}
is inefficient because of the large number of pairs of divisors~$(A,B)$
it has to consider.
In the present section, we describe several ways to mitigate this issue.
The results are rather technical.
They are not used in the rest of the article,
apart from the fact that the resulting improved variant algorithm
is tested beside our other algorithms in~\S\ref{sec:impl-and-benchmark}.

\subsection{Ensuring coprimality}
\label{sec:cartesian-prod}

Given a polynomial~$f \in \bL[t]$,
let $\irred(f)$ denote the set of its \mif factors
and $\mult f p$ denote the multiplicity of a \mif polynomial~$p$ in~$f$.
By representing a monic divisor of~$\ell_0$ by the family $(\alpha_p)_{p\in\irred (\ell_0)}$ of exponents
in its  factorization $\prod_{p\in\irred (\ell_0)} p^{\alpha_p}$ into \mif factors,
the set of such divisors can be viewed as the Cartesian product
\[
  \cA = \prod_{p\in\irred (\ell_0)} \intinv{0}{\mult{\ell_0}p} ,
\]
where $\intinv{a}{b}$~denotes the integer interval~$\{a,\dots,b\}$.
In the same way, the set of monic divisors of~$\ell_r$ is represented by
\[
  \cB = \prod_{q\in\irred (\ell_r)} \intinv{0}{\mult{\ell_r}q} .
\]
So, the main loop~\ref{algo:BP:main-loop} in Algorithm~\ref{algo:BP}
can be viewed as parametrized by a pair~$(\alpha,\beta)$ in the product~$\cA\times\cB$.
However, we are  only interested in pairs~$(A,B)$
that satisfy $\gcd(M^s A, B) = 1$ for all $0 \leq s < r$,
and the basic algorithm has to test all those gcds
in the double loop over $A$ and~$B$.

To explain how to prune $\cA\times\cB$,
let us imagine that $\ell_r$ has a \mif factor~$q$ with multiplicity~$b > 0$
and that $\ell_0$ has a \mif factor~$p$ with multiplicity~$a > 0$
such that $q$~is a factor of some~$M^s p$, $0 \leq s < r$.
In such a situation, we say that the factor~$p$ is \emph{forbidden} (in~$A$) by the factor~$q$ (of~$B$).
When a pair~$(\alpha,\beta)$ of tuples is in~$\cA\times\cB$,
the pair~$(\alpha_p,\beta_q)$ of integers lies in the Cartesian product $\intinv{0}{a} \times \intinv{0}{b}$.
Nonetheless,
only the parts $\intinv{0}{a} \times \{0\}$ and $\{0\} \times \intinv{1}{b}$
have to be considered,
as $(\alpha_p,\beta_q)$ outside of these parts violate the coprimality condition.
The previous considerations are independent of the other coordinates $\alpha_{p'}$ and~$\beta_{q'}$,
so only a fraction $(a + b + 1)/((a + 1)(b + 1))$ of the whole product~$\cA\times\cB$ is useful.
Taking several pairs~$(p,q)$ into account, we expect only a small fraction of~$\cA\times\cB$ to remain.

We now make this observation algorithmic.
Given a \mif factor~$q$ of~$\ell_r$,
we denote by~$\forbiddenby(q)$ the set of \mif factors~$p$ of~$\ell_0$ forbidden by~$q$.
Let $\cR$ be the subset of~$\irred(\ell_r)$ consisting
of those factors~$q$ of~$\ell_r$ such that $\forbiddenby(q)$~is nonempty.
Given a~$B$, a \mif factor~$q$ of~$B$
restricts the choice of the useful~$A$ if it is in~$\cR$,
and places no restriction on~$A$ if it is not in~$\cR$.
Next, for a subset~$\pi \subseteq \cR$,
let $\forbiddenby(\pi)$ denote $\bigcup_{q\in\pi}\forbiddenby(q)$.
The set of useful pairs~$(A,B)$ can now be seen to be
the disjoint union over the subsets $\pi \subseteq \cR$ of the Cartesian products
\begin{equation*}
\cC_\pi = \prod_{p\in \irred(\ell_0)} \cA(p,\pi)
   \times \prod_{q\in \irred(\ell_r)} \cB(\pi,q) ,
\end{equation*}
where
\begin{equation*}
%
\cA(p,\pi) = \begin{cases}
\intinv{0}{\mult{\ell_0}{p}} & \text{if $p\not\in\forbiddenby(\pi)$}, \\
\{0\} & \text{if $p\in\forbiddenby(\pi)$},
\end{cases}
%
\qquad\!
%
\cB(\pi,q) = \begin{cases}
\intinv{0}{\mult{\ell_r}{q}} & \text{if $q\not\in\cR$}, \\
\intinv{1}{\mult{\ell_r}{q}} & \text{if $q\in\pi$}, \\
\{0\} & \text{if $q\in\cR\setminus\pi$}.
\end{cases}
%
\end{equation*}
Rather than precomputing the $\cA(p,\pi)$ and~$\cB(\pi,q)$ explicitly,
in our algorithm
we discard useless pairs on the fly.

In the following, we call \emph{factored representation} of a polynomial
its representation as a power product of \mif factors.
An optimization of Algorithm~\ref{algo:BP}
is obtained by just changing the iteration of loop~\ref{algo:BP:main-loop}
into
\begin{itemize}
\item[\ref{algo:IP-B-loop}]
      For all $B := \prod_{q \in \irred(\ell_r)} q^{\beta_q}$ such that $0 \leq \beta_q \leq \mult{\ell_r}{q}$ for all~$q \in \irred(\ell_r)$:
      \begin{enumerate}[label=(\alph*), start=21]
      \item \label{algo:prose-IP-forbidden-by-actual-factors}
            let $F$ be the union of the~$\forbiddenby(q)$ over all~$q \in \irred(\ell_r)$ such that~$\beta_q>0$,
      \item \label{algo:prose-IP-prohibit-forbidden-factors}
            for $p \in \irred(\ell_0)$, set~$a_p$ to~$0$ if~$p\in F$, to~$\mult{\ell_0}{p}$ otherwise,
      \item for all $A := \prod_{p \in \irred(\ell_0)} p^{\alpha_p}$ such that $0 \leq \alpha_q \leq a_p$ for all~$p \in \irred(\ell_0)$,
            \begin{enumerate}[label=(\arabic*)]
            \item compute $\tilde L(t,M)$ by~\eqref{eq:mahler-necessary-2}, \\ \dots
            \end{enumerate}
      \end{enumerate}
\end{itemize}
\noindent
Here,
by the definition of~$\cB(\pi,q)$,
those~$q$ for which~$\beta_q>0$ are either in~$\pi$ or in~$\irred(\ell_r) \setminus \cR$.
Therefore, the set~$F$ computed at step~\ref{algo:prose-IP-forbidden-by-actual-factors}
is~$\forbiddenby(\pi)$,
because $\forbiddenby(q) = \varnothing$ if~$q \not\in \cR$.
The integer~$a_p$ defined at step~\ref{algo:prose-IP-prohibit-forbidden-factors}
reflects the definition of~$\cA(p,\pi)$.

Additionally, the set~$\forbiddenby(q)$ for a given~$q$ can be computed efficiently
by using the Gräffe operator~$G$ defined by
$Gf = \operatorname{Res}_y (y^b - x, f(y))$
\parencite[\emph{cf.}][\S3.2, especially Lemma~3.1]{ChyzakDreyfusDumasMezzarobba-2018-CSL},
as expressed in the following lemma.
The point of this approach is to avoid carrying out divisions
of high-degree polynomials~$M^s p$ by the polynomials~$q$.

\begin{lem}
  For any \mif factor~$q$ of~$\ell_r$, one has
  \[ \forbiddenby(q) = \irred(\ell_0) \cap \{ q, \sqrt Gq, \dots, \sqrt G^{r-1}q \} , \]
  where $\sqrt G f$ denotes the squarefree part of~$Gf$,
  computed by forcing exponents to~$1$ in the factored representation of~$Gf$.
\end{lem}

\begin{proof}
From the definition of~$G$ follow the multiplicativity formula $G(fg) = Gf\,Gg$
and the degree-preservation formula $\deg Gp = \deg p$.
In particular, $G$~preserves divisibility.
One has the crucial relations
$u\divides M^iG^iu$ and ${G^iM^iu = u^{b^i}}$ for any \mif polynomial~$u$ and~$i\in\bN$.
In terms of~$\sqrt G$, the formulas become
$u\divides M^i\sqrt G^iu$ and~$\sqrt G^iM^iu = u$ for~$i\in\bN$.

Fix an integer~$s$ such that~$0\leq s < r$.
If $q\divides M^s p$, then upon applying~$\sqrt G^s$ we find $\sqrt G^sq\divides \sqrt G^sM^s p = p$, so~$\sqrt G^sq = p$.
Conversely, if $\sqrt G^sq = p$, then upon applying~$M^s$ we find $q\divides M^s\sqrt G^sq = M^s p$, so~$q\divides M^s p$.
Now, a \mif factor~$p$ of~$\ell_0$ is forbidden by a \mif factor~$q$ of~$\ell_r$
if and only if there exists an integer~$s$ such that $0\leq s < r$ and $q\divides M^s p$,
that is, if and only if there exists an integer~$s$ such that $0\leq s < r$ and $p = \sqrt G^s q$.
\end{proof}

\subsection{Avoiding redundant pairs}
\label{sec:avoid-redundant-pairs}

Because some of the coprimality conditions defining bounded Gosper--Pet\-kov\-šek forms
cannot be taken into account in Algorithm~\ref{algo:BP}
until parametrizations of solutions~$C$ have been obtained,
solutions are naturally found with repetitions.
Here, we alleviate this
by predicting some of the repetitions from divisibility conditions on $A$ and~$B$.
By the design of Algorithm~\ref{algo:BP},
a rational solution~$u(x)$ will be generated multiple times
(before the final step that removes redundancy)
if and only if two triples $(A,B,C)$ and~$(A',B',C')$ of monic polynomials satisfying
\begin{equation}\label{eq:ABC-is-A'B'C'}
\frac{MC}{C} \frac{M^{r-1}A}{B} = \frac{MC'}{C'} \frac{M^{r-1}A'}{B'}
\end{equation}
are considered for the same~$\zeta$ during the run of the algorithm.

Recall that in Algorithm~\ref{algo:BP},
ramification is taken care of by introducing a new indeterminate~$t$
that plays the role of some appropriate root of~$x$.
The results described in~\S\ref{sec:cartesian-prod} for polynomials in~$\pol\bL$
apply with trivial modifications for polynomials of~$\bL[t]$,
and for the end of~\S\ref{sec:efficiency-improvements},
we continue with the indeterminate~$t$.
In particular, we let $\ell_0$ and~$\ell_r$ denote $\ell_0(t)$ and~$\ell_r(t)$, respectively.

We will study several scenarios
in which, if the pair $(A,B)$ is considered in the run of the algorithm
and, for a certain~$\zeta$,
leads to a polynomial~$C$ and a rational solution~$u$,
then another triple $(A',B',C')$ leads to the same~$u$ for the same~$\zeta$.
We will thus obtain rules that attempt to:
minimize the multiplicity of~$t$ in~$A$,
maximize the multiplicity of~$t$ in~$B$,
remove factors of the form~$Mp/p$ from~$A$,
introduce factors of the form~$Mp/p$ in~$B$,
replace a divisor~$Mp$ with the factor~$p$ in~$A$,
replace the factor~$p$ with a divisor~$Mp$ in~$B$.
In all cases, the polynomial~$C$ will be adjusted
to compensate for the change.
This compensation will operate by multiplications/divisions by elements of~$\bL[t]$
obtained independently of~$\zeta$.
This makes the actual value of~$\zeta$ irrelevant
when considering equalities of the form~\eqref{eq:ABC-is-A'B'C'},
which justifies our pruning independently of~$\zeta$.

\paragraph{Pruning rules}

The following four situations provide instances of~\eqref{eq:ABC-is-A'B'C'}
that will permit us to discard pairs~$(A,B)$.
Note that in each case, monic $A$, $B$, $C$, and~$p$ induce
monic $A'$, $B'$, and~$C'$:
\begin{itemize}
%
\item If $B = p\tilde B$, define $A'= A$, $B' = Mp \, \tilde B$, $C' = pC$ to get:
\begin{equation*}
    \frac{MC}{C} \frac{M^{r-1}A}{B} =
    \frac{Mp \, MC}{Mp \, C}\frac{M^{r-1}A'}{p\tilde B} =
    \frac{MC'}{C'} \frac{M^{r-1}A'}{B'} .
\end{equation*}
%
\item If $A = Mp \, \tilde A$, define $A'= p \tilde A$, $B' = B$, $C'= M^{r-1}p \, C$ to get:
\begin{multline*}
    \frac{MC}{C} \frac{M^{r-1}A}{B} =
    \frac{MC}{C} \frac{M^{r-1}(Mp \, \tilde A)}{B} = \\
    \frac{M(M^{r-1}p \, C)}{M^{r-1}p \, C} \frac{M^{r-1}(p\tilde A)}{B} =
    \frac{MC'}{C'} \frac{M^{r-1}A'}{B'} .
\end{multline*}
%
\item If $p \divides Mp$, define $A'= A$, $B' = (Mp/p) B$, $C' = pC$ to get:
\begin{equation*}
    \frac{MC}{C} \frac{M^{r-1}A}{B} =
    \frac{Mp \, MC}{pC} \frac{M^{r-1}A}{(Mp/p)B}
     = \frac{MC'}{C'} \frac{M^{r-1}A'}{B'} .
\end{equation*}
%
\item If $p \divides Mp$ and $A = (Mp/p) \, \tilde A$, define $A'= \tilde A$, $B' = B$, $C'= M^{r-1}p \, C$ to get:
\begin{multline*}
    \frac{MC}{C} \frac{M^{r-1}A}{B} =
    \frac{MC}{C} \frac{M^{r-1}((Mp/p)\tilde A)}{B} = \\
    \frac{M(M^{r-1}p \, C)}{M^{r-1}p \, C} \frac{M^{r-1}A'}{B} =
    \frac{MC'}{C'} \frac{M^{r-1}A'}{B'} .
\end{multline*}
%
\end{itemize}
%
For any monic divisor~$A$ of~$\ell_0$, any monic divisor~$B$ of~$\ell_r$,
these guarded formulas provide a rule to discard the pair~$(A,B)$
if there exists a \mif polynomial~$p$ satisfying any of the predicates:
\begin{enumerate}[label=(P\arabic*), ref=(P\arabic*)]
  \item\label{pred:alpha-case-B}
    $B$~is of the form~$p\tilde B$ and $Mp \, \tilde B$ divides~$\ell_r$.
  \item\label{pred:alpha-case-A}
    $A$~is of the form~$Mp \, \tilde A$ and $p\tilde A$ divides~$\ell_0$.
  \item\label{pred:beta-case-B}
    $p$~divides~$Mp$ and $(Mp/p) B$ divides~$\ell_r$.
  \item\label{pred:beta-case-A}
    $p$~divides~$Mp$ and $A$~is of the form~$(Mp/p) \tilde A$.
\end{enumerate}
As an example,
we legitimate the use of~\ref{pred:beta-case-A} after assuming the last situation listed above.
Because $A' \divides A \divides \ell_0$ and $B' = B \divides \ell_r$,
if $(A,B,C)$ is considered in the algorithm for a certain~$\zeta$ and leads to a solution~$u$,
then the pair~$(A', B')$ is also considered,
and the solution~$u$ found with~$(A,B)$ after the polynomial solving step gets~$C$
will also be found with~$(A',B')$ and the same~$\zeta$ after the polynomial solving step gets~$C'$.
Using the pair~$(A',B')$ instead of~$(A,B)$ is better,
because it potentially leads to more solutions,
including polynomials~$C'$ not divisible by~$M^{r-1} p$.
The use of the other predicates is justified by a similar reasoning.

It is clear that the monic nature of~$p$ is no restriction:
it is needed to relate a monic~$B$ and a monic~$\tilde B$ in~\ref{pred:alpha-case-B},
and a monic~$A$ and a monic~$\tilde A$ in~\ref{pred:alpha-case-A};
only~$Mp/p$ plays a role in \ref{pred:beta-case-B} and~\ref{pred:beta-case-A}
and it depends on~$\bL p$ only.

Furthermore, the reasoning on the predicates does not rely on the irreducibility of~$p$:
one easily proves that there exists a (monic) irreducible~$p$ making a rule apply
if and only if there exists a (monic) not necessarily irreducible~$p$
making the same (generalized) rule apply.
So it is algorithmically permissible to restrict to (monic) irreducible~$p$,
and doing so avoids having to consider exponentially more factors~$p$.

Finally, making~$p = t$ in \ref{pred:beta-case-B} and~\ref{pred:beta-case-A}
results in slightly more explicit formulations, respectively:
\begin{enumerate}[label=(P\arabic*), ref=(P\arabic*), resume]
  \item\label{pred:maximize-t-in-B}
    $\mult{B}{t} \leq \mult{\ell_r}{t} - b + 1$.
  \item\label{pred:minimize-t-in-A}
    $\mult{A}{t} \geq b - 1$.
\end{enumerate}
Note that making~$p = t$ in \ref{pred:alpha-case-B} results in special cases of~\ref{pred:maximize-t-in-B},
and doing so in \ref{pred:alpha-case-A} results in special cases of~\ref{pred:minimize-t-in-A}.

\paragraph{Iteration of the rules}

An optimization for factors is obtained
from two distinct \mif polynomials $p$ and~$q$ satisfying~$Mp = pq$:
considering the final result of a repeated use of predicates
makes it possible to fix certain multiplicities
before entering the loops over $A$ and~$B$.
If for~$k\geq1$, $q^kB$~divides~$\ell_r$,
an iterated use of~\ref{pred:beta-case-B} shows that all of $B$, \dots, $q^{k-1}B$ can be skipped,
and we get the predicate:
\begin{enumerate}[label=(P\arabic*), ref=(P\arabic*), resume]
  \item\label{pred:iterated-beta-case-B}
    $Mp = pq$ for~$p\neq q$ and $\mult{B}{q} < \mult{\ell_r}{q}$.
\end{enumerate}
Similarly, if for~$k\geq1$, $A$~is of the~form~$q^k\tilde A$ and divides~$\ell_0$,
an iterated use of~\ref{pred:beta-case-A} shows that all of $q^k\tilde A$, \dots, $q\tilde A$ can be skipped,
and we get the predicate:
\begin{enumerate}[label=(P\arabic*), ref=(P\arabic*), resume]
  \item\label{pred:iterated-beta-case-A}
    $Mp = pq$ for~$p\neq q$ and $\mult{A}{q} > 0$.
\end{enumerate}
Note that $p\neq q$ requires $p\neq t$ and~$q\neq t$.

