\section{Limitations}
\label{limi}
\begin{itemize}[leftmargin=10pt,labelsep=0.8em]
  % \item \textbf{Synthetic prompts.} Although our 5\,000 adversarial instructions span 25 topics, they are generated and curated in silico; real-world malicious behaviors may differ in style and subtlety.
  \item \textbf{Topology scope.} We evaluate four canonical agent architectures, but hybrid or emerging multi-agent designs (e.g., dynamic meshes, hierarchical teams) might exhibit distinct robustness profiles.
  \item \textbf{Static defense rules.} The Enforcement Agent relies on fixed psychometric thresholds and rule-based isolation; adaptive or learning-based defenses could further improve resilience against sophisticated or evolving attacks.
  \item \textbf{Resource requirements.} Particularly for decentralized deployments, token and computation costs are substantial, which may limit applicability in latency- or budget-constrained clinical systems.
  \item \textbf{Tool integration.} We focus on basic debate-based multi-agent interactions and do not evaluate security risks arising when agents leverage external tools or APIs during their workflows.
\end{itemize}
\section{Formal Definitions}
\label{def}

\subsection{Multi-Agent System}

\begin{equation}
\mathcal{M} = (\mathcal{A}, \mathcal{S}, \mathcal{C}, f, g),
\label{eq:mas}
\end{equation}

where  
\begin{itemize}
  \item $\mathcal{A}=\{a_1,\ldots,a_n\}$ is the set of agents;
  \item $\mathcal{S}=\{\mathrm{Layers},\mathrm{SharedPool},\mathrm{Centralized},\mathrm{Decentralized}\}$ enumerates topology types;
  \item $\mathcal{C}=\{c_1,\ldots,c_m\}$ is the set of communication channels;
  \item $f:\mathcal{A}\times\mathcal{A}\to\mathcal{C}$ assigns a channel to every ordered pair of agents;
  \item $g:\mathcal{A}\to\{0,1\}$ labels each agent as \textit{safe} (1) or \textit{dangerous} (0).
\end{itemize}

\subsection{Dark-Personality Agent}

\begin{equation}
a_d \in \mathcal{A}\quad\text{s.t.}\quad R(a_d) > \tau,\qquad \tau = 60,
\label{eq:dark}
\end{equation}

with $R:\mathcal{A}\to[0,100]$ the risk-assessment function.  
Topology-specific injection rules:  
\begin{itemize}
  \item \textbf{Centralized}: replace a random \emph{non-Leader} agent;
  \item \textbf{Decentralized} / \textbf{SharedPool}: replace any random agent;
  \item \textbf{Layers}: replace a random agent not on the final layer.
\end{itemize}

\subsection{Enforcement Agent}

\begin{equation}
a_e \in \mathcal{A}, \qquad a_e \mapsto (P, T, V, I),
\label{eq:enforce}
\end{equation}

where  
\begin{itemize}
  \item $P:\mathcal{A}\to[0,100]$ — psychometric screening score;
  \item $T:\mathcal{A}\times\mathcal{P}(\mathcal{A})\to\{\mathrm{Low},\mathrm{Medium},\mathrm{High}\}$ — risk tagging;
  \item $V:\mathcal{M}\times\mathcal{A}\times\mathcal{D}\to[0,1]$ — speech verification over dialogue set $\mathcal{D}$;
  \item $I:\mathcal{A}\times2^{\mathcal{C}}\to2^{\mathcal{C}}$ — channel-isolation operator that rewrites the offender’s communication edges.
\end{itemize}

The Enforcement Agent flags any $a\in\mathcal{A}$ with $P(a)>\tau$; if subsequent verification $V$ detects concrete safety violations, $I$ excises the agent’s channels following topology-aware policies described in \S\ref{sec:defense}.
