\node[diamondbox, below of=observation, yshift=-0.4cm] (update) {Bayesian \linebreak Update};
\node[roundbox, below of=update, yshift=-0.5cm] (decision) {Recalculate Policy / \linebreak Moderation Strategy};
\node[roundbox, below of=decision, yshift=-0.5cm] (execute) {Execute Action: \linebreak Filter, Refuse, or Allow};
\node[diamondbox, below of=execute, yshift=-0.4cm] (check) {Stop Condition?};
\node[roundbox, below of=check, yshift=-0.5cm] (end) {End Simulation};

% Connections
\draw[->] (start) -- (observation);
\draw[->] (observation) -- (update);
\draw[->] (update) -- (decision);
\draw[->] (decision) -- (execute);
\draw[->] (execute) -- (check);

\draw[->] (check) -- node[right]{No} ++(0,-1.0) 
    |- ($(observation.east)+(0.5,0)$)
    |- (observation.east);

\draw[->] (check) -- node[right]{Yes} (end);

