\begin{theorem}
\label{thm:twoedp}
    \unitsr is NP-complete on directed graphs even for $d=3$.
\end{theorem}

\begin{proof}
    We provide a polynomial-time reduction from the NP-complete problem~\twoedplong (\twoedp) on directed graphs~\cite{fortune1980directed}.

    \pbdef{\twoedplong (\twoedp) on directed graphs}{A directed graph $G=(V,E)$ and two pairs of vertices $(s_1, t_1), (s_2, t_2)$.}{Are there two arc-disjoint paths $P_1, P_2$ from $s_1$ to $t_1$ and from $s_2$ to $t_2$ respectively?}

    Let $\mathcal{I}=(G=(V,E), D)$ be an instance of \twoedp on a directed graph. We construct in polynomial time an instance $\mathcal{I'}=(G'=(V', E'), D', k)$ of \unitsr on a directed graph as follows (see \cref{fig:red_2EDP}):
	\begin{figure}[t]
		\centering
		\begin{tikzpicture}[scale=0.6]
        \input{figures/red-from-2edp}
		\end{tikzpicture}
		\caption{Illustration of the reduction from \twoedp to \unitsr: on the left is the reduced instance and on the right its demand graph.}
		\label{fig:red_2EDP}
	\end{figure}
    \begin{itemize}
        \item Start with the 2-extended graph $S_2(G)=(V',E')$.
        \item Add two new vertices $s_3, t_3$ in $V'$.
        \item For each original vertex $v \in V$ in $S_2(G)$, add the arc $v s_3$ in $E'$. Add the arcs $t_3 t_1$, $t_3 t_2$ and $s_3 t_3$.
        \item Set $D'= \lbrace (s_1, t_1), (s_2, t_2), (s_3, t_3) \rbrace$.
        \item Set $k=|V|$.
    \end{itemize}
    Clearly the above transformation is polynomial. We show that $\mathcal{I}$ is a yes-instance if and only if $\mathcal{I'}$ is a yes-instance.

    ``$\Rightarrow$'' Let $P_1, P_2$ be a solution to $\mathcal{I}$. We assume they are simple paths. Denote $P_1$ by its arcs in $G$: $P_1=(a_1, \ldots, a_{\ell_1})$. Denote $v_i$ the vertex in the middle of the path of two arcs that replaced $a_i$ in $S_2(G)$. Then demand $(s_1, t_1)$ uses $\lsr s_1, v_1, \ldots, v_{\ell_1}, t \rsr$. Proceed identically for $(s_2, t_2)$. Demand $(s_3,t_3)$ uses $\lsr s_3, t_3 \rsr$ (the single arc $s_3 t_3$).

    ``$\Leftarrow$'' Conversely, suppose we have a feasible routing scheme for $\mathcal{I'}$. 
    Since $s_3 t_3$ is the only arc leaving $s_3$, the only way to route $(s_3, t_3)$ is to use $\lsr s_3, t_3 \rsr$ and it saturates the arc. It implies that in any feasible routing scheme, the segment paths of $(s_1, t_1)$ and $(s_2, t_2)$ are contained in $S_2(G)$. 
    Then we prove that in any feasible routing scheme, these two segment paths are ECMP-free. Targeting a contradiction, let $u,v$ be two vertices of $S_2(G)$ such that $FG(u,v)$ is contained in $S_2(G)$ and is not ECMP-free. We can assume that $u,v \in V$ because the other vertices of $S_2(G)$ have in- and out-degree one. There are no parallel arcs in $G$, so two distinct shortest paths from $u$ to $v$ should have length at least 2 in $G$ and 4 in $S_2(G)$. However, the path from $u$ to $v$ using the shortcut $s_3 t_3$ in $G'$ has length 3, so we have a contradiction. 
    Thus, the segment paths of $(s_1, t_1)$ and $(s_2,t_2)$ are ECMP-free. They are also arc-disjoint since capacities are respected, so we can translate them into arc-disjoint paths in $G$. 
\end{proof}

\begin{theorem}
\label{thm:twodonep}
    \unitsr is NP-complete on undirected graphs even for $d=4$.
\end{theorem}

\begin{proof}
    We provide a polynomial-time reduction from the NP-complete problem \twodoneplong (\twodonep) on undirected graphs~\cite{eilam1998disjoint}. 

    \pbdef{\twodoneplong (\twodonep)}{An undirected graph $G$, two pairs of vertices $(s_1, t_1)$ and $(s_2, t_2)$.}{Are there two edge-disjoint paths $P_1$ from $s_1$ to $t_1$ and $P_2$ from $s_2$ to $t_2$ such that $P_1$ is a shortest path?}

    Let $\mathcal{I} = (G=(V,E), s_1, t_1, s_2, t_2)$ be an instance of \twodonep, $G$ connected. Denote $n=|V|$. We construct in polynomial time an instance $\mathcal{I'}=(G', D, k)$ of \unitsr as follows (see \cref{fig:red_2D1SP}):
	\begin{figure}[t]
		\centering
		\begin{tikzpicture}[scale=0.6]
        \input{figures/red-from-2d1sp1}
		\end{tikzpicture}
        \vspace{1em}
		\begin{tikzpicture}[scale=0.6]
        \input{figures/red-from-2d1sp2}
		\end{tikzpicture}
		\caption{Illustration of the reduction from \twodonep to \unitsr. The reduced instance is at the top and below is its demand graph.}
		\label{fig:red_2D1SP}
	\end{figure}
    \begin{itemize}
        \item Start with the $n+2$-extended graph $S_{n+2}(G)=(V',E')$. 
        \item Set the budget to $k=n$.
        \item Add a triangle chain $\nabla_{2k}$. Connect one end of this chain to two new vertices $s_3$ and $s_4$ and the other end to two new vertices $s_3'$ and $s_4'$.
        \item Create a \emph{shortcut} path of $n$ vertices and connect each of them to a different original vertex of $V$ in $S_{n+2}(G)$. Connect one end of the shortcut path to $s_3'$ and the other end to a new vertex $t_3$.
        \item Add a triangle chain $\nabla_{k-d_G(s_1,t_1)}$ where $d_G(s_1,t_1) \leq n$ is the distance from $s_1$ to $t_1$ in $G$ (value computable in polynomial time). Connect one end of this chain to $t_1$ and $s_4'$ and the other end to two new vertices $t_1'$ and $t_4$.
        \item Set $D=\lbrace (s_1, t_1'), (s_2, t_2), (s_3, t_3), (s_4, t_4) \rbrace$.
    \end{itemize}
    Clearly the above transformation is polynomial. We show that $\mathcal{I}$ is a yes-instance if and only if $\mathcal{I'}$ is a yes-instance.

    ``$\Rightarrow$'' Let $P_1$, $P_2$ be a solution of $\mathcal{I}$. We assume they are simple paths. 

    First assign $k$ waypoints to $(s_3, t_3)$ and $k$ waypoints to $(s_4, t_4)$ to route them through $\nabla_{2k}$ as described in \cref{fig:triangle_chain}. Having used all their budget in $\nabla_{2k}$, when leaving $\nabla_{2k}$, $(s_3, t_3)$ uses the straight line across the shortcut path to reach $t_3$, and $(s_4, t_4)$ uses the straight line across $\nabla_{k-d_G(s_1, t_1)}$ to reach $t_4$.

    Denote $P_2$ by its edges: $P_2=(e_1, \ldots, e_\ell)$. Denote $v_i$ the middle vertex of the path of length $n+2$ that replaced $e_i$ in $S_{n+2}(G)$ (if $n+2$ is odd, take $v_i$ as the middle vertex that is closest to the origin of the path). Then route demand $(s_2, t_2)$ on $\lsr s_2, v_1, \ldots, v_\ell, t_2 \rsr$, using $\ell \leq k$ waypoints. This segment path stays in $S_{n+2}(G)$ because the shortest path between two consecutive endpoint/waypoints is the one not using the shortcut. The segment path of $(s_1, t_1')$ is defined similarly between $s_1$ and $t_1$ using $P_1$ ($t_1$ is not a waypoint), using exactly $d_G(s_1, t_1)$ waypoints in $S_{n+2}(G)$. The rest of the segment path is given by $k-d_G(s_1, t_1)$ waypoints in $\nabla_{k-d_G(s_1, t_1)}$. The shortest path between the last waypoint in $S_{n+2}(G)$ and the first in $\nabla_{k-d_G(s_1, t_1)}$ does not use the shortcut and traverses $t_1$ because it is the only way to reach $t_1'$.

    ``$\Leftarrow$'' Conversely, suppose we have a feasible routing scheme for $\mathcal{I'}$. Demands $(s_3, t_3)$ and $(s_4, t_4)$ require $k$ waypoints each in $\nabla_{2k}$, so after leaving $\nabla_{2k}$ they saturate respectively the shortcut path from $s_3'$ to $t_3$ and the straight line from $s_4'$ to $t_4$ across $\nabla_{k-d_G(s_1,t_1)}$. It implies that the segment paths of $(s_1, t_1')$ (from $s_1$ to $t_1$) and $(s_2,t_2)$ are contained in $S_{n+2}(G)$, and that the segment path of $(s_1, t_1')$ uses at most $d_G(s_1, t_1)$ waypoints between $s_1$ and $t_1$.

    Notice that a path in $S_{n+2}(G)$ between two vertices $s,t \in V$ is made of subpaths of length $n+2$ corresponding each to an edge of $G$. Call these subpaths \emph{extended edges}. Let $u,v$ be two vertices of $S_{n+2}(G)$. If $u,v \in V$, then a shortest path from $u$ to $v$ uses the shortcut, with length at most $n+1$. If $u \in V$ and $v \notin V$, then unless $v$ belongs to an extended edge incident to $u$, a shortest path between them also uses the shortcut. Finally, if $u, v \notin V$, then unless $u$ and $v$ are located on adjacent extended edges or the same extended edge, a shortest path between them uses the shortcut.

    Consider the segment path of $(s_2, t_2)$ in our feasible routing scheme: $\lsr s_2, w_1, \ldots, w_\ell, t_2 \rsr$. Given the remarks above, we deduce that there is at least one waypoint per extended edge. It implies that this segment path is ECMP-free, and it can be translated into a solution path for $\mathcal{I}$. Consider the segment path of $(s_1, t_1')$ in our feasible routing scheme. It needs at least $k-d_G(s_1, t_1)$ waypoints in $\nabla_{k-d_G(s_1, t_1)}$, leaving at most $d_G(s_1, t_1)$ waypoints for the part in $S_{n+2}(G)$. Given the above, we also deduce that it uses at least $d_G(s_1, t_1)$ waypoints between $s_1$ and $t_1$ and that it is ECMP-free too. Since a path from $s_1$ to $t_1$ uses at least $d_G(s_1, t_1)$, and that it is possible to use exactly one waypoint per extended edge as shown in $\Rightarrow$, this section of the segment path can be translated into a path of length exactly $d_G(s_1, t_1)$ in $G$, so we have a shortest path for $\mathcal{I}$.
\end{proof}

We now consider the case where~$k=1$ and~$d$ is small (but not constant).

\begin{theorem}
	\label{thm:mcc}
    \unitsr parameterized by the number of demands is W[1]-hard on undirected, bidirected, and directed graphs even for $k=1$.
\end{theorem}

We provide a parameterized reduction from the W[1]-complete problem \mcc parameterized by the number of colors~\cite{pietrzak2003parameterized}. 
We significantly modify a reduction by \citet{bentert2023using} to obtain our result. 

\pbdef{\mcc}{An undirected graph~$G=(V,E)$, an integer~$d$, a coloring function~$c\colon V \rightarrow \lbrace 1, \ldots, d \rbrace$.}{Is there a multicolored clique in $G$, that is, a set of pairwise adjacent vertices containing exactly one vertex of each color?}

Let $\mathcal{I}=(G=(V, E), d, c)$ be an instance of \mcc parameterized by $d$. For each $i=1, \ldots, d$ denote $V_i = \lbrace v \in V : c(v)=i \rbrace$. Then $(V_1, \ldots, V_d)$ is a partition of $V$. We make the following assumptions:
\begin{enumerate}
	\item The $d$ sets $V_1, \ldots, V_d$ have equal size $n \geq 2$: otherwise, take $n=\max_i |V_i|$ and add isolated vertices in the sets of size $<n$. The case $|V_i|=1 \quad \forall i$ is trivial so we assume $n \geq 2$.
	\item The number of colors $d$ is even: if it is odd, add a new color, create $n$ vertices of that color, connect one of these new vertices to every $v \in V_1 \cup \ldots \cup V_d$ and leave the other $n-1$ new vertices isolated.
\end{enumerate}

\paragraph{Construction of the reduced instance}

    We construct in polynomial time an instance $\mathcal{I}'=(G'=(V',E'), D, k)$ of \unitsr on an undirected graph parameterized by the number of demands as follows (see \cref{fig:red_mcc3}):
	Start with an empty graph $G'$. For each color $i= 1,\ldots, d$, add four vertices in $V'$: $s_i$ and $t_i$ facing each other, $s_{d+i}$ and $t_{d+i}$ facing each other.
	For each vertex $v \in V$, create a horizontal path $P_v$ from $s_{c(v)}$ to $t_{c(v)}$ and a vertical path $Q_v$ from $s_{d+c(v)}$ to $t_{d+c(v)}$. 
	The paths are arranged in a grid and in the same order of $V$ horizontally and vertically, grouped by color; see \cref{fig:red_mcc1} for an illustration.

	\begin{figure}[t]
		\centering
		\begin{tikzpicture}[scale=0.8]
        \input{figures/red-from-mcc-layout}
		\end{tikzpicture}
		\caption{
			General layout of the reduced instance: 
			The horizontal and vertical paths are grouped by the colors of the vertices the paths represent.
			$L$-separators are represented by dashed lines and $\ell$-subpaths by dotted lines (shortcuts are not represented).
		}
		\label{fig:red_mcc1}
	\end{figure}

	A path $P_v$ (resp. $Q_v$) consists of several subpaths as follows:
	\begin{itemize}
		\item in the middle, alternately $d$ subpaths of $3n$ edges and $d-1$ subpaths of $\ell=16$ edges, called \emph{$\ell$-subpaths},
		\item between $s_{c(v)}$ (resp. $s_{d+c(v)}$) and the first subpath of length $3n$, a subpath of $L=2\big(3nd+(d-1)\ell \big)$ edges called \emph{$L$-separator}, and another one between the last subpath of length $3n$ and $t_{c(v)}$ (resp. $t_{d+c(v)}$).
	\end{itemize}
	The length of a $L$-separator is chosen so that it is twice as long as the subpath between the two $L$-separators.
	The first subpath of length $3n$ corresponds to where $P_v$ overlaps with the $n$ vertical paths corresponding to~$V_1$, the second corresponds to where $P_v$ overlaps with vertical paths corresponding to~$V_2$, and so on.
	We call these parts \emph{color overlap}; these refer to the boxes in \cref{fig:red_mcc1}.
	More precisely, given two colors $i, j$, the \emph{color overlap} $(i,j)$ refers to the area where the paths $P_v, v \in V_i$ and $Q_u, u \in V_j$ overlap. 
	Merge some edges in the color overlaps: for all $u,v \in V$, $u \neq v$, the crossover of $Q_u$ and $P_v$ consists of three horizontal edges and three vertical edges. 
	If $c(u) = c(v)$ or $uv \notin E$, then $u$ and $v$ cannot be together in a clique, so merge the middle edge as shown in \cref{fig:red_mcc2}.

\begin{figure}[t]
	\centering
	\begin{tikzpicture}[scale=0.45]
    \input{figures/red-from-mcc-intersections}
	\end{tikzpicture}
	\caption{The square shows what is represented by squares in \cref{fig:red_mcc1}.
        \emph{Left side:} Two ways that paths~$P_v$ and~$Q_u$ can intersect. 
		The top refers to when~$u$ and~$v$ can be in a clique together: the subpaths of~$P_v$ and~$Q_u$ do not share any edge. Thus, they can be used in a routing scheme together.
		Below is the case where~$u$ and~$v$ cannot be in a clique together: the two subpaths intersect and it is not possible to use both of them in the routing scheme.
		\emph{Right side:} An example for $n=3$ of a complete color overlap between two colors.}
	\label{fig:red_mcc2}
\end{figure}

	Add a path of three edges, called \emph{shortcut}, between each of the following pairs of endpoints:
	\begin{itemize}
		\item $\lbrace s_i, t_i \rbrace$ and $\lbrace s_{d+i}, t_{d+i} \rbrace$ for $1 \leq i \leq d$ (one shortcut per pair of terminals facing each other),
		\item $\lbrace s_i, s_j \rbrace$, $\lbrace t_i, t_j\rbrace$, $\lbrace s_{d+i}, s_{d+j} \rbrace$, $\lbrace t_{d+i}, t_{d+j} \rbrace$ for $1 \leq i < j \leq d$ (one shortcut per pair of terminals located on the same side of the grid).
	\end{itemize}
	Given a pair $\lbrace u,v \rbrace$ above, we denote by~$u$-$v=v$-$u$ the associated shortcut.
	For each $i=1,\ldots,d$, create demands $(s_i, t_i)$ and $(s_{d+i}, t_{d+i})$ in $D$. For each shortcut, create a \emph{blocker demand} in $D$ corresponding to the middle edge of the shortcut path.
	Finally, set $k=1$.

