\end{bmatrix}
\]

The state space form is as given,

\[
\dot{X} = f(X) + g(X, U) + \delta
\]

From the dynamic equations we derive the state space representation:

\begin{align}
\dot{x}_1 &= x_2 \tag{40} \\
\dot{x}_2 &= a_1 x_4 x_6 + a_2 x_2^2 + a_3 \dot{\Omega} x_4 + b_1 U_2 \tag{41} \\
\dot{x}_3 &= x_4 \tag{42} \\
\dot{x}_4 &= a_4 x_2 x_6 + a_5 x_4^2 + a_6 \dot{\Omega} x_2 + b_2 U_3 \tag{43} \\
\dot{x}_5 &= x_6 \tag{44} \\
\dot{x}_6 &= a_7 x_2 x_4 + a_8 x_6^2 + b_3 U_4 \tag{45} \\
\dot{x}_7 &= x_8 \tag{46} \\
\dot{x}_8 &= a_9 x_8 + U_x \frac{U_1}{m} \tag{47} \\
\dot{x}_9 &= x_{10} \tag{48} \\
\dot{x}_{10} &= a_{10} x_{10} + U_y \frac{U_1}{m} \tag{49} \\
\dot{x}_{11} &= x_{12} \tag{50} \\
\dot{x}_{12} &= a_{11} x_{12} + U_1 \frac{C_{x1} C_{x3}}{m} - g \tag{51}
\end{align}

The above equations are framed, considering the below defined constants:

\[
\begin{aligned}
a_1 &= \left[ \frac{I_y - I_z}{I_x} \right], \quad a_2 = -\frac{K_f a_x}{I_x}, \quad a_3 = -\frac{J_r}{I_x} \\
a_4 &= \left[ \frac{I_z - I_x}{I_y} \right], \quad a_5 = -\frac{K_f a_y}{I_y}, \quad a_6 = \frac{J_r}{I_y} \\
a_7 &= \left[ \frac{I_x - I_y}{I_z} \right], \quad a_8 = -\frac{K_{f tz}}{I_z}, \quad a_9 = -\frac{K_{f tx}}{m} \\
a_{10} &= -\frac{K_{f ty}}{m}, \quad a_{11} = -\frac{K_{f tz}}{m} \\
b_1 &= \frac{d}{I_x}, \quad b_2 = \frac{d}{I_y}, \quad b_3 = \frac{1}{I_z}
\end{aligned}
\]

\[
U_x = C_{x1} S_{x3} C_{x5} + S_{x1} S_{x5}, \quad U_y = C_{x1} S_{x3} S_{x5} - S_{x1} C_{x5}
\]

\section{Slding Mode Control}
Applying the recursive backstepping approach as an algorithm for synthesizing control laws simplifies all stages of computation related to tracking errors and Lyapunov functions in the following manner:

\[
\text{For } i \in \{1, 3, 5, 7, 9, 11\} : 
\begin{cases}
z_i = x_{i,d} - x_i \\
V_i = \frac{z_i^2}{2}
\end{cases} \tag{52}
\]

\[
\text{For } i \in \{2, 4, 6, 8, 10, 12\} : 
\begin{cases}
z_i = \dot{x}_i - \dot{x}_{(i-1),d} - \alpha_i z_{i-1} \\
V_i = \frac{V_{i-1} + z_i^2}{2}
\end{cases} \tag{53}
\]

where, \( \alpha_i > 0, \forall i \in [1,12] \)

The sliding surfaces are as given below:

\[
\begin{aligned}
S_\phi &= z_2 = x_2 - \dot{x}_{1d} - \alpha_1 z_1 \\
S_\theta &= z_4 = x_4 - \dot{x}_{3d} - \alpha_3 z_3 \\
S_\psi &= z_6 = x_6 - \dot{x}_{5d} - \alpha_5 z_5 \\
S_x &= z_8 = x_8 - \dot{x}_{7d} - \alpha_7 z_7 \\
S_y &= z_{10} = x_{10} - \dot{x}_{9d} - \alpha_9 z_9 \\
S_z &= z_{12} = x_{12} - \dot{x}_{11d} - \alpha_{11} z_{11}
\end{aligned}
\]

\( S_\phi, S_\theta, S_\psi, S_x, S_y, S_z \) are the dynamic sliding surfaces. To formulate a stabilizing control law through sliding mode control, it is imperative to validate the requisite sliding condition (i.e. \( S \dot{S} < 0 \)). Consequently, the resultant stabilizing control laws can be expressed as follows equations (54) 

\begin{figure*}[!t]
\begin{align}
U_2 &= \frac{1}{b_1} \left\{ -q_1 \,\text{sign}(S_\phi) - k_1 S_\phi - a_1 x_4 x_6 
- a_2 x_2^2 - a_3 \dot{\Omega} x_4 + \ddot{\phi}_d + \alpha_1 (\dot{\phi}_d - x_2) \right\} \notag \\
U_3 &= \frac{1}{b_2} \left\{ -q_2 \,\text{sign}(S_\theta) - k_2 S_\theta - a_4 x_2 x_6 
- a_5 x_4^2 - a_6 \dot{\Omega} x_2 + \ddot{\theta}_d + \alpha_3 (\dot{\theta}_d - x_4) \right\} \notag \\
U_4 &= \frac{1}{b_3} \left\{ -q_3 \,\text{sign}(S_\psi) - k_3 S_\psi - a_7 x_2 x_4 - a_8 x_6^2 
+ \ddot{\psi}_d + \alpha_5 (\dot{\psi}_d - x_6) \right\} \notag \\
U_x &= \frac{m}{U_1} \left\{ -q_4 \,\text{sign}(S_x) - k_4 S_x - a_9 x_8 
+ \ddot{x}_d + \alpha_7 (\dot{x}_d - x_8) \right\} \notag \\
U_y &= \frac{m}{U_1} \left\{ -q_5 \,\text{sign}(S_y) - k_5 S_y - a_{10} x_{10} 
+ \ddot{y}_d + \alpha_9 (\dot{y}_d - x_{10}) \right\} \notag \\
U_1 &= \frac{m}{C_{x1} C_{x3}} \left\{ -q_6 \,\text{sign}(S_z) - k_6 S_z - a_{11} x_{12} 
+ \ddot{z}_d + \alpha_{11} (\dot{z}_d - x_{12}) + g \right\}
\tag{54}
\end{align}
\end{figure*}





Proof for obtaining equation for \( U_2 \):
From the backstepping approach, we have found the values for \( z_i \) and \( V_i \) from Eqs (52) and (53). We get:

\[
V_2 = \frac{1}{2} \dot{z}_1^2 + \frac{1}{2} z_2^2 \tag{55}
\]

\[
z_2 = x_2 - \dot{x}_{1d} - \alpha_1 z_1 \tag{56}
\]

From Eq:

\[
S_\phi = z_2 = x_2 - \dot{x}_{1d} - \alpha_1 z_1 \tag{57}
\]

\[
V_2 = \frac{1}{2} \dot{z}_1^2 + \frac{1}{2} S_\phi^2 \tag{58}
\]

With the equations:

\[
\dot{V}_2 = z_1 \dot{z}_1 + S_\phi \dot{S}_\phi \tag{59}
\]

\begin{align}
\dot{V}_2 &= z_1 \dot{z}_1 + S_\phi \left\{
    a_1 x_4 x_6 + a_2 x_2^2 + a_3 \dot{\Omega} x_4 + b_1 U_2 
    + \ddot{\phi}_d - \alpha_1 (\dot{\phi}_d - x_2)
\right\} \tag{60}
\end{align}

The chosen law for the attractive surface is the time derivative satisfying $(S_\phi \dot{S}_\phi < 0)$:

\begin{align}
\dot{S}_\phi &= -q_1 \, \text{sign}(S_\phi) - k_1 S_\phi \nonumber \\
             &= \dot{x}_2 - \ddot{\phi}_d - \alpha_1 z_1 \nonumber \\
             &= a_1 x_4 x_6 + a_2 x_2^2 + a_3 \dot{\Omega} x_4 + b_1 U_2 
                - \ddot{\phi}_d + \alpha_1 (\dot{\phi}_d - x_2)
\end{align}

Finally, the control input \( U_2 \) is extracted from the backstepping approach:

\begin{align}
U_2 &= \frac{1}{b_1} \left\{
\begin{aligned}
   &-q_1 \, \text{sign}(S_\phi) - k_1 S_\phi 
   - a_1 x_4 x_6 - a_2 x_2^2 \\
   &- a_3 \dot{\Omega} x_4 
   + \ddot{\phi}_d + \alpha_1 (\dot{\phi}_d - x_2)
\end{aligned}
\right\} \tag{61}
\end{align}


Same steps are carried to extract \( U_3, U_4, U_x, U_y \) and \( U_1 \).


\section{Optimization of Parameters}

The control equations described earlier include parameters $\alpha_i$, $k_i$, and $q_i$ that directly influence the output. These parameters constant and real. The objective is to select values for these parameters that minimize the error between the desired and obtained trajectories. To achieve this optimization, we employ the optimization capabilities of the SciPy library in Python. Specifically, we utilize the ‘minimize’ function, which employs the \textbf{BFGS (Broyden-Fletcher-Goldfarb-Shanno)} algorithm. This iterative optimization algorithm is well-suited for addressing unconstrained nonlinear optimization problems. The algorithm is executed to discover the most suitable values that yield minimal error within the range of 0 to 1000. The outcomes obtained for these parameter values post-optimization are as follows: $\alpha_i = 0.2285737$, $k_i = 0.1$, and $q_i = 0.1$.

