\section{Additional Algorithm on V-function}\label{sec:algo_V}
Note that Algorithm \ref{alg1} involves the action-value function $Q_{\theta}$ during the update. Particularly, the action $a_{t+1}$ is needed. It measures the action-level feedback and involves discrete action spaces. Thus, in the following, we also propose an alternative actor-critic algorithm with the state-value function $V_{\theta}$, only involving the transition at time $t$, namely, the sample $(s_t,a_t,s_{t+1})$. 

Similar to estimating the action-function $Q_{\theta}$ parameterized by $\omega$, we estimate the state-value function $V_{\theta}$ by $V(\cdot;v):\mcal{S}\rightarrow \mbb{R}$, where $v\in \mbb{R}^{m_{V}}$ such that $m_{V}\ll |\mcal{S}|$. Again, we stick to the agent-community structure: Let $\mbf{V}_{a,t}=[V_t^1,\ldots,V_t^N]'$ and $\mbf{V}_{c,t}=[V_t(v_i^{(1)}),\ldots,V_t(v_t^{(K)})]'$ such that $\mbf{V}_{a,t}=\Gamma_t \mbf{V}_{c,t}$, where $\Gamma_t=[\gamma_{1t},\ldots,\gamma_{nt}]'$ is the mixed membership matrix. Similarly, define $\mbf{r}_{a,t}=[r_{t}^1,\ldots,r_t^N]'$ and $\mbf{r}_{c,t}=[r_{t}^{(1)},\ldots,r_{t}^{(K)}]'$, representing the agent and community reward received at time $t$ respectively and $\mbf{r}_{c,t}$ is defined via $\mbf{r}_{a,t}=\Gamma_t\mbf{r}_{c,t}$. Building on the above agent-community structure, the community-wide estimate $V_t(v_t^{(k)})$ is regarded as the baseline learned by updating $v_t^{(k)}$ in the critic step. The details of the critic step are illustrated in Algorithm \ref{alg2_1}.

Once obtaining the agent-wide estimate $V_t^i$ through this structure $\mbf{V}_{a,t}=\Gamma_t\mbf{V}_{c,t}$, we then learn the policy through updating $\theta_t^i$ in the actor step. However, different from that in Algorithm \ref{alg1} using the state-value function $Q(\cdot,\cdot,\omega^i)$ to compute the advantage function $A_t^i$ for agent $i$, we utilize the state-value function $V(\cdot,v^i)$. Specifically, note that
\begin{align}\label{est_A_via_V}
    \mbb{E}(\bar{e}_{t+1}|s_t=s,a_t=a,\pi_{\theta})=A_{\theta}(s,a),
\end{align}
where $\bar{e}_t=\bar{r}_{t+1}-J(\theta)+V_{\theta}(s_{t+1})-V_{\theta}(s_t)$ is called the global state-value TD error. It thus provides an unbiased estimator for $A_{\theta}$, and we then proceed by estimating three quantities: $\bar{r}_{t+1},J(\theta)$ and $V_{\theta}(s_t)$ for agent $i$ in order to obtain the estimate $A_t^i$. The state-value function $V_{\theta}(s_t)$ is already estimated in Algorithm \ref{alg2_1} by $V_t(v_t^i)$ through this structure $\mbf{V}_{a,t}=\Gamma_t\mbf{V}_{c,t}$. We then consider estimating the globally averaged reward function $\bar{R}$ in \eqref{J}. Let $\bar{R}(\cdot,\cdot;\rho):\mcal{S}\times \mcal{A}\rightarrow \mbb{R}$ be a family of functions parameterized by $\rho\in\mbb{R}^{m_{\varrho}}$ such that $m_\varrho\ll |\mcal{S}|\cdot|\mcal{A}|$. Motivated by \eqref{J}, we consider a weighted mean square optimization to learn $\rho$:
\begin{align*}
    \min_{\rho}~\sum_{i\in\mcal{N}}\sum_{s\in\mcal{S},a\in\mcal{A}}\tilde{d}_{\theta}(s,a)\left(\bar{R}(s,a;\rho)-\bar{R}^i(s,a)\right)^2.
\end{align*}
This optimization problem shares the same form as in \cite{nedic2009distributed,boyd2011distributed,chen2012diffusion}. Adapting their approach to our community structure, letting $\bar{\mbf{R}}_{a,t}=[\bar{R}_t^1,\ldots,\bar{R}_t^N]'$ and $\bar{\mbf{R}}_{c,t}=[\bar{R}_t(\rho_i^{(1)}),\ldots,\bar{R}_t(\rho_t^{(K)})]'$ such that $\bar{\mbf{R}}_{a,t}=\Gamma_t \bar{\mbf{V}}_{c,t}$, where $\Gamma_t=[\gamma_{1t},\ldots,\gamma_{nt}]'$ is the mixed membership matrix, we design the following update on $\rho_t^{(k)}$ to learn $\bar{R}_t$ as the estimate for $\bar{r}_t$ through $\bar{\mbf{R}}_{a,t}=\Gamma_t \bar{\mbf{V}}_{c,t}$: for any $1\le k\le K$,
\begin{align}\label{update_barR}
    \rho_{t+1}^{(k)}&=\rho_t^{(k)}+\beta_{\rho,t}(r_{t+1}^{(k)}-\bar{R}_t(\rho_t^{(k)}))\nabla_{\rho}\bar{R}_t(\rho_t^{(k)}),\nonumber\\
    \bar{\mbf{R}}_{a,t}&=\Gamma_t \bar{\mbf{V}}_{c,t}.
\end{align}
Consequently, we can use $\bar{R}^i$ to estimate $\bar{r}_{t+1}$ for agent $i$. Finally, let $\mu_{a,t}=[\mu_{t}^1,\ldots,\mu_t^N]'$ and $\mu_{c,t}=[\mu_{t}^{(1)},\ldots,\mu_{t}^{(K)}]'$ via $\mu_{a,t}=\Gamma_t\mu_{c,t}$. Since we already updated $\mu_t^{(k)}$ in Algorithm \ref{alg2_1} thus we obtain $\mu_t^i$ through $\mbf{r}_{a,t}=\Gamma_t\mbf{r}_{c,t}$, we use $\mu_t^i$ as the estimate for $J(\theta)$.

Plugging these three estimates for $\bar{r}_{t+1}$, $J(\theta)$ and $V_{\theta}(s_t)$ in \eqref{est_A_via_V}, we obtain the estimate $A_t^i$ for agent $i$. This then constitutes the policy update in the actor step shown in Algorithm \ref{alg2_2}.


\begin{algorithm}[tb!]
\renewcommand{\thealgorithm}{2}
\caption{The actor-critic algorithm with the state-value function}\label{alg2_1}
\begin{itemize} \itemsep 2pt
\item {\it (Initialization)}. Initialize the community parameter $v_0^{(k)}$, $\mu_{0}^{(k)}$ and the agent policy parameter $\theta_0^i$, for $1\le k\le K$ and $i\in\mcal{N}$.

\hspace{-0.35in} For each $t=0,\ldots,T$,
\item {\it (Critic Step: Temporal difference (TD) learning)}. Update $$v_{t+1}^{(k)}=(1-\eta_{v,t})v_{t}^{(k)}+\eta_{v,t}r_{t+1}^{(k)},$$ where $\eta_{v,t}>0$ is the stepsize associated with the parameter $v$. Compute the temporal difference (TD) error:
\begin{align*}
    e_t^{(k)}=r_{t+1}^{(k)}-\mu_t^{(k)}+V_{t+1}(v_t^{(k)})-V_{t}(v_t^{(k)}),
\end{align*}
where $V_t(v)=V(s_t;v)$ for any $v\in\mbb{R}^{m_V}$. Update the community parameter:
\begin{align*}
    v_{t+1}^{(k)}=v_{t}^{(k)}+\eta_{v,t}e_t^{(k)}\nabla_{v} Q_t(v_t^{(k)}).
\end{align*}


\item {\it (Actor Step)}. Update the policy:
\begin{align*}
    \theta_{t+1}^i=\theta_t^i+\eta_{\theta,t}A_t^i\psi_t^i,
\end{align*}
where $\eta_{\theta,t}>0$ is the stepsize associated with the parameter $\theta$, and
\begin{align*}
    A_t^i&=Q_t(\omega_t^i)-\sum_{a^i\in\mcal{A}^i}\pi_{\theta_t^i}^i(s_t,a^i)Q(s_t,a^i,a_t^{-i};\omega_t^i),\\
    \psi_t^i&=\nabla_{\theta^i}\log \pi_{\theta_t^i}^i(s_t,a_t^i).
\end{align*}
\end{itemize}
\end{algorithm}

\newpage
\begin{algorithm}[tb!]
\renewcommand{\thealgorithm}{3}
\caption{The actor-critic algorithm with the state-value function}\label{alg2_2}
\begin{itemize} \itemsep 2pt
\item {\it (Initialization)}. Initialize the community parameter $\rho_0^{(k)}$ and the agent policy parameter $\theta_0^i$, for $1\le k\le K$ and $i\in\mcal{N}$.

\hspace{-0.35in} For each $t=0,\ldots,T$,
\item {\it (Actor Step)}. Update the policy:
\begin{align*}
    \theta_{t+1}^i=\theta_t^i+\eta_{\theta,t}A_t^i\psi_t^i,
\end{align*}
where $\eta_{\theta,t}>0$ is the stepsize associated with the parameter $\theta$, and
\begin{align*}
    A_t^i&=\bar{R}_t^i-\mu_t^i+V_{t+1}^i-V_t^i,\\
    \psi_t^i&=\nabla_{\theta^i}\log \pi_{\theta_t^i}^i(s_t,a_t^i),
\end{align*}
where $\bar{R}_t^i$ is given by the update in \eqref{update_barR}, $\mu_t^i$ and $V_t^i$ are given by Algorithm \eqref{alg2_1} via the mixed membership matrix $\Gamma_t$, which is obtained by running MSCORE algorithm in Section \ref{sec:MSCORE}.
\end{itemize}
\end{algorithm}

\section{Proof}
\subsection{Proof of Theorem \ref{thm:convergen_omega}}
For notational ease, we make the following definitions: let $r_t:=\mbf{r}_{c,t}=[r_t^{(1)},\ldots,r_t^{(K)}]'$, $\mu_t=[\mu_t^{(1)},\ldots,\mu_t^{(K)}]'$, $\omega_t=[(\omega_t^{(1)})',\ldots,(\omega_t^{(K)})']'\in\mbb{R}^{Km_{\Omega}}$, $e_t=[e_t^{(1)},\ldots,e_t^{(K)}]'$ and $y_{t+1}=[e_t^{(1)}\phi_t',\ldots,e_t^{(K)}\phi_t']'\in\mbb{R}^{Km_{\Omega}}$. Moreover, since we have assumed $\eta_{\theta,t}=o(\eta_{\omega,t})$, in the spirit of the classical two-time-scale SA analysis \cite[Chapter 6.1]{borkar2008stochastic}, we can let the policy parameter be fixed as $\theta_t\equiv \theta$ when analyzing the convergence of the critic step, which implies we can show the convergence of $\omega_t$ to some $\omega_{\theta}$ depending on $\theta$. For notational simplicity, we eliminate the notations associated with $\theta$ unless otherwise noted.

The update in Algorithm \ref{alg1} is then expressed as
\begin{align*}
    \mu_{t+1}^{(k)}&=(1-\eta_{\omega,t})\mu_{t}^{(k)}+\eta_{\omega,t}r_{t+1}^{(k)},\\
    \omega_{t+1}^{(k)}&=\omega_t^{(k)}+\eta_{\omega,t} y_{t+1}^{(k)}.
\end{align*}
Here, we will apply Theorem \ref{supp1} as a technical result. To this end, we first verify all the assumptions in Theorem \ref{supp1}. We write the above update as
\begin{align}\label{updateomegaode}
    \mu_{t+1}^{(k)}&=\mu_t^{(k)}+\eta_{\mu,t}\mbb{E}\left(r_{t+1}^{(k)}- \mu_t^{(k)}|\mcal{F}_{t,1}\right)+\eta_{\mu,t}A_{\mu,t+1}^{(k)},\nonumber\\
    \omega_{t+1}^{(k)}&=\omega_t^{(k)}+\eta_{\omega,t}\mbb{E}\left( e_t^{(k)} \phi_t|\mcal{F}_{t,1}\right)+\eta_{\omega,t}A_{\omega,t+1}^{(k)},
\end{align}
where $A_{\mu,t+1}^{(k)}=r_{t+1}^{(k)}-\mbb{E}\left(r_{t+1}^{(k)}|\mcal{F}_{t,1}\right)$ and $A_{\omega,t+1}=y_{t+1}^{(k)}-\mbb{E}\left(e_t^{(k)}\phi_t|\mcal{F}_{t,1}\right)$. Here, $\mbb{E}\left(e_t^{(k)} \phi_t|\mcal{F}_{t,1}\right)$ is Lipschitz continuous in $\omega_t^{(k)}$ and $ \mu_t^{(k)}$. Moreover, by definition, $\{A_{\mu,t}^{(k)}\}$ is a martingale difference sequence satisfying: there exists a constant $C>0$ such that
\begin{align*}
    \mbb{E}\left(\|A_{\mu,t+1}^{(k)}\|^2|\mcal{F}_{t,1}\right)\le C(1+\| \omega_t^{(k)}\|^2+\| \mu_t^{(k)}\|^2),
\end{align*}
given $r_{t+1}^{(k)}$ is uniformly bounded by Assumption \ref{Assump_1}. Furthermore, we will show $\{A_{\omega,t}^{(k)}\}$ is also a martingale difference sequence. Note that by definition,
\begin{align*}
    \mbb{E}\left( y_{t+1}^{(k)}|\mcal{F}_{t,1}\right)=\mbb{E}\left(e_t^{(k)}\phi_t|\mcal{F}_{t,1}\right),
\end{align*}
and
\begin{align}\label{boundAomegasqure}
    \mbb{E}\left(\|A_{\omega,t+1}^{(k)}\|^2|\mcal{F}_{t,1}\right)\le 2\left(\mbb{E}\left(\|y_{t+1}^{(k)}\|^2|\mcal{F}_{t,1}\right)+\|\mbb{E}( e_t^{(k)}\phi_t|\mcal{F}_{t,1})\|^2\right).
\end{align}
Thus, the first term can be bounded over the set $\{\sup_t\|z_t^{(k)}\|\le M\}$ for any $M>0$. Note that
Here, by definition and Jensen's inequality, we have:
\begin{align*}
    \mbb{E}(\|y_{t+1}^{(k)}\|^2|\mcal{F}_{t,1})&=\mbb{E}\left(\|\delta_t^{(k)}\phi_t\|^2|\mcal{F}_{t,1}\right)\\
    &=\mbb{E}\left(\|(r_{t+1}^{(k)}-\mu_t^{(k)}+\phi_{t+1}'\omega_t^{(k)}-\phi_t'\omega_t^{(k)})\phi_t\|^2|\mcal{F}_{t,1}\right)\\
    &\le 3\mbb{E}\left(\left(\|r_{t+1}^{(k)}\phi_t\|^2+\|\mu_t^{(k)}\phi_t\|^2+\|\phi_t(\phi_{t+1}'-\phi_t')\|^2(\omega_t^{(k)})^2\right)|\mcal{F}_{t,1}\right).
\end{align*} 
By our assumption, $\mbb{E}\left(\|\phi_t(\phi_{t+1}'-\phi_t')\|^2|\mcal{F}_{t,1}\right)$ and $\mbb{E}\left(\|\phi_t\|^2|\mcal{F}_{t,1}\right)$ are both uniformly bounded for any $s_t\in\mcal{S},a_t\in\mcal{A}$. Also, due to Assumption \ref{Assump_1}, $\mbb{E}\left(|r_{t+1}^{(k)}|^2|\mcal{F}_{t,1}\right)=\mbb{E}\left(|r_{t+1}^{(k)}|^2|s_t,a_t\right)$ is uniformly bounded. Then, over the set $\{\sup_t\|z_t^{(k)}\|\le M\}$, it holds that: there exists a constant $C>0$,
\begin{align*}
    &\mbb{E}\left(\|y_{t+1}^{(k)}\|^2|\mcal{F}_{t,1}\right)\cdot\mathds{1}(\sup_t\|z_t^{(k)}\|\le M)\le C.
\end{align*}
Now, the second term in the right-hand side of \eqref{boundAomegasqure} can be directly bounded by $$\|\mbb{E}(e_t^{(k)}\phi_t|\mcal{F}_{t,1})\|^2\le C(1+\| \omega_t^{(k)}\|^2+\| \mu_t^{(k)}\|^2),$$ for some constant $C>0$ since we assume $r_{t+1}^{(k)}$ and $\phi_t$ are bounded by Assumption \ref{Assump_1} and Assumption \ref{Assump_5}. Then, we have: for any $M>0$,
\begin{align*}
    \mbb{E}\left(\|A_{\omega,t+1}^{(k)}\|^2|\mcal{F}_{t,1}\right)\le C(1+\| \omega_t^{(k)}\|^2+\| \mu_t^{(k)}\|^2),
\end{align*}
over the set $\{\sup_t\|z_t^{(k)}\|\le M\}$. This verifies assumption (4) in Theorem \ref{supp1}.

Now, according to Theorem \ref{supp1}, we consider the ODE associated with the asymptotic behavior of \eqref{updateomegaode}:
\begin{align*}
    \dot{ z}^{(k)}=
    \begin{pmatrix}
        \dot{ \mu}^{(k)}\\\dot{ \omega}^{(k)}
    \end{pmatrix}
    =\begin{pmatrix}
        -1&0\\
        -\Phi'D_{\theta}^{s,a}\mbf{1}&\Phi'D_{\theta}^{s,a}(P^{\theta}-I)\Phi
    \end{pmatrix}
    \begin{pmatrix}
         \mu^{(k)}\\ \omega^{(k)}
    \end{pmatrix}
    +
    \begin{pmatrix}
        J^{(k)}(\theta)\\\Phi'D_{\theta}^{s,a}R^{(k)}
    \end{pmatrix}
    ,
\end{align*}
where recall that $D_{\theta}^{s,a}=\text{diag}(d_{\theta}(s)\pi_{\theta}(s,a),s\in\mcal{S},a\in\mcal{A})$ and $J^{(k)}(\theta)$ and $R^{(k)}$ are defined in Theorem \ref{thm:convergen_omega}. In order to apply the conclusions of Theorem \ref{supp1}, we then examine the equilibrium to the above ODE. Denote by $h^{(k)}( z^{(k)})$ the right-hand side of the above ODE. It is straightforward to verify $h^{(k)}(\cdot)$ is Lipschitz, satisfying assumption (1) there. Moreover, by the Perron-Frobenius theorem, the stochastic matrix $P^{\theta}$ has a simple eigenvalue of $1$ while the rest of the eigenvalues have real parts less than $1$. Thus, $P^{\theta}-I$ has a simple eigenvalue of $0$ with all other eigenvalues having negative real parts, so does the matrix $\Phi'D_{\theta}^{s,a}(P^{\theta}-I)\Phi$, given that we assume $\Phi$ is full column rank in Assumption \ref{Assump_5}. The simple eigenvalue of $0$ has eigenvector $\nu$ such that $\Phi\nu=\varrho\mbf{1}$ for some $\varrho>0$ by checking that $\varrho\mbf{1}$ lies in the eigenspace of $D_{\theta}^{s,a}(P^{\theta}-I$ associated with $0$. Consequently, the above ODE is globally asymptotically stable and has its equilibrium satisfying:
\begin{align*}
    \left\{
    \begin{aligned}
    & \mu^{(k)}=J^{(k)}(\theta)\\
    &\Phi'D_{\theta}^{s,a}(R^{(k)}- \mu^{(k)}\mbf{1}+P^{\theta}\Phi\omega^{(k)}-\Phi\omega^{(k)})=0.
    \end{aligned}
    \right.
\end{align*}
Note here that the solution for $ \omega^{(k)}$ has the form $\omega^{(k)}_{\theta}+\varrho\nu$ with any $\varrho>0$ and $\nu\in\mbb{R}^{m_{\Omega}}$ such that $\Phi\nu=\mbf{1}$. Note that by Assumption \ref{Assump_5}, $\Phi\nu\neq \mbf{1}$. This implies $\omega_{\theta}^{(k)}$ is unique such that $\Phi'D_{\theta}^{s,a}(T_{\theta}^{Q,(k)}(\Phi\omega_{\theta}^{(k)})-\Phi\omega_{\theta}^{(k)})=0$ with $T_{\theta}^{Q,(k)}$ given in Theorem \ref{thm:convergen_omega}.

Now, by \cite[Lemma B.1 and B.2]{zhang2018fully}, it implies that $\{\mu_t^{(k)}\}$ and $\{\omega_t^{(k)}\}$ are both bounded almost surely, showing that $\{z_t^{(k)}\}$ is bounded almost surely. Therefore, all assumptions in Theorem \ref{supp1} are satisfied. Consequently, we obtain $\lim_t\mu_t^{(k)}=J^{(k)}(\theta)$ and $\lim_t\omega_t^{(k)}=\omega_{\theta}^{(k)}$ over the set $\{\sup_t\|z_t^{(k)}\|\le M\}$ for any $M>0$, which holds almost surely. Then, it completes the proof for $k$. Since the above arguments hold for any $1\le k\le K$, we obtain the proof for Theorem \ref{thm:convergen_omega}.

\subsection{Proof of Theorem \ref{thm:convergence_theta}}
Let $\mcal{F}_{t,2}=\sigma(\{\theta_\tau\}_{\tau\le t})$ be the $\sigma$-field generated by $\{\theta_\tau\}_{\tau\le t}$. Now, define:
\begin{align*}
    B_{t+1,1}^i&:=A_t^i\psi_t^i-\mbb{E}_{s_t\sim d_{\theta_t},a_t\sim\pi_{\theta_t}}(A_t^i\psi_t^i|\mcal{F}_{t,2}),\\
    B_{t+1,2}^i&:=\mbb{E}_{s_t\sim d_{\theta_t},a_t\sim\pi_{\theta_t}}((A_t^i-A_{t,\theta_t}^i)\psi_t^i)|\mcal{F}_{t,2}),
\end{align*}
where $A_{t,\theta_t}^i$ is defined in \eqref{Apsi} with $\theta=\theta_t$. Recall that the update in Algorithm \ref{alg1} can be written with a local projection $\mcal{L}^i$:
\begin{align*}
    \theta_{t+1}^i=\mcal{L}^i(\theta_t^i+\eta_{\theta,t}\mbb{E}_{s_t\sim d_{\theta_t},a_t\sim\pi_{\theta_t}}(A_{t,\theta_t}^i\psi_t^i|\mcal{F}_{t,2})+\eta_{\theta,t}B_{t+1,1}^i+\eta_{\theta,t}B_{t+1,2}^i),
\end{align*}
where $B_{t+1,2}^i=o(1)$ since $\eta_{\theta,t}=o(\eta_{\omega,t})$ by Assumption \ref{Assump_3}, then the critic convergence in Theorem \ref{thm:convergen_omega} is faster thus implying $A_t^i\rightarrow A_{t,\theta}^i$ . Furthermore, let $M_t^i=\sum_{\tau=0}^t\eta_{\theta,\tau}B_{t+1,1}^i$. It is a martingale sequence and since $\{\omega_t^{(k)}\}$, $\{\gamma_{it}(k)\}$, $\{\psi_t^i\}$ and $\{\phi_t\}$ are all bounded, by Assumption \ref{Assump_3}, it holds that
\begin{align*}
    \sum_t\mbb{E}\left(\|M_{t+1}^i-M_t^i\|^2|\mcal{F}_{t,2}\right)=\sum_{t\ge 1}\|\eta_{\theta,t}B_{t+1,1}^i\|^2<\infty,\ \text{almost surely}.
\end{align*}
By the martingale convergence theorem \cite[Proposition VII-2-3(c)]{neveudiscrete}, $\{M_t^i\}$ converges almost surely and it implies that for any $\epsilon>0$,
\begin{align*}
    \lim_t\mbb{P}\left(\sup_{n\ge t}\left\|\sum_{\tau=t}^n\eta_{\theta,t}B_{\tau,1}^i\right\|\ge \epsilon\right)=0
\end{align*}
Now, let 
\begin{align*}
    g^i(\theta_t)=\mbb{E}_{s_t\sim d_{\theta_t},a_t\sim \pi_{\theta_t}}(A_{t,\theta_t}^i\psi_t^i|\mcal{F}_{t,2})=\sum_{s_t\in\mcal{S},a_t\in\mcal{A}}d_{\theta_t}(s_t)\pi_{\theta_t}(s_t,a_t)A_{t,\theta_t}^i\psi_{t,\theta_t}^i.
\end{align*}
In order to apply Theorem \ref{supp2} to show the convergence of $\theta_t^i$, we need to verify that $g^i(\theta_t)$ is continuous in $\theta_t^i$. First, $\psi_t^i$ is continuous in $\theta_t^i$. Next, note that $d_{\theta_t}(s_t)\pi_{\theta_t}(s_t,a_t)$ is the stationary distribution and thus is the solution to the equation $d_{\theta_t}(s)\pi_{\theta_t}(s,a)=\sum_{s'\in\mcal{S},a'\in\mcal{A}}P^{\theta_t}(s',a'|s,a)d_{\theta_t}(s')\pi_{\theta_t}(s',a')$ and $\sum_{s\in\mcal{S},a\in\mcal{A}} d_{\theta_t}(s)\pi_{\theta_t}(s,a)=1$, where $P^{\theta_t}(s',a'|s,a)=P(s'|s,a)\pi_{\theta_t}(s',a')$. The unique solution to this set of linear equations can be verified to be continuous in $\theta_t$ with $\pi_{\theta_t}(s,a)>0$. Moreover, $A_{t,\theta_t}^i$ is continuous in $\theta_t^i$ too as $\omega_{\theta_t}=\sum_{k=1}^K \gamma_{it}(k)\omega_{\theta_t}^{(k)}$, where $\gamma_{it}(k)$ is assumed continuous by Assumption \ref{Assump_4} and $\omega_{\theta_t}^{(k)}$ is also continuous due to the fact that it is the unique solution to the linear equation $\Phi'D_{\theta}^{s,a}(T_{\theta}^{Q,(k)}(\Phi\omega_{\theta}^{(k)})-\Phi\omega_{\theta}^{(k)})=0$, which can also be verified to be continuous in $\theta_t$. Therefore, the convergence of $\theta_t^i$ is a direct consequence of applying Theorem \ref{supp2} for each $i\in\mcal{N}$.

\section{Auxiliary Results}
\subsection{Results on Stochastic Approximation}
In this section, we introduce a basic result of stochastic approximation shown in \cite{borkar2008stochastic}. More general conclusions can also be found in \cite{benaim2006dynamics,harold1997stochastic}.

Consider the following $n$-dimensional ($n\in\mbb{N}$) stochastic approximation iteration:
\begin{align*}
    x_{t+1}=x_t+\zeta_t(h(x_t,Y_t)+M_{t+1}+\eta_{t+1}),\ t\ge 0,
\end{align*}
where $\zeta_t>0$ and $\{Y_t\}_{t\ge 0}$ is a Markov chain on a finite set $A$. 

\begin{Theorem}\label{supp1}
    Suppose the following assumptions hold:
    \begin{itemize}
        \item [(1).] $h:\mbb{R}^n\times A\rightarrow \mbb{R}^n$ is Lipschitz continuous in its first argument;
        \item [(2).] $\{Y_t\}_{t\ge 0}$ is an irreducible Markov chain with stationary distribution $\pi$;
        \item [(3).] The stepsize sequence $\zeta_t$ is such that $\sum_t\zeta_t=\infty$ and $\sum_t\zeta_t^2<\infty$;
        \item [(4).] $\{M_t\}$ is a martingale difference sequence, i.e., $\mbb{E}(M_{t+1}|x_\tau,M_\tau,Y_\tau,\tau\le t)=0$, and it holds that for some $C>0$ and $t\ge 0$,
        \begin{align*}
            \mbb{E}\left(\|M_{t+1}\|^2|x_\tau,M_\tau,Y_\tau,\tau\le t\right)\le C(1+\|x_t\|^2);
        \end{align*}
        \item [(5).] The sequence $\{\eta_t\}$ is a bounded random sequence with $\lim_t\eta_t=0$ almost surely.
    \end{itemize}
    Then the asymptotic behavior of the above iteration is associated with the behavior of the solution to the ODE:
    \begin{align*}
        \dot{x}=\bar{h}(x):=\sum_i \pi(i)h(x,i).
    \end{align*}
    Moreover, suppose the above ODE has a unique globally asymptotically stable equilibrium $x^*$. We have:
    \begin{itemize}
        \item [(a).] If $\sup_t\|x_t\|<\infty$ almost surely, then $x_t\rightarrow x^*$.
        \item [(b).] Suppose $\lim_{c\rightarrow\infty}\frac{\bar{h}(cx)}{c}=h_{\infty}(x)$ exists uniformly on compact sets for some $h_{\infty}\in C(\mbb{R}^n)$. If the ODE $\dot{y}=h_{\infty}(y)$ has origin as the unique globally asymptotically stable equilibrium, then
        \begin{align*}
            \sup_t\|x_t\|<\infty,\ \text{almost surely}.
        \end{align*}
    \end{itemize}
\end{Theorem}

\subsection{Kushner-Clark Lemma}
The Kushner-Clark Lemma is a well-known result shown in \cite{kushner2012stochastic}.

Let $\mcal{L}_0$ be an operator projecting a vector onto a compact set $\mcal{X}\subset\mbb{R}^N$. Define an operator $\mcal{L}$ such that for any $x\in\mcal{X}$ and $h:\mcal{X}\rightarrow \mbb{R}^N$ continuous
\begin{align*}
    \mcal{L}(h(x)):=\lim_{\eta\rightarrow 0^+}\frac{\mcal{L}_0(x+\eta h(x))-x}{\eta}.
\end{align*}
Now, consider the following update in $N$ dimensions:
\begin{align*}
    x_{t+1}=\mcal{L}(x_t+\zeta_t(h(x_t)+M_t+\eta_t)).
\end{align*}
Its asymptotic behavior is associated with the following ODE:
\begin{align*}
    \dot{x}=\mcal{L}(h(x)).
\end{align*}

\begin{Theorem}\label{supp2}
Suppose the following assumptions hold:
\begin{itemize}
    \item [(1).] $h(\cdot)$ is a continuous $\mbb{R}^N$-valued function;
    \item [(2).] The sequence $\{\eta_t\}$ is a bounded random sequence with $\lim_t\eta_t=0$ almost surely;
    \item [(3).] The stepsize sequence $\zeta_t$ is such that $\sum_t\zeta_t=\infty$ and $\lim_t\zeta_t=0$;
    \item [(4).] The sequence $\{M_t\}$ satisfies: for any $\epsilon>0$,
    \begin{align*}
        \lim_t \mbb{P}\left(\sup_{n\ge t}\left\|\sum_{t=\tau}^n\zeta_\tau M_\tau\right\|\ge \epsilon\right)=0.
    \end{align*}
\end{itemize}
Then, if the above ODE has a compact set $\mcal{K}^*$ its set of asymptotically stable equilibria, $x_t$ converges almost surely to $\mcal{K}^*$ as $t\rightarrow \infty$.
\end{Theorem}


\section{Experiment Details}\label{sec:exp_detail}
In the first experiment, we consider $N=20$ agents and a binary-valued action space $\mcal{A}^i=\{0,1\}$ for all agents $1\le i\le N$. Therefore, the cardinality of the set of actions is $2^{20}$. Moreover, there are $|\mcal{S}|=20$ states. We follow a similar setting considered in \cite{dann2014policy} on selecting the model and parameters including transition probabilities, rewards, and features. Precisely, we sample the elements of the transition probability matrix $P$ from uniform $[0,1]$ and normalize it to be stochastic. We will also add a small constant $10^{-5}$ to each element in the matrix $P$ if necessary to ensure ergodicity of the MDP we consider. For each agent $i$ and each state-action pair $(s,a)$, $R^i(s,a)$ is sampled uniformly from $[0,4]$ independently. The instantaneous rewards $r_t^i$ are sampled from the uniform distribution $[R^i(s,a)-0.5,R^i(s,a)+0.5]$. The policy $\pi_{\theta^i}^i(s,a)$ is parametrized following the Boltzman policies:
\begin{align*}
    \pi_{\theta^i}^i(s,a)=\frac{e^{q_{s,a^i}'\theta^i}}{\sum_{b^i\in\mcal{A}^i}e^{q_{s,b^i}'\theta^i}},
\end{align*}
where $q_{s,b^i}\in\mbb{R}^5$ stands for the feature vector with the same dimension as $\theta^i\in\mbb{R}^5$. Here, $\{q_{s,b^i}\}$ are also uniformly sampled from $[0,1]$. In addition, the feature vector $\phi\in\mbb{R}^{10}$ is also uniformly sampled from $[0,1]^{10}$. We also make sure that the resulting matrix $\Phi$ has full column rank. The step size $\eta_{\omega,t}=t^{-0.65}$ and $\eta_{\theta,t}=t^{-0.85}$. Finally, for the mixed membership, we consider $K=4$ communities and sample $\Gamma_t\sim \text{Dirichlet}((1,1,1,1))$. The number of iteration is set $T=500$.

In the next experiment, we compare our community-based MARL framework with the baseline neighbor-based MARL in \cite{zhang2018fully}. We consider the same setting in the first experiment but make the following change to accommodate the community structure. For $K=4$ communities, we let Community $0$ prefers action $0$; Community $1$ prefers action $1$; Community 2 prefers even-numbered states, and Community 3 prefers odd-numbered states. Specifically, uniformly, we sample: $R^{(0)}(s,0)\in [3,4]$ and $R^{(0)}(s,0)\in [1,2]$; $R^{(1)}(s,0)\in [1,2]$ and $R^{(1)}(s,0)\in [3,4]$; For even states, $R^{(3)}(s,a)\in [3,4]$ and for odd states, $R^{(3)}(s,a)\in [1,2]$; For odd states, $R^{(3)}(s,a)\in [3,4]$ and for even states, $R^{(3)}(s,a)\in [1,2]$. Finally, we set 
\begin{align*}
    R^i(s,a)=\sum_{k=1}^K\gamma_i(k)R^{(k)}(s,a).
\end{align*}
As for the baseline using neighbor-based MARL, we stick to the paper \cite{zhang2018fully} for setting its consensus weight matrix $C_t$ in their Section E.

We also provide some additional experiment results. Figure \ref{fig:4} presents values of $\omega_t^{(k)}$ for all dimensions as a supplement for Figure \ref{fig:1}. Moreover, Figure \ref{fig:5} and Figure \ref{fig:6} show the value of the policy parameter $\theta^i$ for all $20$ agents as a supplement for Figure \ref{fig:2}.

