The \emph{value} $\nu$ of a red-blue colouring is the number of bichromatic edges. A red-blue colouring with maximum (respectively minimum) value is a \emph{maximum valid red-blue colouring} (respectively \emph{minimum valid red-blue colouring}).
A red-blue colouring is a \emph{red-blue $d$-colouring} if every vertex is adjacent to at most $d$ vertices of the other colour.
We make the following straightforward observations, which has been used in previous works, see e.g.~\cite{LPR23a}.

\begin{observation}\label{o-cut-colouring}
Let $G$ be a graph. Then the following holds.
\begin{itemize}
\item $G$ has a matching cut of size $\nu$ if and only if $G$ has a valid red-blue colouring of value $\nu$.
\item $G$ has a disconnected perfect matching of size $\nu$ if and only if $G$ has a perfect extendable red-blue colouring of value~$\nu$.
\item $G$ has a perfect matching cut if and only if $G$ has a perfect red-blue colouring.
\item $G$ has a $d$-cut, for $d \geq 1$, if and only if $G$ has a red-blue $d$-colouring.
\end{itemize}
\end{observation}

\begin{observation}\label{o-c-all-kr-mono}
For every $d\geq 1$, every complete graph $K_{r}$ with $r \geq 2d+1$ and every complete bipartite graph $K_{r,s}$ with $\min\{r,s\} \geq 2d$ and $\max\{r,s\} \geq 2d+1$ is monochromatic in every red-blue $d$-colouring.
\end{observation}

\noindent
%In the following, instead of using the more complicated framework from \cite{LPR23a} for \pmc, we stick to the easier notions from~\cite{LMPS24} for \dc.
Let $S, T \subseteq V$ be two disjoint vertex sets. We say that a \emph{red-blue $(S,T)$-$d$-colouring} is a red-blue $d$-colouring where the vertices of $S$ are coloured red and those of $T$ are coloured blue. When considering the case of $d=1$, we also use the name of \emph{red-blue $(S,T)$-colouring}.
A \emph{perfect red-blue $(S,T)$-colouring} is a red-blue $(S,T)$-colouring of $G$ where every vertex in $S$ and $T$ for which all neighbours are coloured has exactly one neighbour of the other colour.
We call $(S,T)$ a \emph{precoloured pair} and we define the following rules:
\begin{description}
\item [\bf R1.] Return {\tt no} (i.e., $G$ has no red-blue $(S,T)$-colouring) if 
	\begin{itemize}
		\item[i)] a vertex $v\in Z$ is adjacent to $d+1$ vertices in $S$ and to $d+1$ vertices in $T$.
		\item[ii)] a vertex $v \in S$ has $d+1$ neighbours in $T$.
		\item[iii)] a vertex $v \in T$ has $d+1$ neighbours in $S$.
	\end{itemize}

\item [{\bf R2.}] Let $v\in Z$.
\begin{itemize}
\item [(i)] If $v$ is adjacent to $d+1$ vertices of $S$, then move $v$ from $Z$ to $S$. 
\item [(ii)] If $v$ is adjacent to $d+1$ vertices of $T$, then move $v$ from $Z$ to $T$. 
\end{itemize}
\end{description}



\noindent
For perfect red-blue colourings we add two more rules.
\begin{description}
\item [{\bf R3.}] Return {\tt no} (i.e., $G$ has no perfect red-blue $(S,T)$-colouring) if
\begin{itemize}
\item [(i)] for a vertex $v \in S$,  $N(v) \subseteq S$, i.e.~$v$ cannot have a neighbour in $T$. 
\item [(ii)] for a vertex $v \in T$,  $N(v) \subseteq T$, i.e.~$v$ cannot have a neighbour in $S$. 
\end{itemize}

\item [{\bf R4.}] Let $v \in Z$.
\begin{itemize}
\item [(i)] If $v$ has a neighbour in $S$ with a neighbour in $T$, add $v$ to $S$.
\item [(ii)] If $v$ has a neighbour in $T$ with a neighbour in $S$, add $v$ to $T$.
\end{itemize}
\end{description}


