\section{Handling Complex Matrices} \label{sec:4} 
For some applications, including key rate calculations for QKD channels, we need to handle complex Hermitian matrices. For software packages such as DDS that only accept real symmetric matrices, we need an equivalent formula for $qre(X,Y)$ based on the real and imaginary parts of $X$ and $Y$. For a unitary matrix $U = U_r + \iota U_i$ (where $\iota=\sqrt{-1}$), we have
\begin{eqnarray} \label{eq:un-1}
UU^*=U^*U=I  \Leftrightarrow  \left\{\begin{array}{l}
U_rU_r^\top + U_iU_i^\top = I \\
-U_rU_i^\top + U_iU_r^\top = 0
\end{array} \right..
\end{eqnarray}
For any complex $n$-by-$n$ matrix $X=X_r + \iota X_i$, we define a $2n$-by-$2n$ matrix $\bar X$ as
\[
\bar X = \left[\begin{array}{cc}
X_r & -X_i \\  X_i & X_r
\end{array} \right].
\] 
If $X$ is Hermitian, then $\bar X$ is symmetric. 
By using \eqref{eq:un-1}, we can show that if $U$ is a unitary matrix, then $\bar U$ is also a real unitary matrix. We can also show that if $X=UDU^*$ is a spectral decomposition for $X$, then 
\[
\bar X = \bar U  \Diag(D,D) \bar U^\top,
\]
is a spectral decomposition for $\bar X$. This implies that for every function $f: \mathbb R \rightarrow \mathbb R\cup\{+\infty\}$ we have
\[
\trace(F(\bar X)) = 2 \trace(F(X)).
\]
Now we can prove the following lemma:
\begin{lemma}
For two Hermitian matrices $X,Y \in \H_+^n$ we have
\[
qre(\bar X, \bar Y) = 2 qre(X,Y). 
\]
\end{lemma}
\proof{Proof.}
First we show that for two Hermitian matrices $X,W \in \H_+^n$, we have
\begin{eqnarray} \label{eq:QRE-23}
\trace(\bar X \bar W) = 2 \trace(XW).
\end{eqnarray}
Assume that $X=X_r+\iota X_i$ and $W=W_r+\iota W_i$. Then, we have
\[
\trace(XY) = \trace(X_rW_r-X_iW_i+\iota (X_rW_i+X_iW_r)) = \trace(X_rW_r-X_iW_i),
\]
where for the last equation we used the fact that $\trace(XY)$ is a real number. Then, we have
\[
\trace(\bar X \bar Y) = \trace\left( \left[\begin{array}{cc}
X_r & -X_i \\  X_i & X_r
\end{array} \right] \left[\begin{array}{cc}
W_r & -W_i \\  W_i & W_r 
\end{array} \right]\right)= 2\trace(X_rW_r-X_iW_i).
\]
The last two equations confirm \eqref{eq:QRE-23}. To complete the proof, we claim that for every function $F$, we have
\begin{eqnarray} \label{eq:QRE-24}
\overline {F(X)} = F(\bar X).	
\end{eqnarray}
Assume that the spectral decomposition of $X$ is $X=UDU^*$. 
\begin{eqnarray*}
F(X)=U F(D) U^*&=&(U_r+\iota U_i) F(D) (U_r^\top-\iota U_i^\top)  \\
               &=& U_rF(D)U_r^\top+U_iF(D)U_i^\top + \iota (-U_rF(D)U_i^\top+U_iF(D)U_r^\top).
\end{eqnarray*}
Therefore, we have
\begin{eqnarray*}
\overline {F(X)} = \left[\begin{array}{cc}
U_rF(D)U_r^\top+U_iF(D)U_i^\top & U_rF(D)U_i^\top-U_iF(D)U_r^\top \\  -U_rF(D)U_i^\top+U_iF(D)U_r^\top & U_rF(D)U_r^\top+U_iF(D)U_i^\top
\end{array} \right].
\end{eqnarray*}
The spectral decomposition of $\bar X$ is $\bar X = \bar U \Diag(D,D) \bar U^\top$. Therefore, \\
$F(\bar X)=\bar U \Diag(F(D),F(D)) \bar U^\top$. By expanding this term, we can confirm that  \eqref{eq:QRE-24} holds. Now, \eqref{eq:QRE-23} and \eqref{eq:QRE-24} imply the result of the lemma. If we define $F(X):=\ln(X)$, then
\begin{eqnarray*}
\begin{array}{cclr}
qre(\bar X, \bar Y) & = & \trace(\bar XF(\bar X)) - \trace(\bar XF(\bar Y)) & \\
                    & = & \trace(\bar X \overline {F( X)}) - \trace(\bar X \overline {F(Y)}), &   \ \ \ \text{by using }\eqref{eq:QRE-24}\\
                    & = & 2 \trace{XF(X)} - 2 \trace(XF(Y)),  & \ \ \ \text{by using } \eqref{eq:QRE-23}  \\
                    & = & 2 qre(X,Y).
 \end{array}
\end{eqnarray*} 
  \endproof
