\textup{min} &  & qre\left(A_0+\sum_{i=1}^k x_i A_i, B_0+\sum_{i=1}^k y_i B_i\right) & \\
 & & KL(x,y)  \leq \gamma, &  \\
\end{array}
\end{eqnarray}
where $KL$ is defined in \eqref{eq:KL-1}. 
