\centering
\begin{minipage}{\linewidth}
\begin{algorithm}[H]
	\caption{DK-RRT: Visual Feature and Koopman Operator Learning}
	\label{algo:koopvision}
	\begin{algorithmic}[1]
	\State \textbf{Input:} Dataset $\mathcal{D}$ with robot states $\boldsymbol{\xi}_\rho$ and visual observations $\boldsymbol{\iota}$, visual feature extractor $f_{\vartheta}(\cdot)$, Koopman computation function $\textit{func}(\cdot)$
	\State $\hat{\boldsymbol{\xi}}_\omega \leftarrow f_{\vartheta}(\boldsymbol{\iota}),\quad\forall \boldsymbol{\iota}\in\mathcal{D}$ \small{\color{gray}// Compute object feature predictions}

	\State $\boldsymbol{\mathcal{K}} \leftarrow \textit{func}(\boldsymbol{\xi}_\rho, \hat{\boldsymbol{\xi}}_\omega)$ \small{\color{gray}// Initialize Koopman operator}
	\For {$epoch=1,\dots, N_{epoch}$}
	    \State Sample trajectory $\varpi$ and initial time $\tau_0$ from $\mathcal{D}$
	    \State Extract $\boldsymbol{\xi}_\rho(\tau_0), \boldsymbol{\iota}(\tau_0)$ from trajectory $\varpi(\tau_0)$
	    \State Initialize $\mathcal{L}\leftarrow 0$
	    \For {$k=0,\dots, N_{step}$}
	        \If {$k = 0$}
	            \State $\hat{\boldsymbol{\xi}}_\rho(\tau_0)\leftarrow \boldsymbol{\xi}_\rho(\tau_0)$
	            \State $\hat{\boldsymbol{\xi}}_\omega(\tau_0)\leftarrow f_{\vartheta}(\boldsymbol{\iota}(\tau_0))$ \small{\color{gray}// Compute initial features}
	        \EndIf
	        \State $\hat{\boldsymbol{\xi}}_\rho(\tau_0+k+1)\leftarrow \boldsymbol{\mathcal{K}}'(\hat{\boldsymbol{\xi}}_\rho(\tau_0+k), \hat{\boldsymbol{\xi}}_\omega(\tau_0+k))$ \small{\color{gray}// Predict robot state}
	        \State $\mathcal{L}\leftarrow \mathcal{L}+\|\boldsymbol{\xi}_\rho(\tau_0+k+1)-\hat{\boldsymbol{\xi}}_\rho(\tau_0+k+1)\|^2$ \small{\color{gray}// Accumulate loss}
	    \EndFor
	    \State Optimize feature extractor $f_{\vartheta}$ by minimizing $\mathcal{L}$
	    \If {epoch mod $M=0$}
	        \State $\hat{\boldsymbol{\xi}}_\omega\leftarrow f_{\vartheta}(\boldsymbol{\iota}),\quad\forall \boldsymbol{\iota}\in\mathcal{D}$
	        \State $\boldsymbol{\mathcal{K}}\leftarrow \textit{func}(\boldsymbol{\xi}_\rho, \hat{\boldsymbol{\xi}}_\omega)$ \small{\color{gray}// Periodically update Koopman operator}
	    \EndIf
	\EndFor
	\end{algorithmic}
