\begin{algorithm}
\caption{Receiving Columns in Distributed Reduction.}
\label{alg:local_fin}
\begin{algorithmic}[1]
    \Function{ReceiveColumns}{$C$} \Comment{$C$: received columns}
        \State {$\updated \gets \emptyset$}
        \State{$\sigma \gets \mbox{leftmost of all columns in }C$} \Comment{we start reduction from $\sigma$}
        \State{insert columns of $C$ into $\rfin$}
        \While{\textbf{true}}
            \If{$\sigma$ is not the last column in $\rfin$}
                \State{$\sigma_{next} \gets \mbox{next simplex after $\sigma$ in $\rfin$}$}
            \Else
                \State{$\sigma_{next} \gets \sigma$}
            \EndIf

            \While{$\col{\rfin}{\sigma} \neq 0$}
                \State {$\ell \gets \low(\col{\rfin}{\sigma})$}
                \If {$\piv{\ell} \prec \sigma$ and $\piv{\ell} \neq -1$}
                    \State \Comment {Pivot to the left, standard reduction}
                    \State{$\col{\rfin}{\sigma} \gets \col{\rfin}{\sigma} + \col{\rfin}{\piv{\ell}}$}
                \ElsIf {$\piv{\ell} \succ \sigma$}
                    \State \Comment {Pivot to the right, switch to reducing column $\piv{\ell}$}
                    \State{\Call{Swap}{$\piv{\ell}, \sigma$}}
                    \State{$\col{\rfin}{\sigma} \gets \col{\rfin}{\sigma} + \col{\rfin}{\piv{\ell}}$}
                \Else
                    \State \Comment {We saw that column and reduced it}
                    \State{\textbf{break}}
                \EndIf
            \EndWhile

            \If{$\col{\rfin}{\sigma} \neq 0$}
                \State{$\piv{\low(\col{\rfin}{\sigma})} \gets \sigma$}
                \If {$\low(\col{\rfin}{\sigma}) \notin \rseg{i}$}
                    \State \Comment {$\col{\rfin}{\sigma}$ no longer belongs }
                    \State \Comment {to current rank $i$, mark it to send further}
                    \State{insert $\low(\col{\rfin}{\sigma})$ into $\updated$}
                \EndIf
            \Else
                \State{erase column $\col{\rfin}{\sigma}$}
            \EndIf

            \If{$\sigma_{next} \neq \sigma$}
                \State{$\sigma \gets \sigma_{next}$}
            \Else
                \State{\textbf{break}}
            \EndIf
        \EndWhile
        \State {\Return $\updated$}
    \EndFunction
\end{algorithmic}
\end{algorithm}


