\end{figure}

\textbf{Running example}: We consider a two-player uncontrolled intersection case (see Fig.~\ref{fig:case}a) where each player's state is defined by its position $d_i$ and velocity $v_i$: $x_i=(d_i,v_i)$, and action by its acceleration rate. The terminal loss is $g_i(x) = -\alpha d_i(T) + (v_{i}(T)-\bar{v})^2$, which encourages the agent to move forward ($\alpha>0$) and restoring a target speed $\bar{v}$ at $T$. System dynamics follows:
\begin{equation}
    % {\dot x_{i}(t)}
    \left[
\begin{array}{ccc}
    \dot{d}_{i}(t) \\
    \dot{v}_{i}(t) \\
\end{array}
\right]
    =\left[
\begin{array}{ccc}
    0\hspace{0.4cm} 1 \\
    0\hspace{0.4cm} 0\\
\end{array}
\right]
\left[
\begin{array}{ccc}
    d_{i}(t) \\
    v_{i}(t) \\
\end{array}
\right]
+
\left[
\begin{array}{ccc}
    0 \\
    1 \\
\end{array}
\right]
u_{i}(t).
\label{eq:systemdynamics}
\end{equation}
From the above discussion, the co-state dynamics and the policy become:
\begin{equation}
\begin{aligned}
    & \dot{\lambda}_i^{*}[1] = \nabla_{d_i} \phi_i(\textbf{x}^*), ~ \lambda_i^{*}(T)[1] = \alpha\\
    & \dot{\lambda}_i^{*}[2] = -\lambda_i^{*}[1], ~\lambda_i^{*}(T)[2] = -2(v_i(T) - \bar{v})\\
    & u^*_i = 0.5\lambda^*_i[2].
\label{eq:costate_intersection}
\end{aligned}
\end{equation}
The first element of the co-state trajectory follows
\begin{equation}
    \lambda_i^*(t)[1] = \alpha - q_i \mathds{1}(t\geq t_i^{in}) + q_i \mathds{1}(t \geq t_i^{out}),
\end{equation}
while the second element $\lambda_i^*(t)[2]$ is an integral of $\lambda_i^*(t)[1]$.

\subsection{Learning equilibrium co-states}
We learn a neural network $\hat{\textbf{y}}_w(\cdot)$ that predicts $\textbf{y}(\cdot)$ for given $\textbf{x}_0 \in \mathcal{X}_0$ and time $t_0 \in \mathcal{T}_0$, where the parameters $w$ are learned through a dataset $\{(\textbf{x}_0, t_0,  \textbf{y}(\textbf{x}_0, t_0))_j\}_{j=1}^N$. Below we discuss several key aspects of data collection and learning.

\textbf{Data collection}: 
Finding BVP solutions with the existence of value discontinuity due to the collision requires softening the collision loss. This is done by using a sigmoid function and choosing its shape parameter that allows BVPs to be successfully solved. We solve the resultant BVP problems where the initial states are sampled from $\mathcal{X}_0$ and initial time $t=0$. Due to the softening, the resultant co-states are of the form
\begin{equation*}
    \lambda_i^*(t) = \exp\left(A_i^T (T-t)\right)\lambda_i^*(T) - q'_i \mathds{1}(t\geq t_i^{in}) + q'_i \mathds{1}(t \geq t_i^{out})
\end{equation*}
where $q'_i$ for non-collision close calls are estimated from the trajectory through least square during a post-process step.

\vspace{-0.05in}
% Active learning algorithm
\begin{algorithm}[h]
\SetAlgoLined
\SetKwInOut{Input}{input}
\SetKwInOut{Output}{output}
\Input{$\mathcal{X}_t$, $\mathcal{X}_a$}
\Output{$\hat{\textbf{y}}_w(\cdot)$}
    set $k=0$\;
    train $\hat{\textbf{y}}_w(\cdot)$ using $\mathcal{X}_t$\;
    \While{$\mathcal{X}_a \neq \emptyset$}{
        sample $\tilde{\mathcal{X}}_0^{(k)}  \subset \mathcal{X}_a$\;
        $\mathcal{A} = \emptyset$\;
        \For{$\textbf{x}_0 \in \tilde{\mathcal{X}}_0^{(k)}$ and $t_0 \in \mathcal{T}_0$}{
            compute $\hat{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}$ via $\hat{\textbf{y}}_w(\cdot)$\;
            compute $\hat{\textbf{u}}^*$ and $\hat{\textbf{x}}^*$ using $\hat{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}$ via Eq.~\eqref{eq:systemdynamics} and Eq.~\eqref{eq:costate_intersection}\;
            compute $\tilde{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}$ as solution to an inverse value problem with terminal values $\hat{\textbf{x}}^*(T)$ and $\hat{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}(T)$, and dynamics following Eq.~\eqref{eq:pmp}\;
            compute $a(\textbf{x}_0, t_0;w)$ via Eq.~\eqref{eq:acquisition}\;
            add $a(\textbf{x}_0, t_0;w)$ to $\mathcal{A}$\;
        }
        pick 
        $\textbf{x}^*$ and $t^*$ corresponding to $\max \mathcal{A}$\;
        compute $\textbf{y}(\textbf{x}^*, t^*)$ by solving the corresponding BVP\;
        add $(\textbf{x}^*, t^*, \textbf{y}(\textbf{x}^*, t^*))$ to $\mathcal{X}_t$\;
        remove $(\textbf{x}^*, t^*)$ from $\mathcal{X}_a$\;
        $k = k+1$\;
    }
\caption{Active learning}
\label{alg:active_learning}
\end{algorithm}
\vspace{-0.05in}

\textbf{Active learning}: Let the predicted co-state trajectory be $\hat{\boldsymbol{\lambda}}_{(\textbf{x}_0, t_0)}$. Here the dependence on $\textbf{x}_0$ and $t_0$ suggests that the prediction is derived from $\hat{\textbf{y}}_w(\textbf{x}_0, t_0)$. Using $\hat{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}$ and Eq.~\eqref{eq:pmp} we can compute $\hat{\textbf{u}}^*$ and then $\hat{\textbf{x}}^*$, which allows computing the co-state trajectory again through an inverse value problem. Denote this updated co-state trajectory by $\tilde{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}$, we can now introduce the following acquisition function:
\begin{equation}
    a(\textbf{x}_0, t_0;w) =  || \hat{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)} - \tilde{\boldsymbol{\lambda}}_{(\textbf{x}_0,t_0)}||_2.
    \label{eq:acquisition}
\end{equation}
$a(\cdot;w)=0$ when $\hat{\textbf{y}}_w(\cdot)$ is fully generalizable. At the $k$th iteration of active learning, we sample a subset $\tilde{\mathcal{X}}_0^{(k)} \subset \mathcal{X}_0$, and solve the game $\mathcal{G}(\textbf{x}^*, t^*)$ for $\textbf{x}^*, t^*=\argmax_{\textbf{x} \in \tilde{\mathcal{X}}_0^{(k)}, t\in \mathcal{T}_0} a(\textbf{x},t;w)$. The resultant solution is then added to the dataset to update $w$. Alg.~\ref{alg:active_learning} summarizes the active learning algorithm, where $\mathcal{X}_t,~ \mathcal{X}_a \subset \mathcal{X}_0$ are the training and acquisition datasets, respectively. $\mathcal{X}_t \cap \mathcal{X}_a = \emptyset$.


\vspace{10pt}
\section{Case Study}

\subsection{Case setup}
Using the running example on the uncontrolled intersection, we learn three neural network models: one for value approximation, one for co-state approximation, and the last also for co-state approximation but through active learning. We use a variety of training data sizes for learning to observe how generalization performance improves as data increases. For each learning task, we perform twenty independent experiments to accommodate for randomness in training data sampling, model initialization, and the active learning algorithm. We consider two metrics for generalization performance: (1) the absolute prediction error in co-state at current time, and (2) the total number of collisions over a set of test cases by using the predictive model for closed-loop control. To remove confounding effects, the true equilibria of these test cases have no collisions. The second metric is of higher importance as it directly reflects the risk induced by the learned models.  

\textbf{Hypotheses}: From the experiments, we statistically test the following hypotheses: \textit{With the same training data sizes, closed-loop control using an actively learned co-state network leads to lower collision probability than using a statically learned co-state network, which in turn has lower collision probability than using a value network.}

\textbf{Data preparation}: The initial state set $\mathcal{X}_0$ is defined based on player position range $d_i \in [15, 20]m$ and velocity range $v_i \in [18, 25]m/s$. $\mathcal{T}_0$ is defined as $[0,3]$s with a time interval of $0.1$s. The training, acquisition, and test datasets (denoted by $\mathcal{X}_t$, $\mathcal{X}_a$, and $\mathcal{X}_e$, respectively) are independently sampled from $\mathcal{X}_0$ using a Latin Hypercube sampler with respective sizes 1573, 1000, and 575. For each sample initial state, the Nash equilibrial policies, values, and co-states are solved by the BVP solver for $t=0$. The resultant trajectories are interpolated over $\mathcal{T}_0$. Softening of the collision penalty is necessary for convergence, as described below. Lastly, we use multiple initial policy guesses to explore local equilibria, and choose the ones with the best sum of values across the players.

\textbf{Soften collision penalty for BVP convergence}: Following \cite{chen2020shall}, the collision penalty is modeled as
\begin{equation*}
    \phi_i(x) = b\sigma(d_i, \theta)\sigma(d_{-i}, 1),
\end{equation*}
where 
{\small
\begin{equation}
\begin{aligned}
    \sigma(d,\theta) = & \left(1+\exp(-\gamma (d-R/2+\theta W/2))\right)^{-1}\\
    & \left(1+\exp(\gamma (d-(R+W)/2-L))\right)^{-1},
\end{aligned}
\end{equation}
% \begin{equation}
%     \sigma_2(d) = \left(1+\exp(\gamma (d-R/2-W/2-L))\right)^{-1};
% \end{equation}
}$b=10^4$ sets a high loss for collision; $\gamma=5$ is a shape parameter empirically set to enable effective BVP convergence; $\theta=5$ is a parameter that sets a safety buffer zone to avoid actual collisions at the intersection. $R$, $L$, and $W$ are the road length, car length, and car width, respectively. These parameter settings and the visualization of collision penalty $\phi_i(x)$ are illustrated in Fig.~\ref{fig:case}.

\textbf{Equilibrium solutions}: Fig.~\ref{fig:solution}a,b shows equilibrium policies and co-states sampled from $\mathcal{X}_0$. Consistent with our analysis, co-state trajectories have a low-dimensional representation, i.e., the trajectories over time can be compressed as four parameters. More specifically, each pair of co-state trajectories of Player 1 and 2 specifies: (1) the type of equilibrium interaction that is about to happen (see Fig. 2a of \cite{chen2020shall}) through $t_i^{in}$ and $t_i^{out}$, and (2) the risk of the interaction through $q_i$, where $q_i$ also directly governs the control policy according to Eq.~\eqref{eq:costate_intersection}. It is worth investigating in future studies whether this representation of co-states more closely reflects what human beings learn and use to make decision during collision-avoiding interactions.

We use Fig.~\ref{fig:solution}c-f to qualitatively explain why learning equilibrium co-states is more efficient than learning values. Our conjecture is that the equilibrium value landscape in the joint space of $\textbf{x}_0$ and $t_0$ has larger total variance than the equilibrium co-state landscapes. This is evident, for example, from the sample $d_1-t$ slice in Fig.~\ref{fig:solution}e,f where the value changes rapidly along $d_1$ due to the appearance of near-collision cases, while $q_1$ changes categorically from accelerating of Player 1 (when it is ahead of Player 2), to decelerating (when it is behind Player 2), and to keeping speed (when it is far away). Therefore, while learning of values requires capturing the highly nonlinear value variations, the learning of co-states boils down to a classification. For completeness, we also show landscapes of values of Player 1 and $q_1$ across $d_1$ and $d_2$ for fixed time and speeds in Fig.~\ref{fig:solution}c,d, respectively.

\begin{figure}
    \centering
    \includegraphics[width = \linewidth]{solution_new.jpg}
    \caption{(a) Trajectories in the space of $d_1$ and $d_2$ driven by the equilibrium policies starting from different initial states. (b) The corresponding co-state trajectories along time. (c) Equilibrium value landscape across $d_1$ and $d_2$ with $t_0=0$ and $v_1=v_2=18m/s$. (d) Equilibrium co-state parameter $q_1$ landscape under the same settings of (c). (e, f) Equilibrium values and $q_1$ in the space of $d_1$ and $t$, where $d_2=17.5m$ and $v_1=v_2=18m/s$.}
    \label{fig:solution}
\vspace{-18pt}
\end{figure}

\textbf{Learning architecture and hyperparameters}:
From the value landscape in Fig. 2b of \cite{chen2020shall}, the equilibrium value exhibits two modes along time. Therefore we propose the following value network architecture:
% {\small
\begin{equation}
    \hat{V}(\textbf{x},t) = \eta \mu(\textbf{x},t) + (1-\eta) \nu(\textbf{x},t),
\end{equation}
% }
where $\mu$ and $\nu$ follow the same architecture: \texttt{fc5-(fc16-tanh)$\times$3-(fc2-tanh)}, and \texttt{fc}$n$ represents a fully connected layer with $n$ nodes and \texttt{tanh} is the hyperbolic tangent activation. $\eta$ is a sigmoid function that determines whether one of the agents have passed the intersection zone.

For co-state approximation, we adopt the same architecture as for $\mu$, yet expanding the output dimension of the last layer to match with that of the co-state parameters. It should be noted that a value network trained solely on $\mu$ failed to generalize. Therefore our choice of architecture is in favor of the value network in terms of model flexibility.

For each learning task, we perform full batch training use a learning rate of 0.01. For early termination, we set aside 400 independently drawn validation data points, along with their BVP solutions. The training terminates when it accumulates 500 epochs where the validation error, i.e., the $l_2$-norm between predicted and true values or co-state trajectories, increases.

\textbf{Algorithmic settings for active learning}: For each iteration of active learning, we uniformly sample 50 initial states from $\mathcal{X}_a$ and choose 10 with the highest $a(\cdot,w)$ values. An ablation study is yet to be performed to better understand the tradeoff between effectiveness and computational cost of active learning with respect to its hyperparameters.

\textbf{Closed-loop control}: For both value and co-state networks, we evaluate their generalization performance by counting their collision percentages among test cases when used for closed-loop control for both players. For the value network, we use PyTorch autograd to compute the co-state as $\nabla_{x_i}\hat{V}$. Following Eq.~\eqref{eq:costate_intersection}, the control input is then either $0.5\hat{\lambda}_i[2]$ when it is within the input bounds, or otherwise one of the bounds. We roll out the simulation using a time interval of 0.03s.  

